window.__LIBQ=window.__LIBQ||{};window.__LIBQ["pham-nhan-tu-tien"]=window.__LIBQ["pham-nhan-tu-tien"]||{};window.__LIBQ["pham-nhan-tu-tien"]["q10"]=window.__LIBQ["pham-nhan-tu-tien"]["q10"]||{};window.__LIBQ["pham-nhan-tu-tien"]["q10"]["cotTruyen"]=[{"chuong":1747,"tieuDe":"Lôi Trận","tomTat":"Trên Phong Nguyên Đại Lục, Nhân tộc và Yêu Tộc dựa vào cấm chế cổ đại cùng Thiên Uyên Thành để bảo vệ Tam cảnh Thất địa trước khu hoang dã đầy hiểm nguy. Tại một hồ nước trong khu hoang dã, bốn tu sĩ Hóa Thần bị Thạch Nguyên Quy dùng mạng lưới xúc tu vây ép đến mức Bách Linh Như Ý sắp không thể chống đỡ. Theo đề nghị của nho sinh, Hỏa huynh kích nổ Cực Lôi Châu trong khi hai nữ tu và nho sinh dựng nhiều lớp phòng hộ, qua đó phá hủy phần lớn xúc tu nhưng khiến cả nhóm trọng thương, riêng nho sinh mất một cánh tay. Thạch Nguyên Quy nhanh chóng tái sinh xúc tu, điều khiển thủy vân truy đuổi rồi xuyên hư không chặn đường, đánh tan đội hình của bốn người. Khi cả nhóm quyết định phóng bảo vật liều chết, nhiều lôi cầu trên cao bất ngờ kết thành một lôi trận hình tròn. Một đạo điện quang cực lớn đưa một thân ảnh chưa rõ danh tính tới giữa trận, và người này vừa xuất hiện đã tức giận chửi Lôi Vân Tử, tuyên bố lần gặp sau nhất định sẽ tính sổ."},{"chuong":1748,"tieuDe":"Lôi Vân Tử Và Lôi Quang Pháp Trận","tomTat":"Hàn Lập xuất hiện trên chiến trường giữa bốn tu sĩ Nhân tộc và Thạch Nguyên Quy, nhận lời để họ dẫn tới Thiên Uyên Thành nhưng quyết định lấy yêu đan của cổ thú trước. Khi Thạch Nguyên Quy tấn công bằng cột sáng màu lam và hàng loạt xúc tu, hắn hóa giải công kích rồi ngưng tụ bàn tay lôi điện, thiêu cổ thú thành tro và thu lấy yêu đan. Trước sự kinh hãi của nhóm tu sĩ, Hàn Lập xác nhận mình chưa đạt Hợp Thể kỳ. Chương hồi tưởng hành trình hơn trăm năm của hắn trên Phong Nguyên Đại Lục, gồm những lần bị cổ thú Hợp Thể truy sát, mắc kẹt trong Kỳ Hàn Tuyệt Địa và trọng thương vì kỳ độc sau đại chiến với các tu sĩ dị tộc cao giai. Trong những hiểm cảnh ấy, Ngũ Sắc Hàn Diễm thăng cấp, còn Hàn Lập thu thập được nhiều tài liệu và bí thuật. Tại một thành nhỏ của Minh tộc, hắn từng giao chiến hơn một tháng với Lôi Vân Tử, một Trận Pháp tông sư có Ngũ Lôi Thân Thể và tu luyện đại thần thông Lôi Đình. Hai người sau đó kết thành bằng hữu, trao đổi Lôi Quang Pháp Trận, Ích Tà Thần Lôi và Lôi Văn Thuật, nhưng mỗi bên đều bí mật để lại trở ngại trong pháp môn truyền cho đối phương. Sau quá trình nghiên cứu, Hàn Lập đã hiểu thông khoảng tám chín phần Lôi Quang Pháp Trận."},{"chuong":1749,"tieuDe":"Trở Về Thiên Uyên Thành","tomTat":"Hàn Lập tiếp tục thử nghiệm Lôi Quang Pháp Trận do mình cải tiến, nhưng vì thiếu phần trọng yếu trong pháp quyết nên trận vẫn không thể xác định điểm đến và cần thời gian thi pháp lâu. Gặp lại bốn tu sĩ Nhân tộc sau nhiều năm lưu lạc giữa ngoại tộc, hắn dùng phi xa màu xanh đưa họ trở về Thiên Uyên Thành và tranh thủ hỏi tình hình hai tộc. Nhóm Nho sinh kể rằng liên quân dị tộc từng tấn công thành dữ dội nhưng bất ngờ rút lui, đồng thời thuật lại lời đồn cuộc chiến kết thúc có liên quan đến Huyền Thiên chi bảo. Tin đồn một tu sĩ hạ giới phi thăng mang theo bảo vật vào Nhân tộc khiến Hàn Lập âm thầm cảnh giác, dù hắn vẫn che giấu phản ứng. Hắn còn biết Thiên Diệu Linh Hoàng đã hết thọ nguyên và con gái Nam Ly Giao Vương bị mất tích, nhưng không thu được manh mối chắc chắn nào về Nam Cung Uyển. Nhờ tốc độ của phi xa, hành trình hơn hai tháng được rút xuống còn nửa tháng và Hàn Lập cuối cùng nhìn thấy Thiên Uyên Thành. Tại pháp trận truyền tống ngoài thành, hơn mười Thanh Minh Vệ đang canh giữ, còn quanh lối vào dường như tồn tại một điều bí ẩn."},{"chuong":1750,"tieuDe":"Nhập Thành","tomTat":"Hàn Lập cùng bốn tu sĩ trở lại Truyền Tống pháp trận ngoài Thiên Uyên Thành và gặp Trác Hướng, một Hắc Vệ từng thuộc đội của hắn. Qua cuộc trò chuyện, Hàn Lập xác nhận mình đã tiến vào Luyện Hư cảnh giới, đồng thời biết gần một nửa đội viên cũ đã chết, phần lớn người sống sót đã rời thành, còn Hứa tiên tử hiện chỉ huy một tiểu đội Hắc Vệ. Trác Hướng kể lại thân phận cùng chiến tích năm xưa của Hàn Lập, khiến những tu sĩ xung quanh không còn nghi ngờ hắn là dị tộc biến hóa. Sau khi truyền tống vào thành, Hàn Lập chia tay nhóm Nho sinh, còn bốn người quyết định lưu lại Xuân Miên Các và sẵn sàng chờ hắn sai bảo. Tại đại sảnh kiểm tra, Hàn Lập xuất trình lệnh bài Thanh Minh Vệ mang số Bính năm mươi sáu vì không có lệnh bài thông hành hiện hành. Ngọc Linh Tử xác nhận lệnh bài là thật nhưng đã hết hiệu lực, công nhận Hàn Lập hiện là người tự do, thu hồi tín vật rồi cho phép hắn rời đi."},{"chuong":1751,"tieuDe":"Đuổi Đi","tomTat":"Sau khi Hàn Lập rời thạch tháp, Dị Linh Bàn xác nhận hắn đúng là Nhân tộc, khiến lão già Thiên Vệ gầy ốm quyết định không truy xét thêm dù kinh ngạc trước tốc độ tiến giai của hắn. Trở lại Thiên Uyên Thành, Hàn Lập nhận thấy thành trì đã khôi phục vẻ thịnh vượng và xác định bản thân đã đủ điều kiện chuẩn bị xung kích Hợp Thể. Hắn tới phường thị, mua số lượng lớn vật liệu luyện khí và luyện đan từ một cửa hiệu rồi rời thành tìm nơi bế quan. Sau hai tháng phi hành, hắn phát hiện một linh mạch nhỏ nhưng dồi dào linh khí, vốn đã có hơn mười động phủ của các tu sĩ Nguyên Anh, Kết Đan và Trúc Cơ. Hàn Lập dùng thần niệm xuyên qua cấm chế, áp chế một lão giả đang luyện đan và truyền âm buộc tất cả cư dân phải rời đi trong vòng một ngày. Trước lời đe dọa của hắn, lão giả bỏ cả đỉnh lô quý trọng để chạy trốn, còn những tu sĩ khác cũng hoảng sợ rút đi. Chỉ hơn nửa ngày sau, toàn bộ dãy núi đã không còn một tu sĩ Nhân tộc nào, trở thành nơi Hàn Lập có thể chuẩn bị cho lần phá cảnh tiếp theo."},{"chuong":1752,"tieuDe":"Luyện Thần Tầng 1","tomTat":"Hàn Lập kiểm tra vùng núi bằng thần niệm rồi dùng cự viên khôi lỗi khai mở một động phủ trong vách đá, đồng thời sai Báo Lân Thú tuần tra và ngăn người ngoài tới gần. Báo Lân Thú lúc này đã đạt Luyện Hư trung kỳ nhờ từng nuốt nội đan Ám thú Vương và được bồi dưỡng lâu dài bằng linh đan, sức chiến đấu đủ vượt tu sĩ Luyện Hư hậu kỳ thông thường. Hàn Lập dựng trận pháp tạo biển sương mù che kín phạm vi trăm dặm, bố trí dược viên cùng nhiều tầng cấm chế rồi giao Oa Oa canh giữ bên ngoài mật thất. Oa Oa sau gần trăm năm được Ly Thủy Châu bồi dưỡng đã dần gần với Ly thủy chi thân và có thêm linh tính. Sau ba ngày nhập định, Hàn Lập kiểm tra ngọc giản và xác nhận mình đã lĩnh ngộ hoàn toàn Luyện Thần Thuật tầng một, chỉ còn bước cuối để tiến tới đại thành. Hắn uống đan dược, thả chín vòng tròn ngân quang, bắt pháp quyết và gọi ra kim sắc hư ảnh ba đầu sáu tay, chính thức bắt đầu giai đoạn vận công cuối cùng."},{"chuong":1753,"tieuDe":"Cốc Gia","tomTat":"Trong mật thất tại Húc Nhật Phong, Hàn Lập vận chuyển Phạm Thánh Chân Ma Công tới cực hạn và phối hợp cùng Phạm Thánh Pháp Tướng để dung hợp Kim Triện Văn với Ngân Khoa Văn. Hắn áp súc hàng nghìn phù văn thành hai quang cầu rồi đưa chúng vào trán, khiến thân thể biến dạng và phải chịu đau đớn dữ dội. Quá trình tu luyện Luyện Thần thuật dẫn phát thiên tượng lớn với mây đen, cuồng phong, băng tuyết, gió nóng cùng ánh sáng Kim và Ngân bao phủ biển sương mù quanh ngọn núi. Nhiều tu sĩ lân cận rời động phủ để quan sát, trong đó có một vị thúc tổ Luyện Hư sơ kỳ của Cốc gia và hơn mười tộc nhân. Sau khi nghe tộc trưởng một nhánh Cốc gia kể về thần niệm đáng sợ của Hàn Lập, vị thúc tổ nhận định thực lực đối phương ít nhất đã đạt mức Luyện Hư đại thành và có thể còn cao hơn. Ông nghiêm cấm tộc nhân chọc giận Hàn Lập, quyết định lưu lại để tìm cơ hội giao hảo và dự tính mời hắn làm khách khanh trưởng lão. Không nhận ra thiên tượng bắt nguồn từ bí thuật Chân tiên giới, ông để một thanh niên tiếp tục theo dõi rồi dẫn những người còn lại trở về động phủ."},{"chuong":1754,"tieuDe":"Tiên Vực Cùng Cấm Thuật","tomTat":"Trong bảy ngày Hàn Lập bế quan, biển sương mù xuất hiện thiên tượng kỳ dị với con mắt vàng khổng lồ, quang cầu bảy màu và băng tuyết cuồng phong tàn phá cảnh vật. Tại Tiên giới, Huyền Minh dùng tiên khí giám sát phát hiện một người trong tiểu linh giới đã tu Luyện thần thuật tầng thứ nhất đến đại thành; các tiên nhân xác nhận đây là cấm thuật nhưng quyết định không can thiệp vì cho rằng người hạ giới khó luyện tới tầng cuối và sẽ bị Tiếp Dẫn Thai phát hiện khi phi thăng. Hàn Lập tỉnh lại, nhận ra thần thức đã tăng gấp đôi, mạnh ngang thần niệm của tu sĩ Hợp Thể hậu kỳ đại thành dù bản thân vẫn chưa bước vào Hợp Thể Kỳ. Thần niệm của hắn quét ra ngoài, xuyên qua cấm chế và phát hiện Cốc Vân, một tu sĩ Luyện Hư thuộc Cốc gia. Qua cuộc trò chuyện, Hàn Lập biết Cốc gia là chân linh thế gia truyền thừa từ thượng cổ, còn Diệp gia và Lũng gia là hai gia tộc lớn nhất, trong đó Lũng gia có tu sĩ Hợp Thể trấn giữ. Cốc Vân tặng hắn ngọc giản ghi thông tin về các chân linh thế gia và mời hắn làm khách khanh trưởng lão, nhưng Hàn Lập từ chối. Nhớ lại việc từng phá hỏng mưu đồ của Lũng gia đối với Diệp gia, Hàn Lập quyết định phải đề phòng thế lực này rồi lấy ra một cuộn tranh dài hơn một thước."},{"chuong":1755,"tieuDe":"Niệm Kiếm Quyết","tomTat":"Hàn Lập mở Vạn Kiếm Đồ, dùng Linh Mục quan sát vô số phi kiếm và xác nhận thành quả lĩnh ngộ của mình là Niệm Kiếm Quyết. Hắn dung nhập pháp môn này vào Thanh Bàn kiếm trận, khiến kiếm trận tăng mạnh uy lực, biến hóa tùy tâm và có thể bố trí bằng một niệm. Sau đó, Hàn Lập kiểm kê những thu hoạch từ Nghiễm Hàn giới, xác định công dụng của Hư Linh đan, quả Hồng La, Thực Độc Thảo và Tinh Không Đồ. Để chuẩn bị đột phá Hợp Thể kỳ, hắn luyện đan, chế tạo pháp khí làm trận nhãn và bố trí một pháp trận dẫn thiên địa nguyên khí quanh ngọn núi. Sau hơn nửa năm bế quan điều chỉnh trạng thái, Hàn Lập chính thức phá cảnh, khiến biển sương mù rung chuyển và thiên địa nguyên khí từ các linh mạch điên cuồng hội tụ. Ngũ Sắc Linh Vân cùng tử sắc cự giao hình thành trên trời, còn linh áp khổng lồ khiến những tu sĩ ở gần đó không thể chống đỡ. Cuối chương, một kim sắc cự viên xuất hiện từ ngọn núi và nhảy lên nghênh chiến tử sắc cự giao."},{"chuong":1756,"tieuDe":"Tiến Giai Hợp Thể Thượng","tomTat":"Pháp tướng Sơn Nhạc Cự Viên vặn gãy tử giao lôi điện, nuốt sạch hồ quang và Ngũ Sắc Linh Vân rồi dẫn động thiên địa nguyên khí trong phạm vi vạn dặm. Dị tượng và linh áp lan khắp biển sương mù, khiến các tu sĩ Cốc gia bị trấn áp; tộc trưởng một phân chi nhận ra pháp tướng và suy đoán người trong núi đang xung kích bình cảnh Hợp Thể. Khi tâm ma xâm lấn, pháp tướng trở nên thống khổ và điên cuồng, còn Nguyên Anh của Hàn Lập cũng đứng bên bờ mất hết lý trí. Trong mật thất, Hàn Lập đốt tàn hương để ổn định tâm thần, ép phân thần thiên ngoại ma đầu hiện thành mặt quỷ rồi dùng kim sắc hồ quang đánh tan nó. Vượt qua ma nhiễu, hắn tiếp tục thu nạp phù văn năm màu và lượng nguyên khí khổng lồ do pháp tướng dẫn về lòng núi. Thân thể Hàn Lập dần trong suốt và tỏa hương nồng đậm, còn Nguyên Anh lớn ngang thân thể nhưng vẫn nhắm mắt chịu đau đớn, cho thấy quá trình tiến giai chưa hoàn tất."},{"chuong":1757,"tieuDe":"Tiến giai Hợp Thể","tomTat":"Hàn Lập hoàn thành tiến giai Hợp Thể khi Nguyên Anh trở về pháp thân và luồng năng lượng trong cơ thể phá mở trở ngại nơi biển thần thức. Tiếng huýt phát ra trong quá trình này trực tiếp chấn động thần thức của các tu sĩ quanh biển sương mù, khiến họ rơi khỏi không trung và vội vàng rời xa Húc Nhật Phong. Một nhánh Cốc gia cũng di dời, đồng thời phái người mang ngọc giản về bản gia, làm tin tức về vị tu sĩ Hợp Thể mới nhanh chóng lan rộng. Sau ba ngày củng cố tu vi, Hàn Lập thử điều khiển thiên địa nguyên khí và xác nhận mình có thể ngưng tụ vô số phong nhận mà gần như không hao pháp lực. Hắn đánh giá chiến lực hiện tại đủ để có hơn phân nửa khả năng thắng một tu sĩ Hợp Thể đại thành nếu liều mạng. Hàn Lập quyết định tiếp tục bế quan vài năm rồi tìm Nam Cung Uyển, gặp Hứa Thiên Vũ để hỏi tung tích Băng Phách tiên tử, đồng thời trì hoãn việc gặp Thanh Nguyên Từ cho tới khi đạt Hợp Thể hậu kỳ đại thành."},{"chuong":1758,"tieuDe":"Lai Khách","tomTat":"Sau khi tiến giai Hợp Thể, Hàn Lập hoạch định việc luyện đan từ Thực Độc Thảo, luyện Thái Ất Thanh Sơn thành Cực Sơn và tìm hiểu cách dùng Hư Linh Đan. Thần niệm tăng mạnh giúp hắn tạm thời điều khiển hơn một nghìn Phệ Kim Trùng trưởng thành, đồng thời hắn chuẩn bị Thất Thải đan cùng các vật liệu khác để tiếp tục bồi dưỡng đàn trùng. Tuy đã đủ thần niệm để tu luyện tầng hai của Luyện Thần Thuật, thân thể hắn vẫn chưa đạt yêu cầu nên phải trông cậy vào Phạm Thánh Chân Ma công và Hồng La Thiên Tửu. Hàn Lập ở lại Húc Nhật Phong một năm để củng cố pháp lực và tâm cảnh, trong khi các thế lực lân cận chờ cơ hội tiếp xúc. Trưởng lão Thiên Uyên Thành Thích Húc Băng và người bảo hộ Cốc gia Hiểu Phong tiên tử cùng đến, mỗi người đều muốn tranh thủ vị tu sĩ Hợp Thể mới vì lợi ích của thế lực mình. Hàn Lập mở biển sương mù đón họ vào động phủ, nơi khôi lỗi nữ tử áo trắng cấp Luyện Hư có thể tự do hoạt động khiến cả hai kinh ngạc. Khi Hàn Lập xuất hiện, Hiểu Phong tiên tử xác nhận cảnh giới Hợp Thể của hắn và thay mặt Cốc gia chúc mừng; hắn giải thích rằng lần gặp Cốc Vân trước đó, bản thân chỉ chưa chắc có thể trùng kích bình cảnh thành công chứ không cố ý che giấu."},{"chuong":1759,"tieuDe":"Yêu Cầu Cùng Linh Hoàng Đại Bỉ","tomTat":"Hàn Lập trò chuyện với Thích Húc Băng và Hiểu Phong tiên tử về kiến văn tu luyện, đồng thời xác nhận mình vừa trở về từ Man Hoang, từng đi qua một đại lục khác và từng làm Thiên Uyên Vệ. Hiểu Phong tiên tử cho biết Cốc gia đã điều tra quá khứ của hắn, đồng thời tiết lộ Diệp gia từng tìm hắn hơn trăm năm còn Lũng gia dường như vẫn chưa hủy lệnh truy tìm. Thích Húc Băng thay Hội trưởng lão Thiên Uyên Thành mời Hàn Lập gia nhập, trong khi Hiểu Phong tiên tử mời hắn làm Thái thượng trưởng lão Cốc gia và hứa truyền bí thuật Chân Linh Huyết cùng sự trợ giúp thành lập một thế gia mới. Khi biết Thiên Diệu Linh Hoàng đã tọa hóa và Thánh Tu Đại Bỉ sẽ diễn ra sau hơn trăm năm, Hàn Lập bày tỏ ý định tham gia để gặp gỡ, trao đổi với các tu sĩ Hợp Thể. Hắn từ chối cả hai lời mời chiêu mộ vì không muốn ở lâu một nơi hoặc vướng quá nhiều quan hệ nhân quả. Tuy vậy, Hàn Lập vẫn muốn có bí thuật của Cốc gia và đề nghị dùng bảo vật hoặc công pháp để trao đổi, khiến câu chuyện dừng lại trước phản ứng của Hiểu Phong tiên tử."},{"chuong":1760,"tieuDe":"Chân Huyết Ẩn Ưu 1","tomTat":"Hàn Lập khẳng định sẽ không gia nhập Cốc gia hay bất kỳ thế lực nào khác, khiến Hiểu Phong tiên tử và Thích Húc Băng tạm thời cáo từ. Sau khi chia đường với Thích Húc Băng, Hiểu Phong bí mật quay lại, trao ngọc bài và đề nghị Hàn Lập tạm mang thân phận trưởng lão Cốc gia để hơn mười năm sau giúp gia tộc tranh lợi tại Chân Linh đại điển. Đổi lại, nàng sẽ truyền cho hắn một phần bí thuật luyện hóa Chân linh huyết không thuộc hàng trọng yếu, và Hàn Lập chấp thuận vì thỏa thuận không ràng buộc lâu dài. Hàn Lập cần bí thuật này để đối chiếu với Kinh Chập Quyết sau khi phát hiện những phần Chân linh huyết tưởng đã luyện hóa hoàn toàn vẫn còn ẩn sâu trong cơ thể, có thể khiến hắn mất khả năng biến thân nếu tiếp tục hấp thu chân huyết. Trong ba năm tiếp theo, hắn củng cố hoàn toàn tu vi Hợp Thể kỳ và tiếp tục từ chối nhiều lời chiêu mộ, kể cả sứ giả của Thiên Nguyên Thánh Hoàng. Sau khi xuất quan, Hàn Lập mất hai tháng tới Thiên Uyên thành và tìm gặp nhóm bốn tu sĩ Hóa Thần gồm Nho sinh, Hồng giáp đại hán cùng hai nữ tu. Cả bốn kinh ngạc khi nhận ra hắn rồi cung kính nghênh đón vào lầu các."},{"chuong":1761,"tieuDe":"Người Quen Cũ (1)","tomTat":"Hàn Lập nhận ra bốn người nho sinh vẫn chưa hoàn toàn hồi phục vì chân nguyên bị tổn thương nên ban cho mỗi người một bình đan dược, đủ giúp họ bình phục trong khoảng một tháng. Biết nhóm này dự định lưu lại Thiên Uyên thành khoảng một trăm năm, hắn nhờ họ tìm Nam Cung Uyển, một tu sĩ phi thăng có thể đã đổi tên, và chuẩn bị để lại ngọc giản chứa chân dung nàng. Vì sắp đi xa và còn thiếu nhiều tài liệu hiếm để luyện đan, Hàn Lập giao cho họ một túi chứa lượng lớn cực phẩm linh thạch để thay mình thu mua. Hắn đồng thời lấy ra bốn hộp ngọc chứa bảo vật làm thù lao cho nhóm. Nho sinh kinh hãi khi kiểm tra số linh thạch được giao, sau đó mở một hộp và lấy ra ngọc phiến màu trắng phủ đầy phù văn. Ngọc phiến vừa xuất hiện đã tạo ra nhiều phiến ảnh di động và tỏa một luồng linh áp kinh người."},{"chuong":1762,"tieuDe":"Người Quen Cũ (2)","tomTat":"Hàn Lập trao Sơn Hà phiến cho Nho sinh, còn ba người đồng hành của y lần lượt nhận đôi vòng bạc, một chiếc khăn và Huyền Băng phi đao. Để ngăn cả nhóm nhận linh thạch cùng bảo vật rồi đổi ý, hắn công khai tu vi Hợp Thể và biểu diễn khả năng thao túng thiên địa nguyên khí. Sau đó, Hàn Lập trở lại khu thạch tháp nơi mình từng làm Thanh Minh vệ và dùng một phần khí tức khiến lực lượng canh cửa phải kinh sợ. Nhạc đạo hữu nhận ra người quen cũ, trong khi Đinh huynh báo rằng Hứa Thiên Vũ đang dẫn đội tuần tra ngoài thành. Hàn Lập nhờ Đinh huynh chuyển lời mời nàng tới Tụ Tiên các rồi rời đi. Nhạc đạo hữu kể lại việc Hàn Lập từng dùng tu vi Hóa Thần trung kỳ giết đối thủ tương đương Luyện Hư và tiến vào Man Hoang thế giới làm nhiệm vụ bí ẩn. Việc Hàn Lập đạt Hợp Thể chỉ sau khoảng ba trăm năm khiến người quen cũ vừa khiếp sợ vừa đố kỵ."},{"chuong":1763,"tieuDe":"Ma Ảnh Tái Hiện","tomTat":"Sau khi rời thạch tháp, Hàn Lập tiếp tục tới phường thị Thiên Uyên thành thu mua tài liệu và tìm linh dược phụ trợ trong đại điện giao dịch của Nhân–Yêu nhị tộc. Hắn cân nhắc rằng tự lập thế lực sẽ hao tổn tâm lực, còn ngôi vị Linh Hoàng có thể trực tiếp đem lại quyền lực và thuộc hạ mà không cản trở con đường tu luyện. Tại một động quật bí mật của Ngân Tộc, hắc bào đại hán và bạch y nữ tử được tôn là Thánh Tổ xuất hiện qua truyền tống trận, nhanh chóng phá hủy hơn mười khôi lỗi canh giữ. Người Ngân Tộc định dùng bí thuật đào thoát nhưng bị hoa hư ảnh của bạch y nữ tử ép hiện thân, khóa cứng rồi bị hắc bào đại hán sát hại. Trong một cung điện nằm giữa Phong Nguyên đại lục và Lôi Minh đại lục, chiếc kén huyết quang phập phồng phía trên mười hai dị thú đã bị hút khô khí huyết, bên cạnh là mười hai cổ đăng đã tắt và thủy tinh cầu hiển thị đài sen bạc. Trở lại Thiên Uyên thành, Hàn Lập gặp nữ tử Yêu tộc từng giao dịch linh dược hơn trăm năm trước và đồng ý xem xét nhóm linh dược quý mới của nàng, dù cho biết nhu cầu hiện tại của mình đã gần đủ."},{"chuong":1764,"tieuDe":"Kim Việt Thiền Sư","tomTat":"Hàn Lập đề nghị dùng linh dược vạn năm đổi lấy linh cốt, nội đan và các tài liệu quý hiếm trong danh sách của mình. Nữ tử Yêu tộc cảnh báo cấm kỵ liên quan đến vật liệu của bổn tộc nhưng vẫn nhận lời thu thập hơn nửa danh sách, đồng thời hẹn hắn vài năm sau giao dịch tại Vạn bảo giao dịch hội trong Huyền Vũ cảnh. Những tài liệu này không chỉ phục vụ luyện đan mà còn là nguyên liệu phụ trợ để Hàn Lập luyện Thái Ất Thanh Sơn, một quá trình phiền toái hơn việc luyện Nguyên Từ Cực Sơn. Sau khi nhận trữ vật trạc từ cửa hàng và nhận ra số hàng thu mua còn quá ít, Hàn Lập tới Tụ Tiên các nghỉ lại. Sáng hôm sau, Kim Việt Thiền Sư, một trưởng lão phi thăng xuất thân Phật tông, đích thân tới gặp và xác minh lai lịch cùng tốc độ tiến giai của hắn. Kim Việt báo rằng Lôi La chân nhân đã chết trong lần dị tộc công thành, khiến ông trở thành trưởng lão phi thăng duy nhất còn lại trong Trưởng lão hội. Ông vì thế tiếp tục mời Hàn Lập gia nhập hội, hy vọng sự góp mặt của hắn sẽ cải thiện vị thế của cộng đồng tu sĩ phi thăng tại Thiên Uyên thành."},{"chuong":1765,"tieuDe":"Hứa Gia Thượng","tomTat":"Kim Việt thiền sư tiếp tục mời Hàn Lập gia nhập Trưởng lão hội để cùng bảo vệ quần thể tu sĩ phi thăng, nhưng Hàn Lập từ chối vì muốn chuyên tâm theo đuổi trường sinh và con đường phi thăng Chân Tiên. Kim Việt tôn trọng lựa chọn ấy, hứa trợ giúp hắn tại Thiên Uyên Thành, rồi hai người trao đổi tâm đắc tu luyện suốt một ngày một đêm. Đến ngày thứ bảy, Hứa Thiên Vũ tới Tụ Tiên Các gặp Hàn Lập và xác nhận mình là hậu nhân của Băng Phách tiên tử. Nàng tiết lộ Băng Phách tiên tử đã mất tích từ hàng vạn năm trước sau một lần ra ngoài khi vừa tiến giai Hợp Thể. Hứa Thiên Vũ cũng cho biết hậu nhân của vị tổ tiên này đã phân thành hơn mười nhánh, còn Hứa gia là nhánh chính thống giữ truyền thừa trực tiếp. Vì đang mang một vật được nhờ chuyển cho Băng Phách tiên tử hoặc hậu nhân trực hệ của bà, Hàn Lập quyết định đích thân đến gặp tộc trưởng Hứa gia. Hứa Thiên Vũ nhận lời dẫn đường và hai người hẹn sau hai ngày sẽ dùng các Truyền Tống pháp trận để lên đường tới Thiên Nguyên cảnh."},{"chuong":1766,"tieuDe":"Lưỡng Tộc Đại Thừa","tomTat":"Hứa Thiên Vũ nói rõ tên thật với Hàn Lập, xác nhận sẽ tới Thiên Uyên thành đúng hẹn rồi lên đường chuẩn bị. Hàn Lập nhận số tài liệu nhóm Nho sinh đã thu mua, giao thêm danh sách mới và trở về Tụ Tiên Các đóng cửa không ra ngoài. Trong một điện phủ bí mật, các trưởng lão Thiên Uyên thành xác nhận Hàn Lập không muốn gia nhập thế lực nào, đồng thời lo ngại Trưởng lão hội chưa đủ mười tu sĩ Hợp Thể. Kim Việt Thiền Sư công bố cảnh báo của Thánh đảo và kết quả Mạc Giản Ly dùng Tinh bàn thăm dò Chân Ma giới, qua đó xác định Cổ Ma đang chuẩn bị một cuộc chiến xâm lấn Linh giới có thể xảy ra chỉ sau vài trăm năm. Trước tình trạng các thế lực lớn đều co cụm tự bảo vệ, Trưởng lão hội quyết định di chuyển phàm nhân vào đại thành, xây thêm thành trống, tuyển thủ vệ cao giai và tìm kiếm ứng viên có khả năng tiến giai Hợp Thể. Ngân Quang tiên tử sau đó tiết lộ Ngao Khiếu đã vượt qua Đại thiên kiếp lần thứ hai mươi mốt nhưng phải bí mật bế quan vì hao tổn nguyên khí. Nhờ quá trình hồi phục thuận lợi và có Linh Lung ở bên trong nhiều năm, vị Đại Thừa Yêu tộc được dự đoán sẽ sớm khôi phục pháp lực rồi xuất quan."},{"chuong":1767,"tieuDe":"Hứa Gia Hạ","tomTat":"Trong cuộc nghị sự tại Thiên Uyên thành, các Trưởng lão xác nhận Linh Lung là hậu nhân chính thống của Ngao Khiếu, đã đạt Luyện Hư trung kỳ đỉnh phong và hiện tu luyện bên cạnh ông. Nguyên nhân Ngao Khiếu chủ động đưa nàng rời khỏi Thiên Khuê vẫn chỉ được giải thích bằng những lời phỏng đoán. Cuộc họp sau đó chuyển sang việc Dạ Xoa tộc và Mộc tộc phái sứ giả tới trong bối cảnh ma kiếp sắp xảy ra. Hai ngày sau, Hàn Lập cùng Hứa Thiên Vũ dùng pháp trận đường dài tới Phong Lâm thành, khiến ba Thành chủ Luyện Hư tại đây bất an khi nhận ra thần niệm của một tu sĩ Hợp Thể. Hàn Lập tiếp tục dùng phi xa đi về Hứa gia và phát hiện vùng đất đỏ có Tinh Đồng khoáng mạch quy mô lớn. Hứa Thiên Vũ xác nhận gia tộc đã định cư tại đây từ một vạn năm trước, nhờ khoáng mạch trở nên giàu có nhưng phải chịu bất lợi vì linh khí loãng. Cuối cùng, hai người tới sơn môn Hứa gia, nơi mười ngọn núi có nhiều kiến trúc và được một hệ thống cấm chế khá lợi hại bảo vệ."},{"chuong":1768,"tieuDe":"Mê Trận Huyễn Cảnh","tomTat":"Hứa Thiên Vũ đưa Hàn Lập tới sơn mạch Hứa gia, vào báo tin trước rồi cùng tộc trưởng Hứa Giao, Hứa Lỗ và hai đội nữ tu ra nghênh đón. Hứa Giao dùng lệnh bài mở cấm chế, để lộ Mê Trận Huyễn Cảnh có khả năng làm sai lệch hình ảnh và vị trí thật của hơn mười ngọn núi. Hàn Lập nhận ra đây là cổ trận chưa được phục hồi hoàn chỉnh, đồng thời chỉ rõ những điểm bố trí khiếm khuyết khiến nó khó ngăn tu sĩ Hợp Thể tinh thông trận đạo. Hắn giải thích rằng mình từng mua được điển tịch đầy đủ về trận pháp này tại một phường thị dị tộc và đã nghiên cứu qua. Sau khi vào đại điện, Hàn Lập gặp hai thúc tổ Luyện Hư của Hứa gia là Hứa Hỏa và Hứa Nham. Hắn xác nhận đang giữ một vật liên quan tới Băng Phách tiên tử, nhưng vì bà còn để lại những nhánh hậu duệ khác nên yêu cầu Hứa gia dùng công pháp, thần thông hoặc bảo vật truyền thừa để chứng minh tư cách hậu nhân trực hệ trước khi nhận vật."},{"chuong":1769,"tieuDe":"Hàn Diễm Cùng Kim Phù","tomTat":"Theo đề nghị của Hứa Giao, Hứa Nham thi triển Kiền Lam Băng Diễm, đóng băng chén trà và khiến vùng hư không quanh nó tạm thời trì trệ. Hàn Lập nhận ra thần thông này, đồng thời hiểu rõ sự khác biệt giữa Hàn Diễm hấp thu từ Hư Thiên Đỉnh và Hàn Diễm được tu luyện theo khẩu quyết truyền thừa. Sau khi xác nhận Hứa gia là hậu nhân trực hệ của Băng Phách tiên tử, hắn giao ngọc giản lam nhạt cùng hộp ngọc trắng do một cường giả dị tộc nhờ chuyển lại. Hàn Lập còn tự hiện ra Kiền Lam Băng Diễm để chứng minh mình từng thu được một phần Hàn Diễm do Băng Phách tiên tử lưu lại ở hạ giới. Người Hứa gia suy đoán hai vật có thể liên quan đến việc tổ tiên mất tích sau khi tiến vào Hoang Dã Thế Giới. Trong mật thất, Hứa Hỏa xác nhận không thể cưỡng ép bóc phù, còn Hứa Giao dùng máu của mình khiến kim phù trên ngọc giản mất linh khí và tự rời xuống. Nội dung ngọc giản cùng vật nằm trong hộp ngọc vẫn chưa được tiết lộ."},{"chuong":1770,"tieuDe":"Huyết Hồn","tomTat":"Hứa Giao mở hộp ngọc và xác nhận chiếc bình đỏ bên trong là Huyết Hồn Bình tổ truyền từng được Băng Phách tiên tử mang khỏi Hứa gia. Ngọc giản đi kèm cho biết Băng Phách đã tới khu vực hoang dã rồi sang một đại lục khác, nhưng sau biến cố chưa rõ chỉ chuyển về được một tia huyết hồn. Vì phù triện phong ấn đã bị gỡ, Hứa Giao lập tức huy động mật vệ, phong tỏa núi Tông Miếu, mời Đại thúc tổ xuất quan và quyết định cử hành nghi thức đánh thức huyết hồn ngay trong đêm. Hứa Giao cùng Hứa Hỏa cũng nhận định Hàn Lập là chỗ dựa tiềm năng nên chủ trương tiếp đãi long trọng và giữ hắn ở lại. Muốn biết tung tích Băng Phách tiên tử, Hàn Lập đồng ý tạm chờ tại Hứa gia nhưng chỉ giới hạn thời gian trong khoảng hơn một tháng. Trong thời gian đó, hắn nghiên cứu phù triện tiên giới từ Quảng Hàn giới và tìm được manh mối nhập môn Thiên Qua Phù trong tàn trang Kim Khuyết Ngọc Thư. Đêm khuya, dị tượng mặt trăng đỏ cùng huyết quang trên núi Tông Miếu lọt vào linh mục của Hàn Lập, khiến hắn suy ra phần lớn chân tướng nghi thức bí mật đang diễn ra."},{"chuong":1771,"tieuDe":"Hứa Gia Tông Miếu","tomTat":"Hàn Lập tiếp tục tĩnh tọa nghiên cứu phù lục, quan sát dị tượng linh khí bùng phát nhiều đêm liền trên ngọn núi. Hứa Thiên Vũ liên tục tới vấn an nhưng lộ vẻ lo âu, muốn cầu viện nhưng do dự. Sáng ngày thứ năm, Hứa Giao dẫn Đại trưởng lão Hứa Nguyên — tu sĩ Luyện Hư hậu kỳ gần đại viên mãn đang chuẩn bị trùng kích Hợp Thể — tới cầu viện Hàn Lập. Hứa Giao tiết lộ món đồ Hàn Lập từng giao lại chính là Huyết Hồn Bình do Băng Phách tiên tử đích thân tế luyện, chứa đám huyết hồn có thể chỉ ra tung tích của bà; bà từng phát hiện y bát của Huyết Tinh Thượng Nhân — kỳ tài Nhân tộc thời cổ tu luyện Huyết Hồn Đại Pháp — và chọn tu luyện một số bí thuật bảo mệnh. Ba tu sĩ Luyện Hư của Hứa gia đã nhiều lần thử nghi thức gọi hồn nhưng thất bại, phù lục phong ấn đã bị tháo và huyết hồn chỉ còn hai ngày trước khi tiêu tán. Hàn Lập đồng ý hỗ trợ với điều kiện chỉ bảo đảm nếu nguyên nhân thất bại nằm ở pháp lực, rồi lập tức yêu cầu kiểm tra huyết hồn. Cả nhóm bay tới ngọn núi đặt tông miếu, nơi được bảo vệ nhiều tầng cấm chế và hơn trăm mật vệ phần lớn Nguyên Anh có bí thuật liên thủ. Hứa Giao dùng pháp bàn mở cấm chế rồi dẫn mọi người qua cửa hông tiến vào mật điện bên trong Hứa gia tông miếu."},{"chuong":1772,"tieuDe":"Nghi Thức","tomTat":"Hứa Giao dẫn Hàn Lập xuyên qua hậu điện, đi qua thông đạo ngầm có mật vệ canh giữ, tới đại sảnh bằng hắc sắc ngọc thạch nơi hơn mười tu sĩ Hứa gia cùng Hứa Nham và Hứa Hoả đã chờ sẵn quanh pháp trận. Hàn Lập dùng linh mục nhận ra vật nằm trong linh dịch huyết trì mới là mấu chốt, Hứa Nguyên xác nhận đó là Huyết tinh quan — trấn gia chi bảo dùng ngưng luyện thân thể ký thác cho Huyết hồn. Hàn Lập đối chiếu Huyết hồn đại pháp với công pháp phân hồn của Thiên Vân tộc nhân, nhận thấy nhiều điểm tương đồng trong phân hồn và ký phụ, nâng mức nắm chắc hỗ trợ nghi thức từ ba bốn thành lên bảy tám phần. Hắn yêu cầu Hứa gia cứ tiến hành như thường lệ, chỉ ra tay khi cần. Khi màn đêm buông xuống, phù văn trên đỉnh đại sảnh tự kết thành tiểu pháp trận và phóng quang trụ trắng kích hoạt huyết trì sôi trào. Hứa Nguyên phát lệnh, toàn bộ tu sĩ đồng loạt niệm chú bắt quyết vận hành đại trận, ba tu sĩ Luyện Hư phun tinh huyết tế trận kỳ tạo huyết sắc quang hà phủ kín pháp trận. Huyết tinh quan xuất hiện trong huyết sắc hỏa diễm, toàn bộ tu sĩ trắng bệch run rẩy vì đã thúc pháp lực tới cực hạn."},{"chuong":1773,"tieuDe":"Thức Tỉnh","tomTat":"Bạch sắc phù văn từ huyết trì nhập vào Huyết tinh quan, còn Hứa Giao dùng Huyết sắc tiểu bình phóng huyết ti khiến nhân ảnh trong quan tài biến thành huyết nhân. Các tu sĩ Hứa gia vận hành huyết kỳ và pháp trận để tạo huyết kén, nhưng huyết ti nhanh chóng khô héo khiến nghi thức đứng trước nguy cơ thất bại trong lúc pháp lực mọi người gần cạn. Theo lời cầu viện của Hứa Giao, Hàn Lập gọi Đệ nhị Nguyên anh và Báo Lân Thú trợ lực cho hai lá huyết kỳ, đồng thời tự mình truyền linh lực vào lá cờ còn lại. Uy lực Huyết trì pháp trận nhờ đó tăng mạnh, huyết kén phục hồi và dần ngưng thành thân thể nữ tử gần như người thật. Lớp vỏ đỏ tươi sau đó nứt vỡ, để lộ một nữ tử tuyệt mỹ với đôi mắt đỏ có dị quang chấn nhiếp linh hồn. Huyết sắc quang hà hóa thành cung trang che thân, rồi nàng chậm rãi mở mắt mà không biểu lộ bất cứ dao động tình cảm nào."},{"chuong":1774,"tieuDe":"Huyết Linh","tomTat":"Cung trang nữ tử dùng thần niệm dò xét Hàn Lập nhưng bị Đại Diễn quyết tự động vận hành và đẩy ra ngoài, sau đó nàng thu nhỏ Huyết Tinh Quan rồi hiện thân trước mọi người. Nàng xác nhận mình chỉ là Huyết hồn kế thừa một phần ký ức của Băng Phách tiên tử, không phải bản tôn chân chính, và yêu cầu hậu nhân gọi mình là Huyết Linh. Hàn Lập giải thích việc mình được mời tới đánh thức Huyết hồn rồi chủ động rời tông miếu để nàng nói chuyện riêng với Hứa gia. Huyết Linh tiết lộ rằng nàng chưa biết Băng Phách còn sống hay đã ngã xuống, nhưng mơ hồ nhớ bản tôn có thể đang bị nhốt tại một đại lục khác. Theo yêu cầu của nàng, Hứa Giao thuật lại đại kiếp Ma giới, những biến động của Nhân tộc, Yêu tộc và Hứa gia, đồng thời kể về quan hệ giữa Hứa Thiên Vũ với Hàn Lập. Sau ba ngày, Huyết Linh đã dung hợp Huyết hồn với pháp thân và củng cố huyết thân tới đại thành nhờ pháp lực tinh thuần của Hàn Lập. Để báo đáp, nàng trao cho hắn ngọc giản ghi Huyết Hồn bí thuật, một thần thông có thể ngưng tụ hóa thân và hỗ trợ bảo mệnh."},{"chuong":1775,"tieuDe":"Hoàn Đỉnh","tomTat":"Hàn Lập xem bảo điển do Huyết Linh trao nhưng từ chối tu luyện Huyết Hồn Đại Pháp vì công pháp này xung đột với bí thuật thần niệm đặc thù của hắn. Huyết Linh giải thích phương pháp huyết luyện hồn niệm của công pháp, đồng thời cho biết ký ức được bản tôn truyền thừa không chứa rõ những trải nghiệm tại Nhân giới. Khi Hàn Lập lấy Hư Thiên đỉnh ra, nàng lập tức nhận ra bảo vật và suy đoán nó có cùng xuất xứ với Hư Linh đỉnh, đều do bản tôn tự tay luyện chế. Huyết Linh sai Hứa Giao bày Ngọc Ma Hoa ba vạn năm, Bát Giao Nhận và cực phẩm linh thạch trị giá ba nghìn vạn để đổi lấy chiếc đỉnh. Hàn Lập chỉ nhận Ngọc Ma Hoa rồi chủ động hoàn trả Hư Thiên đỉnh, còn Huyết Linh đại diện Hứa gia cùng bản tôn cảm tạ và hứa trợ giúp hắn về sau. Việc trả lại bảo vật từng nhiều lần giúp mình đối địch khiến Hàn Lập hóa giải sự áy náy, nguy cơ tâm ma và ảnh hưởng của lời thề cũ với thanh niên họ Ông. Sau khi xử lý xong mọi việc tại Hứa gia, hắn quyết định rời đi, du ngoạn Thiên Nguyên cảnh rồi mới tới Vạn Bảo Đại Hội."},{"chuong":1776,"tieuDe":"Hải Đại Thiếu Cùng Khí Linh Tử","tomTat":"Sau khi rời sơn mạch Hứa gia, Hàn Lập dành khoảng năm năm du lịch một phần Thiên Nguyên cảnh, qua đó hiểu rõ hơn sự chênh lệch thực lực giữa Nhân tộc và các dị tộc lớn. Danh tiếng của hắn lan rộng sau khi diệt vài tán tu, nhưng hắn từ chối mọi lời mời từ các tông môn và thế gia. Trên đường tới Huyền Vũ cảnh dự Vạn bảo đại hội, hắn gặp Hải đại thiếu và Khí Linh Tử đang bị năm tu sĩ Trúc Cơ truy sát, liền che giấu tu vi và hiện thân dọa lui đối phương. Hải đại thiếu có linh căn tuyệt hảo nhưng từng bị kiểm tra sai nên đi theo con đường luyện thể, còn Khí Linh Tử là truyền nhân của Vụ Hải môn với công pháp kỳ lạ. Hai người mang theo linh trà thượng phẩm cùng vài khối quặng sắt mà ngay cả Hàn Lập cũng không nhận ra lai lịch. Vì tò mò và do đại hội còn lâu mới khai mở, Hàn Lập đồng ý dùng phi xa đưa cả hai tới Huyền Vũ cảnh."},{"chuong":1777,"tieuDe":"Cửu Tiên Sơn","tomTat":"Hải đại thiếu và Khí Linh Tử kết bạn đồng hành, được Hàn Lập giúp giải quyết cuộc truy sát của một tiểu tông môn rồi chỉ điểm về tu luyện và luyện thể. Trong lúc nghỉ chân, Hàn Lập dùng thần niệm kiểm tra Hải đại thiếu và xác nhận phong linh căn của hắn có thể tạm thời biến mất hoàn toàn trước khi xuất hiện trở lại. Hàn Lập lấy sáu trái Ngưng châu quả cho cả ba cùng dùng, còn Khí Linh Tử tiết lộ loại quả này từng giúp tu vi trì trệ của mình đột phá. Khi kiểm tra Khí Linh Tử, Hàn Lập phát hiện trong đan điền tiểu đạo sĩ có một truyền thừa pháp khí chứa phong ấn mạnh, có khả năng lưu giữ sở học của tiền nhân và tự bạo nếu bị cưỡng đoạt. Ba người sau đó dùng phi xa tiếp tục tiến về Huyền Vũ cảnh, vùng đất có đông tu tiên giả, luyện thể sĩ và thường xuyên chịu yêu thú xâm nhập do tiếp giáp Thất Yêu chi địa. Tại khu vực giáp ranh giữa Huyền Vũ cảnh và Yêu hồ chi địa, Cửu Tiên Sơn được tinh nhuệ Nhân tộc cùng Yêu tộc trấn giữ để chuẩn bị cho Vạn bảo giao dịch hội diễn ra mỗi ngàn năm một lần."},{"chuong":1778,"tieuDe":"Bạch Quả Nhi","tomTat":"Trước ngày Vạn Bảo Đại Hội, hơn mười Phường thị tạm thời hình thành quanh Cửu Tiên Sơn, thu hút đông đảo tu sĩ và yêu tu từ Tam cảnh Thất địa tới trao đổi tài liệu quý. Dù Nhân tộc và Yêu tộc bị cấm công khai giải quyết ân oán, lực lượng tuần tra chỉ giữ được vẻ yên ổn bên ngoài nên những vụ cậy mạnh ép giao dịch vẫn xảy ra tại nơi hẻo lánh. Trên một ngọn núi hoang, Thạch Luân cùng hai hắc y tu sĩ Trúc Cơ hậu kỳ bao vây Bạch Hóa Cập và Bạch Quả Nhi để cưỡng đoạt Thiên Niên Huyết Sâm. Thạch Luân giả vờ thả Quả Nhi rồi bắt cô bé trở lại làm con tin, buộc Bạch Hóa Cập phải giao hộp gấm chứa linh dược. Sau khi xác nhận Huyết Sâm là thật, nhóm này vẫn quyết định giết cả hai cha con để tránh Nhạc Hoa tiên tử truy cứu. Ngay khi Quả Nhi sắp bị bẻ cổ, cô bất ngờ được tráo bằng một thiết khôi lỗi đầy gai xanh lam khiến bàn tay Thạch Luân bị đâm thủng. Hải Đại Thiếu cùng người đồng hành ẩn sau đại thụ sau đó lên tiếng phản đối và chuẩn bị dựa vào sự hỗ trợ của Hàn huynh để đối đầu ba kẻ phục kích."},{"chuong":1779,"tieuDe":"Ba Đấu Ba","tomTat":"Ba người Hàn Lập, Hải Đại Thiếu và Khí Linh Tử tới gần Cửu Tiên Sơn, vô tình chứng kiến nhóm Thạch Luân giết người đoạt bảo và dùng Bạch Quả Nhi uy hiếp đối phương. Khí Linh Tử nhờ Hàn Lập kích phát phù Thay mận đổi đào, tráo nữ đồng với một khôi lỗi và cứu nàng khỏi hiểm cảnh. Thạch Luân đánh giá thấp nhóm mới đến, cùng hai tu sĩ áo đen bất ngờ hợp kích trung niên nam tử, nhưng hoàng sa hộ thân đã tạm thời chặn được các pháp khí. Hải Đại Thiếu dùng bao tay ánh vàng và quyền pháp luyện thể áp chế tu sĩ điều khiển ngân thương. Khí Linh Tử phối hợp phù màu lam với độn thuật để đánh lén tu sĩ dùng hắc thuẫn, khiến đối phương bị thương rồi né tránh các quỷ đầu phun lửa truy kích. Khi hai đồng bọn đều bị cầm chân, Thạch Luân lấy ra chiếc áo da đỏ như máu chứa linh trùng. Tuy nhiên, Hàn Lập đã âm thầm xuất hiện ngay sau lưng hắn và nhận ra linh trùng bên trong có cấp bậc không thấp."},{"chuong":1780,"tieuDe":"Hàn Độc","tomTat":"Thạch Luân thả hàng trăm Huyết Sắc Độc Phong và dùng cổ kính màu xanh tập kích Hàn Lập, nhưng cả hai thủ đoạn đều bị hóa giải. Hàn Lập giết Thạch Luân cả thân thể lẫn nguyên thần, sau đó dùng kim sắc lôi quang đánh thành tro hai đồng bọn đang chia hướng đào tẩu. Bạch Hóa Cập dẫn con gái Bạch Quả Nhi đến cảm tạ ba ân nhân, còn Hải Đại Thiếu và Khí Linh Tử tiếp tục đấu khẩu về thực lực. Quan sát Bạch Quả Nhi, Hàn Lập phát hiện hàn độc đã xâm nhập đan điền và kinh mạch, khiến nàng chỉ còn sống tối đa ba năm nếu không được chữa trị. Nhạc Hoa tiên tử, ngoại tổ mẫu của Bạch Quả Nhi, vội tới nơi và hiểu lầm nhóm Hàn Lập là Nam Sơn Tam Ác nên dùng linh áp áp chế họ, nhưng bị Hàn Lập đánh tan. Bạch Hóa Cập kịp thời giải thích rằng Nam Sơn Tam Ác đã chết và ba người trước mặt là ân nhân cứu mạng phụ tử mình. Khi biết Hàn Lập có thể có cách chữa bệnh cho Bạch Quả Nhi, Nhạc Hoa tiên tử lập tức vui mừng và chuẩn bị hỏi rõ phương pháp."},{"chuong":1781,"tieuDe":"Thiên Nguyên Thánh Hoàng","tomTat":"Nhạc Hoa dò xét Hàn Lập nhưng không thể nhìn thấu tu vi thật của hắn, sau đó mời hắn cùng Hải Đại Thiếu và Khí Linh Tử tới động phủ để cảm tạ việc cứu Bạch Hóa Cập và Ngân Hạnh Nhi. Trước khi mọi người rời đi, một đoàn hộ giá hùng hậu xuất hiện với hơn một trăm kỵ sĩ Nguyên Anh, ba mươi sáu chiến xa, mười tám tu sĩ Luyện Hư và một thú xa khổng lồ do tám Khổng Tước trắng kéo. Nhờ cờ hiệu mang chữ cổ Thánh, Nhạc Hoa nhận ra đây là xa giá của Thiên Nguyên Thánh Hoàng. Hàn Lập quan sát và xác định trên tầng hai có ba tu sĩ Hợp Thể, gồm Hoàng Đãng, một tăng nhân áo cà sa tím và Thiên Nguyên Thánh Hoàng. Thánh Hoàng phát hiện Hàn Lập là tu sĩ đồng giai nên chủ động mời hắn lên xa giá uống linh tửu. Hàn Lập để hai người đồng hành theo Nhạc Hoa về động phủ trước rồi bay lên gặp Thánh Hoàng, qua đó khiến mọi người biết rõ thân phận Hợp Thể của hắn. Trên xa giá, Hàn Lập tự giới thiệu và xác nhận với Hoàng Đãng rằng mình mới tiến giai Hợp Thể được vài năm."},{"chuong":1782,"tieuDe":"Tửu Hoàng","tomTat":"Thiên Nguyên Thánh Hoàng và Thiên Thiền đại sư chú ý tới Hàn Lập vì hắn chỉ mất vài trăm năm để từ Hóa Thần tiến lên Hợp Thể, còn Hàn Lập quy thành tựu ấy cho những cơ duyên tại Man Hoang. Trong bữa tiệc, Thánh Hoàng bộc lộ niềm say mê mỹ tửu, tự nhận muốn mang danh Tửu Hoàng và mời Hàn Lập thưởng thức Hổ Phách Linh Tửu. Hàn Lập đánh giá cao loại rượu này, kể về Cửu Hương Linh Tửu rồi tiết lộ mình có phương pháp ủ Hồng La Tiên Tửu cùng Hồng La Quả. Ba tu sĩ Hợp Thể đồng ý hỗ trợ thu thập phụ liệu, còn Hàn Lập giao danh sách nguyên liệu cho Thánh Hoàng và hẹn ba ngày sau quay lại. Thánh Hoàng tiếp đó báo tin Ly Hỏa Giao Vương và Hắc Phượng Yêu Vương đã tới Cửu Tiên Sơn, đồng thời cảnh báo Hàn Lập về thực lực của Thất Đại Yêu Vương. Hàn Lập phủ nhận quan hệ trực tiếp với Hắc Phượng Yêu Vương, chỉ thừa nhận từng giao thiệp với người của Hắc Phượng Tộc. Cuối cùng, bốn người chuyển sang trao đổi công pháp, kinh nghiệm vượt bình cảnh và tâm đắc tu luyện."},{"chuong":1783,"tieuDe":"Khô Nhãn Đại Pháp Và Vọng Khí Thuật","tomTat":"Sau nửa ngày trao đổi tâm đắc tu luyện với Thiên Nguyên Thánh Hoàng, Thiên Thiền đại sư và Hoàng Đãng, Hàn Lập cáo từ rồi bay về phía Cửu Tiên Sơn. Hai loại bí thuật Khô Nhãn Đại Pháp và Vọng Khí Thuật giúp ba tu sĩ Hợp Thể nhận ra hắn còn rất trẻ nhưng có pháp lực gần gấp đôi tu sĩ Hợp Thể sơ kỳ thông thường, nhiều thần thông lợi hại và thể phách có thể sánh với Yêu Vương. Thiên Nguyên Thánh Hoàng vì thế nhận định Hàn Lập có khả năng sánh vai với mình nếu vượt qua kỳ ma kiếp. Tới vùng phụ cận Cửu Tiên Sơn, Hàn Lập dùng truy tung linh ấn tìm ra động phủ của Điền Thanh Diệp và phá lớp huyễn thuật che giấu cửa vào. Điền Thanh Diệp dẫn Nhạc Hoa tiên tử, Bạch Hóa Cập, Hải Đại Thiếu và Khí Linh Tử ra nghênh tiếp, sau đó xác nhận Hàn Lập chính là tu sĩ mới tiến giai Hợp Thể tại Thiên Nguyên cảnh. Qua cuộc trò chuyện, Hàn Lập biết Điền Thanh Diệp là trưởng lão Kim Quảng Tông, Bạch Quả Nhi là huyết mạch duy nhất của Nhạc Hoa tiên tử, còn Bạch Hóa Cập từng định bán Thiên Niên Huyết Sâm để đổi linh dược chữa hàn độc cho con gái. Khi nghe tin hàn độc của Bạch Quả Nhi vừa phát tác, Hàn Lập yêu cầu lập tức tới gặp cô bé và tiết lộ rằng hơn nửa mục đích chuyến đi của mình là vì nàng."},{"chuong":1784,"tieuDe":"Băng Tủy Thân Thể","tomTat":"Nhạc Hoa tiên tử dẫn Hàn Lập vào phòng ngủ, nơi Bạch Quả Nhi đang hôn mê trên giường viêm mộc vì hàn khí phát tác. Hàn Lập dùng ngũ sắc hàn quang gom hàn khí về cổ tay, lấy một giọt tinh huyết bằng ngân châm rồi xác nhận hiện tượng bất thường khi giọt máu lập tức đông thành băng trên ngọc bàn. Hắn tạm thời làm hàn khí tiêu tán, giúp Bạch Quả Nhi tỉnh lại trong chốc lát trước khi để nàng tiếp tục ngủ dưỡng sức. Bạch Hóa Cập kể lại những chẩn đoán trước đây và giả thuyết con gái từng bị kẻ thù ám toán, nhưng Hàn Lập khẳng định hàn khí đã tồn tại từ khi nàng còn trong thai. Sau khi cân nhắc, hắn xác định Bạch Quả Nhi mang Băng Tủy Thân Thể, một linh thể thượng cổ thường phát tác lần đầu vào năm chín tuổi và có thể đe dọa trực tiếp tính mạng. Sư phụ của Nhạc Hoa tiên tử cho biết hàn khí sẽ mạnh dần, khiến người mang linh thể có nguy cơ chết vào khoảng mười lăm hoặc mười sáu tuổi nếu không được cứu chữa. Một tu sĩ trên Hợp Thể kỳ có thể hằng năm khu trừ hàn độc và tẩy tủy kinh mạch cho nàng tới khi qua trăm tuổi, nhưng người ra tay sẽ hao tổn lớn và có thể bị trì hoãn tu hành vài trăm năm. Nếu vượt qua được giai đoạn này, Bạch Quả Nhi có thể hoàn toàn thích ứng với hàn khí và tu luyện đại thần thông Băng Tủy Hàn Phách."},{"chuong":1785,"tieuDe":"Ký Danh Đệ Tử","tomTat":"Sau khi nghe phương án dùng đan dược chí dương kết hợp Thủy Hỏa Giao Tế có thể làm Bạch Quả Nhi mất linh căn, Nhạc Hoa tiên tử và Bạch Hóa Cập tiếp tục cầu xin Hàn Lập cứu con. Hàn Lập đồng ý giúp Quả Nhi tu thành Băng Tủy Hàn Phách, nhận nàng làm đệ tử ký danh trong một trăm năm và yêu cầu nàng về sau tìm một vật chỉ người tu luyện thần thông này mới cảm ứng được. Biết nàng phải đạt ít nhất Hóa Thần và chỉ tiến vào Man Hoang khi đủ sức tự bảo vệ, cha mẹ Quả Nhi chấp nhận giao ước. Hàn Lập giao Viêm Dương ngọc cùng Dưỡng Tinh Đan để ổn định thân thể và nguyên khí của đệ tử mới. Hải Đại Thiếu và Khí Linh Tử nhân cơ hội xin bái sư, nhưng Hàn Lập chỉ giữ họ bên mình trong kỳ Vạn Bảo đại hội để tiếp tục quan sát. Hắn vẫn ban cho mỗi người một bình đan dược, rồi dùng phi xa đưa cả hai rời đi. Trên đường tới Cửu Tiên Sơn, Hàn Lập khẳng định cấm chế tại đó chỉ ngăn tu sĩ bình thường và sẽ có người chủ động ra tiếp đón mình."},{"chuong":1786,"tieuDe":"Nghênh Tiên Cung","tomTat":"Hàn Lập đưa Hải Đại Thiếu và Khí Linh Tử vượt phường thị, tiến tới cấm địa Cửu Tiên Sơn nhưng bị biển mây lam ngăn đường. Hắn phóng hai tia chớp vàng kích động cấm chế, khiến một tiểu đội Lôi Vệ cưỡi quái thú ra kiểm tra. Sau khi biết Hàn Lập từng từ chối lời mời của Phách Hoàng cung, thủ lĩnh Lôi Vệ nhận ra hắn là tu sĩ Hợp Thể mới tiến cấp và cung kính dẫn đoàn vào núi. Trên đường, người này giới thiệu cách Nhân tộc và Yêu tộc phân chia chín ngọn núi, đồng thời cho biết Phi Tiên Phong sẽ đặt hội trường chính còn tám ngọn núi khác mở các phó hội trường. Hàn Lập còn biết đại hội có thể xuất hiện khách ngoại tộc và công khai đấu giá chí bảo dị tộc, dù nguồn tin chưa xác định chủng tộc cụ thể. Hắn ban mấy bình Bổ Nguyên Đan cho bốn Lôi Vệ để thưởng tin tức và yêu cầu họ tiếp tục hồi báo. Cuối cùng, đoàn tới Nghênh Tiên Cung, khu tiếp đãi dành cho tu sĩ Hợp Thể, và được biết Vạn Cốt chân nhân cùng môn hạ đã cư trú tại đây từ một tháng trước."},{"chuong":1787,"tieuDe":"Vạn Cốt Chân Nhân","tomTat":"Hàn Lập được nhóm Lôi Vệ cho biết Vạn Cốt chân nhân vốn là tán tu đã khai sáng Bạch Cốt môn, một trong những tông môn hàng đầu Huyền Vũ cảnh. Sau khi nhóm Lôi Vệ đưa ba người tới Nghênh Tiên Cung, Tổng quản Tông Miễn đích thân ra tiếp đón và cho Hàn Lập lựa chọn nơi tạm trú. Hàn Lập chọn tầng thứ năm, rồi cùng Hải Đại Thiếu và Khí Linh Tử thông qua pháp trận truyền tống tới không gian cư trú có cảnh vật do cấm chế huyễn hóa. Tông Miễn giao cho Hàn Lập lệnh bài duy nhất có thể khống chế cấm chế tầng này và dặn hắn hoàn trả sau đại hội. Sáng hôm sau, Vạn Cốt chân nhân dùng bạch diễm truyền âm xuyên qua cấm chế để mời Hàn Lập tới gặp. Hải Đại Thiếu và Khí Linh Tử nhân dịp xin ra ngoài thăm phường thị, được Hàn Lập dùng lệnh bài đưa đi trước khi hắn một mình lên bái phỏng Vạn Cốt chân nhân."},{"chuong":1788,"tieuDe":"Hắc Vực Trao Đổi Hội","tomTat":"Hàn Lập dùng lệnh bài màu bạc khởi động truyền tống pháp trận, đưa Hải Đại Thiếu và Khí Linh Tử xuống tầng thứ nhất rồi rời khỏi bình đài. Hắn tới cung điện của Vạn Cốt chân nhân, trò chuyện về hành trình Man hoang, tốc độ tiến cấp và mục tiêu tìm kiếm tài liệu luyện đan tại Vạn Bảo đại hội. Vạn Cốt chân nhân nhắc lại thời kỳ Nhân tộc thiếu tu sĩ Đại Thừa, từng suýt bị liên quân dị tộc tiêu diệt và chỉ vượt qua nhờ liên kết với Yêu tộc. Sau khi cho các thị thiếp lui ra, ông tiết lộ Hắc Vực trao đổi hội, một hội giao dịch bí mật chủ yếu dành cho tu sĩ Hợp Thể, không truy xét thân phận và chỉ lấy vật đổi vật. Hội có thể xuất hiện tài liệu yêu thú bị cấm, trứng linh thú cùng những giao dịch cưỡng ép tộc nhân trái với cấm lệnh giữa Nhân tộc và Yêu tộc, trong khi nhóm tổ chức đủ mạnh để giết tu sĩ Hợp Thể gây chuyện. Biết Hắc Vực là địa điểm có thể di chuyển và cách tiến vào sẽ được thông báo bí mật, Hàn Lập vì quan tâm tới tài liệu yêu thú nên nhận lời để Vạn Cốt chân nhân dẫn mình tham dự."},{"chuong":1789,"tieuDe":"Thiên Hồ Yêu Nữ","tomTat":"Vạn Cốt chân nhân tỏ ý muốn nhờ Hàn Lập giúp vài việc trong tương lai, cùng hắn trao đổi tâm đắc tu luyện rồi đích thân tiễn hắn rời đi qua truyền tống trận. Sau đó, lão bí mật gặp Hoa tiên tử, một Thiên Hồ yêu nữ từng giả làm thị thiếp để quan sát Hàn Lập. Hai người nhận định các tán tu Hợp Thể kỳ rất dễ bị Cổ Ma cao cấp lần lượt tiêu diệt khi Ma Kiếp bộc phát, vì vậy quyết định lợi dụng Vạn Bảo đại hội để vận động thành lập một nhóm tự vệ gồm cường giả hai tộc Nhân–Yêu. Vạn Cốt chân nhân bác bỏ phương án giải tán Bạch Cốt môn và nương nhờ Tam Hoàng hoặc Yêu Vương vì lo bị ước thúc hay biến thành pháo hôi. Hoa tiên tử nhận trách nhiệm thuyết phục Thiên Khôn Hắc Lang và các tán tu Yêu tộc, còn Vạn Cốt dự định vận động Thiên Âm lão tổ cùng những cường giả Nhân tộc có giao tình. Cuối cùng, Hoa tiên tử tiết lộ thần niệm Hàn Lập mạnh đến mức có thể đã nhìn thấu dung mạo ảo hóa của nàng, nhưng nàng vẫn tin bí thuật khóa chân nguyên đã che giấu được tu vi Hợp Thể kỳ."},{"chuong":1790,"tieuDe":"Tiên Tửu Cùng Động Thiên Thử Vương","tomTat":"Hoa tiên tử được hé lộ là người từng thoát ly Thiên Hồ nhất tộc, hút chân dương của nhiều thanh niên yêu tộc và sống sót sau cuộc truy sát của Thiên Hồ Vương. Sau khi bóng gió uy hiếp các hậu bối của Vạn Cốt chân nhân, nàng biến thành dung mạo sủng cơ của hắn rồi được truyền tống rời đi, khiến Hàn Lập càng nghi ngờ động cơ giao hảo của Vạn Cốt. Hàn Lập hoạch định việc tham gia Hắc Vực trao đổi hội, luyện Vô Cực Sơn thứ hai, bồi dưỡng Bạch Quả để tìm Hạo Âm Hàn Phách Sơn và đưa phân thân trở lại Nhân giới tìm Bắc Cực Viễn Sơn. Mục tiêu lâu dài của hắn là tập hợp đủ Nguyên Hợp Ngũ Cực Sơn để chống Đại Thiên kiếp, tranh thủ thời gian tiến vào Đại Thừa và cảnh giới cao hơn. Sau khi Hải Đại Thiếu cùng Khí Linh Tử trở về, Hàn Lập lấy vật liệu từ Thiên Nguyên Thánh Hoàng và bế quan chế hai bình Hồng La Tiên Tửu để tặng cùng bảy, tám bình khác dùng cho bản thân và giao dịch. Trong thời gian chờ Vạn Bảo đại hội, hắn kết giao với các tu sĩ cùng giai và nhờ Vạn Cốt tham dự một hội trao đổi cấp cao để đổi lấy một số vật liệu. Khi hơn nửa Nghênh Tiên Cung đã có khách, Động Thiên Thử Vương bí ẩn đến Cửu Tiên Sơn nhưng không gặp bất cứ ai; diện mạo và thần thông của vị Yêu Vương này vẫn là điều khó dò, còn những cao thủ từng đắc tội hắn đều đã lần lượt biến mất."},{"chuong":1791,"tieuDe":"Tham Linh","tomTat":"Hàn Lập từ bỏ ý định gặp Động Thiên Thử Vương, dành thời gian nghiên cứu linh căn có thể biến mất của Hải Đại Thiếu và chỉ điểm tu luyện cho hai hậu bối. Khi chấn động lan tới Nghênh Tiên Cung, hắn đưa Hải Đại Thiếu cùng Khí Linh Tử ra ngoài và nhìn thấy một cự thú giống lục địa sống đang mang thành trì cùng đại quân tiến vào Cửu Tiên Sơn. Hàn Lập sau đó phát hiện Liễu Thanh bí mật tiếp cận bằng một khôi lỗi hóa thân có thực lực không dưới Luyện Hư hậu kỳ. Liễu Thanh cho biết cự thú của Huyền Vũ Phách Hoàng có lẽ là hậu duệ dòng chính của Tham Linh, một cự quy mang huyết mạch chân linh Huyền Vũ và tinh thông thần thông thủy, thổ. Nàng kể Tham Linh có sức phòng ngự cực mạnh, thường ngủ sâu dưới bùn và cứ ba nghìn năm mới thôn thổ tinh hoa nhật nguyệt một lần. Cự thú cuối cùng dừng gần chỗ mọi người, nâng phần lưng cao như núi rồi thò chiếc đầu đầy sừng, vảy đen và hàm răng khổng lồ khỏi bùn đất."},{"chuong":1792,"tieuDe":"Khuyến Giới","tomTat":"Cự quy của Huyền Vũ Phách Hoàng thu đầu và tứ chi, hóa thành Hắc Sơn để Lôi Vệ cùng các giáp sĩ dựng nhiều tầng pháp trận, cấm chế và sương mù bảo vệ Hắc thành. Thiên Nguyên Thánh Hoàng cưỡi Kim Giao tới thăm, bỏ qua lời đáp thiếu khách khí của chủ nhân rồi trực tiếp vượt ảo trận tiến vào. Sau khi đám tu sĩ giải tán, Hàn Lập giao cấm chế lệnh bài cho Hải Đại Thiếu và Khí Linh Tử, sau đó theo Liễu Thanh tới tầng sáu Nghênh Tiên Cung gặp Diệp Dĩnh. Hàn Lập nhận ra Diệp Dĩnh đã đạt Luyện Hư sơ kỳ, còn nàng xác nhận Liễu Thanh đang luyện chế khôi lỗi mạnh để chuẩn bị tranh ngôi Linh Hoàng. Theo lời mẫu thân, Diệp Dĩnh khuyên Liễu Thanh từ bỏ ý định này vì cuộc tranh đoạt sau một trăm năm sẽ mang họa. Nàng tiếp đó tiết lộ Ma kiếp sẽ giáng xuống Linh giới trong vòng một nghìn năm, tin tức hiện chỉ được lưu truyền trong giới Hợp Thể. Hàn Lập nhờ vậy hiểu nguyên nhân nhiều thế lực từng ra sức chiêu dụ mình và bắt đầu nghi ngờ ngôi Linh Hoàng có liên quan trực tiếp tới đại kiếp sắp tới."},{"chuong":1793,"tieuDe":"Thảo Hồn Đan Cùng Niết Bàn Thánh Linh Đại","tomTat":"Diệp Dĩnh tiết lộ Mạc Giản Ly từng dùng Tinh Bàn tiến vào Ma giới điều tra, giao chiến với hai Cổ ma thánh tổ rồi trở về Linh giới trong tình trạng nguyên khí tổn thương. Những thông đạo Ma giới xuất hiện gần cây Kình Thiên Thông Linh khiến Mạc Giản Ly và Thánh Đảo quyết định biến Thiên Linh Thành thành chiến trường tiêu hao quân Ma tộc, buộc tân nhiệm Linh Hoàng phải tử thủ. Biết Ma kiếp lần này nguy hiểm vượt xa dự liệu, Hàn Lập và Liễu Thanh đều từ bỏ ý định tranh ngôi Linh Hoàng. Diệp Dĩnh thay mặt gia tộc mời hai người làm Thái Thượng Khách Khanh Trưởng Lão; Liễu Thanh ban đầu từ chối nhưng lập tức đổi ý sau khi nhận được một lời truyền âm liên quan đến nỗi tiếc nuối nhiều năm. Hàn Lập vẫn từ chối gia nhập, khiến Diệp Dĩnh đưa ra ba mươi viên Thảo Hồn Đan và cơ hội tiếp xúc Niết Bàn Thánh Linh Đại Pháp làm điều kiện chiêu mộ. Khi biết bí thuật này có thể cải biến thể chất và đạt hiệu quả gần với niết bàn trùng sinh, Hàn Lập nhận ra nó có thể bổ trợ cho Phạm Thánh Chân Ma Công nên bắt đầu động tâm. Phản ứng đỏ mặt của Diệp Dĩnh cùng tiếng cười của Liễu Thanh cho thấy phương thức phối hợp thi triển bí thuật giữa một nam và một nữ còn ẩn chứa nội tình chưa được nói rõ."},{"chuong":1794,"tieuDe":"Lo Lắng","tomTat":"Hàn Lập dứt khoát từ chối gia nhập Diệp gia dù Liễu Thanh gợi ý việc Diệp Dĩnh có thể hiệp trợ hắn tu luyện Niết Bàn Thánh Linh Đại Pháp nhờ Thiên Phượng Chân Huyết. Diệp Dĩnh chuyển sang mời hắn giúp Diệp gia tại Chân Linh đại điển, nhưng hắn cho biết đã nhận lời hỗ trợ Cốc gia cho Hiểu Phong tiên tử. Liễu Thanh tiếc nuối vì không chiêu mộ được tu sĩ trẻ đã tiến giai Hợp Thể, muốn dùng bản thể thử sức nhưng hiện chỉ có khôi lỗi hóa thân. Diệp Dĩnh tiết lộ tổ mẫu là Hợp Thể trung kỳ và Liễu Thanh từng được Thiên Diệu Linh Hoàng truyền thủ thuật luyện chế khôi lỗi. Trở về chỗ ở, Hàn Lập phân phó Hải Đại Thiếu rồi vào mật thất, thay đổi kế hoạch tu luyện với mục tiêu đạt Hợp Thể hậu kỳ trước Ma kiếp vì lo ngại Nguyên Sát Thánh Tổ có thể nhân cơ hội truy cứu. Hắn xác định bình cảnh là trở ngại lớn nhất, kỳ vọng vào Hư Linh Đan và Minh Hà Thần Nhũ của Thanh Nguyên Tử. Kiểm tra Đề Hồn Thú đang ngủ say trong Linh Thú hoàn, nhớ tới Ngân Nguyệt và thừa nhận tình cảm với nàng, rồi chủ động bình ổn tâm cảnh để chuyên tâm nghiên cứu Vạn Kiếm Đồ."},{"chuong":1795,"tieuDe":"Ẩn Linh Căn","tomTat":"Sau hơn mười ngày ở trong mật thất, Hàn Lập thu Vạn Kiếm Đồ rồi nhận kim sắc bái thiếp để chuẩn bị dự phiên đấu giá mở màn của Vạn Bảo đại hội trên Phi Tiên Phong. Hải Đại Thiếu và Khí Linh Tử báo rằng năm trong bảy đại Yêu vương đã đến, còn Thiên Khuê Lang Vương đang bế quan và Thiên Hồ Vương vắng mặt vì có việc quan trọng. Hàn Lập cho phép hai người đi cùng với thân phận môn nhân, sau đó chính thức nhận họ làm đệ tử ký danh và đặt điều kiện phải tiến giai Hóa Thần mới trở thành đệ tử chính thức. Hắn xác định Khí Linh Tử mang Truyền thừa Khí vật của Vụ Hải Quan, trong đó phong ấn công pháp bí thuật sẽ tự giải khi tu vi đạt yêu cầu, nên quyết định để hắn tiếp tục kế thừa Vụ Hải nhất mạch. Hải Đại Thiếu tiết lộ tên thật là Hải Nguyệt Thiên và được xác nhận có Dong Kim chi thể giúp tu luyện luyện thể thuật rất nhanh. Hàn Lập còn phát hiện hắn có một Lôi linh căn bị che giấu, gọi chính xác là Ẩn Lôi linh căn. Cuối cùng, Hàn Lập giải thích rằng Ẩn Linh Căn bị thể chất hoặc huyết mạch đặc thù che lấp, khó xác định thời điểm xuất hiện và chỉ khi hiện ra mới cho phép người sở hữu tu luyện pháp lực."},{"chuong":1796,"tieuDe":"Tử Sam Nữ Tử","tomTat":"Hàn Lập giải thích rằng Ẩn Lôi Linh căn tuy gây khó khăn cho việc tu luyện nhưng cho phép người sở hữu đi theo Lôi Đình chi đạo và có thể hỗ trợ chống lôi kiếp khi đạt cấp cao. Hắn nói rõ Hải Đại Thiếu được thu làm đệ tử vì thích hợp kế thừa công pháp pháp thể song tu, đồng thời có triển vọng trở thành trợ lực cho mình khi độ kiếp; Hải Đại Thiếu dùng tên Nguyệt Thiên và nghiêm túc cam kết sẽ toàn lực tương trợ. Sau đó, Hàn Lập dẫn Hải Đại Thiếu và Khí Linh Tử rời Nghênh Tiên Cung, bay tới Phi Tiên Phong giữa lúc Cửu Tiên Sơn tập trung đông đảo người của Nhân tộc và Yêu tộc. Một đội Lôi Vệ chặn ba người kiểm tra, nhưng lão giả cầm đầu nhanh chóng nhận ra thân phận Hàn Lập qua kim sắc thiệp mời rồi đích thân dẫn đường. Trên đỉnh Phi Tiên Phong, Hàn Lập nhìn thấy biển mây, cầu ngũ sắc và quần thể điện phủ có Vạn Bảo Đại Điện nằm ở trung tâm. Trước một lối vào yên tĩnh, hắn gặp Bành Quyết, hắc y phụ nhân và một tử sam nữ tử có khí chất thanh linh; thiếu nữ thoáng kinh hỉ, mắt hiện dị quang khi nhìn thấy hắn, còn phụ nhân cũng phản ứng khác thường. Bành Quyết tự giới thiệu là phó thành chủ Huyền Vũ thành, quản sự phụ trách phía Nhân tộc tại đại hội và chúc mừng Nhân tộc có thêm một Hợp Thể tu sĩ."},{"chuong":1797,"tieuDe":"Đại Nhi","tomTat":"Hàn Lập gặp Tiêu Quán, Hắc Phượng Vương có tu vi Hợp Thể hậu kỳ, và nghe bà giải thích chuyện Tiểu Hồng từng can dự vào mưu tính Thiên Phượng chân huyết của Diệp gia. Tiêu Quán cho biết Tiểu Hồng đã bị phạt diện bích một nghìn năm tại viêm vực, đồng thời cảm tạ Hàn Lập vì không khiến Hắc Phượng tộc trở mặt với Diệp gia. Khi nghe tên Đại Nhi, Hàn Lập nghi tử sam nữ tử đi cùng Tiêu Quán chính là nữ đồng Nhân–Yêu hỗn huyết năm xưa, nhưng chưa thể xác nhận do dung mạo nàng bị che giấu và nàng không tỏ dấu hiệu nhận ra hắn. Bành Quyết tiết lộ Đại Nhi mang danh Phượng Linh tiên tử, có tư chất nổi bật, huyết thống Nhân–Yêu và đang được Tiêu Quán dùng bổn mạng chân linh biến ảo khuôn mặt. Hàn Lập cùng Hải Đại Thiếu và Khí Linh Tử sau đó vào quý tân phòng tầng ba, nơi hắn nhận ra bốn ngân sắc phi kiếm bảo vệ đài là một bộ linh bảo có thể phối hợp với nhau. Khi khách thuộc Nhân tộc và Yêu tộc đã ổn định chỗ ngồi, Huyền Vũ Phách Hoàng cùng Ly Hỏa Giao Vương xuất hiện trên đài Bạch Ngọc và chính thức khai mạc cuộc đấu giá đầu tiên của Vạn Bảo Thiên Hội."},{"chuong":1798,"tieuDe":"Khấp Linh Huyết Mộc","tomTat":"Huyền Vũ Phách Hoàng và Ly Hỏa giao vương tuyên bố khai mạc đấu giá hội rồi giao vị trí chủ trì cho Thiên Nhãn Tử. Vật phẩm mở màn là Ngân Ti Tinh từ Bạch Bích Hạp Cốc, cuối cùng bị một yêu tu bí ẩn mua với giá bảy trăm ba mươi vạn linh thạch. Người này tiếp tục thâu tóm nhiều vật liệu luyện khí, khiến Hàn Lập dùng thần niệm nhìn xuyên áo da che giấu và nhận ra hắn là Hắc Lang Yêu Luyện Hư sơ kỳ. Khi Tinh Viêm Ti xuất hiện, Hàn Lập giải thích cho Hải Đại Thiếu và Khí Linh Tử về nguồn gốc cùng công dụng của linh tài hỏa thuộc tính này, nhưng nó vẫn bị Hắc Lang Yêu mua với giá cao. Thiên Nhãn Tử sau đó đưa Khấp Linh Huyết Mộc ra đấu giá, khiến nhiều tu sĩ và các tồn tại Hợp Thể kỳ tại tầng ba chú ý. Hàn Lập nhận ra linh vật là tàn khu của Linh Tộc Nhân mộc thuộc tính biến dị và đặc biệt quan tâm khả năng dùng nó luyện hóa kiếp khôi lỗi. Loại dị bảo này có thể thế kiếp cho tu sĩ Hợp Thể nhưng chỉ dùng được một lần và phải được kích phát đúng thời điểm."},{"chuong":1799,"tieuDe":"Lang Vương Hóa Thân","tomTat":"Thiên Nhãn Tử đưa Khấp Linh Huyết Mộc ra đấu giá và dùng pháp lực kích phát những đặc tính kỳ dị của vật liệu để chứng minh đây là hàng thật. Giá nhanh chóng tăng cao vì Huyết Mộc có thể dùng luyện chế hóa kiếp khôi lỗi, một thủ đoạn bảo mệnh đặc biệt hữu dụng khi Ma kiếp đang đến gần. Một người Hắc lang Yêu tộc trả giá lớn rồi bị Hắc Phượng Vương nhận ra là hóa thân của Thiên Khuê Lang Vương, qua đó làm lộ công dụng đặc biệt của ngũ đại hóa thân. Động Thiên Thử Vương nhập cuộc, tranh giá với hóa thân Lang Vương và cùng đối phương nhắc lại lần giao thủ bằng Thiên Lang trảo cùng Động Thiên Toản. Hàn Lập bất ngờ nâng giá lên sáu ngàn bảy trăm vạn linh thạch, khiến Động Thiên Thử Vương dừng lại và giúp hắn chính thức giành được Khấp Linh Huyết Mộc. Dù mất gần nửa số linh thạch, Hàn Lập không hối tiếc, đồng thời ngừng tích cực tranh các vật phẩm kế tiếp để dành sự chú ý cho tài liệu yêu thú tại Hắc Vực trao đổi hội."},{"chuong":1800,"tieuDe":"Vạn Sâm Pháp Bàn Cùng Kình Thiên Cự Thuyền","tomTat":"Đại hội đấu giá tiếp tục với nhiều linh dược, đan dược, công pháp và pháp bảo quý hiếm, trong đó Hàn Lập từ bỏ ý định mua linh dược của Linh tộc vì cho rằng bình nhỏ thần bí không thể thúc chín chúng. Hơn mười bình Húc Nhật Đan, truyền thừa của một tu sĩ Hợp Thể và Chiến Ngẫu khổng lồ lần lượt đẩy không khí lên cao trào. Thiên Nhãn Tử sau đó nhường quyền chủ trì hai món cuối cho Ly Hỏa giao vương và chủ nhân bảo vật. Thiên Thu thánh nữ xuất hiện với tư cách đại diện Khí Linh tộc, tuyên bố mang Vạn Sâm luân bàn cùng bản vẽ Kình Thiên chiến thuyền tới đấu giá và dùng tiền thu được để biểu thị thành ý với Nhân Yêu lưỡng tộc. Nàng giới thiệu Vạn Sâm luân bàn là Thông Thiên linh bảo có thể thi triển tám mươi mốt loại huyễn thuật rồi trực tiếp biểu diễn một huyễn cảnh hoa cỏ trong đại điện. Bản vẽ Kình Thiên chiến thuyền cũng được công bố với khả năng chế tạo chiến thuyền chở hơn nghìn người và tăng mạnh chiến lực tập thể, dù chi phí tài nguyên cực lớn. Ly Hỏa giao vương mở đấu giá Vạn Sâm luân bàn ở mức tám mươi triệu linh thạch, nhưng các tu sĩ Hợp Thể trên tầng ba vẫn im lặng dò xét và chưa ai ra giá trước."},{"chuong":1801,"tieuDe":"Lời Mời Của Vạn Cốt","tomTat":"Sau khi Vạn Bảo đại hội kết thúc, Hàn Lập cùng Hải Đại Thiếu và Khí Linh Tử rời Phi Tiên Phong, đồng thời biết Vạn Sâm luân bàn đã thuộc về Tiêu Quán còn Lũng gia giành được bản vẽ Kình Thiên chiến thuyền. Hắn đánh giá Lũng gia lão tổ là tu sĩ Hợp Thể hậu kỳ đại thành có thực lực sâu khó dò, nhưng bớt lo ngại nhờ quan hệ với Cốc gia, Diệp gia và tu vi hiện tại của bản thân. Vạn Cốt chân nhân đuổi theo, tặng Hàn Lập Khiên Dẫn lệnh để tham dự Hắc Vực đại hội rồi mời hắn dự cuộc tụ hội tán tu Nhân–Yêu nhằm bàn cách ứng phó Ma kiếp. Hàn Lập nhận lời, sau đó giao nửa miếng ngọc bài cho hai đệ tử và sai họ đi tìm một nữ tử Yêu tộc. Trở lại Nghênh Tiên cung, hắn kiểm tra Khấp Linh Huyết Mộc, xác nhận đã đủ tài liệu phụ trợ và quyết định sớm luyện Hóa kiếp khôi lỗi. Sáng hôm sau, Hải Đại Thiếu một mình hốt hoảng trở về, báo rằng Khí Linh Tử đã xảy ra chuyện."},{"chuong":1802,"tieuDe":"Phụ Tâm Ti","tomTat":"Hải Đại Thiếu trở về Nghênh Tiên Cung cầu cứu Hàn Lập, thuật lại việc Khí Linh Tử bị một phụ nhân tóc dài xám trắng bắt đi còn mình bị đánh ngất. Hàn Lập kiểm tra đồ đệ và phát hiện Phụ Tâm Ti ẩn trong cơ thể, một loại yêu trùng có thể phóng nhiệt độc công tâm vào giờ Ngọ rồi quay về với chủ nhân. Hắn cưỡng ép kéo yêu trùng ra và dùng ngân diễm thiêu thành tro, khiến lão phụ nhân đang ẩn ngoài Cửu Tiên Sơn lập tức chịu phản phệ. Qua thủ đoạn này, Hàn Lập nhận ra đối phương muốn xác minh Hải Đại Thiếu có Hợp Thể tu sĩ chống lưng hay không. Ở nơi ẩn náu, lão phụ nhân xác nhận trong cơ thể Khí Linh Tử có một bảo châu truyền thừa và vẫn quyết chuyển linh lực cùng bí thuật bên trong sang con trai là Danh nhi. Mụ tiết lộ mình là con gái ruột của Lũng gia lão tổ và định dùng khả năng kích phát Chân Long chi huyết của Danh nhi để đổi lấy sự coi trọng cùng che chở từ Lũng gia. Hắc mi lão giả ban đầu lo con trai sẽ bị Lũng gia giữ lại, nhưng cuối cùng đồng ý đưa Danh nhi tới Nghênh Tiên Cung vì tương lai của con."},{"chuong":1803,"tieuDe":"Truy Địch","tomTat":"Lão phụ yêu cầu Danh nhi lập tức tới chỗ Lũng gia trong Nghênh Tiên cung và tiết lộ kế hoạch chuyển truyền thừa pháp khí của Khí Linh Tử sang con để chữa ác tật, trợ giúp kết thành Kim Đan. Nhờ một phần Thiên Nhĩ thần thông, Danh nhi đã nghe được cuộc bàn bạc của cha mẹ và cảnh báo rằng tu sĩ Hợp Thể có thể bí mật để lại tiêu ký thần niệm, khiến cả nhà quyết định lên đường ngay. Hắc mi lão giả dùng phù lục đen cùng chuông đồng màu xanh khống chế Khí Linh Tử như khôi lỗi rồi đưa tiểu đạo sĩ rời khỏi động phủ. Hàn Lập và Hải Đại Thiếu tới nơi sau đó, chờ tiêu ký thần niệm bí mật trong cơ thể đệ tử phản ứng mạnh rồi lần theo dấu vết về phía Cửu Tiên Sơn. Ba canh giờ sau, họ tới một tòa Nghênh Tiên cung và xác nhận Khí Linh Tử đang bị giữ tại tầng thứ chín. Nghi ngờ đối phương có quan hệ với một tu sĩ Hợp Thể, Hàn Lập không lập tức xông vào mà sai Hải Đại Thiếu dò hỏi thân phận chủ nhân tầng này. Hải Đại Thiếu xuống đất, nhìn qua Nghênh Tiên cung rồi đi tới khu vực náo nhiệt gần nhất để thu thập tin tức."},{"chuong":1804,"tieuDe":"Xâm Nhập","tomTat":"Hải Đại Thiếu dò hỏi tại phường thị và báo cho Hàn Lập biết tầng chín Nghênh Tiên cung là khu vực của Lũng gia, nơi tập trung lão tổ, gia chủ cùng nhiều trưởng lão. Vì quan hệ với Lũng gia không tốt, Hàn Lập từ bỏ phương án công khai đòi Khí Linh Tử và quyết định bí mật xâm nhập. Hắn kết hợp Thiên Biến Huyễn Diện với da Kim Tí Viên để cải trang, đồng thời dùng hai khăn sa màu đen che giấu thân hình. Hàn Lập lần lượt dùng hồ quang kim sắc và hỏa diễm bạc vượt qua các lớp cấm chế, trong khi hai vệ sĩ Hóa Thần kỳ phát hiện dao động nhưng không dám truy xét sâu. Khi gặp cấm chế không gian trên vách tầng chín, hắn mở yêu mục trên trán, phóng ô quang làm tan phù văn bạc và tạo lỗ hổng để tiến vào. Trong khu rừng phía sau vách cấm chế, Hàn Lập đánh ngất hai đệ tử Lũng gia rồi thi triển Sưu Hồn thuật. Qua đó, hắn xác nhận Khí Linh Tử đã bị đưa tới Lũng gia, nhưng vẫn chưa tìm được vị trí cụ thể vì thần niệm của hai đệ tử đã được bí mật bảo vệ."},{"chuong":1805,"tieuDe":"Một Trảo, Một Quyền, Một Chưởng","tomTat":"Hàn Lập chỉ lấy được từ thần thức đôi nam nữ manh mối rằng Khí Linh Tử đã bị đưa tới Lũng gia, sau đó chôn giấu họ và dùng mây xám xuyên qua cấm chế sương mù để bí mật vào thành. Cảm ứng với Khí Linh Tử bị Nguyệt Kết Tâm Ngọc cắt đứt, buộc hắn phải lần lượt dò xét từng kiến trúc trong khi tránh khu vực kim tháp có Lũng gia lão tổ và nhiều cao thủ. Trong một lầu các, tử bào lão giả đồng ý tạm thu lưu gia đình em gái vì Danh nhi đã kích phát Chân Long chi huyết, nhưng cấm họ xử lý Khí Linh Tử trước khi phụ thân xuất quan. Ông cũng tuyên bố lão phụ không còn được coi là người Lũng gia do từng trái lệnh lấy người ngoài tộc, chỉ cho phép Danh nhi ở lại. Bất chấp lời cảnh cáo, cha mẹ Danh nhi vẫn định đưa Khí Linh Tử xuống mật thất để mưu lấy truyền thừa cho con. Hàn Lập xuất hiện đúng lúc, dùng Kim Mao đại thủ phá cự chung bảo vệ Khí Linh Tử, đánh văng hắc mi lão giả rồi xé tan phòng hộ và bóp cổ lão phụ trước khi mụ kịp phát tín hiệu cảnh báo."},{"chuong":1806,"tieuDe":"Cự Viên Chiến Lão Tổ","tomTat":"Một yêu tu hiện hình thành Kim Mao Cự Viên, đánh trọng thương người cản đường và khống chế lão phụ nhân để bắt Khí Linh Tử ngay trong trụ sở Lũng gia. Lũng gia lão tổ dùng Tử sắc Cự Thủ phá cấm chế cứu người, nhưng Cự Viên nhân lúc giao thủ chộp lấy Khí Linh Tử rồi chạy ra ngoài thành. Hai cường giả truy đuổi tới biển sương trắng và giao chiến ngang sức, khiến các tu sĩ Lũng gia không dám xen vào. Thiên Thu thánh nữ đề nghị tách đôi bên nhưng từ chối giúp bắt Cự Viên vì không muốn vô cớ đắc tội một đại năng. Lũng gia lão tổ kích phát hơn nửa long thân để đối đầu Cự Viên cao hơn ba mươi trượng, song vẫn không thể áp đảo đối phương. Kim Mao Cự Viên không tiết lộ thân phận, dùng ngân diễm hòa tan hư không rồi mang Khí Linh Tử rời đi. Sau trận chiến, Lũng gia gia chủ thừa nhận cuộc truy bắt có liên quan tới Lệ nương và cho biết bản thân không ngờ đối phương lại tới nhanh như vậy."},{"chuong":1807,"tieuDe":"Thánh Đảo","tomTat":"Lũng gia gia chủ báo tin Lệ Nương trở về rồi tuân lệnh lão tổ dẫn các tu sĩ rút đi. Lũng gia lão tổ thu hồi nửa Long thân và cùng Thiên Thu Thánh nữ phân tích lai lịch Kim mao Cự viên, từ sức chiến đấu, ngân sắc hỏa diễm đến khả năng thuộc Kim Cương Yêu Viên nhất tộc bảo hộ Thánh đảo. Vì không chắc có thể bắt sống đối phương và không muốn mạo hiểm đắc tội Thánh đảo, lão tổ quyết định điều tra trước. Sau cuộc thương lượng kéo dài, Lũng gia và Linh tộc thống nhất dùng bảy phế linh đổi mỗi Chiến Chu, đồng thời Linh tộc được nhận bốn thành sản lượng Kình Thiên Cự thuyền để chuẩn bị cho Ma kiếp. Trong khi đó, Kim mao Cự viên dùng ngân sắc hỏa diễm xuyên thủng cấm chế Tiên cung và thoát khỏi các thủ vệ nhờ độn tốc quỷ dị. Tin một yêu tu Hợp Thể đại náo Lũng gia nhanh chóng lan đến nhiều lão quái Hợp Thể, khiến họ phái người điều tra và liên tưởng tới Thánh đảo. Sau khi rời xa hơn ngàn dặm, Cự viên đáp xuống một đỉnh núi rồi hóa thành một thanh niên có khuôn mặt bình thường."},{"chuong":1808,"tieuDe":"Mê Thiên Lâu","tomTat":"Sau khi dùng Thiên Biến Huyễn Diện và Kinh Chập Quyết giao thủ với Lũng gia lão tổ, Hàn Lập thuận lợi thoát khỏi phạm vi truy đuổi rồi trở lại chân thân. Hắn ép luồng hắc khí ra khỏi cơ thể Khí Linh Tử, giúp đệ tử tỉnh lại nhưng không thể nhớ những việc xảy ra trong thời gian bị khống chế. Trước sự phẫn nộ của Khí Linh Tử, Hàn Lập ngăn hắn báo thù và quyết định cho hắn cùng Hải Đại Thiếu gia nhập vệ binh Thiên Uyên thành để lánh nạn và rèn luyện. Hải Đại Thiếu báo rằng hai người đã dùng tín vật gặp một tiền bối Yêu tộc, người hẹn Hàn Lập tới Mê Thiên Lâu vào trưa hôm sau. Hàn Lập bố trí một ảo trận bảo vệ chỗ ở rồi tới hiệu buôn ngầm chuyên cung cấp Mê Thiên thạch tại phường thị Cửu Tiên Sơn. Tại đây, Mị Linh tự nhận là em gái song sinh của Tố Nhi và dẫn hắn xuống gặp một nữ tử áo trắng có dung nhan vô cùng quen thuộc, khiến hắn kinh ngạc gọi nàng là Uyển Nhi."},{"chuong":1809,"tieuDe":"Tần Thị Tỷ Muội","tomTat":"Hàn Lập nhìn thấu nữ tử mang dung mạo Nam Cung Uyển chỉ là hình ảnh do Tâm Huyễn đại pháp tạo ra, khiến đối phương thu hồi huyễn hóa và tự nhận là Tần Tố Nhi của Thiên Hồ Tộc. Hắn còn nhận ra các pháp trận trong điếm có khả năng tăng mạnh uy lực của huyễn thuật và mê mị thuật, làm sự khinh thị còn sót lại của Tần Tố Nhi hoàn toàn tiêu tan. Theo yêu cầu của tỷ tỷ, Mị Linh lấy Tiểu Di Châu đã luyện hóa trong cơ thể ra, giao cho Hàn Lập hơn phân nửa số tài liệu yêu thú hắn cần và nhận lại Vạn Niên Linh Dược. Trước nguy cơ Ma Kiếp sắp giáng xuống, Hàn Lập đề nghị duy trì việc đổi linh dược lấy vật phẩm đặc biệt của yêu tộc và được Tần Tố Nhi chấp thuận. Sau khi hắn rời đi, Tần Tố Nhi tiết lộ rằng nàng đã giữ lại một bảo vật nguy hiểm để thử trao đổi tại Hắc Vực đại hội, bất chấp cảnh báo về họa sát thân của Mị Linh. Nhờ số nguyên liệu vừa nhận, Hàn Lập chỉ còn thiếu hai ba loại vật phẩm để luyện chế tòa Cực Sơn thứ hai, nhưng khi trở về hắn chưa biết một vị khách ngoài dự liệu đã tìm tới cửa."},{"chuong":1810,"tieuDe":"Ngỡ Gặp Người Xưa","tomTat":"Hàn Lập gặp riêng tử sam thiếu nữ và nhận ra nàng chính là Đại Nhi nhờ chiếc khăn quyên hắn từng tặng khi nàng còn nhỏ. Đại Nhi tháo phượng trâm, để lộ dung mạo giống Nam Cung Uyển đến bảy tám phần, còn Hàn Lập dùng Minh Thanh Linh Mục xác nhận đó không phải huyễn thuật. Nàng giải thích hình ảnh Nam Cung Uyển từng in sâu trong ký ức có thể đã ảnh hưởng đến dung mạo của mình khi kích phát Hắc Phượng chi huyết và hóa hình. Đại Nhi cũng nói rõ lần gặp trước cố tình lạnh nhạt vì không muốn sự khác biệt giữa người và yêu mang lại phiền toái cho Hàn Lập. Sau khi nàng rời đi, những dấu hiệu liên tiếp liên quan đến Nam Cung Uyển khiến Hàn Lập bất an và nghi nàng đã gặp chuyện. Hắn gọi Hải Đại Thiếu cùng Khí Linh Tử đến phòng, rồi sáng hôm sau lặng lẽ rời chỗ ở. Tại một ngọn núi nhỏ gần Nghênh Tiên Cung, Hàn Lập hội hợp với Vạn Cốt Chân Nhân và chuẩn bị nghe những điều cần lưu ý trước khi tiến vào Hắc Vực đại hội."},{"chuong":1811,"tieuDe":"Khiên Dẫn Sứ Giả Cùng Vào Cửa","tomTat":"Vạn Cốt chân nhân giải thích cho Hàn Lập những điều cần kiêng kị tại Hắc Vực đại hội và khuyên hắn che giấu chân diện trước khi vào. Hàn Lập dùng Nguyên Từ Thần Quang bao phủ cơ thể, còn lão đạo dùng hắc khí ẩn giấu hình dáng rồi dẫn hắn tới một sơn cốc hoang vắng ngoài Cửu Tiên Sơn. Tại đây, họ gặp Kim quang nhân, một nữ tu có thân ảnh như sương khói và một lão giả được lục quang bao quanh. Khi năm tấm Khiên Dẫn Lệnh đồng loạt phát sáng, mây đen cùng hồ quang bạc ngưng tụ thành một cánh cửa khổng lồ trên không trung. Hắc bào nhân tự xưng Khiên Dẫn sứ giả bước ra, cảnh cáo rằng chỉ người có lệnh mới được vào Hắc Vực rồi dùng dùi trống bạc mở cửa. Năm tấm lệnh hóa thành hắc quang, lần lượt đưa những người tham dự qua cửa trước khi sứ giả theo vào và cánh cửa biến mất. Phía sau cửa là một không gian đầy sương đen, những cơn lốc dữ dội và vô số yêu thú kỳ dị mang khí tức bạo ngược nhưng chưa dám tới gần."},{"chuong":1812,"tieuDe":"Hắc Sa Thị Nữ","tomTat":"Hắc bào nhân dùng hắc quang kéo Hàn Lập cùng bốn tu sĩ khác xuyên qua biển hắc khí để tiến sâu vào Hắc Vực. Trên đường, Hàn Lập vận dụng Linh Mục và phát hiện một cự thú giống Giao Mãng có khí tức đủ uy hiếp tu sĩ Hợp Thể, khiến sứ giả phải đổi hướng tránh né. Cả đoàn hạ xuống hơn mấy vạn trượng rồi tiến vào một không gian bí mật có quang cầu lam sắc, rừng cột đá đen và quần thể kiến trúc mang phong cách thượng cổ. Tại quảng trường trước Hắc Vực đại điện, đội hắc sa thị nữ tiếp đón và phân người phục vụ từng vị khách; nữ tu thân như làn khói nhẹ cùng lão giả trong lục quang đi thẳng vào điện, còn Vạn Cốt chân nhân và kim quang nhân chọn thị nữ bầu bạn. Hàn Lập chọn thị nữ số Mười một làm người dẫn đường, sau đó dùng thanh hà thay đổi phương thức che giấu thân phận đến mức Vạn Cốt chân nhân cũng không thể nhận ra. Khi vào hội trường có hàng trăm thạch đình lơ lửng quanh ngọc đài trung tâm, hắn quan sát pháp trận cùng hai bàn đá đen trắng rồi hỏi về số kỳ trân mà Hắc Vực sẽ đưa ra trao đổi trước khi đại hội chính thức bắt đầu."},{"chuong":1813,"tieuDe":"Hắc La","tomTat":"Hàn Lập hỏi thị nữ số mười một về nội tình Hắc Vực đại hội và biết nơi này sở hữu tài phú có thể so sánh với Tam Hoàng Thất Vương, đồng thời thu nhận nhiều kỳ trân từ các dị tộc Man Hoang. Nữ thị xin làm thị thiếp nhưng bị hắn từ chối, sau đó tiếp tục ở lại hầu hạ và giải đáp các câu hỏi. Trước cửa đại điện, một hồng bào yêu tu nổi giận định giết thị nữ số ba mươi bảy, song hư ảnh áo xám đeo mặt nạ ác quỷ kịp xuất kiếm ngăn cản và hòa giải. Khi khách tham dự đã tập trung gần đủ, một lực sĩ da xanh xuất hiện trên đài ngọc cùng chiếc cự la màu đen. Lực sĩ phình lớn thành cự hán rồi gõ chiêng một lần, sau đó suy kiệt thành lão giả gầy đét vì dường như đã hao sạch máu huyết cùng lượng lớn thọ nguyên. Tiếng chiêng khiến linh lực và máu huyết trong cơ thể Hàn Lập sôi trào, nhưng sau khi dùng chân nguyên trấn áp, hắn phát hiện pháp lực của mình đã tăng thêm một phần."},{"chuong":1814,"tieuDe":"Tề Thiên La","tomTat":"Tiếng vang từ cự la màu đen làm pháp lực của các tu sĩ hiện diện tăng lên, nhưng mức hưởng lợi giảm dần theo cảnh giới. Kim Diện Nhân xuất hiện và công bố cự la là Tề Thiên La, bảo vật áp trục đầu tiên được Hắc Vực đưa ra giao dịch. Hắn phủ nhận đây là Huyền Thiên chi bảo, đồng thời tiết lộ nó là trấn tộc chi bảo hư tổn của một dị tộc man hoang đã tuyệt diệt và vốn ghép bộ với Chấn Thiên Chùy. Chính phẩm Chấn Thiên Chùy đã thất lạc, còn bản phỏng chế do Hắc Vực chế tạo chỉ phát huy được một phần mười công hiệu. Tề Thiên La có thể tăng pháp lực cho tu sĩ từ Hóa Thần kỳ trở lên tối đa ba lần, nhưng người gõ phải tu luyện công pháp luyện thể chuyên biệt và chịu phản phệ tinh huyết cùng thọ nguyên. Hàn Lập nhận thấy bảo vật không đem lại nhiều lợi ích cho mình nên từ bỏ ý định tranh đoạt, dù vẫn chú ý đến công pháp của dị tộc. Cuối cùng, Kim Diện Nhân công bố Hắc Vực chấp nhận bảo vật, cực phẩm linh thạch hoặc linh dược lâu năm và đưa ra danh sách hơn trăm tài nguyên quý hiếm cần thu mua."},{"chuong":1815,"tieuDe":"Âm Phượng Thảo","tomTat":"Tại hội trao đổi Hắc Vực, một nữ tu muốn dùng Tuyết Linh Mộc dài một trượng cộng linh thạch để đổi Tề Thiên La nhưng bị từ chối vì vật liệu phải đủ ba trượng. Chủ nhân Bạch hạc tiếp tục đưa ra một vật phẩm có giá trị lớn, song món này cần hơn vạn năm bồi dưỡng nên cũng không phù hợp với nhu cầu của Hắc Vực trước đại kiếp nạn. Khi Kim Diện Nhân chuẩn bị chuyển Tề Thiên La sang đấu giá bằng cực phẩm linh thạch và linh dược lâu năm, Hàn Lập lên tiếng ngăn lại rồi dùng Bạch xà khôi lỗi đưa một gốc Âm Phượng Thảo tới đài. Linh thảo có nguồn gốc từ dược viên trong di chỉ Quảng Hàn Giới và được Kim Diện Nhân xác nhận có dược tính vượt hai mươi vạn năm. Hàn Lập cho rằng giá trị ấy cao hơn một kiện Tề Thiên La nên yêu cầu Hắc Vực thể hiện thêm thành ý, nếu không hắn sẽ giữ linh thảo để giao dịch với người khác. Sau khi thương lượng nội bộ, Hắc Vực đồng ý bổ sung đúng một bảo vật áp trục do họ tự chọn và hứa bồi thường thêm linh thạch nếu món thứ hai không khiến Hàn Lập hài lòng."},{"chuong":1816,"tieuDe":"Vật Phẩm Trong Túi","tomTat":"Hàn Lập đồng ý xem món trao đổi thứ hai do Kim Diện Nhân đưa ra vì vẫn đặc biệt quan tâm tới phương pháp luyện thể đi kèm Tề Thiên La. Trong túi kim sắc, hắn phát hiện phôi thai của một kỳ bảo thiên địa có khả năng phụ trợ tu luyện sau khi hoàn thiện, nhưng quá trình luyện chế gần như bất khả thi. Sau khi cân nhắc Ma Kiếp sắp tới và lợi ích lâu dài, Hàn Lập vẫn dùng Âm Phượng Thảo đổi lấy Tề Thiên La cùng phôi thai kỳ bảo. Hắc Vực sau đó tổ chức ba đợt trao đổi tài liệu luyện khí, luyện đan khan hiếm, khiến bầu không khí trong hội trường trở nên sôi động. Một thần bí nhân trùm tử bào dùng Huyền Quang Thiết đổi lấy nhóm bảy nữ tu có thể chất thích hợp làm song tu đỉnh lô. Cuối cùng, hoàng sắc Cổ phiên do đại năng Nhân tộc thời cổ để lại được đổi cho thần bí nhân trong huyết vụ, người còn buộc Hắc Vực bù thêm lượng lớn linh thạch và vì thế khiến Hàn Lập đặc biệt chú ý."},{"chuong":1817,"tieuDe":"Lại Thấy Ô Kim","tomTat":"Kim Diện Nhân tiếp tục đưa các vật phẩm đặc biệt của Mộc tộc và Linh tộc ra trao đổi, cuối cùng dùng Di Hải Phiến làm bảo vật áp trục và đổi nó cho một người trả nhiều tinh thạch quý hiếm cùng vài món bất phàm. Khi phần giao dịch của Hắc Vực kết thúc, hắn tuyên bố mở trao đổi tự do với giới hạn ba người lên đài trong mỗi lượt. Chúc huynh, Hôi bào nhân và một nữ tu ẩn trong ngũ sắc quang hà giành được ba vị trí đầu tiên. Chúc huynh đưa ba đạo Kim Ô chân hỏa ra đổi Kim Cốt Chi hoặc Mạch Thảo trên hai vạn năm, khiến Hàn Lập động tâm vì nghĩ tới khả năng tăng cường Phệ Linh chân hỏa. Tuy nhiên, Hàn Lập dùng linh mục nhận ra chúng chỉ là chân hỏa còn nhạt, còn những người khác cũng không thể đáp ứng điều kiện trao đổi. Hôi bào nhân đổi thành công Tam sắc Liên hoa, nữ tu đổi thành công trứng Huyết Diễm Ưng, trong khi Chúc huynh phải thu lại ba đạo chân hỏa rồi rời đài."},{"chuong":1818,"tieuDe":"Nghiệt Vân Cùng Tịnh Minh Đan","tomTat":"Trước nguy cơ Ma kiếp, phần lớn khách tham dự Hắc Vực đại hội ưu tiên dùng tài liệu quý đổi lấy bảo vật thành phẩm có thể sử dụng ngay. Hàn Lập đổi được một bộ trận kỳ uy lực lớn, hơn mười loại mầm linh dược và toàn bộ tài liệu yêu thú còn thiếu để chuẩn bị luyện chế tòa Cực sơn thứ hai. Một thân ảnh trong hắc khí sau đó mang ra Nghiệt Vân ngưng tụ từ ngàn vạn thú hồn và chỉ chấp nhận Thông Thiên Linh Bảo công kích có tên trên Hỗn Độn Vạn Linh Bảng. Người này mở chiếc bát, thả một phần thú hồn để chứng minh đặc tính của cấm vật nhưng vẫn từ chối mọi đề nghị không đúng điều kiện. Nhân ảnh cao gầy trong huyết quang đưa Tịnh Minh Đan có khả năng hỗ trợ đột phá bình cảnh Hợp Thể kỳ ra trao đổi, khiến các lão quái Hợp Thể náo động, song chủ nhân Nghiệt Vân vẫn không đồng ý. Giao dịch rơi vào bế tắc vì không ai muốn bỏ ra một Thông Thiên Linh Bảo phù hợp để đổi Nghiệt Vân trước. Khi người trong hắc khí định rời thạch đài, nhân ảnh cao gầy bay tới cản đường, khiến đối phương nổi giận và tỏa ra khí tức băng hàn."},{"chuong":1819,"tieuDe":"Ba Đổi Một","tomTat":"Nhân ảnh cao gầy trong huyết quang ngăn chủ nhân Nghiệt Vân rời đi vì vật này liên quan trực tiếp đến khả năng sống sót qua Đại thiên kiếp sắp tới của hắn. Chủ nhân Nghiệt Vân chấp nhận chờ thêm nhưng kiên quyết chỉ đổi lấy một Thông thiên Linh bảo công kích có tên trên Vạn Linh Bảng. Để nâng giá, Nhân ảnh cao gầy trong huyết quang lần lượt đưa ra Tịnh Minh đan, Quyển trục vô danh còn nguyên phong ấn Kim Triện văn và Băng Phượng đang bị giam trong Băng Thiết Lung. Hàn Lập nhận ra Băng Phượng nên đưa Huyền Quang Nhận ra tham gia giao dịch, còn chủ nhân Nghiệt Vân xác nhận đây là Linh bảo phù hợp yêu cầu. Cuộc trao đổi ba bên hoàn tất khi chủ nhân Nghiệt Vân nhận Huyền Quang Nhận, Nhân ảnh cao gầy trong huyết quang nhận Nghiệt Vân, còn Hàn Lập thu Tịnh Minh đan, Quyển trục và Băng Phượng. Gần nửa ngày sau, Kim Diện Nhân tuyên bố đại hội trao đổi kết thúc; Hàn Lập từ chối dự tiệc, rời không gian Hắc Vực và lập tức trở về Cửu Tiên Sơn."},{"chuong":1820,"tieuDe":"Hội Cố Nhân","tomTat":"Sau Hắc Vực đại hội, Hàn Lập trở về Cửu Tiên Sơn, hỏi Hải Đại Thiếu cùng một ký danh đệ tử khác và xác nhận chỗ ở vẫn bình an. Trong mật thất, hắn lấy Linh Thú Hoàn màu lam ra và phóng xuất chiếc lồng băng đang giam Băng Phượng, cố nhân từng cùng hắn vượt không gian tiết điểm từ Nhân giới. Hàn Lập tháo phù lục, mở lồng, dùng linh lực kỳ hàn phá tan cấm chế trong cơ thể nàng rồi truyền chân nguyên giúp nàng tạm thời khôi phục hình người. Băng Phượng kể rằng sau khi hai người chia lìa, nàng mất gần trăm năm luyện hóa cấm chế cũ, lại bị đệ tử đích hệ Hắc Phượng tộc đánh trọng thương nên phải dùng bí thuật đào thoát và liên tiếp rơi cảnh giới. Một ma tu Hợp Thể từng cứu nàng nhưng sau đó muốn ép nàng làm linh thú, rồi phong ấn và nhốt nàng trong lồng băng khi nàng từ chối. Vì không thể nương nhờ Hắc Phượng tộc, pháp lực chưa phục hồi và băng phượng chi thể dễ dẫn tới tai họa, nàng xin tạm thời đi theo Hàn Lập."},{"chuong":1821,"tieuDe":"Tụ Linh Thung","tomTat":"Băng Phượng chủ động xin đi theo Hàn Lập, cho rằng thiên phú trận pháp, thần thông không gian và Thiên Phượng nguyên âm của mình có thể trợ giúp hắn. Hàn Lập chấp thuận nhưng yêu cầu nàng nghe phân phó, giữ kín bí mật và mang thân phận thị thiếp hoặc tỳ nữ khi có người ngoài. Sau khi nhận nhiều bình linh đan, Băng Phượng ở lại mật thất luyện hóa dược lực để khôi phục tu vi. Hàn Lập sang một mật thất khác, kiểm tra viên đan gần như trong suốt và hy vọng nó có thể giúp mình vượt qua bình cảnh. Tiếp đó, hắn xác nhận mười hai mộc côn trong túi vàng là Tụ Linh Thung luyện từ Linh Nhãn Chi Mộc, có thể tăng khoảng một nửa tốc độ hấp thu linh lực sau khi được luyện hóa hoàn toàn. Cuối cùng, hắn nghiên cứu quyển trục vàng nhưng Linh Mục không thể nhìn xuyên, thần niệm còn bị lực hút mạnh uy hiếp nguyên thần. Thanh Trúc Phong Vân Kiếm cũng không làm quyển trục trầy xước, song cú chém đã khiến Kim triện linh văn ẩn bên trong hiện ra."},{"chuong":1822,"tieuDe":"Ước Định Gặp Mặt","tomTat":"Hàn Lập dùng kiếm khí kích thích quyển trục vàng, làm hiện ra một thiên Kim Triện văn hoàn chỉnh và nhận ra bên trong ghi cách bố trí một pháp trận cực kỳ huyền diệu. Vì cần hàng chục năm mới có thể nghiên cứu thấu đáo, hắn tạm cất quyển trục rồi vào mật thất luyện chế Khấp Linh Huyết mộc suốt bảy tám ngày. Sau khi xuất quan, hắn cấp đan dược và pháp khí cho Khí Linh Tử cùng Hải Đại Thiếu, phái hai môn đồ tới Thiên Uyên thành, đồng thời bí mật gặp Bạch Cốt chân nhân và một nhóm tán tu Hợp Thể. Trong những ngày cuối của Vạn Bảo đại hội, Hàn Lập tiếp tục thu thập tài liệu, tham dự các hội trao đổi và từ chối lời chiêu dụ của Huyền Vũ bảo hoàng cùng Thiên Nguyên thánh hoàng trước khi lặng lẽ rời Cửu Tiên sơn; Bạch Quả Nhi cũng biến mất cùng thời điểm. Bốn năm sau, gần trăm tu sĩ Cốc gia do Hiểu Phong tiên tử và Tiêu trưởng lão dẫn đầu tập trung tại Vọng Quy Phong để chờ một tu sĩ Hợp Thể trợ quyền cho Chân linh đại điển. Cốc gia buộc phải nhờ ngoại viện vì Thái thượng trưởng lão duy nhất bị thương trong man hoang thế giới và đang bế quan lâu dài. Sau hai canh giờ chờ đợi, một đạo thanh hồng đáp xuống đỉnh núi, để lộ một thanh niên áo xanh cùng một nữ đồng, nhưng danh tính của hai người chưa được xác nhận."},{"chuong":1823,"tieuDe":"Yêu Ảnh Nơi Hoang Nguyên","tomTat":"Hàn Lập đưa ký danh đệ tử Bạch Quả Nhi tới hội hợp với Hiểu Phong tiên tử, Tiêu trưởng lão và đoàn tu sĩ Cốc gia đang chuẩn bị dự Chân Linh đại điển. Do Thiên Lê tiên tử bị thương tại man hoang chi địa và phải bế quan, Cốc gia từ bỏ mục tiêu nâng cao thứ hạng, chỉ mong giữ vững vị trí hiện có. Hiểu Phong tiên tử giao thêm linh thạch cực phẩm để bù cho việc thay đổi thỏa thuận, còn Hàn Lập nhận lời lấy thân phận khách khanh Cốc gia dốc toàn lực tại đại điển, sau đó cả đoàn lên đường tới Vạn Linh Đài. Tại Thiên Mã hoang nguyên, một đội hơn mười tu sĩ kết trận chống kẻ địch ẩn trong cát vàng nhưng bị một xác giả đánh lừa. Tuyết Bạch Ngô Công hiện nguyên hình, cắn chết cẩm bào đại hán Luyện Hư trung kỳ, phun hàn sương đóng băng nhiều người rồi dùng sáu đạo bạch quang truy sát toàn bộ số còn lại, hủy cả thi thể lẫn Nguyên Anh. Sau cuộc tàn sát, yêu vật thu nhỏ thân thể và hóa thành một thanh niên áo trắng có hoa văn kim ngân, sau đó dùng bạch khí cuốn lấy thủ cấp của cẩm bào đại hán."},{"chuong":1824,"tieuDe":"Nghịch Linh Chân Âm Đại Pháp","tomTat":"Nguyên Anh của tông chủ Lam Thủy Tông cố viện dẫn quan hệ với Thiên Nguyên Thành và dâng bảo vật để cầu mạng, nhưng vẫn bị Lục Dực phá lớp hộ thể rồi nuốt chửng. Lục Dực tiếp tục nghiền nát Lam Cực Châu cùng Bạch Thủy Phiên, luyện hóa các mảnh vụn khiến khí tức tăng lên. Đại hán râu quai nón sừng kép tìm ra Huyền Âm Tinh Bích bị phong ấn trong hộp ngọc và giao cho Lục Dực hấp thu bằng mười hai hóa thân ngô công trắng. Cuộc trò chuyện sau đó hé lộ Lục Dực có bạch long chân huyết, thích hợp tu bí thuật trong Kim Khuyết Ngọc Thư và đang hướng tới việc đại thành Nghịch Linh Chân Âm Đại Pháp để ngưng tụ Chân Linh chi thể. Đại hán muốn mượn năng lực của Lục Dực để vượt qua vài đợt lôi kiếp trong kỳ thiên kiếp kế tiếp, đồng thời sẵn sàng vứt bỏ phân thân Thiên Lan tại Hạ giới. Lục Dực cảnh cáo đối phương không được ngầm gây bất lợi cho Hàn Lập trước khi hắn giải trừ hồn niệm trong bổn mạng huyết chú. Khi Lục Dực ám chỉ đã biết thân phận thật của người hợp tác, đại hán lập tức kinh động, nhưng bí mật ấy vẫn chưa được công bố."},{"chuong":1825,"tieuDe":"Vạn Linh Đài","tomTat":"Lục Dực thương lượng với đại hán râu quai nón về việc tu luyện Nghịch Linh đại pháp, chấp nhận sau khi đại thành sẽ trợ giúp đối phương vượt thiên kiếp. Hắn dự định hấp thu âm khí trong Huyền Âm Tinh Bích, đột phá Hợp Thể rồi tiến vào Man Hoang săn cổ thú hàn thuộc tính, hướng tới Hợp Thể hậu kỳ và Chân Linh chi thể. Hai tháng sau, Hàn Lập theo Hiểu Phong tiên tử, Tiêu trưởng lão và đoàn Cốc gia tới Vạn Linh Đài dự kỳ tụ hội ba ngàn năm một lần của các Chân Linh thế gia. Vì Thiên Lê tiên tử vắng mặt, nhiều tu sĩ Hợp Thể dò xét Hàn Lập, nhưng hắn dùng ngân diễm khiến các thần niệm bất thiện kinh sợ rút lui. Hàn Lập nhận ra Lũng Đông và dùng đồng thuật trừng phạt đối phương vì ánh mắt oán độc, buộc Lũng gia lão tổ phải ra tay hóa giải. Sau khi chất vấn Hàn Lập, Lũng gia lão tổ bất ngờ thừa nhận hậu bối tâm cao khí ngạo và không tiếp tục truy cứu."},{"chuong":1826,"tieuDe":"Tính Toán","tomTat":"Lũng gia lão tổ giải thích rằng quan hệ chưa rõ giữa Hàn Lập với Thánh đảo và Yêu Viên thần bí khiến Lũng gia không nên tùy tiện kết thêm đại địch trước Ma kiếp. Tuy vậy, ông vẫn giao Huy trưởng lão phụ trách tỷ thí xếp hạng và cho phép toàn lực thử thực lực thật của Hàn Lập nếu hai bên gặp nhau. Hiểu Phong tiên tử cùng Tiêu trưởng lão nhẹ nhõm khi xung đột không tiếp tục, trong khi thái độ hờ hững của Hàn Lập khiến các thế gia càng đánh giá hắn khó dò. Phía Diệp gia, lão tổ công khai tiếc việc Hàn Lập chưa gia nhập gia tộc và trêu Diệp Dĩnh về khả năng kết duyên với hắn. Phong gia và Lao gia đồng thời lập kế hoạch tiêu hao Hàn Lập, ép hắn lộ thực lực rồi dốc sức khiêu chiến Cốc gia trong lúc Thiên Lê tiên tử vắng mặt. Trong thời gian chờ đợi, Hàn Lập lấy một kim sắc hồ lô nhỏ có hình thể chập chờn ra thưởng thức. Pháp trận giữa Vạn Linh Đài sau đó mở rộng, kéo theo cột sáng, mây đen, sấm sét và tử kim hồ quang; Lũng gia lão tổ được giao chủ trì nghi thức và ra lệnh dâng tế phẩm. Cuối chương, lưới điện trên trời liên kết với những cột sáng quanh hạp cốc, hình thành một lồng giam khổng lồ báo hiệu Vạn Linh đại nhân sắp xuất hiện."},{"chuong":1827,"tieuDe":"Vạn Linh Thú","tomTat":"Theo hiệu lệnh của Lũng gia lão tổ, đệ tử các thế gia đổ hơn mấy chục loại Chân huyết tế phẩm vào bồn đá trên Vạn Linh Đài rồi kích hoạt pháp trận triệu gọi. Một hóa thân phân niệm của Vạn Linh đại nhân cách giới hàng lâm trong hình dạng quái thú thân sư tử có tám đầu giao. Sau khi hấp thu gần hết tế phẩm của năm mươi mốt Chân Linh thế gia, hóa thân trở nên rõ ràng và tăng khí tức từ Luyện Hư sơ kỳ lên Hợp Thể hậu kỳ đỉnh phong, gần nửa bước Đại Thừa. Vạn Linh thử dùng tia chớp xanh công kích Ngự Lôi Vạn Phong đại trận nhưng không thể làm tổn hại lưới điện tử kim đang phong ấn mình. Theo ước định cổ xưa, nó thi pháp chế tạo chín trăm chín mươi chín Tiềm Linh Lệnh rồi rời đi, đồng thời tuyên bố lần triệu gọi tiếp theo phải chờ ba nghìn năm. Lũng gia lão tổ cho thu giữ các lệnh bài, tiếp tục chủ trì nghi lễ tế tổ kéo dài gần nửa ngày rồi công bố quy tắc tranh hạng giữa các thế gia. Thứ hạng cũ của ngũ đại gia tộc bị bãi bỏ và họ phải tiến hành xa luân chiến trước, trong khi nam tử tự xưng Lâm mỗ tuyên bố sẽ tránh Lũng gia nhưng muốn dùng thần thông mới để giao đấu với Diệp tiên tử."},{"chuong":1828,"tieuDe":"Tỷ Thí Thượng","tomTat":"Cuộc tỷ thí xếp hạng của Ngũ đại Chân Linh thế gia bắt đầu bằng việc rút huyết thăm trên Vạn Linh Đài: Lâm gia gặp Phong gia, Lũng gia gặp Cốc gia, còn Diệp gia được miễn trận đầu. Phong gia chủ động nhận thua vì hai đại diện Hợp Thể không tin có thể phá Mộc Thận đại pháp của đại trưởng lão Lâm gia. Khi Cốc gia chuẩn bị đối đầu Lũng gia, Hiểu Phong tiên tử muốn bỏ cuộc để Hàn Lập giữ sức, nhưng hắn từ chối vì muốn kiểm nghiệm thực lực với tu sĩ cao giai cùng bậc và gây dựng uy danh trong Nhân tộc. Lũng gia lão tổ hỏi về tình hình bế quan của Khí Linh Tử rồi tuyên bố Hàn Lập phải đánh bại Huy trưởng lão trước khi có thể giao đấu với mình. Sau khi Hàn Lập và Huy trưởng lão lên đài, cấm chế phòng hộ được gia tăng để bảo vệ người xem. Huy trưởng lão lần lượt gọi ra Ngô Câu đen, đoản kiếm trắng và phi đao bạc, khiến Hàn Lập chú ý đến số pháp bảo dường như vô tận của đối phương."},{"chuong":1829,"tieuDe":"Tỷ Thí (Trung)","tomTat":"Hắc bào nhân đồng thời điều khiển bảy mươi hai bảo vật giao chiến với toàn bộ Thanh Trúc Phong Vân Kiếm của Hàn Lập, khiến hai bên nhất thời giằng co ngang sức. Hắn tiếp tục dẫn động thiên địa nguyên khí tạo hắc tơ, nhưng Hàn Lập dùng Nguyên Từ Thần Quang giữ lại rồi cuốn sạch đòn công kích. Đối thủ bèn ngưng tụ hắc vụ thành cự kiếm và liên tiếp phóng quang cầu xé rách không gian, tạo thành hắc động khổng lồ bao phủ Hàn Lập cùng hai ngọn núi phòng ngự. Trong lúc những người quan chiến lo lắng, Hàn Lập phá hắc quang thoát ra và điều khiển ngọn núi đen hóa lớn để chặn đại ấn của đối phương. Hắn sau đó dùng ngọn núi xanh liên tục tạo kiếm khí vô ảnh, buộc Hắc bào nhân phải triển khai thuẫn bài, cổ kính và hắc vụ bảo vệ toàn thân. Khi cổ kính phóng quang trụ màu vàng kim, quang thuẫn của ngọn núi xanh làm tiêu tán một phần rồi phản hồi phần lớn công kích, cuối cùng đánh tan lớp hắc vụ che chắn của đối thủ."},{"chuong":1830,"tieuDe":"Tỷ Thí Hạ","tomTat":"Huy trưởng lão để lộ những vết thương do Thái Ất thanh quang của Hàn Lập gây ra, dù thân thể hắn kiên cố và có thể nhanh chóng chữa lành bàn tay. Khi hắn vận dụng thần thông bí mật khiến hắc hà cùng vằn đen phủ kín cơ thể, Lũng gia lão tổ lập tức ngăn lại và tự mình bước lên Vạn Linh Đài. Lão đặt điều kiện rằng Hàn Lập chỉ cần đỡ được ba chiêu thì sẽ được tính là thắng, và Hàn Lập bình tĩnh chấp thuận. Trong chiêu đầu, Hàn Lập dùng ngọn núi đen thoát khỏi lực phong tỏa rồi biến ngũ sắc đại thủ đã vỡ thành hàn diễm, đóng băng kim sắc cự trảo. Sang chiêu thứ hai, Lũng gia lão tổ cho hư ảnh giao long vàng nhập thể, hóa thành trạng thái nửa người nửa rồng và dùng trảo vàng đánh văng ngọn núi đen, phá tan quyền ảnh của Phạm Thánh Ma cùng dòng thác thước bạc. Ngay khi đòn đánh sắp giáng xuống Hàn Lập, một quyền màu xanh bí ẩn xuất hiện từ hư không và đánh rung bàn tay vàng. Hàn Lập nhân cơ hội dịch chuyển ra xa, trong khi danh tính người can thiệp và kết quả của cuộc tỷ thí vẫn chưa được làm rõ."},{"chuong":1831,"tieuDe":"Lao Gia Khiêu Chiến","tomTat":"Lũng gia lão tổ huy động thiên địa nguyên khí cho chiêu thứ ba, nhưng Hàn Lập nhận thấy uy thế quá mạnh nên chủ động nhận thua và rời Vạn Linh Đài. Thực lực mà Hàn Lập thể hiện khiến Hiểu Phong tiên tử và Tiêu trưởng lão tin rằng Cốc gia có thể giữ vững vị trí trong Ngũ đại Chân Linh thế gia. Hai tu sĩ Hợp Thể của Phong gia cũng từ bỏ kế hoạch phối hợp với Lao gia nhằm hạ bệ Cốc gia vì không muốn đắc tội với Hàn Lập. Hàn Lập tiếp tục bỏ trận tranh hạng với Phong gia để giữ sức cho vòng khiêu chiến tự do, trong khi Diệp gia đánh bại Lâm gia và bảng xếp hạng Ngũ đại thế gia được giữ nguyên. Đến vòng tự do, Lao Ai đại diện Lao gia công khai thách đấu Cốc gia và Hàn Lập lên đài ứng chiến. Lao Ai mở đầu bằng thanh thước đen tạo linh hoa hộ thân và cây bút vàng kim vẽ ra những yêu điệp khổng lồ ngũ sắc."},{"chuong":1832,"tieuDe":"Kim Thân Sính Uy","tomTat":"Lao Ai điều khiển đàn yêu điệp tạo Ngũ Sắc Độc Vân, đồng thời dùng thẻ trúc màu hồng nhạt phóng vô số Hồng sắc Hỏa điểu để vây công Hàn Lập. Hàn Lập ngưng Phạm Thánh Kim Thân thành thực thể ba đầu sáu tay, khiến Lũng gia lão tổ cùng các tu sĩ Hợp Thể của Diệp gia và Lâm gia kinh sợ. Kim thân tạo lốc xoáy kim sắc hút sạch độc vân và hỏa điểu, sau đó đánh ra sáu quyền ảnh phá liên tiếp các tầng phòng ngự của Lao Ai. Lao Ai bị đánh khỏi Vạn Linh Đài nhưng không hề bị thương vì Hàn Lập đã chủ động lưu thủ, nên hắn công khai nhận thua và cảm tạ. Chiến thắng này khiến các tu sĩ Hợp Thể kiêng kị Hàn Lập, đồng thời củng cố địa vị của Cốc gia trong ngũ đại Chân Linh thế gia. Sau khi tỷ thí xếp hạng kết thúc, các gia tộc nhận lệnh bài và thương nghị phân chia tài nguyên, còn Hàn Lập giao mọi việc cho Hiểu Phong tiên tử cùng Tiêu trưởng lão. Cuối chương, Lũng gia lão tổ truyền âm thừa nhận hai bên đều chưa bộc lộ hết thần thông rồi bất ngờ hỏi Hàn Lập có quan hệ gì với Thánh Đảo."},{"chuong":1833,"tieuDe":"Thương Nghị Lúc Đêm Tối (1)","tomTat":"Lũng gia lão tổ tránh giải thích rõ câu hỏi về Thánh Đảo rồi bí mật mời Hàn Lập tới Vạn Linh Điện vào ban đêm. Ông hé lộ cuộc thương nghị có liên quan đến Ma Kiếp, lợi ích lớn và cơ hội tiến vào Đại Thừa, đồng thời cho rằng đệ nhị hóa thân cùng Pháp Tướng Kim Thân khiến Hàn Lập đủ tư cách tham dự. Sau khi cân nhắc, Hàn Lập nhận lời. Chân Linh Đại Điển sau đó kết thúc, Hiểu Phong Tiên Tử giao cho hắn điển tịch về Chân Linh chi huyết cùng toàn bộ vật phẩm đã hứa. Hàn Lập tiếp tục từ chối lời mời gia nhập Cốc gia nhưng đồng ý duy trì giao hảo với gia tộc này. Đêm xuống, hắn tới Vạn Linh Điện, được Huy trưởng lão dẫn qua đại điện đã rút sạch thủ vệ vào một thiên điện bí mật. Ba vị khách chưa rõ danh tính đang ngồi quanh thạch bàn khiến Hàn Lập lập tức trở nên cảnh giác."},{"chuong":1834,"tieuDe":"Thương Nghị Lúc Đêm Tối (2)","tomTat":"Hàn Lập đến thiên điện và hội hợp với Lũng Gia Lão Tổ, Huy trưởng lão, thiếu nữ Diệp gia cùng thái thượng trưởng lão Lâm gia, tạo thành nhóm năm tu sĩ có thực lực từ Hợp Thể trung kỳ trở lên. Theo lời gọi của Lũng Gia Lão Tổ, một chiếc gương đồng màu vàng ẩn trong góc tối hiện ra rồi hóa thành Thiên Thu Thánh Nữ, khiến những người chưa biết trước lập tức cảnh giác. Nàng tiết lộ bản thể vốn là bảo vật tùy thân của Tham Thiên Chân Nhân, sau khi chủ nhân vẫn lạc mới tự mở linh trí và gia nhập Khí Linh Tộc. Thiên Thu Thánh Nữ còn xác nhận mình là sứ giả liên minh và đã cùng Thiên Nguyên Thánh Hoàng, Huyền Vũ Bá Hoàng cùng các tu sĩ Đại Thừa hậu kỳ thương nghị định ước tại Thánh đảo. Sau khi Lũng Gia Lão Tổ bảo đảm nàng chỉ vào Vạn Linh cốc sau đại điển và sẽ rời đi ngay trong đêm, thiếu nữ Diệp gia cùng nam tử Lâm gia tạm chấp nhận sự hiện diện của nàng. Cuối cùng, Lũng Gia Lão Tổ công bố kế hoạch chờ tai họa Ma tộc bộc phát, lợi dụng lúc Cổ Ma giới và Linh Giới giao hòa để cả nhóm xâm nhập Ma giới."},{"chuong":1835,"tieuDe":"Tẩy Linh Trì Cùng Tịnh Linh Liên","tomTat":"Lũng Gia lão tổ đề nghị cả nhóm xâm nhập Ma giới, khiến nam tử tóc dài phản đối dữ dội vì nguy cơ gặp Thánh tổ và vô số Cổ Ma cao giai. Để chứng minh kế hoạch khả thi, Thiên Thu thánh nữ nuốt Ngụy Ma Châu và dùng bí thuật biến thân thể, pháp lực cùng khí tức thành trạng thái giống Cổ Ma, đến mức Hàn Lập và những người khác cũng không tìm thấy sơ hở. Nàng giải thích viên châu được luyện từ Ma hạch Cổ Ma và từng vượt qua cuộc thử nghiệm kéo dài nhiều tháng với những Cổ Ma bị Linh tộc bắt sống, dù vẫn có thể bị Thánh tổ hoặc Ma tộc sở hữu thần thông đặc biệt nhìn thấu. Khi Diệp tiên tử yêu cầu nói rõ lợi ích của chuyến đi, Lũng Gia lão tổ tiết lộ mục tiêu là Tẩy Linh Trì và Tịnh Linh Liên, hai kỳ vật có thể giúp người sử dụng thoát thai đổi cốt và tăng mạnh tuệ căn. Diệp tiên tử cho biết tổ tiên Diệp Gia từng lấy được tin tức về chúng từ tàn hồn một Cổ Ma cao giai, còn Thiên Thu thánh nữ kể rằng một vị Linh Vương đã tận mắt nhìn thấy hai vật nhưng phải trọng thương trở về mà không thể đắc thủ. Cuối cùng, Thiên Thu thánh nữ giải thích hai kỳ vật này có thể tiến hóa thành Hóa Tiên Trì và Thất Khiếu Nhất Khí Liên của Chân Tiên giới, đồng thời suy đoán ma khí lâu đời tại Ma giới đã ép linh khí chi nguyên hội tụ và tạo thành chúng."},{"chuong":1836,"tieuDe":"Ma Giới Chi Ước","tomTat":"Lũng gia lão tổ công bố kế hoạch cùng lực lượng Lũng gia và Khí Linh Tộc bí mật tiến vào Ma giới tìm Tẩy Linh Trì cùng Tịnh Linh Liên, đồng thời mời Hàn Lập, Diệp tiên tử và nam tử họ Lâm tham gia. Chuyến đi dự kiến bắt đầu vài chục năm sau khi ma kiếp bùng nổ, lúc chiến cuộc chuyển sang thế giằng co, nhưng riêng hành trình đến khu vực trung tâm Ma giới đã có thể kéo dài hàng chục năm. Nam tử họ Lâm nhận lời với điều kiện gia tộc không gặp đại nguy, còn Diệp tiên tử cần cân nhắc và Hàn Lập chưa thể cam kết vì có việc trọng yếu phải hoàn thành trong vài trăm năm tới. Lũng gia lão tổ yêu cầu tất cả giữ bí mật và phải đưa ra quyết định cuối cùng trước khi ma kiếp bắt đầu. Sau khi ba vị khách rời đi, ông giải thích với Thiên Thu Thánh nữ rằng huyết thống Thiên Phượng của Diệp tiên tử có lợi cho việc bảo mệnh, còn Hàn Lập có thực lực vượt Huy trưởng lão và khả năng vận dụng Chân Ma khí. Thiên Thu Thánh nữ giữ nguyên thỏa thuận số người ngang nhau, để lại Ma châu và đại diện Linh tộc xác lập hiệp ước với phía Lũng gia. Trở về chỗ ở, Hàn Lập vẫn âm thầm cân nhắc lời mời tiến vào Ma giới."},{"chuong":1837,"tieuDe":"Trăm Năm Trôi Qua","tomTat":"Hàn Lập cân nhắc cơ duyên tiến giai Đại Thừa từ Tẩy Linh Trì và Tịnh Linh Liên nhưng e ngại Nguyên Sát Thánh Tổ truy sát nếu tiến vào Ma giới. Hắn quyết định chỉ tham gia hành động của Lũng gia lão tổ nếu kịp đạt Hợp Thể hậu kỳ, đồng thời đặt hy vọng vào Luyện Thần Thuật, linh dược và Minh Hà Thần Nhũ. Sáng hôm sau, Hàn Lập cùng Bạch Quả Nhi âm thầm rời lầu các bằng Phi Xa màu xanh; Bạch Quả Nhi lúc này đã Trúc Cơ và có thể dùng pháp bàn hỗ trợ điều khiển xe. Hàn Lập cho biết chuyến du hành Tam Hoàng Thất Yêu nhằm tìm một nữ nhân có thể đã phi thăng Linh giới, đồng thời tôi luyện tâm cảnh và ổn định cảnh giới. Sau hai mươi năm đi qua Tam Hoàng Cảnh và một thời gian xuất hiện lời đồn tại lãnh địa Thất Yêu, hành tung của hắn hoàn toàn biến mất. Trong hai trăm năm kể từ Vạn Bảo đại hội, một nữ tu thần bí với tu vi Hợp Thể trung kỳ thắng mười một đối thủ tại Đại Bỉ, đoạt ngôi Linh hoàng và giúp Thiên Linh Cảnh khôi phục ổn định. Cũng trong thời gian này, Thánh Đảo đại diện Nhân Yêu lưỡng tộc công bố đình chiến với các dị tộc đối địch và thiết lập Ngàn năm minh ước cùng nghĩa vụ đồng minh công thủ."},{"chuong":1838,"tieuDe":"Bạch Quả Nhi Cùng Giao Dịch","tomTat":"Tin tức Ma kiếp đã lan xuống các tầng lớp thấp hơn, khiến Nhân tộc và Yêu tộc từng bước di dân, xây pháp trận, huấn luyện luyện thể sĩ và tích trữ trang bị trong suốt hơn trăm năm. Bạch Quả Nhi, nay đã đạt Kết Đan trung kỳ, bay thẳng vào Thiên Uyên Thành nhờ đặc quyền dành cho đệ tử ký danh của Hàn Lập. Các giáp sĩ thủ thành giải thích thân phận của nàng và nhắc tới danh tiếng Hàn Lập, người hiện vẫn đang bế quan. Tại đại điện giao dịch của phường thị Nhân–Yêu, Bạch Quả Nhi gặp Tần Tố Nhi và dùng hai nửa ngọc bội ghép lại để xác nhận thân phận. Hai người trao đổi vật phẩm, hoàn thành giao dịch tài liệu quý đã được Hàn Lập ước định từ trước. Sau đó Bạch Quả Nhi rời Thiên Uyên Thành, đi suốt hai tháng và hạ xuống một ngọn núi sâu trong sơn mạch có linh khí nồng đậm."},{"chuong":1839,"tieuDe":"Tiểu Thế Giới Trong Lòng Núi","tomTat":"Bạch Quả Nhi trở về động phủ và gặp Hải Đại Thiếu, người đã tiến vào Kết Đan kỳ sau hai trăm năm, vừa sống sót qua một nhiệm vụ nguy hiểm của Thiên Uyên thành và đang chuẩn bị trùng kích Kết Đan trung kỳ. Qua cuộc trò chuyện, nàng cho biết Khí Linh Tử đã đạt Kết Đan đại thành và sắp ngưng kết Nguyên Anh, còn hai sư huynh đệ đều phải che giấu quan hệ với Hàn Lập khi hoạt động bên ngoài. Sau khi Hải Đại Thiếu rời đi, Bạch Quả Nhi vượt qua nhiều tầng cấm chế để tiến vào tiểu thế giới nằm sâu trong lòng núi, nơi có thảo nguyên rộng lớn, hai ngọn tiểu sơn và một lầu các bạch ngọc. Nàng giao số hắc sắc yêu đan đã thu thập cho thân ảnh màu vàng giống Hàn Lập, giúp hắn hoàn tất số tài liệu Yêu tộc cần thiết. Hàn Lập thông báo sẽ thu hồi đệ nhị Nguyên Anh, phong bế hoàn toàn động phủ và tiến hành đợt bế quan sinh tử nhằm chuẩn bị trùng kích Hợp Thể trung kỳ, có thể kéo dài tới hai, ba trăm năm. Sau khi Bạch Quả Nhi rời đi, pháp trận từ hai ngọn núi phủ khắp thảo nguyên rồi hóa thành biển sương ngũ sắc, cắt đứt tiểu thế giới với ngoại giới. Trong tầng một lầu các, bản thể Hàn Lập quan sát kim sắc cự đỉnh được ngân sắc hỏa diễm bao quanh, bên trong là chất lỏng thần bí ngũ sắc đang cuồn cuộn lưu chuyển."},{"chuong":1840,"tieuDe":"Vạn Độc Hỗn Nguyên Thân","tomTat":"Hàn Lập nhận số Độc Đan Hàn Đàm Ma Chu do Bạch Quả Nhi mang về, dung luyện chúng cùng độc dịch pha chế từ hơn trăm loại kỳ độc để chuẩn bị tu luyện tầng thứ bảy của Vạn Độc Hỗn Nguyên Thân. Luyện thể thuật Dị tộc này gồm bảy tầng, có thể khiến thân thể người tu sánh với yêu tu cao cấp và đạt hiệu quả vạn độc bất xâm, nhưng cũng tiềm ẩn nguy cơ độc phát hoặc tử vong. Nhờ căn cơ được Phạm Thánh Chân Ma Công, Tinh Nguyệt Dịch và Hồng La tiên tửu củng cố, Hàn Lập tiến vào cự đỉnh ngâm mình trong nọc độc ngũ sắc và đóng kín nơi bế quan. Trong thời gian đó, hắn còn dựa vào lục dịch thần bí để thúc đẩy linh dược, luyện đan dược Hợp Thể kỳ và duy trì tốc độ tinh tiến pháp lực vượt xa tu sĩ bình thường. Khí Linh Tử ngưng kết Nguyên Anh rồi trở thành cao cấp vệ sĩ của Thiên Uyên Thành, Bạch Quả Nhi đạt Kim Đan hậu kỳ và rời động phủ du ngoạn, còn Hải Đại Thiếu tiến lên Kết Đan trung kỳ và đảm nhiệm việc kiểm tra cấm chế. Sau hơn một trăm hai mươi năm, thiên tượng lốc xoáy ngũ sắc cùng ngân sắc điện hồ xuất hiện trên ngọn núi, khiến Hải Đại Thiếu vội trở về. Hàn Lập xuất quan và xác nhận đã tiến giai Hợp Thể trung kỳ, đồng thời cho biết Băng Phượng đã kích phát cấm chế, áp chế hơn phân nửa thiên địa nguyên khí để tránh thu hút sự chú ý từ bên ngoài."},{"chuong":1841,"tieuDe":"Tân Phệ Kim Trùng Biến Dị","tomTat":"Hải Đại Thiếu vui mừng khi biết Hàn Lập đã tiến giai Hợp Thể trung kỳ, nhưng Hàn Lập yêu cầu giữ kín tin này và cảnh tỉnh đệ tử phải khẩn trương tu luyện trước ma kiếp. Hắn dự định trùng kích Hợp Thể hậu kỳ với sự hỗ trợ từ nguyên âm khí Thiên Phượng của Băng Phượng, đồng thời quyết định thực hiện một chuyến đi bắt buộc tới Man Hoang thế giới. Khí Linh Tử và Bạch Quả Nhi lần lượt trở về động phủ, cùng Hải Đại Thiếu tiếp nhận sự chỉ điểm của Hàn Lập trong ba năm. Trước khi rời đi, Hàn Lập giao ba đệ tử cho Băng Phượng tiếp tục chăm sóc và chỉ điểm. Trên đường tới Thiên Uyên Thành, hắn kiểm nghiệm Phệ Kim Trùng biến dị được bồi dưỡng bằng Thất Thải Đan, xác nhận chúng đã tăng tốc độ, độ cường ngạnh và thức tỉnh khả năng ẩn nặc thân hình. Hàn Lập nhận định muốn điều khiển hơn vạn linh trùng làm sát thủ uy hiếp tu sĩ Hợp Thể hậu kỳ, hắn cần tiến giai Hợp Thể hậu kỳ và luyện thành tầng thứ hai của Luyện Thần Thuật."},{"chuong":1842,"tieuDe":"Ma Ảnh Tới Gần","tomTat":"Hàn Lập ngồi tu luyện trên chiến xa màu đồng cổ bay qua sa mạc và tiện tay phóng kiếm khí giết một con Cự tằm khổng lồ ẩn dưới cát. Trong một cung điện dưới biển, kén máu bí ẩn chứa hắc ảnh đang phát ra nhịp đập trầm đục như trái tim. Tại Phong Nguyên đại lục, bạch y nữ tử dùng tu vi Đại Thừa trấn áp các cường giả Lục Chi tộc, trong khi hắc bào đại hán tàn sát hơn nghìn tộc nhân để ép họ giao Thánh Tinh Chi Hoa. Đại trưởng lão cuối cùng khuất phục để cứu tộc, nhưng bạch y nữ tử kiểm tra rồi xác định linh vật đoạt được không phải thứ mình đang tìm kiếm. Hai người rời đi và tiếp tục lùng tìm tại những khu vực khác của đại lục. Tám mươi năm sau, một nhóm Phi Linh nhân trẻ tuổi bị thiên tai Ngân Triều truy đuổi ngoài biển; khi pháp lực gần cạn, tu sĩ Nguyên Anh dẫn đội ra lệnh dừng chạy, lập trận và lấy pháp trượng chuẩn bị chống đỡ."},{"chuong":1843,"tieuDe":"Lại Trở Về Phi Linh","tomTat":"Một nhóm đệ tử Ngũ Sắc, Bạch Ngọc và Thiên Bằng dùng trận kỳ chống đỡ giữa Ngân triều nhưng lớp phòng hộ nhanh chóng suy yếu. Hiên sư muội và Miện huynh phối hợp phát tín hiệu cầu cứu, khiến Hàn Lập đang đi xuyên qua thiên tai dừng lại hỏi rõ lai lịch của họ. Vì trong nhóm có đệ tử Thiên Bằng tộc, Hàn Lập dựng Lôi Quang Điện Trận, phá quang cầu phòng hộ rồi truyền tống toàn bộ mọi người tới nơi an toàn cách hơn vạn dặm. Hành động này diễn ra khi hắn vừa hoàn tất hành trình hơn tám mươi năm để trở lại phụ cận Phi Linh tộc. Hàn Lập từ chối báo danh nhưng hỏi thăm những biến động gần đây và được Hiên sư muội cho biết các đại yêu vương Địa Uyên đã mất tích, tạo cơ hội để các tộc Phi Linh liên thủ công chiếm toàn bộ khu vực. Sau khi hắn rời đi, Miện huynh nghi ngờ ân nhân là người ngoại tộc, song Hiên sư muội cho rằng những tin tức đã tiết lộ không phải cơ mật. Cả nhóm cuối cùng gác lại tranh luận và mau chóng rời khỏi hải vực nguy hiểm."},{"chuong":1844,"tieuDe":"Giật Mình","tomTat":"Sau khi rời nhóm Phi Linh nhân, Hàn Lập biết tứ đại yêu vương vẫn chưa trở về, khiến các tộc Phi Linh chiếm giữ Địa Uyên, còn Bạch Bích và Lôi Lan đã trở thành thánh chủ giúp Thiên Bằng tộc thoát họa diệt tộc. Vì tọa độ Thanh Nguyên Tử dùng để tiếp dẫn hắn vào Minh Hà Chi Địa nằm sâu trong Địa Uyên, Nghịch Tinh Bàn không thể phát huy tác dụng nếu hắn chưa đến đúng vị trí. Hàn Lập quyết định một lần nữa mượn sức Thiên Bằng tộc, kiểm tra ngọc giản màu lam cùng viên bàn trắng nhạt rồi tăng tốc lên đường. Năm tháng sau, hắn đến bên ngoài Thánh Thành Thiên Bằng, hóa thành Thanh Bằng khổng lồ và phát ra khí tức Thiên Bằng tinh thuần, khiến nhiều trưởng lão Hợp Thể phải ra xem xét. Kim Duyệt dùng Linh Mục Thần Thông quan sát rồi nhận ra hắn qua giọng nói. Khi Hàn Lập hiện chân thân, Tư trưởng lão và mỹ phụ trưởng lão kinh hãi vì người từng bị cho là đã chết trong Địa Uyên nay đã tiến tới Thánh giai. Hàn Lập thừa nhận mình trở về vì có việc cần trao đổi, sau đó được Kim Duyệt đích thân mời vào thành."},{"chuong":1845,"tieuDe":"Nửa Bộ Pháp Quyết","tomTat":"Kim Duyệt đưa Hàn Lập cùng các trưởng lão vào cung điện tại Thánh Thành, dùng lễ khách quý tiếp đãi và tặng hắn năm cân Hương Nữ Trà thượng đẳng. Nàng công khai việc Hàn Lập từng giúp Bạch Bích và Lan nhi vượt qua thí luyện, qua đó bảo toàn Thiên Bằng nhất tộc, rồi dò hỏi hắn về sự mất tích của Tứ Đại yêu vương. Hàn Lập không tiết lộ nội tình, chỉ khẳng định các Yêu Vương không thể trở lại Địa Uyên. Khi Kim Duyệt nghi hắn hóa thành Cự bằng ngoài thành để thị uy, Hàn Lập đưa ra một ngọc giản chứa nửa bộ pháp quyết huyền ảo dành riêng cho Thiên Bằng nhân. Nhận ra giá trị của pháp quyết, Kim Duyệt cho các trưởng lão rời điện, còn Hàn Lập dựng cấm chế cách âm bằng hơn mười tiểu kỳ ngũ sắc. Hắn xác nhận mình nắm toàn bộ công pháp luyện hóa Thiên Bằng chi huyết và đề nghị dùng nó làm thù lao để Thiên Bằng Tộc đưa mình trở lại Địa Uyên."},{"chuong":1846,"tieuDe":"Trở Lại Địa Uyên Thượng","tomTat":"Hàn Lập đề nghị trao phần còn lại của pháp quyết tăng cường Thiên Bằng biến thân để đổi lấy việc được đưa tới tầng ba Địa Uyên. Kim Duyệt cho biết Địa Uyên đang bị nửa phong bế vì một khoáng mạch quý hiếm tại tầng sâu nhất, đồng thời dò hỏi kỹ mục đích của hắn. Hàn Lập giải thích mình cần tới không gian ẩn cư của một vị tiền bối có quan hệ với Nhân tộc, ngầm viện dẫn uy thế Đại Thừa kỳ của Thanh Nguyên Tử và giữ phần pháp quyết còn lại trong thần niệm để đề phòng đối phương trở mặt. Sau khi cân nhắc, Kim Duyệt chấp thuận giao dịch và bí mật bàn bạc với các trưởng lão Thiên Bằng tộc. Hàn Lập rời Thánh Thành, mở mật thất tạm thời dưới một sơn khê và chờ nửa tháng, tin rằng tu vi Hợp Thể trung kỳ cùng các thần thông hiện có đủ giúp mình thoát thân nếu bị vây công. Đến ngày khởi hành, Kim Duyệt dùng việc đưa Lôi Lan vào Địa Uyên tu luyện Băng Sát bí thuật làm vỏ bọc để Hàn Lập giả làm thủ vệ đi cùng. Trước lúc lên đường, nàng cảnh báo hắn phải đề phòng những thiên phú bí thuật và phương pháp tra xét của lực lượng thủ vệ Phi Linh Tộc."},{"chuong":1847,"tieuDe":"Kinh Biến Trong Địa Uyên","tomTat":"Hàn Lập quyết định giả làm thị vệ Thiên Bằng tộc, dựa vào Thiên Bằng linh huyết, Phong Lôi Sí và bí thuật che giấu để tránh bị nhìn thấu. Lôi Lan dùng nhu cầu hấp thu Băng Sát khí tu luyện bí thuật làm lý do hợp lệ cho cả nhóm tiến vào Địa Uyên, còn Bạch Bích không tham gia vì đang bế quan. Sau mấy tháng lên đường, Hàn Lập biến đổi dung mạo và ép pháp lực biểu hiện xuống Luyện Hư kỳ trước khi cùng Kim Duyệt và Lôi Lan tới đại thành trấn thủ Địa Uyên. Kim Duyệt xuất trình ngọc bài, dùng quyền hạn Đại trưởng lão Thiên Bằng tộc để vượt qua đội thủ vệ cửa thành. Tại pháp trận dẫn xuống Địa Uyên, họ gặp Kim Phong đang trực tiếp trấn giữ vì một kẻ thần thông cao cường vừa cướp sạch quáng thạch quý hiếm trong khoáng mỏ và sát thương nhiều thủ vệ. Kim Phong chấp nhận cho Lôi Lan vào tu luyện nhưng ban đầu muốn giữ Hàn Lập ở ngoài. Kim Duyệt bí mật truyền âm giải thích quan hệ giữa Hàn Lập và việc tu luyện của Lôi Lan, khiến Kim Phong đổi thái độ và cho cả ba cùng tiến vào Địa Uyên."},{"chuong":1848,"tieuDe":"Tái Hồi Đệ Nhị Tầng","tomTat":"Nam tử mặc thanh giáp cho thị vệ dùng mộc bài tím kích hoạt trận pháp, mở cánh cửa bạc để Kim Duyệt, Hàn Lập và Lôi Lan tiến vào Địa Uyên rồi nhanh chóng phong bế lối vào. Hàn Lập với tu vi Hợp Thể trung kỳ dễ dàng vượt qua tà phong và băng phong từng gây khó khăn cho hắn, trong khi Kim Duyệt bảo hộ Lôi Lan. Ba người đi qua Lan Độc đầm lầy, nơi Hàn Lập dùng kiếm quét sạch đàn Độc Phong, rồi tới ngọn núi hình chữ Nhân dẫn xuống tầng hai. Tại đây, họ gặp sáu tu sĩ Luyện Hư thuộc chấp pháp đội đang mai phục để phong tỏa đường ra vào và truy bắt kẻ đã cướp sạch khoáng mạch. Một thành viên cánh xám chú ý tới khuôn mặt xa lạ của Hàn Lập, nhưng Minh Chấn lấy lý do Thiên Bằng tộc có đông tộc nhân để gạt bỏ nghi vấn. Trên đường xuyên qua vùng sương đen, Kim Duyệt nói rõ Thiên Bằng tộc chỉ nhận được phần nhỏ lợi ích từ khoáng mạch và đặt hy vọng phục hưng vào nửa sau công pháp của Hàn Lập. Hàn Lập cam kết sẽ giao công pháp tại tọa độ đã định để nàng kiểm tra, sau đó cả ba chính thức tiến vào tầng thứ hai của Địa Uyên."},{"chuong":1849,"tieuDe":"Ngân Sắc Lôi Quang Cùng Truyền Tống","tomTat":"Hàn Lập, Kim Duyệt và Lôi Lan vượt qua tầng thứ hai Địa Uyên, nhờ thân phận Đại trưởng lão của Kim Duyệt mà không bị các đội chấp pháp gây khó dễ, rồi đi qua cửa dưới đáy sông để xuống tầng thứ ba. Tại đây, họ phát hiện một vùng đá cháy đen cùng nhiều pháp bảo hư hại và nhận định ba chấp pháp đội viên đã bị kẻ cướp khoáng mạch tinh thông thần thông lôi hệ giết chết. Lo viện binh lần theo bí thuật cảm ứng tới nơi, ba người lập tức rời đi và sau bảy ngày tiến vào một dãy sơn mạch đen, nơi họ hợp sức đánh tan đàn yêu cầm giống quạ. Bạch sắc viên bàn sau đó phát sinh cảm ứng, giúp Hàn Lập xác định tọa độ do một vị tiền bối chỉ dẫn dù Kim Duyệt không nhận thấy tiết điểm không gian. Hàn Lập giao Hoàng sắc ngọc giản chứa phần sau của pháp quyết cho Kim Duyệt, và nàng kiểm tra rồi xác nhận nội dung là thật. Hoàn tất giao dịch, hắn bố trí năm trận kỳ ngũ sắc, đưa hơn trăm cực phẩm linh thạch cùng Bạch sắc viên bàn vào trận pháp và cáo biệt Kim Duyệt, Lôi Lan. Khi Hàn Lập bước vào trận, vô số phù văn màu bạc tuôn ra, còn quang đoàn màu trắng ở trung tâm cuồng trướng nhưng kết quả truyền tống chưa được hé lộ."},{"chuong":1850,"tieuDe":"Gặp Gỡ Ngoài Ý Muốn","tomTat":"Khi Ngũ sắc truyền tống quang trận vận chuyển tới cực hạn, Kim Duyệt phát hiện một kẻ ẩn nấp nhưng không kịp ngăn hắn hóa thành Ngân xà lọt vào trận cùng Hàn Lập. Sau khi nhận định đối phương là kẻ đang bị Đội Chấp Pháp truy tìm, nàng xóa sạch dao động truyền tống rồi đưa Lôi Lan tới Băng sát chi địa. Tại Minh Hà Chi Địa, Hàn Lập nhận ra kẻ đi nhờ chính là Ngư điếm chủ từng tổ chức hàng phục Lôi Thú và suy ra hắn đã cướp sạch khoáng mạch sâu trong Địa Uyên. Họ Ngư bộc lộ tu vi Hợp Thể sơ kỳ, nhưng Hàn Lập giải khai phần tu vi bị che giấu và dùng linh áp mạnh hơn khiến đối phương tưởng hắn là Thánh giai trung kỳ. Hàn Lập yêu cầu họ Ngư giao toàn bộ tài liệu đã cướp để đổi lấy cơ hội rời đi. Ngư điếm chủ hai lần giả vờ hợp tác, trước tiên dùng lam sắc viên hoàn hóa điện võng nhưng bị lôi điện pháp trận của Hàn Lập thu sạch. Hắn tiếp tục điều khiển hơn mười tế châm đánh lén từ phía sau, đồng thời gọi ra quái thú nửa người nửa chim trong tam sắc lôi quang để giáng lôi hồ xuống Hàn Lập."},{"chuong":1851,"tieuDe":"Hoá Linh Chi Chiến Thượng","tomTat":"Hàn Lập phá tan tam sắc điện hồ rồi cho Nguyên Anh đen nhánh nhập vào Phạm Thánh Kim Thân, dùng sáu Kim Nhận giao chiến bất phân thắng bại với Lôi Thú. Ngư điếm chủ triển khai Ngũ sắc thần quang và âm thầm điều khiển hơn mười cây ngân châm chứa độc đánh lén, nhưng Hàn Lập thả Chi Tiên linh khu ra chặn đòn. Linh khu hóa giải chất độc, ép các ngân châm khỏi cơ thể rồi nuốt toàn bộ, thể hiện sức mạnh của cảnh giới Hợp Thể sơ kỳ đại thành. Khi bị ngũ sắc quang hải vây khốn, Hàn Lập vận dụng Kinh Trập quyết cùng chân huyết Khổng Tước để biến thân và xuyên qua các tầng cấm chế. Ngư điếm chủ kinh ngạc trước Ngũ sắc biến thân của đối phương, nghi Hàn Lập có liên quan đến những kẻ mình căm hận. Hắn dung hợp thân thể với hư ảnh Khổng Tước, đẩy khí tức hóa thân lên Hợp Thể hậu kỳ đỉnh phong và dẫn động thiên địa nguyên khí trong phạm vi trăm dặm, khiến trận chiến bước sang giai đoạn nguy hiểm hơn."},{"chuong":1852,"tieuDe":"Hoá Linh Chi Chiến Hạ","tomTat":"Ngư điếm chủ hợp nhất thân thể với pháp tướng Ngũ Sắc Khổng Tước, khiến tu vi tăng liền hai cấp và quyết phân sinh tử với Hàn Lập. Hàn Lập vận dụng hình thái mạnh nhất trong Kinh Trập biến hóa, hóa thành Sơn Nhạc Cự Viên cao hơn trăm trượng rồi dùng cự lực phá vỡ quầng sáng ngũ sắc. Ngư điếm chủ biến Ngũ sắc thần quang thành nhiều tầng quang thuẫn và vô số phi kiếm phản kích, nhưng Hàn Lập dùng ba tầng phòng hộ kim sắc cùng nhục thân cường hãn chống đỡ. Trong cuộc va chạm trực diện, Sơn Nhạc Cự Viên tiếp tục chiếm ưu thế và đánh bật đôi cánh hóa thành cự nhận của Ngũ Sắc Khổng Tước. Hàn Lập áp sát tung quyền khiến đối phương rơi xuống, sau đó hợp ba mươi sáu kim sắc tiểu kiếm thành cự kiếm và dùng kiếm quang ép thân thể Khổng Tước đập xuống mặt đất, tạo thành một hố sâu rộng. Khi Hàn Lập chưa xác định được đòn kiếm có thực sự chém trúng hay không, Ngư điếm chủ từ dưới hố tuyên bố sẽ dùng thủ đoạn liều mạng."},{"chuong":1853,"tieuDe":"Há Không Dị Biến","tomTat":"Ngư điếm chủ trong hình thái Ngũ Sắc Khổng Tước gom hàng trăm quang trận nhỏ thành một ngũ sắc quang trận có khả năng tự khôi phục, khiến những đòn kiếm của Hàn Lập không thể phá hủy hoàn toàn. Hắn thúc giục lôi thú rời cuộc chiến với Phạm Thánh kim thân để tiến vào trận, nhưng Hàn Lập cùng Ma Anh liên tiếp ngăn cản và gây thương tích cho nó. Lôi thú sau đó mọc ba đôi cánh vàng, bạc và lam, dùng năng lực dịch chuyển tức thời để vượt qua sự truy kích rồi chui vào quang trận. Ngư điếm chủ cũng nhập trận, khiến tám mươi mốt cột sáng dựng lên và xé mở một lỗ thủng màu bạc tuôn ra linh khí tinh thuần tương tự Quảng Hàn giới. Cột sáng bạc từ lỗ thủng làm đại trận khuếch trương gấp mười lần, đồng thời phát ra tiếng phụ nữ và trẻ nhỏ khóc có thể dẫn người nghe vào ma chướng. Cảm nhận nguy hiểm mãnh liệt, Hàn Lập gọi Phạm Thánh kim thân trở lại và lần đầu sau khi tiến giai Hợp Thể trung kỳ toàn lực thi triển Động Tuyền kim quang. Vòng xoáy kim sắc phát triển thành biển sáng vàng mang cự lực, khiến hư không vặn vẹo rồi đánh thẳng vào trung tâm đại quang trận."},{"chuong":1854,"tieuDe":"Lôi Thú Chi Lực","tomTat":"Động Tuyền Kim Quang ép quang trận đến bờ tan vỡ, nhưng quang trận tiêu tán lại để lộ một quái cầm hai đầu tám cánh do Ngư điếm chủ dung hợp với lôi thú, mang sức mạnh cấp Đại Thừa. Quái cầm dùng ngũ sắc lôi quang phá hủy thần thông của Hàn Lập rồi vận dụng một phần lôi điện pháp tắc, khiến lôi trận truyền tống của hắn tắt hẳn. Sau khi phá vòng vây điện hồ và trở lại hình người, Hàn Lập lấy Huyền Thiên Tàn Nhận, thả hơn nghìn Phệ Kim Trùng trưởng thành, gọi Linh tiên chi thể cùng Oa Oa ra trợ chiến và chuẩn bị tử chiến. Hắn vẫn giữ mấy vạn Phệ Kim Trùng cùng Huyền Thiên Chi Kiếm làm hậu thủ, đồng thời tính toán kéo dài cuộc chiến để động tĩnh có thể kinh động Thanh Nguyên Tử. Ngư điếm chủ nhận ra pháp tắc chi lực khác thường trên Tàn Nhận nên âm thầm cảnh giác, làm kế hoạch đánh lén của Hàn Lập khó thành. Khi không gian xung quanh bị ngũ sắc điện hồ phủ kín và Hàn Lập sắp tế Tàn Nhận, một tiếng viên hầu rống vang lên, rồi hắc quang từ Linh Thú Hoàn màu đen tự lao vào vùng lôi điện khiến quái cầm cũng bất ngờ."},{"chuong":1855,"tieuDe":"Hình Thú Tái Xuất","tomTat":"Linh Thú Hoàn bị lôi điện phá vỡ, nhưng hắc khí do Đề Hồn biến thành hấp thu sạch điện hồ rồi hóa thành cự quỷ ba mắt có sừng và ba gai xương. Đề Hồn dùng Huyết Liên kéo Cự Cầm hai đầu khỏi hư không, trói chặt nó và phong tỏa toàn bộ thần thông lôi điện. Sau đó, gai xương được thượng cổ chú ngữ kích phát xuyên thủng đầu Lôi thú, khiến phần đầu này cùng thân thể Cự Cầm tan thành ngũ sắc quang điểm. Ngư điếm chủ kịp dùng Kim sắc đoản kiếm tự chém phần đầu mình khỏi thân hợp nhất rồi hóa huyết quang chạy trốn, còn Đề Hồn nuốt toàn bộ ngũ sắc lôi quang. Hàn Lập thu hồi Tàn nhận kim sắc cùng Phệ Kim Trùng, biến thành Kim sắc Cự Viên và dịch chuyển chặn đường đối phương. Ngư điếm chủ trong tình trạng tu vi bất ổn hóa thành huyết sắc Khổng tước để liều mạng. Vì Đề Hồn chỉ mải chơi với một khối tinh hạch và không đáp lại lời thúc giục, Hàn Lập tự triệu hai tòa tiểu sơn vào tay để tiếp tục nghênh chiến."},{"chuong":1856,"tieuDe":"Diệt Địch","tomTat":"Hàn Lập trong hình thái Sơn Nhạc Cự Viên ném hai tòa cực sơn xuống Ngư điếm chủ, phá tan huyết quang có khả năng làm ô uế linh bảo. Bức họa không gian của đối phương dựng lên hư ảnh lầu các và cung điện để phòng thủ nhưng vẫn bị quang hà màu tro, kiếm khí vô hình cùng trọng áp của cực sơn nghiền nát. Khi huyết nhục Ngư điếm chủ định tái tụ thành thân thể mới, Hàn Lập tiếp tục phá hủy chúng rồi dùng kim sắc điện hồ diệt Nguyên Anh hình Khổng Tước. Hắn thu hai nhẫn trữ vật, tinh luyện huyết vụ thành chân huyết ngũ sắc và nhận định Ngư điếm chủ có thể mang huyết mạch chính thống của Ngũ Sắc Khổng Tước. Trận chiến giúp Hàn Lập xác lập sự phối hợp giữa Nguyên Hợp Ngũ Cực sơn và thần lực Cự Viên thành một sát chiêu mới. Sau đó, hắn đến chỗ Đề Hồn và nhận ra liên hệ tâm thần giữa hai bên gần như đã biến mất. Đề Hồn nuốt tinh hạch lôi thú, chủ động trò chuyện, cho biết mình có thêm nhiều tri thức sau khi thức tỉnh và chỉ có phần tương tự Hình Thú. Cuối cùng, Đề Hồn tuyên bố sắp phải rời khỏi Linh giới, khiến Hàn Lập biến sắc."},{"chuong":1857,"tieuDe":"Cự Nhãn","tomTat":"Đề Hồn cho Hàn Lập biết rằng việc thôn phệ thần niệm của Thiên Ngoại Ma Quân và hấp thu thiên lôi đã khiến nó bị thiên địa lực lượng của Linh Giới bài xích, sắp được dẫn tới Chân Tiên Giới. Một Cự Nhãn ngũ sắc mang uy áp khủng bố lập tức giáng lâm, dùng cột sáng huyết sắc kéo Đề Hồn lên cao rồi thu linh thú vào trong mắt. Hàn Lập hoàn toàn không thể phản kháng, chỉ có thể cô độc tiễn biệt người bạn đã theo mình từ Loạn Tinh Hải và nhiều lần cứu mạng mình. Nguyên Dao sau đó tìm tới, khiến Hàn Lập nhận ra nàng đã đạt Luyện Hư hậu kỳ, còn Thanh Nguyên Tử xuất hiện dưới dạng một Nguyên Anh cố hình thuộc tam đại hóa thân. Khi Thanh Nguyên Tử hỏi về khí tức khác thường tại hiện trường, Hàn Lập che giấu chuyện Đề Hồn và nói rằng một cừu gia đã theo truyền tống tới rồi bị mình giải quyết. Thanh Nguyên Tử không truy hỏi thêm, dẫn Hàn Lập cùng Nguyên Dao về nơi ở của mình. Trên đường đi, Nguyên Dao đoán Hàn Lập trở lại vì Minh Hà Thần Nhũ và hắn xác nhận đó chính là mục tiêu của chuyến đi."},{"chuong":1858,"tieuDe":"Biến Hoá","tomTat":"Trên đường trở về động phủ, Nguyên Dao báo trước với Hàn Lập rằng việc giao Minh Hà thần nhũ đã gặp một biến cố ngoài khả năng kiểm soát của Thanh Nguyên Tử. Tại động phủ, nguyên anh hóa thân của Thanh Nguyên Tử tiếp khách vì chủ nguyên anh đang bế quan tham ngộ đại thần thông, còn Nghiên Lệ kinh ngạc khi biết Hàn Lập đã đạt Hợp Thể trung kỳ. Hàn Lập giao trữ vật thủ trạc chứa đủ mười phần tài liệu quý hiếm, vượt mức cần thiết và giúp Thanh Nguyên Tử tăng thêm hai thành nắm chắc trong lần độ kiếp kế tiếp. Khi Thanh Nguyên Tử đề nghị đổi sang vật khác, Hàn Lập vẫn kiên quyết yêu cầu Minh Hà thần nhũ vì vật này rất quan trọng đối với việc tiến giai. Thanh Nguyên Tử phải thừa nhận phần linh nhũ của mình đã được một thái thượng trưởng lão Phù Du tộc mượn dùng gấp. Cuối cùng, lão quyết định tự mình bái phỏng những đại năng đang giữ phần linh nhũ còn lại và cam kết sẽ bồi hoàn thỏa đáng nếu không thể lấy được."},{"chuong":1859,"tieuDe":"Bái Phỏng","tomTat":"Thanh Nguyên Tử quyết định phải dùng bản thể đích thân đi gặp người nắm giữ linh nhũ và bảo Hàn Lập chờ từ ba tháng đến nửa năm. Biết Hàn Lập đã tái luyện bảy mươi hai thanh phi kiếm, tu tới Thanh Bàn kiếm trận và đạt Hợp Thể trung kỳ, lão hứa truyền thêm sở ngộ về Thanh Nguyên kiếm quyết cùng kinh nghiệm tiến lên hậu kỳ. Trong lúc chờ đợi, Hàn Lập gặp lại Nguyên Dao và Nghiên Lệ, biết hai nữ đã có phương pháp dần thoát khỏi bán quỷ thân nhưng còn cần hai ba ngàn năm để khôi phục hoàn toàn. Hắn kể có chọn lọc những trải nghiệm kể từ khi rời Minh Hà chi địa, rồi dành ba tháng tiếp nhận sự chỉ điểm của nguyên anh hóa thân Thanh Nguyên Tử. Khi bản thể Thanh Nguyên Tử xuất quan, hai người lên đường tìm một đại năng cổ xưa dường như do dị thú tu luyện thành công, từng chịu nhân tình của lão và đang nắm giữ linh nhũ. Sau mười ngày phi hành, họ vượt qua hồ lớn phủ sương xám, nơi có vô số ngư yêu sở hữu pháp lực. Cuối cùng, hai người tới một kim đảo có cung điện lớn, kỳ hoa dị quả và nhiều lớp cấm chế, được Thanh Nguyên Tử xác nhận là nơi ở của người cần bái phỏng."},{"chuong":1860,"tieuDe":"Kim Diễm Hậu","tomTat":"Hàn Lập theo Thanh Nguyên Tử tới Kim Diễm Đảo, nơi cả hòn đảo lẫn cung điện đều rực sắc vàng theo sở thích của chủ nhân. Thanh Nguyên Tử dùng cự kiếm kim sắc đánh động quầng sáng phòng hộ, khiến bốn kim giáp vệ sĩ xuất hiện rồi mở đường dẫn hai người vào gặp Kim Diễm Hậu. Vị chủ đảo Đại Thừa nhận ra lai lịch của Hàn Lập và nghe Thanh Nguyên Tử xác nhận hắn chỉ là cố nhân cùng thuộc Nhân tộc, không phải đệ tử. Thanh Nguyên Tử sau đó đưa Cửu Đồng Châu ra, đề nghị đổi lấy ba bình Minh Hà chi nhũ cùng một khối Tức Nhưỡng chi thổ. Kim Diễm Hậu coi trọng Cửu Đồng Châu nhưng từ chối vì muốn giữ Tức Nhưỡng chi thổ để luyện bảo vật hộ thân cho lần đại thiên kiếp kế tiếp. Để tăng sức nặng cho giao dịch, Thanh Nguyên Tử đưa thêm ba khối Kim Cương Diệt ma thần lôi do mình hao phí hàng trăm năm luyện từ lá Kim Lôi Trúc và nhiều tài liệu lôi thuộc tính. Khả năng khắc chế Vực Ngoại Thiên Ma của số lôi châu này khiến Kim Diễm Hậu rúng động, nhưng quyết định cuối cùng của ông vẫn chưa được công bố."},{"chuong":1861,"tieuDe":"Khách Đến","tomTat":"Hàn Lập nhận ra ba viên Kim Cương Diệt Ma Lôi được luyện từ lá Kim Lôi Trúc mà hắn từng tặng Thanh Nguyên Tử, đồng thời xác định loại thần lôi này chuyên đối phó Vực Ngoại Thiên Ma. Thanh Nguyên Tử dùng ba viên thần lôi thuyết phục Kim Diễm Hậu trao Tức Nhưỡng Chi Thổ cùng Minh Hà thần nhũ, qua đó hoàn tất cuộc giao dịch. Sau khi kiểm tra vật phẩm, Thanh Nguyên Tử chuyển cả ba bình thần nhũ cho Hàn Lập để chuẩn bị đột phá bình cảnh Hợp Thể. Đúng lúc mọi người định rời đi, cấm chế bảo vệ Kim Diễm Đảo bị ngoại lực đánh tan và Hư Linh lên tiếng ép Thanh Nguyên Tử cùng Kim Diễm Hậu ra gặp. Hàn Lập theo hai vị Đại Thừa ra ngoài, nhìn thấy Hư Linh đứng trên đầu một con bọ cánh cứng đen khổng lồ, còn ba kim giáp vệ sĩ đã bị tơ trắng trói chặt. Hư Linh thừa nhận đã đi qua các động phủ quanh vùng và phá nơi ở của những người đang bế quan để buộc họ xuất hiện."},{"chuong":1862,"tieuDe":"Hỉ Nộ Vô Thường","tomTat":"Hư Linh thu hồi con bọ cánh cứng rồi ngang nhiên vào cung điện của Kim Diễm Hậu, khiến nàng phải giải cứu ba Kim giáp sĩ và sai họ tu sửa cấm chế. Trong đại sảnh, lão nhìn thấu Hàn Lập chưa tới hai nghìn tuổi nhưng đã đạt Hợp Thể trung kỳ, sau đó mời hắn làm khách khanh trưởng lão của Phù Du tộc. Hàn Lập từ chối vì muốn trở về cùng Nhân tộc gánh chịu đại kiếp sắp tới, khiến Hư Linh nổi giận và dùng khí thế trấn áp hắn. Hàn Lập dựa vào thân thể cường đại chống đỡ trong khi chiếc ghế bên dưới bị nghiền thành bột, cho tới khi Thanh Nguyên Tử phóng kim hà hóa giải áp lực. Thanh Nguyên Tử tiếp tục từ chối lời đề nghị luận bàn và xin Hư Linh không làm khó hậu bối cùng tộc. Sau đó, Hư Linh tiết lộ mục đích thật sự của chuyến đi là dùng Ngũ nguyên đan cùng trứng Vạn khôn trùng đổi lấy toàn bộ Minh Hà Chi Nhũ. Kim Diễm Hậu cho biết số linh nhũ trong tay mình đã được giao dịch với Thanh Nguyên Tử."},{"chuong":1863,"tieuDe":"Thực Tiên Đan","tomTat":"Hư Linh muốn đổi lấy Minh Hà thần nhũ và sẵn sàng trả giá gấp đôi, nhưng Thanh Nguyên Tử khẳng định linh nhũ đã được tặng cho Hàn Lập để báo đáp đại ân. Hư Linh chuyển sang đưa ra hàng chục bình linh đan tăng tiến tu vi Hợp Thể, trong đó có Thanh Ảnh đan, song Hàn Lập vẫn từ chối vì bản thân không thiếu đan dược. Để chứng minh, Hàn Lập lấy ra Thực Tiên đan khiến Hư Linh nhận ra nó được luyện từ Thực Độc tiên thảo đã sớm tuyệt diệt. Hư Linh còn tiết lộ độc tính của linh thảo này có thể được tinh luyện thành Thực Độc tiên dịch để cưỡng ép xung kích bình cảnh Đại Thừa, nhưng phương pháp có tỷ lệ thành công thấp, nguy cơ tử vong cao và gây tổn hao nguyên khí nghiêm trọng. Khi linh đan không thể khiến Hàn Lập động tâm, Hư Linh lấy ra hàng trăm đỉnh giai linh bảo và cho phép hắn chọn ba món. Kim Diễm Hậu nhận định thân gia Hàn Lập rất phong phú nên thúc Hư Linh đưa ra những bảo vật quý hiếm chân chính hơn."},{"chuong":1864,"tieuDe":"Lại Thấy Huyền Thiên Chi Bảo Tàn Phiến","tomTat":"Hư Linh lấy ra một tàn phiến Huyền Thiên chi bảo có hình lư hương, rồi kích hoạt một phần uy lực khiến thiên địa chi lực bao phủ đại sảnh và làm Hàn Lập chao đảo. Lão cho biết mình tìm được vật này tại một chiến trường cổ sâu trong Man hoang thế giới, sau đó phải hao phí nhiều tài lực luyện chế lại mới có thể khu sử. Thanh Nguyên Tử nhận định tàn phiến có thể tăng cơ hội độ kiếp cho Hư Linh, nhưng lão vẫn không muốn mạo hiểm phi thăng nếu không đủ sức vượt qua đại thiên kiếp. Cuộc trò chuyện chuyển sang một Huyền Thiên chi bảo mới từng xuất hiện trên Hỗn Độn Vạn Linh bảng nhưng đã mất dấu dù Giác Xi tộc, Hải tộc và các trưởng lão Phù Du tộc đều tìm kiếm. Hàn Lập chấn động trong lòng khi nghe chuyện nhưng không để lộ quan hệ với bảo vật, đồng thời tiếp tục từ chối đổi Minh Hà linh nhũ. Để chứng minh mình không thiếu bảo vật, hắn lấy ra một cây thước bạc thuộc hàng Thông thiên linh bảo và thúc động vô số thước ảnh. Sau hai lần giao dịch thất bại, Hư Linh tuyên bố sẽ dùng một phương pháp khác khiến Hàn Lập không thể cự tuyệt."},{"chuong":1865,"tieuDe":"Phệ Kim Trùng Cùng Phệ Kim Trùng","tomTat":"Hư Linh xác nhận thân phận Thái thượng trưởng lão Phù Du Tộc và đề nghị đổi phương pháp nuôi dưỡng tám mươi mốt loại linh trùng cùng các kỳ trùng mạnh lấy Minh Hà linh nhũ. Lão lần lượt đưa Tử Điện Trùng và Địa Giao Trùng có chiến lực tương đương tu sĩ Hợp Thể sơ kỳ ra làm điều kiện, nhưng Hàn Lập từ chối vì đã sở hữu hàng vạn Phệ Kim Trùng. Khi Hư Linh nổi giận và phô bày thêm Kim Cương Trùng, Sát Tàm cùng Huyết Đường Lang, Thanh Nguyên Tử đứng ra hòa giải và đề nghị Hàn Lập chứng minh lai lịch linh trùng của mình. Hàn Lập thả hơn mười Phệ Kim Trùng trưởng thành, khiến Kim Diễm Hậu kinh ngạc và Hư Linh vui mừng khác thường. Hư Linh sau đó thu hồi đàn kỳ trùng, dùng hồ lô bạc phóng ra một con Phệ Kim Trùng trưởng thành có khí tức hung dữ hơn hẳn đàn của Hàn Lập. Lão tiết lộ mình cần nhiều Minh Hà linh nhũ chính là để dùng cho con linh trùng này, khiến Hàn Lập lập tức truy hỏi tác dụng của linh nhũ đối với Phệ Kim Trùng."},{"chuong":1866,"tieuDe":"Phệ Kim Trùng Vương","tomTat":"Hư Linh lão giả giải thích Minh Hà linh nhũ không giúp Phệ Kim Trùng chưa trưởng thành, nhưng lại có thể hỗ trợ thành thục thể tiến thêm một cấp và được dùng để đào tạo Trùng Vương. Lão nhường phần linh nhũ cho Hàn Lập rồi gọi Hắc Phong Các ra, đưa hắn vào không gian phong bế để tiến hành một cuộc thương lượng bí mật. Ở bên ngoài, Kim Diễm Hậu lo Hàn Lập có thể gặp nguy hiểm, còn Thanh Nguyên Tử khẳng định sẽ chiếu cố hắn trong giới hạn không buộc mình đối đầu trực tiếp với Hư Linh lão giả. Bên trong lầu các, Hư Linh lão giả xác nhận Hàn Lập có hơn năm nghìn Phệ Kim Trùng trưởng thành và đề nghị đổi lấy ít nhất năm nghìn con. Hàn Lập không muốn giao đàn linh trùng do chính mình bồi dưỡng, bởi hắn dự định dùng chúng làm át chủ bài sau khi tiến giai Đại Thừa. Sau khi buộc đối phương nói rõ mục đích, Hàn Lập biết Hư Linh lão giả đã có năm nghìn thành thục thể và muốn gom thêm số lượng tương ứng để đào tạo Phệ Kim Trùng Vương. Cuộc giao dịch chưa hoàn tất, nhưng bí mật rằng Trùng Vương có thể được đào tạo bằng lượng lớn thành thục thể hoặc Minh Hà linh nhũ đã được hé lộ."},{"chuong":1867,"tieuDe":"Dục Trùng Bí Thuật","tomTat":"Hư Linh lão giả giải thích rằng việc đào tạo Phệ Kim trùng vương cần một lượng lớn Phệ Kim trùng cắn nuốt lẫn nhau, nhưng ngay cả lão cũng chỉ nắm chắc hai thành thành công. Hàn Lập dùng năm nghìn Phệ Kim trùng thành thục thể đổi lấy năm bình Minh Hà linh nhũ và bản đầy đủ Dục Trùng Bí Thuật, đồng thời phát Tâm Ma Thệ không truyền bí thuật cho người khác. Sau khi nhận ngọc giản, hắn nhận ra truyền thừa này có thể giải đáp nhiều nghi vấn trước đây về khu trùng thuật. Hư Linh thực chất không tin Hàn Lập có thể đào tạo thành công trùng vương mà muốn dùng đàn trùng vừa nhận để luyện Vạn Linh Tán, vì vậy lão đóng băng và dán phù lên Linh Thú Hoàn để phong giữ chúng. Rời cuộc tụ hội của Kim Diễm, Hàn Lập theo Thanh Nguyên Tử trở về động phủ. Gần tới nơi, Thanh Nguyên Tử tuyên bố đã trả hết nhân tình, quyết định phong sơn chuẩn bị đại thiên kiếp và buộc Nguyên Dao bế quan cho tới khi tiến giai Hợp Thể."},{"chuong":1868,"tieuDe":"Môn Nhân","tomTat":"Hàn Lập chấp nhận đề nghị của Thanh Nguyên Tử, không trở lại động phủ gặp Nguyên Dao mà nhờ chuyển lời cáo biệt rồi trực tiếp rời Minh Hà chi địa. Với tu vi Hợp Thể trung kỳ, hắn tự phá mở khe nứt không gian; sau khi hắn đi, Thanh Nguyên Tử nhận định số Minh Hà linh nhũ vừa thu được đủ giúp hắn tiến vào Hợp Thể hậu kỳ và hy vọng sau này có thể mượn sức hắn nếu hắn đạt Đại Thừa. Hơn ba trăm năm trôi qua, lời cảnh báo của Thánh đảo khiến toàn bộ tam cảnh Nhân tộc bước vào trạng thái tổng động viên trước ma kiếp, với thành lũy, giáp sĩ, pháp trận, lực lượng luyện thể và kho tài nguyên được mở rộng mạnh mẽ. Thiên Uyên thành, Tam Đại Hoàng thành, mười đại tông môn cùng tam đại gia tộc Chân Linh trở thành những trung tâm tập trung dân cư và lực lượng phòng thủ, trong khi Yêu tộc cùng các ngoại tộc lân cận cũng động viên và trao đổi tin tức. Tại một vùng núi gần Thiên Uyên thành, Bạch Quả Nhi thay Khí Linh Tử và Hải Đại Thiếu giảng pháp cho khoảng ba bốn trăm môn nhân. Nhờ Thần Dẫn Đại Pháp và số đan dược Hàn Lập để lại, hàng môn nhân tiến bộ nhanh chóng, trong đó đã có vài người đạt Kết Đan. Ba ký danh đệ tử của Hàn Lập vẫn giữ diện mạo gần như trước kia nhưng thần thái và khí tức đã biến đổi rõ rệt."},{"chuong":1869,"tieuDe":"Ma Ban Hàng Thế","tomTat":"Bạch Quả Nhi, Hải Đại Thiếu và Khí Linh Tử bàn về việc Hàn Lập đã bế quan suốt hai trăm năm sau khi trở về từ Man Hoang thế giới, có thể để trùng kích Hợp Thể Hậu kỳ hoặc tu luyện một đại thần thông. Trước nguy cơ Ma Kiếp, Khí Linh Tử và Hải Đại Thiếu dự định đưa môn hạ vào Thiên Uyên Thành, còn Bạch Quả Nhi quyết định trở về Huyền Vũ hoàng thành với gia đình. Một Ma ban khổng lồ bất ngờ xuất hiện trên trời, báo hiệu Ma giới đã bắt đầu xâm thực Linh giới và Ma tộc có thể hàng lâm sau ít nhất nửa năm. Vệ sĩ Thiên Uyên Thành nhanh chóng dùng phi chu đến nơi, triển khai trận kỳ, trận bàn và pháp khí quanh Ma ban. Ba đệ tử lập tức trở về động phủ để báo tin cho Hàn Lập. Trong mật thất, ba phân thân Hàn Lập đang vây quanh cự đỉnh, thả ra hơn mười con bọ cánh cứng tử kim hung hãn cắn xé đồng loại rồi đồng loạt thi pháp chế ngự chúng."},{"chuong":1870,"tieuDe":"Hậu Tuyển Trùng Vương","tomTat":"Trong mật thất, Hàn Lập dùng nhiều thủ đoạn luyện hóa và kiểm nghiệm mười ba Tử Văn Phệ Kim Trùng, nhưng cả Ích Tà Thần Lôi lẫn kiếm tơ từ bảy mươi hai thanh tiểu kiếm đều không thể làm chúng bị thương. Khi đàn trùng lao về phía ba thân ảnh của hắn, Hàn Lập dùng ngôn quyết làm chúng mất thăng bằng rồi điều khiển cự đỉnh màu xanh thu toàn bộ trở lại. Hắn nhận thấy phương pháp khống chế ban đầu đã suy yếu theo mức trưởng thành của linh trùng và quyết định phải tiến hành lại nghi thức nhận chủ. Chương truy lại quá trình Hàn Lập trở về Nhân tộc, triệu tập ba đệ tử, bố trí cấm chế và bế quan chuẩn bị cho Ma Kiếp bằng việc tăng tiến tu vi cùng đào tạo Phệ Kim Trùng Vương. Trong hơn hai trăm năm, hắn cải biến bí thuật của Phù du tộc bằng kinh nghiệm bản thân, bình nhỏ thần bí và Ích Tà Thần Lôi, khiến mấy vạn Phệ Kim Trùng biến dị cắn nuốt lẫn nhau. Cuối cùng chỉ còn mười ba Tử Văn Phệ Kim Trùng có sức liên thủ đủ chế trụ tu sĩ Hợp Thể trung kỳ, nhưng quá trình sinh Trùng Vương vẫn bế tắc vì chúng có thực lực ngang nhau và không con nào thôn phệ được con khác."},{"chuong":1871,"tieuDe":"Mê Ảnh Nơi Biển Sâu","tomTat":"Hàn Lập tiếp tục rèn luyện hơn mười Phệ Kim trùng có tử văn vì chưa tìm được cách khiến chúng cắn nuốt lẫn nhau để sinh ra Trùng Vương. Sau hai trăm năm dùng Minh Hà linh nhũ và đan dược, thể chất cùng tốc độ chuyển hóa thiên địa nguyên khí của hắn tăng mạnh, pháp lực cũng tiến gần Hợp Thể hậu kỳ. Một hỏa cầu truyền tin báo Ma Ban đã xuất hiện sớm khiến hắn hợp nhất với hai thân ảnh, thu cự đỉnh và rời mật thất. Tại một sơn mạch sâu trong Man Hoang, bạch y thanh niên hóa thành ngô công trắng sáu cánh, dùng hàn diễm giết rồi nuốt song đầu cự nhân cùng hai xích mãng. Hắn sau đó phát hiện Tử Âm Quáng Mạch trong lòng cự phong và tiến vào khai thác vì quáng mạch có thể thúc đẩy Chân Linh Chi Khu đại thành. Ở một cung điện dưới biển sâu, huyết kén bất ngờ nổ tung, để lộ thanh niên mang minh ấn liên hoa vàng cùng hai luồng hỏa diễm kim ngân trong mắt. Khi tỉnh lại, thanh niên này chú ý tới thủy tinh cầu đang hiển thị hình ảnh một đài sen ngân quang sống động."},{"chuong":1872,"tieuDe":"Mộc Tộc Đại Thừa","tomTat":"Thanh niên tuấn mĩ hoàn tất pháp thể trọng sinh trong cung điện dưới đáy biển, thu thủy tinh cầu vào cơ thể và thề truy sát kẻ đã lấy vật từng khiến mình suýt ngã xuống tại Tiên giới. Hắn phá hủy toàn bộ cung điện rồi bay thẳng về phía Phong Nguyên Đại Lục. Tại thánh địa Mộc tộc, một bạch y nữ tử cảnh giới Đại Thừa cùng hắc giáp đại hán đã lấy hơn mười đóa Hắc Linh Hoa và bị Đại trưởng lão họ Ô dẫn người chặn lại. Hai cường giả tiến vào khe hở không gian do Đại trưởng lão mở ra để giao đấu, còn Mộc Quân và Mộc Giảo bao vây thuộc hạ của nữ tử. Sau khoảng một tuần trà, Đại trưởng lão trở ra với sắc mặt tái nhợt, trong khi bạch y nữ tử vẫn hoàn toàn thong dong. Biết mình không phải đối thủ, ông ra lệnh toàn tộc không được ngăn cản hai kẻ xâm nhập rời đi. Mộc Giảo sau đó vận Thanh Linh Tuệ Nhãn đến cực hạn nhưng vẫn không nhìn thấu bản thể nữ tử, khiến thân phận và mục đích của nàng trước thềm Ma Kiếp tiếp tục là bí ẩn."},{"chuong":1873,"tieuDe":"Nương Tựa","tomTat":"Sau khi nghe nữ tử Mộc tộc báo cáo, Đại trưởng lão Mộc tộc dựa vào quan hệ đối địch giữa Giao Long tộc và Chân Ma tộc để phán đoán lai lịch Tiểu Ngạc, nhưng không biết hắn thực chất là hậu duệ Tà Long tộc. Bảo Hoa giải thích rằng Hắc Linh Hoa chỉ có tác dụng trong giới hạn mười đóa và nàng tuy có thể đánh bại Đại trưởng lão Mộc tộc nhưng chưa chắc giết được lão. Do bí thuật chỉ ra vật cần tìm có hy vọng xuất hiện tại Phong Nguyên đại lục, nàng quyết định ở lại và cùng Tiểu Ngạc bay về hướng Nhân tộc. Tại động phủ gần Thiên Uyên Thành, Hàn Lập nhận định Ma Kiếp sẽ bùng phát sau nửa năm nên ra lệnh đưa toàn bộ môn hạ vào thành, còn bản thân dự tính chỉ trợ chiến qua vài đợt rồi tiếp tục ẩn tu để chuẩn bị trùng kích Hợp Thể hậu kỳ. Băng Phượng đồng ý chuyển đi và tái khẳng định sẽ giúp hắn vượt bình cảnh, trong khi Bạch Quả Nhi được phép tới Huyền Vũ thành sau khi thu xếp môn hạ. Ba ngày sau, Hàn Lập dẫn mấy trăm người rời động phủ bằng cự thuyền. Cùng lúc đó, Huyết Linh huy động hàng trăm chiến thuyền đưa hàng nghìn người Hứa gia bỏ gia nghiệp tới Thiên Nguyên Thành nương tựa, còn nhiều gia tộc Nhân tộc khác cũng bắt đầu chạy nạn. Hai tháng sau, lão tăng áo vàng cùng hơn mười tu sĩ đứng trên tường thành Thiên Uyên Thành chờ đón cự thuyền của Hàn Lập và những đoàn chiến thuyền đang lần lượt xuất hiện."},{"chuong":1874,"tieuDe":"Cứ Điểm Của Thế Gia","tomTat":"Hàn Lập đưa khoảng một nghìn môn nhân trở lại Thiên Uyên Thành và được Kim Việt thiền sư xác nhận đã đạt Hợp Thể trung kỳ. Sau khi môn nhân được thu xếp chỗ ở, hắn gặp các trưởng lão Hợp Thể, hỏi Ngân Quang tiên tử về Ngân Nguyệt và biết nàng vẫn bình an, hiện đã tiến giai Luyện Hư hậu kỳ. Hàn Lập đồng ý trợ giúp Thiên Uyên Thành chống những đợt công kích đầu tiên của Ma tộc, đổi lại các trưởng lão sẽ che chở cho môn nhân của hắn trong Ma Kiếp. Hai ngày sau, hắn gặp riêng Ngân Quang tiên tử tại động phủ nhưng rời đi với sắc mặt âm trầm, còn nội dung cuộc trao đổi không được tiết lộ. Hơn mười ngày sau, Hàn Lập dặn dò ba đệ tử rồi dùng pháp trận truyền tống rời thành để hoàn thành một việc trước khi Ma Kiếp bộc phát. Sau khoảng hai tháng, hắn tới sơn mạch nơi Lũng gia liên kết hơn mười thế gia xây dựng cứ điểm phòng thủ và biết Lũng gia lão tổ dự định tiến vào Ma giới trước khi Ma Kiếp kết thúc. Hàn Lập kích phát một tấm phù vàng truyền tin rồi hạ xuống ngọn núi gần đó để chờ đợi."},{"chuong":1875,"tieuDe":"Giao Dịch","tomTat":"Lũng gia lão tổ rời đại thành nghênh tiếp Hàn Lập, xác nhận hắn đã đạt Hợp Thể trung kỳ và hỏi lại quyết định về hành trình Ma giới. Hàn Lập khẳng định sẽ tham gia, sau đó đề nghị dùng Minh Hà linh nhũ để đổi Long Linh đan cùng Kình Thiên Cự Chu phỏng chế. Lũng gia lão tổ công nhận linh nhũ hữu dụng với bình cảnh Hợp Thể hậu kỳ nhưng cho rằng giá trị chưa đủ, khiến hai bên phải tiếp tục mặc cả. Hàn Lập giả vờ hủy giao dịch rồi đưa thêm nhóm tài liệu quý hiếm trị giá hơn một ức linh thạch, buộc đối phương chấp thuận điều kiện. Hai bên hoàn tất trao đổi, Hàn Lập nhận một lọ Long Linh đan và chiến thuyền thu nhỏ, còn Lũng gia lão tổ nhận linh nhũ cùng tài liệu. Sau khi xác định Long Linh đan có thể tăng thêm nửa thành tỷ lệ đột phá bình cảnh hậu kỳ, Hàn Lập ném Kình Thiên Cự Chu lên không trung để bắt đầu thử uy năng."},{"chuong":1876,"tieuDe":"Ma Dơi (1)","tomTat":"Kình Thiên Cự Thuyền được phóng lớn, để lộ ba cột buồm, vô số pháp trận cùng ba tinh trụ ngũ sắc khổng lồ. Lũng gia lão tổ nhận linh nhũ và vòng tay trữ vật, còn Hàn Lập thu nhỏ chiến thuyền rồi cất vào tay áo, chính thức hoàn tất giao dịch. Hàn Lập cam kết sẽ tham gia chuyến đi Ma giới khi được báo tin tại Thiên Uyên Thành. Trước khi rời đi, hắn nhìn thấu một nam tử áo bào đen đang ẩn mình trong hư không, khiến vị Thái Thượng Trưởng Lão Lũng gia này phải thừa nhận năng lực dò xét của hắn vượt ngoài dự liệu. Lũng gia lão tổ quyết định tiếp tục trọng dụng Hàn Lập và xem chuyến đi Ma giới là cơ hội quyết định để vượt khỏi Hợp Thể kỳ. Ông cũng cho biết đã tập hợp mười ba thế gia xây dựng một cứ điểm công thủ tương trợ. Nam tử áo bào đen kết luận rằng Ma chướng đang lan rộng và Chân Ma tộc có thể phá giới sau khoảng ba, bốn tháng."},{"chuong":1877,"tieuDe":"Ma Dơi (2)","tomTat":"Sau khi chia tay Lũng gia lão tổ và hắc bào nam tử, Hàn Lập mất hơn hai tháng dùng các pháp trận truyền tống để trở về Thiên Uyên Thành. Thành trì đã giới nghiêm, mở toàn bộ cấm chế và hạn chế quyền sử dụng truyền tống trận nhằm chuẩn bị cho Ma kiếp. Hàn Lập giao Kình Thiên Cự Thuyền cho Hải Đại Thiếu cùng các môn nhân, yêu cầu họ tập hợp mấy trăm người luyện cách điều khiển bảo vật làm át chủ bài bảo toàn tính mạng. Hắn tiếp tục bế quan trên tầng cao nhất của tòa tháp nhưng dặn đệ tử báo cáo tình hình ma chướng mỗi ngày. Ngoài thành, Kim đạo hữu, Trần huynh và các hắc giáp vệ sĩ đóng quân trên hai chiếc thuyền vàng để giám sát một vùng ma chướng. Khi họ đang bàn về nguy hiểm và phần thưởng nhiệm vụ, hư không phía dưới ma chướng đột ngột rung chuyển dữ dội. Sau một tiếng nổ lớn, vô số Ma Dơi lông đỏ, đầu mọc sừng đen tràn ra, phát tiếng gào tạo thành sóng âm khiến hư không dao động."},{"chuong":1878,"tieuDe":"Thiếu Niên Cùng Cự Hán","tomTat":"Sóng âm làm không trung phía trên ma chướng vỡ tung, khiến ma khí, Ma dơi và nhiều ma thú bắt đầu tràn vào Linh Giới. Hai tu sĩ Luyện Hư kỳ Nhân tộc cùng các hắc giáp vệ sĩ lập tức khởi động pháp trận truyền tống trên hai Kim Chu để rút lui. Bức Liệt bất ngờ tập kích, dùng âm ba kim sắc vô hiệu hóa bổn mạng tiểu kiếm rồi xuyên thủng chiến giáp giết kim giáp đại hán, sau đó tiêu diệt toàn bộ vệ sĩ trên cùng thuyền. Lão giả thấp bé vẫn kịp truyền tống chiếc Kim Chu còn lại thoát khỏi đòn truy kích. Mông Man của Lôi Ngưu tộc xuất hiện và cho biết tộc mình cũng thuộc nhóm đầu được thánh tổ điều vào Linh Giới. Hắn cùng Bức Liệt lập cược trong ba ngày xem tộc nào giết được nhiều tu sĩ Nhân tộc hơn, lấy ba thành thu hoạch tại Linh Giới làm tiền cược. Cuối cùng, Bức Liệt triệu tập Ngũ Bức và ra lệnh bắt một số phàm nhân Nhân tộc."},{"chuong":1879,"tieuDe":"Quần Ma Sơ Hiện","tomTat":"Sau khi Ngũ Bức nhận lệnh rời đi, thủ lĩnh Lôi Ngưu dùng Tù Và màu vàng kim triệu tập hàng nghìn Lôi Ngưu, còn thủ lĩnh Huyết Bức chia đàn thú của mình thành hơn mười đội tiến về nhiều hướng. Vệ huynh xuất hiện cùng khoảng năm sáu nghìn Tam Nhãn Ma Mãng và bổn mạng thần mãng đã tiến giai tới mức được đánh giá ngang thánh giai sơ kỳ. Hồn Châu đồng ý liên thủ với hắn, triệu tập khoảng bảy tám chục vạn ma trùng rồi dẫn trùng hải đuổi theo đàn mãng xà xuống đất. Sau đó, nhiều Ma tộc cao cấp tiếp tục dẫn các đàn ma thú vượt khỏi ma khí, tạo thành khoảng mười ba đợt thú triều phân tán khắp nơi. Ma hải trên trời cao mở rộng, hàng trăm cự tháp hình tam giác vượt giới hàng lâm và chống lại điện hồ không gian bằng phù văn bạc. Từ các cự tháp, chiến chu màu đen, giáp sĩ có cánh và đông đảo ma nhân liên tục được triển khai. Một số ma nhân biến thành hình thái hai đầu bốn tay, gầm rú đầy hưng phấn và bộc lộ sát ý, đánh dấu đại quân Ma tộc đã chính thức tiến vào Linh Giới."},{"chuong":1880,"tieuDe":"Ma Triều Mãnh Liệt","tomTat":"Giữa đoàn Ma tộc vừa tới Linh Giới, Sa huynh và Tam Dương huynh bàn về cơ hội chiếm giữ vùng đất này cũng như khả năng những tu sĩ phi thăng từ Nhân giới được lưu lại nếu lập đại công. Hàng ngàn Thạch Ma sau đó dựng tường, hóa đất thành đá, còn quỷ ảnh và cao giai Ma tộc bố trí pháp trận cùng cấm chế để hoàn thành một đại thành dưới ma hải. Huyết Quang giáng lâm trên tế đàn, dùng Ô trượng đầu quỷ thân giao giải phóng ma khí phủ toàn thành, giúp quân Ma tộc hồi phục pháp lực và thể lực nhanh hơn. Hắn ra lệnh xây thêm ba Thánh thành trong ba ngày, tập kết đầy đủ lực lượng sau bảy ngày rồi tiến đánh cứ điểm Nhân tộc lớn nhất ở gần đó. Hoạt động dựng thành tương tự đồng loạt xuất hiện tại nhiều Ma chướng trong địa bàn Nhân tộc và Yêu tộc, khiến các phòng tuyến bắt đầu chịu áp lực trực tiếp. Một tăng một đạo ngoài Thiên Nguyên Thánh thành phải rút về Thiên Nguyên Hoàng Thành khi phát hiện cao giai Ma tộc kéo tới. Trên lãnh địa Yêu tộc, đại quân sói u âm và bạch ưng cũng đã giao chiến dữ dội với ma sư lam sắc cùng song đầu phi xà."},{"chuong":1881,"tieuDe":"Ma Tới Dưới Thành","tomTat":"Trên các chiến trường, Yêu tộc Hóa Hình và cao giai Ma tộc đứng ngoài kiềm chế nhau, còn một cự thú màu xanh dưới vùng biển quanh cự đảo trồi lên nuốt sạch hàng nghìn ma thú. Tại tháp trắng, Hàn Lập kiểm nghiệm kim sắc hồ lô cùng bộ phi kiếm ngũ hành vừa được hoàn thiện từ các tài liệu quý hiếm. Hắn tiếp tục vận dụng Phá Diệt Pháp Mục và phương pháp tế luyện đặc thù để điều khiển hơn vạn kiếm ảnh trong Vạn Kiếm Đồ, nhưng bảo vật mất linh quang khiến lần thử thất bại. Qua đó, Hàn Lập xác định kiếm khí Chân tiên giới trong đồ có thể uy hiếp tu sĩ Hợp Thể, song mỗi lần sử dụng đều làm hao tổn kiếm khí và đẩy kiếm đồ tới chỗ bị hủy. Hải Đại Thiếu sau đó truyền tin Trưởng lão hội triệu Hàn Lập tới Quan Thiên Thai vì Ma tộc cùng cao giai Ma tộc đã tới dưới thành. Hàn Lập lập tức thu bảo vật và trở về Thiên Uyên thành, nơi toàn bộ lực lượng phòng thủ đang được triển khai giữa ma khí và tiếng trống trận. Kim sắc cổ kính trên bảo tháp chiếu sáng hơn nửa thành, khiến lực sĩ và tu sĩ Nhân tộc phấn chấn tinh thần, tăng thêm dũng khí nghênh chiến."},{"chuong":1882,"tieuDe":"Nhân Ma Chi Chiến (1)","tomTat":"Hàn Lập đến Quan Thiên Thai, hội kiến Kim Việt thiền sư cùng các trưởng lão Thiên Uyên thành và quan sát đại quân Ma tộc đang tập kết ngoài thành. Lực lượng đối phương gồm vô số ma thú, năm siêu đại ma thú và hơn vạn Ma nhân có pháp lực tương đương Hóa Thần hoặc Luyện Hư, nhưng Cốc trưởng lão nhận định đây vẫn chưa phải toàn bộ tinh nhuệ Ma tộc. Các trưởng lão cho rằng lần ma kiếp này khác thường, song vẫn tin tưởng hệ thống thành lũy, cấm chế và pháp trận được chuẩn bị gần ngàn năm; họ cũng tiết lộ Linh Hoàng Thành mới là hướng chịu áp lực chính. Hàn Lập dùng Linh Mục dò vào ma khí nhưng bị thần nhãn của Mạc Lục phát hiện, trong khi cấm chế của cả hai phía đều ngăn đối phương nhìn rõ bố trí thật sự. Phía Ma tộc, Mạc Lục cho biết đã dùng Hỗn Ma Kỳ che giấu quân lực, còn Thạch tôn giả xác nhận hai người chỉ phụ trách hư trương thanh thế theo kế hoạch của Thánh tổ. Thạch tôn giả quyết định phát động một đợt công kích để buộc Thiên Uyên thành bộc lộ phần lớn thủ đoạn phòng ngự. Hắn kích hoạt hai lá cờ đen, điều động Song Đầu Ma Tích và Độc Dịch Ma Trùng lao về phía thành, khiến Cốc trưởng lão lập tức ra lệnh cho tuyến trước tăng cường đề phòng."},{"chuong":1883,"tieuDe":"Nhân Ma Chi Chiến (2)","tomTat":"Kim Việt thiền sư và Cốc trưởng lão nhận diện quân tiên phong Ma tộc gồm Song Đầu Ma Tích cùng Độc Dịch Ma Trùng, trong khi quân phòng thủ tại hàng nghìn thành lũy quanh Thiên Uyên thành chuẩn bị ứng chiến. Khoảng ba bốn vạn ma thú dưới sự đốc chiến của hơn trăm Ma tộc cấp cao tràn tới, rồi đàn Song Đầu Ma Tích đồng loạt phóng Hỏa cầu và Phong nhận thành một đợt sóng phong hỏa dữ dội. Cốc trưởng lão vận dụng Kim Húc Bảo Kính, mượn linh lực Thiên Bảo thần điện tạo quầng sáng kim sắc chặn hoàn toàn đợt oanh kích đầu tiên. Quân Nhân tộc lập tức tế ra hàng nghìn Pháp khí phản công, nhưng Độc Dịch Ma Trùng biến dị phun lục tuyến hóa thành sương độc, làm phần lớn Pháp khí chuyển xanh, mất linh quang và rơi xuống. Từ trong Thú Xa, tử giáp đại hán và lục bào lão giả xác nhận đàn ma thú chỉ là pháo hôi, đồng thời tiết lộ độc dịch còn có khả năng tác động tới pháp trận và cấm chế. Các tu sĩ tại thành lũy chuyển sang dùng trận bàn kích hoạt pháp trận ngũ sắc, trong lúc sóng phong hỏa và hàng nghìn lục tuyến tiếp tục đánh thẳng vào quầng sáng của Kim Húc Bảo Kính."},{"chuong":1884,"tieuDe":"Nhân Ma Chi Chiến (3)","tomTat":"Pháp trận ngân sắc trong các thành lũy kịp thời phát động, dùng điện hồ và hàng rào điện phá tan nhiều loại công kích rồi khiến Ma Tích cùng Độc Trùng tổn thất gần một nửa. Tử giáp Ma tộc lập tức điều động ma thú hai đầu phóng cột sáng xuyên thủng quầng sáng kim sắc, thiêu các tu sĩ trong hàng chục thành lũy thành tro. Ma thú, ma nhân, giáp sĩ và phi xa sau đó đồng loạt tiến quân, nhưng số lượng tinh nhuệ quá ít khiến các tu sĩ Hợp Thể nhận định đây chưa phải tổng công kích. Hàn Lập xin trở về tiếp tục tế luyện một bảo vật đang ở thời điểm mấu chốt và cam kết sẽ trợ chiến khi Thiên Uyên Thành lâm nguy. Cốc trưởng lão bố trí các tu sĩ Hợp Thể luân phiên phòng thủ, đồng thời quyết định dùng một thành uy lực của Thất Tinh Tinh Hỏa đại trận để phản thăm dò mà không để lộ toàn bộ đòn sát thủ. Theo mệnh lệnh truyền xuống cự tháp đỏ đậm, bảy lão giả Luyện Hư kỳ xuất Nguyên Anh và đưa bộ bảy dị bảo cực hỏa vào trung tâm trận đồ, bắt đầu kích phát tinh hỏa lực thất tinh."},{"chuong":1885,"tieuDe":"Nhân Ma Chi Chiến 4","tomTat":"Trên đường trở về, Hàn Lập phát hiện bảy tinh tú đỏ sậm xuất hiện phía trên Thiên Uyên Thành và cảm nhận lực lượng đang hình thành đủ sức uy hiếp tính mạng mình. Bảy tinh tú nhanh chóng hợp thành một trận đồ khổng lồ, hóa ra hư ảnh Hỏa điểu rồi phát động vụ nổ tạo nên cột hỏa vân cao vạn trượng và biển lửa rộng gần ngàn dặm ngoài thành. Ma nhân cùng ma thú cấp thấp gần như bị thiêu sạch; trong năm Cự Ma thú cao cấp, chỉ Hắc sắc Cự cầm và Cự Viên đỏ đậm chạy thoát, còn hai Bạch Sắc Ốc Sên cùng Tam Thủ Tử Mãng đều chết. Thạch tôn giả và Lục bào lão giả thoát khỏi hỏa vân trong tình trạng chật vật, sau đó quyết định trở về phục mệnh dù toàn bộ thuộc hạ đã bị tiêu diệt. Tại một tòa thành Ma tộc ở xa, Huyết bào Nam tử cùng hơn hai mươi Ma tộc cao cấp theo dõi toàn bộ chiến trường qua cặp tinh cầu truyền ảnh. Ban huynh đòi nghiêm trị hai chỉ huy thất trận, còn Huyễn tôn giả cho rằng họ có công phát hiện đòn sát thủ của Nhân tộc. Huyết bào Nam tử chấm dứt tranh cãi và yêu cầu thuộc hạ đánh giá phòng ngự, tìm cách nhanh chóng công phá Thiên Uyên Thành trong lúc những lộ đại quân Ma tộc khác bắt đầu hành động."},{"chuong":1886,"tieuDe":"Nhân Ma Chi Chiến (5)","tomTat":"Tại chiến trường Thiên Uyên Thành, Huyễn Vũ trưởng lão đề xuất dùng đại quân Ma thú luân phiên công kích với sức ép tăng dần để buộc hệ thống phòng ngự của thành bộc lộ, và Huyết Quang chấp thuận kế hoạch tiêu hao này. Theo đề nghị của phụ nhân hoàng bào, Huyết Quang còn điều Già Luân Chiến Ma, Huyết Quang Tinh Vệ và Vạn Tượng Ma Kỵ đi càn quét những cứ điểm Nhân tộc còn lại, bất chấp lời can gián về việc đưa đội thân vệ rời khỏi mình. Ở Linh Hoàng Thành, Lục Cực huy động toàn bộ đại quân Ma tộc và trực tiếp phát lệnh tổng công kích, trong khi một nữ tử cung trang tím đứng bên cạnh nàng với ánh mắt phức tạp. Hàn Lập trở về mật thất tế luyện Vạn Kiếm Đồ và Hồ Lô Kiếm, sau một tháng trao Hồ Lô Kiếm cho Hải Đại Thiếu rồi dành hơn nửa năm nghiên cứu Vạn Kiếm Đồ. Trong thời gian đó, các cứ điểm Nhân tộc quanh Thiên Uyên Thành lần lượt thất thủ, tù binh tu sĩ bị chuẩn bị chuyển hóa bằng Ma Khí Quán Thể và một số cường giả Hợp Thể tử trận trước thuật liên thủ của tinh nhuệ Ma tộc. Sau khi nhận lời mời của Kim Việt Thiền Sư, Hàn Lập tới Trưởng Lão Điện tham gia nghị sự cùng Cốc trưởng lão, Ngân Quang tiên tử và các trưởng lão khác. Cốc trưởng lão cho biết Tứ Đại Tông Môn đang cầu viện vì hơn mười Ma tộc cao cấp đã dụ các Thái Thượng trưởng lão ra ngoài đánh lén, khiến hai người vẫn lạc và Ỷ Thiên Thành đứng trước nguy cơ thất thủ. Nếu không cứu viện cứ điểm này, Thiên Uyên Thành sẽ mất thế hỗ trợ và phải đơn độc chống lại đại quân Ma tộc."},{"chuong":1887,"tieuDe":"Nhân Ma Chi Chiến (6)","tomTat":"Cốc trưởng lão chủ trì hội nghị trưởng lão, xác định Ỷ Thiên Thành là cứ điểm phụ cận còn sót lại cần được cứu viện, nhưng chỉ cử hai ba tu sĩ Hợp Thể để tránh suy yếu phòng thủ Thiên Uyên Thành. Sau khi Bạch mi trung niên, Dư đạo hữu, Tần đạo hữu và Lôi huynh đều từ chối vì công việc không thể rời bỏ, Ngân Quang tiên tử tự nguyện đi vì giao tình lâu năm với Lâm tiên tử của Thiên Vương Tông, Hàn Lập cũng chủ động nhận nhiệm vụ còn lại. Hội nghị thảo luận thêm về sức ép lâu dài từ đại quân Ma thú cấp thấp và mức tiêu hao linh thạch đáng lo; Ngân Quang tiên tử cảnh báo tới giữa ma kiếp có thể hơn mười bản thể Thánh Tổ Ma tộc hàng lâm, Nhân Yêu lưỡng tộc sẽ không đủ sức chống đỡ. Hàn Lập trở về động phủ ban bảo vật và đan dược cho đệ tử, đả tọa suốt đêm rồi sáng hôm sau cùng Ngân Quang tiên tử tới truyền tống đại điện. Thủ lĩnh vệ sĩ cảnh báo đầu Truyền Tống Trận bí mật có thể đã bị Ma tộc phát hiện; sau khi xác nhận pháp trận hoạt động bình thường, Hàn Lập vẫn ra lệnh lập tức truyền tống."},{"chuong":1888,"tieuDe":"Nhân Ma Chi Chiến 7","tomTat":"Hàn Lập và Ngân Quang tiên tử sử dụng một truyền tống trận bí mật, nhưng đầu bên kia đã bị hơn năm mươi Giáp sĩ Ma tộc chiếm giữ làm điểm phục kích. Hàn Lập lập tức phát hiện nguy hiểm, khống chế rồi đảo chiều loạt tên độc của đối phương, sau đó dùng tia sáng xám diệt sạch toán Giáp sĩ và lấy cự chưởng đánh chết thủ lĩnh Hóa Thần đang bỏ chạy. Hắn thiêu hủy thi thể, thu các đai lưng trữ vật chứa Ma Tinh Thạch cùng dụng cụ trận pháp rồi cùng Ngân Quang tiên tử che giấu độn quang rời khỏi hang động. Gần nửa ngày sau, một Bạch giáp Lão hán Ma tộc Hợp Thể tới nơi, đau đớn vì ái tôn bị giết và xác định hướng hung thủ đã rời đi. Lão dùng cự côn phá nát gần nửa ngọn núi rồi cưỡi cự hạc đen bốn cánh truy đuổi với tốc độ cực nhanh. Tại một ngọn núi ngoài vạn dặm, Lam tôn giả và một Ma tộc đầu trọc vẫn chờ Lực lão quái quay lại để cùng thực hiện đại sự do Huyết Quang giao phó."},{"chuong":1889,"tieuDe":"Lần Đầu Gặp Ma Tôn","tomTat":"Lam tôn giả và Mễ mỗ nhận được liên lạc từ Lực tôn giả qua La Sâm ma khí, biết rằng người cháu duy nhất của hắn vừa bị hai tu sĩ Nhân tộc giết chết. Lực tôn giả hứa chia một nửa thu hoạch trong lần Thánh Tế và tặng Hủ Ti Chi để đổi lấy sự trợ giúp, khiến hai Ma tôn đồng ý lên đường hội hợp. Trong khi họ sử dụng thần thông độn hành bám theo, Lực tôn giả tiếp tục dùng bí thuật huyết mạch khóa vị trí mục tiêu và tăng tốc truy đuổi. Sau một ngày một đêm bay về Ỷ Thiên Thành cùng Ngân Quang Tiên Tử, Hàn Lập phát hiện côn đen bất ngờ đánh tới từ hư không và dùng đoản thước bạc chặn lại. Lực tôn giả hiện thân trong hình thể cao lớn, trực tiếp đối mặt với hai tu sĩ Nhân tộc. Ngân Quang Tiên Tử nhận ra đối phương là Ma tộc tôn giả và tế ra đôi ngân sắc loan câu, còn Hàn Lập vận chuyển kim quang rồi phun ra một luồng hắc ti để chuẩn bị nghênh chiến."},{"chuong":1890,"tieuDe":"Kịch Chiến Tam Ma Thượng","tomTat":"Hàn Lập phát hiện lão giả một sừng đang ẩn nấp nhờ dao động của dấu hiệu huyết mạch, còn đối phương tự xưng là Lực tôn giả dưới trướng Huyết Quang thánh tổ và tuyên bố báo thù cho người cháu đã chết. Hàn Lập cùng Ngân Quang Tiên Tử lập tức hợp kích, dùng thước bạc và hai ngân câu kiềm chế trường côn rồi trói chặt đối thủ. Lực tôn giả biến thành ma vật ba đầu sáu tay, tạm tăng tu vi lên Hợp Thể trung kỳ và dùng sáu ma kiếm chém nát vật trói buộc. Sau khi hóa thành ma thể khổng lồ, hắn tung cự chưởng tấn công cả hai người nhưng bị kim sắc điện hồ của Hàn Lập khắc chế. Lực tôn giả tiếp tục phóng hai đạo huyết ti xuyên không, khiến một đạo cắm sâu vào Nguyên Từ Cực Sơn. Đạo còn lại xuyên qua ba kiện phòng ngự, đánh thương vai Ngân Quang Tiên Tử và khiến các bảo vật hộ thân của nàng tổn hại nghiêm trọng."},{"chuong":1891,"tieuDe":"Kịch Chiến Tam Ma Trung","tomTat":"Ngân Quang Tiên Tử phát hiện cánh tay nhiễm Thực Huyết Ma Diễm nên lập tức tự chặt bỏ, sau đó uống đan dược và thi triển Chi Thể Trọng Sinh để mọc lại chi thể. Hàn Lập hóa thành Kim Mao cự viên, dùng hai ngọn núi áp đảo Cầu Long Đại Lực của Lực tôn giả, đánh văng cự côn và khiến đối thủ thổ huyết. Lực tôn giả liên tiếp hy sinh tay chân để thi triển bí pháp thoát hiểm, nhưng lần ẩn độn đầu tiên bị con mắt đen tại mi tâm của Hàn Lập phá giải. Cuối cùng lão ma biến cước cốt ngân sắc thành đôi phi luân bốc huyết diễm rồi bỏ chạy. Ngân Quang Tiên Tử dùng Bích Thiên Toa truy đuổi, còn Hàn Lập kết hợp Thiên Bằng biến thân với Phong Lôi Sí thành đại bàng bốn cánh kim ngân để tăng tốc truy sát. Trong lúc đó, Lực tôn giả hướng về nơi hai đồng bạn đang chờ, còn Ma tộc đầu trọc truyền âm báo rằng một ma trận tạm thời đã được bố trí để dụ hai tu sĩ Nhân tộc vào cuộc phục kích của ba ma tôn."},{"chuong":1892,"tieuDe":"Kịch Chiến Tam Ma Hạ","tomTat":"Lực tôn giả đổi hướng chạy về quần tiểu sơn, nơi hai Ma Tôn Hợp Thể đã bố trí một đại trận bí mật để mai phục người truy kích. Trước khi hắn lọt vào trận, Hàn Lập hóa thành linh cầm bốn cánh mang điện, bất ngờ áp sát và xuyên thủng hai vai đối phương. Hàn Lập tiếp tục biến thành Khổng Tước ngũ sắc, phá huyết sắc hỏa cầu và dùng ngũ sắc quang hà khiến đường chạy của lão ma đình trệ. Lực tôn giả gọi đồng bọn cứu viện và triệu chiến giáp chống đỡ, nhưng Hàn Lập dùng Phiên Thiên Chân Ma, thần lực và kim sắc lôi điện phá tan phòng ngự. Ngân sắc hỏa diễm sau đó thiêu cả thân thể lẫn Nguyên Anh của Lực tôn giả thành tro. Hai Ma Tôn còn lại xuất hiện, một kẻ triệu cánh cửa xanh quỷ đầu, kẻ kia thả hơn trăm phi xà có cánh băng và triển khai mười ba cây ma phiên. Ngân Quang Tiên Tử nhận ra tử mẫu Chân Ma Phiên cùng truyền thừa tu ma Thiên Quỷ môn, lập tức biến sắc cảnh báo Hàn Lập."},{"chuong":1893,"tieuDe":"Tử Mẫu Chân Ma Cùng Tu La Quỷ Vương","tomTat":"Ngân Quang Tiên Tử nhận ra Thiên Quỷ Môn và Tử Mẫu Chân Ma phiên là những ma khí nguy hiểm nên đề nghị rút lui, nhưng Hàn Lập quyết định ở lại tiêu diệt hai đối thủ để tránh bị tiếp tục cản trở trên đường tới Ỷ Thiên thành. Theo kế hoạch chia cắt chiến trường, Hàn Lập giao chiến với Lam tôn giả bằng bảy mươi hai phi kiếm và Ngân sắc Hỏa Điểu, đối đầu đàn phi xà hóa băng trùy cùng mười ba ma nữ do Ma phiên biến thành. Ngân Quang Tiên Tử dùng mặt nạ bạc hóa thành đầu lâu mỹ nữ, phun tinh ti dựng cự võng, tinh tráo và pháp trận màu vàng để vây Ma tộc đầu trọc cùng Thiên Quỷ Môn. Dù bị phong khốn, Ma tộc đầu trọc vẫn hiến tinh huyết và mở hoàn toàn quỷ môn. Tu Quỷ Vương mang hình dáng thiếu niên đạo bào bước ra, trách kẻ triệu hoán tùy tiện gọi mình và đòi xem vật huyết tế. Ma tộc đầu trọc yêu cầu hắn triệu hoán Thiên Quỷ rồi dùng trường đao huyết sắc tự chém rơi một cánh tay, khiến nghi thức triệu hoán tiếp tục đứng trước một cái giá chưa rõ."},{"chuong":1894,"tieuDe":"Kinh Ma","tomTat":"Quỷ Vương nuốt phần tay do Ma tộc đầu trọc hiến tế nhưng vẫn viện dẫn khế ước để đòi thêm một chiếc chân mới chịu ra tay. Sau khi nhận đủ huyết tế, hắn giao quỷ lệnh gọi ra bốn Thiên Quỷ rồi trở vào quỷ môn. Ma tộc đầu trọc điều khiển bốn quỷ vật cùng đại ấn màu đen liên tục công kích tinh tráo, trong khi Ngân Quang Tiên Tử dùng đầu lâu mỹ nữ ngân sắc dẫn động trận pháp để phục hồi các vết nứt. Ở những chiến tuyến khác, kiếm ti kim sắc của Hàn Lập tiêu diệt đàn phi xà, Tử Văn quái trùng khắc chế mười ba Tử Mẫu Chân Ma, còn hình thái kim viên cùng hai ngọn núi áp đảo Lam tôn giả. Chứng kiến toàn bộ thủ đoạn phe mình bị khắc chế, Ma tộc đầu trọc nhận định phải có ba hoặc bốn Ma Tôn Hợp Thể hậu kỳ đại thành mới có phần chắc đối phó Hàn Lập. Hắn vẫn duy trì công kích tinh tráo nhưng âm thầm truyền âm cho đồng bạn, báo hiệu một sự thay đổi trong cách ứng phó."},{"chuong":1895,"tieuDe":"Ma Trận","tomTat":"Lam tôn giả tự bạo hai bảo vật để thoát khỏi sự áp chế của Hàn Lập, sau đó dụ chàng truy kích xuống khu vực tiểu sơn. Khi Hàn Lập tiến vào, hắn kích hoạt một ma trận rộng vài dặm lấy các sơn phong làm mắt trận, tạo xiềng xích và xúc tu ma khí để giam giữ cự viên. Hàn Lập dùng sức mạnh thân thể phá xiềng xích, lấy ngân sắc cự thước chém xúc tu rồi vận dụng Ích Tà Thần Lôi quét sạch cốt xoa kịch độc cùng ma khí. Chàng tiếp tục dùng quyền kình và hai ngọn núi pháp bảo đánh sập ba sơn phong, khiến uy lực của ma trận suy yếu. Trước tình thế bất lợi, Lam tôn giả tung huyết hoàn cho mười ba bộ bạch cốt nuốt xuống. Hắn cuối cùng tự làm huyết nhục rơi khỏi thân thể và biến thành bộ khung xương thứ mười bốn giữa đội hình bạch cốt."},{"chuong":1896,"tieuDe":"Mẫu Ma","tomTat":"Lam tôn giả lấy thân thể làm lô đỉnh, hợp nhất với mười ba Tử Ma và hóa thành Mẫu Ma để tăng mạnh tu vi, dù việc này có thể khiến thần trí bị ma tính ô nhiễm nếu ma thể trọng thương. Y phun ma phong lạnh thấu xương, ẩn mình tập kích Hàn Lập và tung vô số đao ảnh, nhưng Hàn Lập dùng hai tòa cự sơn cùng mười ba Phệ Kim Trùng biến dị chặn lại. Mẫu Ma bất ngờ xuất hiện phía trên Kim Mao Cự Viên, sử dụng hai mươi sáu Cốt Nhận tấn công, khiến Hàn Lập phải gọi ra ma giáp, kim sắc điện võng và thi triển Động Tuyền Kim Quang. Các Cốt Nhận bị hấp lực của sáu vòng xoáy kim sắc kiềm chế liền hợp thành Cốt Liên, phóng quang nhận màu xám để phản kích. Khi thế công vẫn không thể áp đảo đối thủ, Mẫu Ma rút thêm xương tái tạo binh khí rồi lao xuống cận chiến, đồng thời thả mười ba Tử Ma kiềm chế đàn Phệ Kim Trùng. Nguyên anh thứ hai của Hàn Lập mang Ngân Sắc Đoản Nhận nhập vào kim thân, khiến bảo vật tỏa ngũ sắc hà quang và dẫn động thiên địa pháp tắc chi lực tràn ngập hư không."},{"chuong":1897,"tieuDe":"Tru Ma","tomTat":"Pháp Tắc chi lực từ Huyền Thiên Tàn Nhận khiến toàn bộ Ma trận sụp đổ, đồng thời giúp Hàn Lập thoát khỏi ảnh hưởng của ma tính và khôi phục lý trí. Hàn Lập dùng hai mươi sáu khẩu cốt nhận giam chân Mẫu Ma, còn Sương nhi điều khiển Chi Tiên Linh khu giữ chặt đối phương khi thân thể nó phân liệt. Đệ nhị Nguyên Anh thao túng Phạm Thánh Kim Thân phát động Huyền Thiên Tàn Nhận, tạo thành hắc sắc cự lãng mang Pháp Tắc chi lực và tiêu diệt hoàn toàn Mẫu Ma. Khi tinh tráo tan vỡ, Ngân Quang tiên tử vì tiêu hao quá lớn nên phải ở lại uống đan dược hồi phục. Trọc đầu Ma tộc nhận thấy tình thế bất lợi liền bỏ chạy cùng bốn đầu Thiên Quỷ, nhưng bị Hàn Lập hóa thành tứ cánh Cự bằng và dẫn theo Tử vân Phệ Kim Trùng truy đuổi. Nửa canh giờ sau, Hàn Lập trở lại chiến trường và ném một đầu lâu Thiên Quỷ khổng lồ xuống trước mặt Ngân Quang tiên tử."},{"chuong":1898,"tieuDe":"Nổi Giận","tomTat":"Hàn Lập xác nhận với Ngân Quang tiên tử rằng hắn đã giết kẻ bỏ chạy cùng ba con Thiên Quỷ còn lại, đồng thời đưa Thiên Quỷ Môn bị tổn thương ra làm bằng chứng. Ngân Quang nhận lời tìm cách truyền tin cho Linh Lung, còn Hàn Lập hứa sẽ tận lực giúp nàng khi cần. Trên đường tới Ỷ Thiên thành, Hàn Lập kiểm tra hộp gỗ nhũ bạch lấy từ Trọc đầu Ma tộc nhưng cả thần niệm lẫn linh mục đều không thể xuyên qua, vì vậy hắn gia cố thêm cấm chế rồi cất giữ. Tại một ma thành mới xây, hóa thân Huyết Quang phát hiện thần niệm trên món đồ trọng yếu bị ngăn cách và được báo rằng hồn hỏa của Lam tôn giả cùng hai Ma tôn đồng hành đã tắt. Huyết Quang lập tức phái hai thuộc hạ cao giai dẫn hơn trăm Huyết Quang Tinh Vệ tới chiến trường tìm hung thủ và món đồ thất lạc. Hơn một tháng sau, Hàn Lập và Ngân Quang tới gần Ỷ Thiên thành, nơi hơn vạn chiến chu cùng vô số kỵ sĩ Ma tộc đã tập kết bên ngoài thành."},{"chuong":1899,"tieuDe":"Vạn Trượng Ma Kỵ","tomTat":"Hàn Lập và Ngân Quang tiên tử quan sát chiến trường, nhận diện hơn mười vạn Vạn Trượng Ma Kỵ cùng vài nghìn Gia Luân chiến ma đang bao vây Ỷ Thiên thành. Hai người đánh giá Gia Luân chiến ma đặc biệt nguy hiểm và nghi lực lượng này có liên quan đến cái chết của hai đại thái thượng trưởng lão trong thành. Ma quân mở màn tổng công kích bằng hắc sắc cự chu, hơn trăm siêu cấp ma thú và vô số ma thú cấp thấp, khiến pháp trận cùng nhiều đoạn tường thành nhanh chóng bị xuyên thủng. Hỏa lực và lôi trận của Nhân tộc tiêu diệt hàng vạn ma thú cấp thấp, đồng thời đánh trọng thương các cự thú nhưng không thể giết chúng. Chấp pháp tu sĩ dùng pháp khí trảm sát những binh sĩ tháo chạy, ép toàn quân tiếp tục tử thủ. Ma tộc dùng tử sắc quang trụ chữa lành các cự thú rồi điều Vạn Trượng Ma Kỵ kết trận áp sát thành. Trước nguy cơ phòng tuyến sụp đổ, các tổ tu sĩ Nhân tộc phải dùng pháp bàn triệu xuất đá lớn để tạm thời bịt kín những lỗ hổng trên tường thành."},{"chuong":1900,"tieuDe":"Giằng Co","tomTat":"Nhân tộc nhanh chóng dùng đá đã qua luyện chế để vá lại tường thành, đồng thời biến các lầu các thành thạch khôi lỗi siêu cấp nhằm tiêu diệt số ma thú đang trọng thương. Sau khi tu sĩ trên thành quét sạch phần lớn đê giai ma thú, Vạn Trượng Ma Kỵ tăng tốc tiến công, phá hủy hàng loạt pháp khí và dùng hắc sắc phù trận ngưng tụ đòn hợp kích. Hắc sắc cự nhận chém đứt một đoạn tường thành, khiến hơn vạn tu sĩ tử trận, rồi ma kỵ tiếp tục áp sát đánh cho quang mạc phòng hộ chao đảo. Lực lượng phòng thủ vận hành cự tháp, đưa đại quân thanh sắc đồng nhân gồm bộ binh, kỵ binh và chiến xa ra nghênh chiến. Mấy ngàn tu sĩ cao giai tiếp tục nhập trận, giúp Nhân tộc giữ được thế giằng co và tạm giành chút thượng phong. Sau vài canh giờ giao tranh, Vạn Trượng Ma Kỵ nhận lệnh rút lui theo đội hình nghiêm mật, còn Gia Luân chiến ma vốn được giữ ở phía sau bắt đầu tiến lên quan sát đối phương."},{"chuong":1901,"tieuDe":"Đại Địch","tomTat":"Sau một đợt công thành, kỵ sĩ Ma tộc và Gia Luân chiến ma lần lượt trở lại các cự thuyền rồi rút khỏi khu vực Ỷ Thiên Thành, còn phía Nhân tộc không dám truy kích. Hàn Lập suy đoán Ma tộc từng chịu thiệt bởi một đòn sát thủ bí mật của thành, song thủ đoạn ấy vẫn không đủ để Ỷ Thiên Thành tự mình chống lại toàn bộ ma quân. Khi Hàn Lập và Ngân Quang tiên tử bay về thành, Thiết Long bất ngờ dùng ma trảo khổng lồ tập kích, buộc hai người hợp lực phá giải. Phi Nha tiếp tục ẩn nấp phía sau Hàn Lập, dùng kỳ hàn và phi đao tuyết trắng đánh lén, nhưng Hàn Lập kháng được hàn lực và kịp thả Linh Khu ra đỡ đòn. Linh Khu bị chém mất một bàn tay nhưng lập tức tái sinh, khiến cuộc ám kích thất bại. Thiết Long và Phi Nha công khai thân phận là Tôn giả của Cương Cốt bộ và Băng Linh bộ rồi chia nhau đối đầu hai viện binh. Cuối chương, hai viện thủ từ Ỷ Thiên Thành hóa thành kinh hồng bay tới chiến trường."},{"chuong":1902,"tieuDe":"Hội Hợp","tomTat":"Nhận ra hai luồng linh áp Hợp Thể kỳ đang tới gần, hai Ma Tôn lập tức rút khỏi chiến trường bằng chiến xa màu đen và thân pháp vô hình; Hàn Lập cùng Ngân Quang tiên tử đều không truy kích. Hai người sau đó hội hợp với Thanh Long thượng nhân của Cửu Tinh tông và Lâm Loan tiên tử, thái thượng trưởng lão Thiên Hoàng tông, rồi cùng trở về Ỷ Thiên thành. Trên đường qua các phòng tuyến, Hàn Lập nhận thấy tu sĩ thủ thành đã hao tổn nguyên khí và phần lớn Thanh Đồng Khôi Lỗi đều bị hư hại, dù công việc tu bổ vẫn diễn ra có trật tự. Tại điện nghị sự, Lâm Loan cho biết lực lượng vừa công thành chỉ là một phần nhỏ, còn đại quân Ma tộc chủ lực đang đồn trú tại Trung Kiếm sơn mạch. Nàng cũng thuật lại việc hai tu sĩ Hợp Thể bị Vạn Tượng Ma Kỵ cùng hai Ma Tôn nhử ra ngoài, sau đó rơi vào cuộc mai phục của bốn Ma Tôn khác và bị diệt cả Nguyên Anh. Hàn Lập yêu cầu hồ sơ thần thông của bốn Ma Tôn để chuẩn bị đối phó. Cuối cùng, Lâm Loan tiết lộ quân Ma đang chờ ngày Ngũ Dương hóa nguyệt sau hai tháng, khi đại trận hộ thành của Ỷ Thiên thành mất hiệu lực."},{"chuong":1903,"tieuDe":"Cửu Dương Cương Nhật Tuyệt Trận","tomTat":"Lâm Loan tiên tử giải thích rằng Ỷ Thiên Thành được bảo vệ bởi Cửu Dương Cương Nhật Tuyệt Trận, một tuyệt trận do bốn đại tông môn dốc sức nghiên cứu và có thể giết Ma tộc tôn giả khi đạt trạng thái toàn thịnh. Tuy nhiên, trận pháp phụ thuộc vào chín tuyệt địa hỏa lực cùng thiên địa dương lực, lại sẽ mất hiệu lực khi kỳ Ngũ Dương hóa Nguyệt xuất hiện sau hai tháng. Hàn Lập chỉ ra tốc độ điều động chậm khiến tuyệt trận không thể tự mình uy hiếp bốn Ma Tôn, đồng thời cảnh báo đối phương có thể trì hoãn tổng công kích cho đến lúc đại trận suy yếu. Theo báo cáo của Thạch đạo hữu, toàn bộ pháo đài phụ trợ đã mất, năm tầng cấm chế bị phá, lực lượng Đồng giáp Khôi Lỗi tổn thất nặng và năng lực phòng ngự của thành giảm ba phần, dù nhân lực cùng vật tư vẫn đủ để cố thủ lâu dài. Thanh Long thượng nhân dự định tranh thủ thời gian đình chiến để sửa cấm chế, tu bổ khôi lỗi và chuẩn bị thêm thủ đoạn, còn Hàn Lập cùng Ngân Quang tiên tử chính thức nhận lời trợ chiến. Sau khi hai viện quân rời đi, Thanh Long thừa nhận hai Ma Tôn từng giết các đồng đạo nguy hiểm hơn dự kiến, trong khi Lâm Loan tiết lộ phe thủ thành vẫn còn một vật bí mật có thể tạo cơ hội chiến thắng."},{"chuong":1904,"tieuDe":"Hậu Nhân Của Thánh Tổ","tomTat":"Thanh Long thượng nhân và Lâm Loan tiên tử bàn cách bảo vệ Ỷ Thiên thành trong hai tháng then chốt trước ngày Ngũ Dương hóa nguyệt. Lâm Loan cho biết Huyết Hồn Phù sắp hoàn thành, đủ sức khống chế quái vật đang bị Cửu Dương Cương Nhật đại trận phong ấn, đồng thời chuẩn bị Phá Vân Lăng đưa đệ tử và tài liệu tới Thiên Uyên thành nếu phòng tuyến tan vỡ. Hai người còn tính việc ổn định sĩ khí, tu bổ đại quân Đồng giáp Khôi Lỗi và dành lực lượng tinh nhuệ đối phó Gia Luân chiến ma. Tại một sơn cốc cách thành mấy vạn dặm, Tàng ma tôn triệu tập Lãnh Nhận, Vũ Tiên tử và Hồng giáp cự nhân để truyền lệnh của Huyết Quang thánh tổ tạm dừng công thành sau khi ba Lực tôn giả bị diệt và làm mất một vật quan trọng. Âm Dương nhị sát đã được phái tới điều tra, còn quân Ma tộc dự tính chờ ngày Ngũ Dương hóa nguyệt mới tổng tiến công. Khi đánh giá hai viện binh Nhân tộc, Lãnh Nhận cho rằng người mạnh có thể giết Vũ Tiên tử, còn Tàng ma tôn thừa nhận Hàn Lập đã đỡ được Vạn Trọng Nhất Khí Đại Cầm Nã và khiến hắn không nắm chắc phần thắng. Hồng giáp cự nhân vì vậy nghi ngờ Hàn Lập có liên quan trực tiếp tới cái chết của ba Lực tôn giả."},{"chuong":1905,"tieuDe":"Hộp Gỗ Thần Bí","tomTat":"Tàng ma tôn cùng Vũ Tiên tử, Lãnh Nhận và Hỏa giáp cự nhân bàn về khả năng tu sĩ Nhân tộc đang phòng thủ Ỷ Thiên thành chính là hung thủ giết ba người Lực tôn giả. Họ xem người này là biến số lớn, nhưng bất đồng về việc có nên tái sử dụng sát cục từng khiến Ma tộc tổn thất gần một nghìn ma kỵ và hơn mười Gia Luân chiến ma. Tàng ma tôn quyết định phái người điều tra, chờ Âm Dương nhị sát rồi mới hành động, đồng thời cùng đồng bọn phân chia trước kỳ hàn chi lực và bảo vật của mục tiêu. Trong mật thất tại Ỷ Thiên thành, Hàn Lập dùng Minh Thanh linh mục nghiên cứu chiến lợi phẩm lấy từ Trọc đầu ma tôn suốt ba ngày ba đêm. Hắn xác định hộp gỗ là tu di chi vật bị mười ba thượng cổ cấm chế phong ấn và không thể phá giải nhanh theo cách thông thường. Hàn Lập bèn phối hợp dị tộc bí thuật với hơn mười viên châu ngũ sắc, tách một hư ảnh thần niệm từ Nguyên Anh rồi đưa vào hộp. Hư ảnh xuất hiện trong không gian tối tăm và nhận ra nơi này có vẻ là cấm chế ảo thuật đang giữ thần niệm, chứ không phải tu di không gian thông thường."},{"chuong":1906,"tieuDe":"Trấn Ma Tỏa","tomTat":"Hàn Lập phân một luồng thần niệm và dùng bí thuật ngoại tộc xâm nhập hộp gỗ, nhưng thay vì đến đích, hóa thân lại rơi vào một không gian sương xám vô biên. Sau thời gian dò xét và ngồi chờ, hắn buộc Lục bào lão giả đang ẩn giấu phải hiện thân; hai người tiếp tục im lặng giằng co hơn ba ngày trước khi lão chủ động lên tiếng. Lão giả xác nhận đây là tầng thứ mười của ảo thuật cấm chế, rồi biến sương xám thành núi xanh, suối nước và sinh vật có cảm giác gần như chân thực để phô bày khả năng điều khiển nơi này. Khi Hàn Lập nhận ra đối phương cũng chỉ là thần niệm bị vây, lão nổi giận, nghi hắn do Huyết Quang phái tới và dùng sức bóp cổ hóa thân để tra hỏi. Trong lúc chất vấn, lão tiết lộ hộp gỗ thực chất là Trấn Ma Tỏa, một bảo vật từng lưu truyền qua tay nhiều thánh tổ. Hàn Lập vẫn bình tĩnh tuyên bố việc mất phân niệm không ảnh hưởng đáng kể đến bản thể và đe dọa sẽ vứt bảo vật vào nơi không ai tìm được. Tin rằng Hàn Lập không biết thân phận mình và không thuộc phe Huyết Quang, lão giả đổi thái độ, thả hắn rồi đề nghị hai bên luân phiên trao đổi câu hỏi."},{"chuong":1907,"tieuDe":"Xa Kỵ Cung","tomTat":"Hàn Lập cùng lão giả áo xanh luân phiên trao đổi tin tức, qua đó biết đối phương tên Xa Kỵ Cung và là một trong những Thánh Tổ lâu đời nhất Cổ Ma giới. Khi nghe Ma kiếp mới bắt đầu và chân thân các Thánh Tổ chưa thể hàng lâm Linh giới, Xa Kỵ Cung tỏ ra kích động rồi âm thầm suy tính. Lão tiết lộ Trấn Ma Tỏa là Huyền Thiên Chi Bảo bán thành phẩm, chứa hai khí âm dương đang diễn biến thành hỗn độn và tự hình thành không gian mười ba tầng phủ đầy thượng cổ cấm chế. Bảo vật đủ sức giam cầm tồn tại Đại Thừa hoặc Thánh Tổ, nhưng ngoại tộc không thể khu sử vì việc vận dụng nó cần thiên địa pháp tắc của Cổ Ma giới. Xa Kỵ Cung còn cho biết có thể đặt Trấn Ma Tỏa trong Âm Dương Minh Trì hoặc Hoàng Tuyền Địa Hỏa rồi dùng bí thuật Cổ Ma để rút khí hỗn độn. Hàn Lập động tâm khi biết một tia khí này có thể giúp tu sĩ Hợp Thể tăng cảnh giới hoặc tạo thêm cơ hội tiến giai Đại Thừa, trong khi Xa Kỵ Cung vẫn cố ý che giấu hạn chế trí mạng của Trấn Ma Tỏa."},{"chuong":1908,"tieuDe":"Hỗn Độn Nhị Khí","tomTat":"Hàn Lập chất vấn Xa Kỵ Cung về mục đích của Huyết Quang và kể lại thần thông của ba Ma Tôn đã bị mình giết. Xa Kỵ Cung nhận ra một kẻ từng là thuộc hạ Huyết Quang, từ đó suy đoán Trấn Ma Tỏa được giao cho họ để mang tới Hoàng Tuyền Địa Hỏa rút Hỗn Độn nhị khí. Lão đề nghị tiết lộ phương pháp tế luyện Trấn Ma Tỏa nếu Hàn Lập giúp rút bớt hỗn độn khí và đáp ứng thêm một số điều kiện, nhưng Hàn Lập chưa nhận lời mà rút thần niệm. Trở lại nhục thân, Hàn Lập lo Huyết Quang để lại thủ đoạn trên bảo vật nên dùng phù lục cùng lưới điện kim sắc phong kín Trấn Ma Tỏa rồi cất đi. Hắn cũng từ bỏ ý định thử lục dịch thần bí vì nguy cơ phá cấm chế và giải phóng Xa Kỵ Cung. Sau khi cân nhắc sức tự vệ trước hóa thân cùng chân thân Huyết Quang, Hàn Lập dự tính dựa vào Thánh đảo và rời địa phận Thiên Uyên Thành khi cần thiết. Hơn một tháng sau, một phi xa do cầm điểu đen hai đầu kéo chở hai Ma tộc cao giai tiến vào sơn cốc gần nơi đại quân Ma tộc đóng quân."},{"chuong":1909,"tieuDe":"Đại Chiến Tái Khởi","tomTat":"Âm Dương nhị sát đến sơn cốc hội quân sau khi nhận tin tu sĩ Nhân tộc từng giết Lực tôn giả đang ở Ỷ Thiên thành. Dù mang theo chí bảo được thánh tổ cho mượn, họ vẫn thận trọng và thống nhất để phe Tàng ma tôn phụ trách phá thành, còn mình chuyên đối phó mục tiêu. Tàng ma tôn, Lãnh Nhận, Vũ Tiên tử cùng các cường giả Ma tộc thương nghị hơn nửa ngày rồi hoàn tất kế hoạch. Hơn mười ngày sau, bảy vầng thái dương phía trên Ỷ Thiên thành hoàn toàn hóa xám, khiến dân chúng hoảng sợ. Tứ đại tông môn lập tức điều động lực lượng tuần tra, phong tỏa đường phố và ổn định trật tự. Hàn Lập đến đại điện hội nghị, được Ngân Quang tiên tử nhắc phải cẩn thận vì hắn là chiến lực lớn nhất của phe phòng thủ. Thanh Long thượng nhân báo đại quân Ma tộc đã tái xuất động, trong khi hư ảnh chiến trường cho thấy các đoàn hắc khí đang áp sát Ỷ Thiên thành từ bốn phía."},{"chuong":1910,"tieuDe":"Ỷ Thiên Chi Chiến (1)","tomTat":"Hàn Lập và Ngân Quang tiên tử đến đại điện nghị sự, được Thanh Long thượng nhân cùng Lâm Loan tiên tử đón tiếp và nhờ trợ giúp trong trận chiến quyết định sự tồn vong của Ỷ Thiên thành. Tứ đại tông môn trao cho mỗi người một trữ vật thủ trạc chứa lượng tài nguyên tương đương tài sản của một tông môn trung bình, đồng thời hứa sẽ có thêm đại lễ nếu giữ được thành. Các cường giả thống nhất phải chống đỡ cho tới khi Ngũ Dương Hóa Nguyệt chấm dứt và Cửu Dương Cương Nhật đại trận phục hồi; Thanh Long thượng nhân cũng cho biết đã chuẩn bị biện pháp riêng đối phó Già Luân chiến ma. Toàn thành sau đó được tổng động viên, các cấm chế và pháp trận vận hành hết uy lực, quân sĩ, tu sĩ, linh thú cùng khôi lỗi lần lượt vào vị trí chiến đấu. Đại điện nghị sự bay lên cao rồi hóa thành quang cầu ngũ sắc lơ lửng trên tường thành, trong khi Tử Mẫu Liên Hoàn đại trận bí ẩn được chuẩn bị tại quảng trường phía trong. Sau vài canh giờ, tiếng trống trận vang lên và toàn bộ đại quân Ma tộc hóa thành ma hải rợp trời, mang theo những chiến thuyền khổng lồ cuồn cuộn tiến về Ỷ Thiên thành."},{"chuong":1911,"tieuDe":"Ỷ Thiên Chi Chiến (2)","tomTat":"Hàn Lập, Thanh Long thượng nhân và các tu sĩ cao tầng chứng kiến bốn tôn giả Ma tộc hiện thân ngoài ma hải, đồng thời chuẩn bị thực hiện kế hoạch chia nhau kiềm chế đối thủ. Hai phe tạm thời giằng co cho đến khi năm vầng thiên dương cùng tối đi, bởi Ma tộc vẫn kiêng dè Cửu Dương Cương Nhật đại trận. Tàng ma tôn dụ Thanh Long quy thuận và tiếp nhận Ma Khí Quán Thể đại pháp, nhưng Thanh Long tuyên bố thà chết trận chứ không đầu hàng. Sau tín hiệu tổng công kích, chiến thuyền Ma tộc phóng ra ma thú, Vạn Tượng ma kỵ, hơn ba trăm siêu cấp ma thú và đội quân ba mắt mặc lục bào. Loạt hắc sắc cột sáng suýt đánh tan cấm chế ngoài thành, song hơn trăm pháp trận ngầm đã tạo ngân sắc trận đồ để hóa giải phần lớn pháo kích. Nhân tộc lập tức huy động lực sĩ, tu sĩ cấp thấp và đại quân Thanh Đồng khôi lỗi phản kích, biến khu vực mười dặm trước tường thành thành tử địa. Cuối chương, Tàng ma tôn dùng song cự chùy đánh thẳng vào cấm chế và gọi Thanh Long khiêu chiến, khiến ngân sắc quang tráo vừa được củng cố lại rung chuyển bất ổn."},{"chuong":1912,"tieuDe":"Ỷ Thiên Chi Chiến (3)","tomTat":"Tàng ma tôn dùng đôi cự chùy màu đen công kích cấm chế đầu thành, buộc Thanh Long thượng nhân chủ động xuất chiến. Thanh Long thượng nhân dùng bảy tiểu kiếm và tinh huyết thi triển Chú Huyết Tố Linh đại pháp, hóa thành Thanh Long chân chính rồi giao chiến ngang sức với đối thủ, dù thần thông này phải tiêu hao máu. Lâm Loan tiên tử thay Hàn Lập nghênh chiến Lãnh Nhận, dùng ba hồ lô tạo Hỏa Vân và đôi cánh lửa để khắc chế hàn khí, nhưng bản thân cũng hao tổn nguyên khí. Ngân Quang tiên tử chủ động đánh Vũ tiên tử bằng đôi Ngân Câu và nhiều bảo vật, trong khi đối phương dùng phấn vụ cùng quái thú huyễn hóa bao vây nàng. Khi ba cặp đối thủ đã hình thành, Hàn Lập chọn Hỏa giáp cự nhân, kết lôi quang pháp trận phá không xuất hiện ngay trên đầu đối phương. Hắn ném hai ngọn núi đen và xanh xuống, đồng thời phát động ánh sáng xám, hàng ngàn vạn kiếm khí cùng một tiếng hừ lạnh, nhưng kết quả đòn tập kích chưa được hé lộ."},{"chuong":1913,"tieuDe":"Ỷ Thiên Chi Chiến (4)","tomTat":"Hàn Lập dùng Thất Thần thứ đánh vào thần hồn Yên tôn giả, rồi phối hợp hai tòa cự sơn, Thanh Trúc Phong Vân kiếm và ngân thước phá tan chiến giáp hộ thân. Lốc xoáy kiếm quang nghiền nát cả nhục thân lẫn nguyên anh của vị Ma tôn Hợp Thể sơ kỳ. Ngay sau đó, Âm Dương nhị sát từ ma hải hiện thân, chất vấn Hàn Lập về cái chết của ba Lực tôn giả và quyết định dùng nhị bảo do thánh tổ ban tặng để đối phó hắn. Trung niên nam tử tế bảo tháp bảy tầng, còn mỹ phụ điều khiển Tử Ngôn đỉnh hút thước ảnh và tạo hắc liên hoa nâng hai cự sơn. Hàn Lập dùng Lôi Độn chuyển lên đỉnh núi, gia tăng trọng lực rồi phóng kim sắc điện hồ che giấu kiếm ảnh tấn công. Mỹ phụ tiếp tục rót ma khí vào cự đỉnh, khiến nhiều cổ văn bắn ra khi trận chiến vẫn chưa phân thắng bại."},{"chuong":1914,"tieuDe":"Ỷ Thiên Chi Chiến (5)","tomTat":"Hàn Lập liên tục dùng hai tòa sơn phong, hôi sắc quang ti và kiếm ảnh công kích, nhưng quang mạc của Tử Ngôn đỉnh đều phục chế rồi phản xạ các đòn đánh. Trung niên mỹ phụ tiếp tục dùng hấp lực của chiếc đỉnh giữ chân hắn, tạo cơ hội cho nam tử áo bào ngân ti kích phát Thất thải bảo tháp và thu hắn vào không gian Tu Di. Bên trong bảo tháp, Hàn Lập triển khai hơn trăm kiếm quang đối phó đàn hắc sắc ma thú, trong khi mỹ phụ mang Tử Ngôn đỉnh tiến vào truy sát và sư huynh của nàng vận chuyển cấm chế từ bên ngoài. Chiến cuộc phía Nhân tộc đồng thời chuyển xấu khi Thanh Long thượng nhân khó duy trì trạng thái hóa long, Lâm Loan tiên tử bị phi đao cực hàn khắc chế và Ngân Quang tiên tử chỉ còn miễn cưỡng chống đỡ đàn ma vượn. Nhận thấy kế hoạch chờ Hàn Lập tiếp viện đã thất bại, Thanh Long thượng nhân dốc sức đẩy lui Tàng ma tôn rồi ra lệnh phóng thích át chủ bài trong thành. Một tu sĩ dùng Kim ngân lệnh bài phát tín hiệu, dẫn động chín bạch bào tu sĩ hợp nhất các quang trụ và kích phát tám mươi mốt phù văn pháp trận. Chương kết thúc khi toàn bộ quang trụ vỡ vụn, còn vật bí mật được phóng thích vẫn chưa lộ diện."},{"chuong":1915,"tieuDe":"Ỷ Thiên Chi Chiến (6)","tomTat":"Hợp Tức thú phá phong ấn trong Ỷ Thiên thành, phun sương vàng nuốt nhóm bạch bào tu sĩ rồi giết thêm hàng trăm người đang tháo chạy. Theo lời thúc giục của Thanh Long thượng nhân, Lâm Loan tiên tử cho nổ ba hồ lô, giải phóng ba Hỏa Phong Vương để buộc Lãnh Nhận tránh lui, sau đó kích hoạt huyết phù khống chế mãnh thú. Tàng ma tôn nhận ra Hợp Tức thú đang nguyên khí đại thương và pháp lực suy giảm nên từ bỏ ý định rút lui, tiếp tục áp đảo Thanh Long và phát tín hiệu điều động quân dự bị. Trong ma hải, một ma tướng ra lệnh cho mấy nghìn Vạn Tượng Ma Kỵ và Gia Luân chiến ma nuốt đan dược màu đen, khiến toàn quân mọc huyết văn và tăng vọt khí tức. Thanh Long thượng nhân bị đánh trọng thương, phải trở lại thân người với bảy lỗ máu trước ngực. Cuối cùng, Hợp Tức thú cuốn hoàng vụ và quái phong tiến vào chiến trường, còn Lâm Loan tiên tử ra lệnh cho nó tiêu diệt Ma tộc và hứa trả tự do sau trận chiến."},{"chuong":1916,"tieuDe":"Ỷ Thiên Chi Chiến (7)","tomTat":"Hợp Tức thú nhận ra những kẻ từng phong ấn mình nhưng không muốn mạo hiểm vì thương thế chưa lành và pháp lực chưa phục hồi quá nửa. Lâm Loan tiên tử kích phát huyết phù trong đầu, ép nó phun hoàng phong tàn sát hơn ngàn ma thú cùng trên trăm ma kỵ. Tàng ma tôn dùng phi xoa, cự lang điện, cự chùy và hư ảnh phân thân đối kháng nhưng vẫn bị cự thú áp chế, trong khi Thanh Long thượng nhân dùng cặp phi kiếm triệu hiện Thanh Giao và Kim Khổng Tước để phối hợp vây giết hắn. Trước tình thế nguy cấp, Tàng ma tôn điều Hóa Huyết Minh vệ hóa thành huyết vụ, triển khai Huyết Minh đại trận bao vây các chiến lực Hợp Thể. Cùng lúc đó, hơn một ngàn Già Luân Chiến Ma đang giả dạng ma thú cấp thấp đồng loạt hiện nguyên hình ngay sát phòng tuyến. Chúng phá vỡ quang tráo tại hơn mười vị trí, tràn lên tường thành và tàn sát quân phòng thủ. Nhiều tu sĩ cao cấp ứng cứu cũng bị vây giết, khiến các khu vực bị đột phá rơi vào hỗn loạn và sĩ khí Nhân tộc suy sụp."},{"chuong":1917,"tieuDe":"Ỷ Thiên Chi Chiến 8","tomTat":"Trên chiến trường Ỷ Thiên thành, các Già Luân chiến ma mở đường xông vào nhưng bị ba mươi kim sắc khôi lỗi chặn lại, trong khi phòng tuyến Nhân tộc chỉ có thể dựa vào cấm chế để miễn cưỡng cầm cự. Ở tầng giao phong đỉnh giai, Vũ Tiên tử và Lãnh Nhận ép Ngân Quang tiên tử cùng Lâm Loan tiên tử liên tiếp lui về sau. Bên trong thất sắc bảo tháp, Hàn Lập tiêu diệt nhiều lớp quái thú nhưng nhận ra chúng tái sinh không ngừng và ngày càng mạnh, khiến pháp lực của hắn liên tục bị tiêu hao. Hắn mở Phá Diệt pháp mục, lần theo sợi tơ đen và tìm thấy một cự tháp bảy tầng che giấu tiếp điểm không gian. Đòn công kích bằng Xuân Thu Huyền Thước bị phù văn thất sắc hấp thu, buộc hắn phải tiến vào tháp để tìm đường phá giải từ bên trong. Khi dùng linh mục dò xét cửa đá tầng một, Hàn Lập suýt bị cấm chế kim quang hút lấy ánh mắt, may nhờ Đại Diễn Quyết tự vận chuyển và Chi Tiên linh thể chắn đỡ. Nhận ra mức độ nguy hiểm của nơi này, hắn tế bảy mươi hai thanh phi kiếm, thả mười hai con tử văn linh trùng và lấy hai tòa tiểu sơn xanh đen ra phòng bị trước khi tiếp tục tiến sâu."},{"chuong":1918,"tieuDe":"Ỷ Thiên Chi Chiến 9","tomTat":"Hàn Lập thi triển Kinh Trập Quyết hóa thành Sơn Nhạc Cự Viên, dùng hai tòa cực sơn phá tan kim quang cấm chế và cửa đá của bảo tháp. Hắn phối hợp sức mạnh thân thể, kiếm quang và mười ba Tử Văn Giáp Trùng tiêu diệt hơn một trăm khôi lỗi bạc tại tầng đầu, nhưng không phá chướng bích đi tắt vì lo làm tổn hại tiếp điểm không gian. Sau khi hắn rời đi, trung niên mỹ phụ thuộc Âm Dương nhị sát hiện thân, đánh giá sự lợi hại của hắn rồi dùng trận bàn ngân sắc tiếp tục ẩn mình bám theo. Hàn Lập lần lượt vượt qua khôi lỗi bạc từ Hóa Thần trung kỳ đến Hóa Thần hậu kỳ đại thành tại tầng hai và tầng ba, rồi đánh bại khôi lỗi kim sắc từ Luyện Hư sơ kỳ đến Luyện Hư hậu kỳ đại thành ở ba tầng kế tiếp. Tới tầng bảy, Phá Diệt Pháp Mục giúp hắn xác định tiếp điểm không gian nằm gần phía trước, nhưng mười ba linh trùng lập tức cảnh báo sự xuất hiện của hai khôi lỗi lưu ly Hợp Thể sơ kỳ. Hàn Lập tung cực sơn, linh trùng và thước bạc tấn công, song hai khôi lỗi tháo bốn bàn tay tạo quang tráo thất sắc, chặn dòng lưu thủy bạc rồi đánh bật đòn đánh trở lại."},{"chuong":1919,"tieuDe":"Ỷ Thiên Chi Chiến 10","tomTat":"Hàn Lập dùng hai tòa cực sơn và mười ba con linh trùng tấn công quang tráo bảy màu, khiến linh lực của nó nhanh chóng suy giảm dù hai khôi lỗi lưu ly liên tục bổ sung năng lượng. Hắn tiếp tục hợp nhất bảy mươi hai thanh Thanh Trúc Phong Vân kiếm thành cự kiếm, chuẩn bị chém vỡ tầng phòng hộ. Đúng lúc đó, mỹ phụ trong Âm Dương nhị sát phối hợp với một khôi lỗi Hợp Thể kỳ phát động cuộc ám toán liên hoàn, dùng chữ áp, tiểu đỉnh, quỷ diện lục hỏa và huyết sắc phi kiếm vây giết Hàn Lập. Hàn Lập biến thành Sơn Nhạc cự viên phá giải cấm chế, đồng thời triệu xuất Thiên Ngoại ma giáp, Kim thân pháp tướng và hóa thân Linh Khu chống trả. Sau khi đánh mỹ phụ trọng thương, hắn dùng thần nhãn phá thuật ẩn thân, biến thành Cự Bằng đuổi kịp rồi thiêu cả thân thể lẫn Nguyên anh của nàng thành tro. Hàn Lập quay lại hỗ trợ Kim thân pháp tướng chém nát khôi lỗi Hợp Thể kỳ, còn quang tráo bảy màu cũng tự tan vỡ vì bị mười ba con linh trùng hút cạn linh lực."},{"chuong":1920,"tieuDe":"Thánh Tổ Ma Âm - Ỷ Thiên Chi Chiến (11)","tomTat":"Mười ba tử văn giáp trùng giao chiến với hai lưu ly khôi lỗi, xuyên qua ngân hồ và hoàng sắc quang hà trước khi bám vào thân chúng cắn nuốt. Hàn Lập biến thành cự viên, dùng Nguyên Từ cực sơn cùng Lôi sí áp sát và phá thủng ngực hai khôi lỗi, nhưng Phệ Linh Thiên Hỏa lại không thể hòa tan chất liệu lưu ly của chúng. Các linh trùng sau đó thôn phệ sạch hai khôi lỗi, song biểu hiện chưa hoàn toàn thuần phục khiến Hàn Lập quyết định phải tiếp tục dưỡng dục. Khi Hàn Lập sắp thu Tử Ngôn đỉnh, Huyết Quang thánh tổ dùng tử sắc lôi điện cách không lấy lại bảo vật và truyền thần niệm cấp Đại Thừa tới đe dọa hắn. Tại một thành Ma tộc gần Thiên Uyên thành, một hóa thân khác của Huyết Quang thánh tổ cảm ứng được biến động và kinh hãi suy đoán bản thể đang thi triển công pháp để đột phá cách giới lực. Nhận thấy nguy cơ một Thánh Tổ bản thể có thể giáng lâm, Hàn Lập thu hồi hóa thân Linh Khu cùng Phạm thánh kim thân. Hắn dùng Phá Diệt pháp mục phối hợp pháp tướng phá vỡ khối tinh thạch trên đài cao, làm lộ một hang động màu trắng rồi hóa thành kinh hồng bay vào trong thoát đi."},{"chuong":1921,"tieuDe":"Băng Hàn Cửu Thiên","tomTat":"Hàn Lập thoát khỏi cự tháp và nhận thấy thời gian bên trong dường như trôi khác ngoại giới, khiến hắn liên tưởng đến Huyền Thiên chi bảo. Quan sát chiến trường ngoài Ỷ Thiên thành, hắn thấy Thanh Long thượng nhân cùng Hợp Tức thú đang bị Tàng ma tôn và đội quân Ma tộc có khả năng phục hồi cầm chân, còn Ngân Quang tiên tử và Lâm Loan tiên tử bị Lãnh Nhận cùng Vũ Tiên tử ép vào thế nguy. Nam tử áo bào ngân ti đã biến mất không dấu vết, làm Hàn Lập cảm thấy một đại họa đang tới gần. Dù từng định rời đi, hắn quyết định tham chiến vì không muốn mất chỗ đứng trong Nhân tộc và cho rằng bản thể Huyết Quang thánh tổ chưa thể phủ xuống khi ma kiếp vừa bắt đầu. Theo đề nghị của Lâm Loan tiên tử, Hàn Lập đứng ra ngăn hai Ma tộc tôn giả để nàng tập trung điều khiển Hợp Tức thú. Nguyên Từ cực sơn của hắn bị kỳ hàn đông kết non nửa, còn Thanh Bàn kiếm trận sau khi được triển khai cũng dần ngưng trệ trước cự nhận do các phi đao của Lãnh Nhận hợp thành."},{"chuong":1922,"tieuDe":"Thanh Bàn","tomTat":"Trước kỳ hàn thần thông của Lãnh Nhận, Hàn Lập gọi Ngũ Tử Đồng Tâm ma phóng hàn diễm năm màu, giúp kiếm trận thoát khỏi sự đình trệ. Hắn tụ vô số kiếm quang thành Bàn long màu xanh để phá cự đao băng, nhưng nhanh chóng nhận ra những binh đao do kỳ hàn ngưng tụ có thể liên tục tái tạo khi đối thủ còn pháp lực. Hàn Lập dùng Lôi độn thuật áp sát, đồng thời dung hợp ngũ sắc hàn diễm với Phệ Linh Thiên Hỏa để phá tan bàn tay băng của Lãnh Nhận. Nhân lúc ngân diễm che khuất tầm nhìn, hắn bí mật phóng Linh Tuyền tà quang vào ngực đối thủ, khiến Lãnh Nhận trúng độc và bị thương nặng. Ngân Quang tiên tử vẫn điều khiển ngân thước giữ chân Vũ Tiên tử, ngăn nàng can thiệp vào cuộc truy sát. Đúng lúc Hàn Lập định kết liễu đối thủ, một vòng xoáy đen khổng lồ xuất hiện trên chiến trường và tỏa ra khí tức giống thần niệm từng phủ xuống cự tháp nhưng mạnh hơn nhiều. Nam tử áo bào ngân ti xuất hiện dưới vòng xoáy, dùng huyết hồng tinh thạch tiếp nhận ma khí đỏ thẫm rồi nuốt trở lại, khiến thân thể, diện mạo và khí tức của hắn biến đổi dữ dội."},{"chuong":1923,"tieuDe":"Huyết Tinh Ma Ảnh","tomTat":"Huyết Quang thánh tổ hoàn thành việc ký sinh vào thân thể một trung niên nam tử để giáng lâm Linh giới, hiện hình thành thiếu niên mắt đỏ mang huyết tinh khí tức và được toàn bộ Ma tộc đại quân quỳ bái. Thanh Long thượng nhân nhận định hóa thân này chưa có tới một phần mười pháp lực bản thể nên lệnh cho Lâm Loan tiên tử điều khiển Hợp Tức thú tấn công, đồng thời tự mình dùng Thanh Long hóa hình cản quân Ma tộc. Huyết Quang thánh tổ dùng tử sắc tiểu đỉnh xuyên thủng phòng ngự, trói Hợp Tức thú rồi gọi Thất sắc bảo tháp lên từ mặt đất để thu cự thú làm tọa kỵ. Thấy thế trận tan vỡ, Thanh Long thượng nhân, Lâm Loan tiên tử và Ngân Quang tiên tử chia nhau bỏ chạy, còn Hàn Lập thu Thanh Bàn kiếm trận và dùng Phong Lôi sí rời đi. Hàn Lập tiếp tục thi triển Côn Bằng biến thân thuật, hóa thành ngân sắc cự bằng bốn cánh để tăng tốc đào thoát. Huyết Quang thánh tổ phân thành ba thân ảnh, phái hai phân thân mang pháp bảo truy kích những tu sĩ Nhân tộc khác, còn bản thể dùng tiểu thuyền máu đỏ mọc cánh đích thân đuổi theo Hàn Lập."},{"chuong":1924,"tieuDe":"Sa Lão","tomTat":"Ba Huyết Tinh thiếu niên chia nhau hành động: Vũ Tiên tử đuổi theo Ngân Quang tiên tử, Lãnh Nhận truy kích Lâm Loan tiên tử, còn Tàng ma tôn ở lại chỉ huy cuộc công thành. Trước lời tuyên bố làm dao động sĩ khí của Ma tộc, Thanh Long thượng nhân kích hoạt một trăm linh tám Cự Kiếm Tinh Kim khôi lỗi cấp Luyện Hư, giúp quân phòng thủ Ỷ Thiên thành lấy lại tinh thần. Tàng ma tôn tiếp tục điều Hóa Huyết Minh vệ tham chiến, khiến Ma tộc chiếm thế thượng phong, nhưng các khôi lỗi tinh kim vẫn chưa xuất kích. Sau đó hắn trở về cự thuyền, dùng tinh huyết kích hoạt Phân Giới kính để báo cáo với Sa lão về việc Huyết Quang ký phụ thần niệm lên Dương Sát và biến người này thành hóa thân tại Linh giới. Sa lão nhận định hành động ấy có thể khiến bản thể Huyết Quang ở Thánh giới gặp nguy hiểm nếu các đối thủ biết được. Trong khi Vũ Tiên tử và Lãnh Nhận lần lượt liên lạc về Ma giới trên đường truy kích, Hàn Lập hóa thành cự bằng bốn cánh bạc bỏ chạy nhưng vẫn bị thuyền nhỏ màu máu của Huyết Quang hóa thân đuổi sát phía sau."},{"chuong":1925,"tieuDe":"Ngăn Địch","tomTat":"Hàn Lập biến thân thành Côn Bằng và dốc toàn lực chạy khỏi Ỷ Thiên thành, nhưng chiếc thuyền nhỏ của Huyết Quang thánh tổ vẫn bám sát vì hắn đã bị thần niệm khóa chặt. Hàn Lập dựng một phiên bản tạm thời của đại trận Thiên Diệu Hải Vân trên dãy núi, song Tử Ngôn đỉnh nhanh chóng phóng lốc đen xé nát trận pháp. Hắn tiếp tục dùng ảnh khôi lỗi làm mồi và gọi ra Chân Ma pháp tướng phục kích, nhưng Huyết Quang lần lượt dùng bảo tháp bảy màu cùng vòng tròn cổ quái để thu khôi lỗi, chặn công kích và phá hủy pháp tướng. Cửu Cung Thiên Kiền phù bí mật phát động sau đó cũng bị bảo tháp thu mất, khiến cuộc truy sát tiếp diễn. Trong lúc ấy, toàn bộ cấm chế bên ngoài Ỷ Thiên thành bị Ma tộc công phá, gần nửa tường thành thất thủ và quân thủ thành tan vỡ sĩ khí khi biết một trăm lẻ tám Tinh Kim giáp sĩ trên trời chỉ là hư ảnh. Trên ngọn núi cách thành vài nghìn dặm, Thanh Long thượng nhân tập hợp gần nghìn tu sĩ hạt giống của tứ đại tông môn, tuyên bố Ỷ Thiên thành không thể cứu vãn và ra lệnh lập tức rút lui."},{"chuong":1926,"tieuDe":"Vấn Kế","tomTat":"Sau khi các thủ đoạn cản địch liên tiếp bị phá, Hàn Lập nhận định cơ hội thắng ba hóa thân Huyết Quang chưa tới năm thành và quyết định tránh giao chiến trực diện. Hắn duy trì biến thân Côn Bằng để chạy trốn nhưng ước tính dù liên tục bổ sung linh lực cũng chỉ có thể cầm cự thêm năm hoặc sáu ngày, trong khi đối phương luân phiên điều khiển huyết sắc tiểu thuyền và thong dong chờ hắn kiệt sức. Hàn Lập nghĩ đến việc vứt bỏ Trấn Ma Tỏa để dẫn kẻ địch rời đi, song không nỡ từ bỏ một Huyền Thiên linh bảo bán thành phẩm chứa Hỗn độn nhị khí. Hắn đưa Nguyên anh thứ hai vào không gian nội tại của Trấn Ma Tỏa để hỏi kế Xa Kỵ Cung, đồng thời đe dọa sẽ vứt bảo vật cho Huyết Quang nếu lão không chịu giúp. Xa Kỵ Cung tức giận nhưng cuối cùng nhượng bộ, nhận ra hai chí bảo của các hóa thân là Tử Ngôn đỉnh và Thải Quang tháp. Lão xác nhận cả hai đều là Huyền Thiên tàn bảo, tuyên bố có cách đối phó và cho rằng Hàn Lập thậm chí có cơ hội cướp được một kiện."},{"chuong":1927,"tieuDe":"Đối Sách","tomTat":"Xa Kỵ Cung tiết lộ Tử Ngôn đỉnh vốn thuộc về mình và bên trong có thể vẫn còn một phần thần niệm bí mật đủ sức tranh đoạt quyền khống chế với Huyết Quang Thánh Tổ. Trước uy năng khó phá giải của Thải Quang tháp, ông đề xuất trì hoãn bảo vật này để Hàn Lập thu phục Tử Ngôn đỉnh rồi dùng chính chiếc đỉnh chống lại đối phương. Đổi lại, Hàn Lập phải đưa ông đến Hoàng Tuyền địa hỏa, lấy Hỗn Độn nhị khí khỏi Trấn Ma Tỏa và chia cho ông một phần ba. Hàn Lập còn lập tâm ma thệ rằng nếu tương lai đạo pháp đại thành và đủ sức dễ dàng giết Huyết Quang Thánh Tổ, hắn sẽ giúp Xa Kỵ Cung báo thù. Sau khi đạt thỏa thuận, Hàn Lập học bí thuật dẫn động thần niệm cùng phương pháp gây nhiễu không gian để trì hoãn Thải Quang tháp rồi hủy ngọc giản truyền pháp. Cuối cùng, lời kể về khả năng hóa thân Huyết Quang phân thành ba khiến Xa Kỵ Cung nhận ra đối phương đang sử dụng một thần thông vượt ngoài phương thức thần niệm cách giới thông thường."},{"chuong":1928,"tieuDe":"Phân Nguyên Trảm Thi Đại Pháp","tomTat":"Hàn Lập dùng hắc nguyên anh dò hỏi Xa Kỵ Cung về hóa thân của Huyết Quang và biết tới Phân Nguyên Trảm Thi đại pháp, một cấm thuật thượng cổ có thể chia nguyên thần thành nhiều thần niệm độc lập, không phân chủ thứ nhưng mang theo hậu hoạn nghiêm trọng. Sau khi hắc nguyên anh rời đi, Xa Kỵ Cung gọi nam tử bí ẩn đang nghe lén ra và mặc cả với người này về Hỗn Độn nhị khí. Hai bên thống nhất nam tử bí ẩn sẽ nhận một phần tư, đổi lại hắn không phá hỏng kế hoạch thoát vây và sẽ hỗ trợ Xa Kỵ Cung báo thù Huyết Quang. Họ nhận định chân thân Huyết Quang đang suy yếu do tu luyện cấm thuật, song vẫn lo Hàn Lập có thể bị hóa thân của đối phương giết và khiến Trấn Ma Tỏa rơi lại vào tay Huyết Quang. Trong không gian bên trong hình thái Cự Bằng, hắc nguyên anh trở về dung hợp với nguyên anh kim sắc, giúp Hàn Lập tiếp nhận toàn bộ tin tức. Dù chưa xác định phương pháp khắc chế hai bảo vật là thật hay giả, Hàn Lập vẫn quyết định thử và chuẩn bị vứt bỏ Trấn Ma Tỏa nếu thất bại. Sau hai canh giờ, hắn trở lại hình người trên một cao nguyên màu vàng, tung bảy mươi hai tiểu kiếm hóa thành hàng trăm kiếm quang rồi giấu toàn bộ vào không gian xung quanh."},{"chuong":1929,"tieuDe":"Dẫn Niệm","tomTat":"Hàn Lập giao Huyền Thiên tàn nhận cho Phạm Thánh kim thân, trang bị nhiều bảo vật cho linh khu rồi bố trí kiếm trận, các pháp trận tạm thời, phù lục và linh trùng để nghênh địch. Hắn dùng tinh huyết cùng pháp quyết ngưng tụ một huyết sắc ký hiệu trong tinh cầu, sau đó hóa thành kim mao cự viên đứng giữa trận chờ đợi. Ba hóa thân Huyết Quang đi trên huyết sắc tiểu thuyền xuất hiện và giao chiến với hắn; Nguyên Từ Thần Quang, Ngũ Sắc Hàn Diễm cùng kiếm trận lần lượt phá các đòn xúc tu của đối phương. Hai hóa thân còn lại dùng Tử Ngôn đỉnh và Thải Quang tháp ép linh khu cùng Phạm Thánh kim thân hiện hình, khiến hóa thân cầm đầu nhận ra nguồn gốc Chân Ma Pháp Tướng. Hàn Lập bí mật kích hoạt huyết sắc ký hiệu, làm Tử Ngôn đỉnh rung chuyển rồi thoát khỏi tay hóa thân đang điều khiển. Tiếng rống của kim mao cự viên phá tan trảo ảnh định bắt lại chiếc đỉnh, buộc hóa thân cầm đầu ra lệnh cho đồng bạn ném Thải Quang tháp chặn đường. Chương kết thúc khi cuộc tranh đoạt Tử Ngôn đỉnh vẫn chưa phân thắng bại."},{"chuong":1930,"tieuDe":"Biển Máu","tomTat":"Một hóa thân Huyết Quang dùng Thải Quang tháp thu lấy Tử ngôn đỉnh, nhưng linh khu cho nhẫn không gian tự bạo để làm lệch thần thông, giúp tiểu đỉnh độn xa và buộc một hóa thân khác truy đuổi. Hóa thân cầm đầu thúc giục ma ảnh tạo biển máu kỳ độc, nhanh chóng ăn mòn các pháp trận tạm thời của Hàn Lập, song kiếm mạc thanh sắc vẫn ngăn được huyết lãng. Hắn tiếp tục ngưng tụ hàng trăm huyết tằm có cánh, dùng tơ máu khóa phần lớn kiếm quang và làm phòng tuyến lộ khe hở. Hàn Lập điều khiển kiếm trận hóa ngũ trảo thanh long, phóng kiếm quang, cột sáng và hoa sen xanh để giằng co với biển máu. Hóa thân cầm Thải Quang tháp thuấn di lên phía trên, gọi tháp ảnh cùng thất sắc quang hà trấn áp toàn bộ kiếm trận, khiến Hàn Lập phải triệu hiện hư ảnh đền đài lầu các đối kháng. Trong lúc đó, Phạm Thánh kim thân dùng kim sắc lốc xoáy hút huyết sắc tiểu thuyền, nhưng ma ảnh hợp hơn mười xúc tu thành cự thương, phá tan lốc xoáy và sáu đạo ánh đao rồi đâm vào ngực kim thân."},{"chuong":1931,"tieuDe":"Kịch Chiến","tomTat":"Phạm Thánh kim thân dùng hấp lực khóa cự thương của Ma Ảnh, sau đó giao chiến giằng co với cự mãng do binh khí này biến thành và dùng thần quang từ ba mắt dọc phá tan độc khí gây buồn ngủ. Trên không trung, cự tháp đang trấn áp kiếm trận bị Cửu Cung Thiên Kiền Phù cùng lực lượng phát sinh từ vụ tự bạo không gian bảo vật kiềm chế. Hàn Lập gọi ra hai tòa Cực Sơn, phối hợp với lưới lục ti của linh khu để tranh đoạt Thải Quang tháp, nhưng hóa thân cầm tháp dùng cơn lốc bảy màu phá lưới và tìm cách cắt đứt liên hệ thần niệm để cưỡng đoạt hai ngọn núi. Nhờ thần niệm cường đại cùng sự phối hợp của quyền ảnh, quang hà và kiếm khí, Hàn Lập phá tan cơn lốc rồi thu hồi cả hai pháp bảo. Hắn tiếp tục ném hai tòa Cực Sơn xuyên thủng quang mạc của huyết sắc tiểu thuyền, buộc hóa thân cầm đầu của Huyết Quang Thánh Tổ hợp nhất với Ma Ảnh và hiện ra trong ma giáp, huyết dực cùng Bát quỷ hoàn. Cuối cùng, hóa thân cầm tháp niệm thượng cổ chú ngữ, khiến quầng sáng bảy màu mang ký hiệu vàng và dao động pháp tắc lực nhanh chóng lan khắp bầu trời."},{"chuong":1932,"tieuDe":"Khốn Địch","tomTat":"Hàn Lập điều động mười ba tử văn Phệ Kim trùng và tung quyền ảnh công kích, nhưng tất cả đều bị thất thải quang mang quanh Thải Quang tháp đẩy lui. Hắn biến thành Sơn Nhạc cự viên khổng lồ và thi triển Kim võng hống, khiến các hóa thân Huyết Quang choáng váng, kim sắc phù văn tan rã và quầng sáng phòng hộ chao đảo. Trong lúc hóa thân cầm đầu bị Phệ Kim trùng kiềm chế, Phạm Thánh kim thân nhập vào cự viên, giúp Hàn Lập hóa thành ba đầu sáu tay rồi đánh tan hoàn toàn thất thải quang mang. Hóa thân Huyết Quang dùng tinh huyết gia trì tiểu tháp, còn hóa thân cầm đầu nhập vào bên trong để ổn định pháp bảo. Hàn Lập lập tức cấm chế không gian, dùng kim sắc điện võng tạo kim cầu, phối hợp với Linh khu bọc thêm lục ti và phù lục để vây kín đối thủ. Tuy nhiên, Thải Quang tháp vẫn khiến các lớp phong cấm biến dạng và đứt gãy, buộc Hàn Lập quyết định sử dụng phương án khác dù có thể phải hy sinh một kiện trọng bảo. Cuối chương, hắn ném cự cầu lên độ cao hơn ngàn trượng, trong khi Linh khu vượt lên chờ sẵn và ném một vật chưa rõ về phía cự cầu."},{"chuong":1933,"tieuDe":"Nghịch Chuyển","tomTat":"Hàn Lập vận dụng Vạn Kiếm Đồ phối hợp với Cửu Cung Thiên Kiền Phù, ép Thải Quang Tháp cùng hóa thân Huyết Quang ký phụ bên trong lộ diện. Biển kim sắc phi kiếm liên tục công kích, khiến hóa thân phải dồn pháp lực phòng thủ và không thể đưa bảo tháp thoát khỏi phù trận. Một hóa thân Huyết Quang khác quay lại sau khi truy đuổi Tử Ngôn Đỉnh nhưng bị Linh khu dùng hắc tia cùng Ngân sắc đoản thước giữ chân. Hóa thân cầm đầu triệu hồi tám huyết sắc bóng quỷ nhập thể, biến thành Cự Ma đối đầu với hình thái Kim Mao Cự Viên của Hàn Lập. Hàn Lập thi triển Niệm Kiếm Quyết mới lĩnh ngộ, khiến kiếm ảnh xuất hiện trong thần thức Cự Ma và chém thương thần hồn đối phương. Dù chịu phản phệ đến mức toàn thân bắn ra tơ máu, hắn vẫn áp sát trong trạng thái ba đầu sáu tay và dùng sáu kim sắc trường nhận chém xuống đầu Cự Ma."},{"chuong":1934,"tieuDe":"Lui Địch","tomTat":"Hàn Lập trong hình thái cự viên ba đầu sáu tay dùng sáu kim nhận chém bay thủ cấp Cự Ma, nhưng đối phương mọc lại đầu mới bằng cách tiêu hao một đầu quỷ trên vai. Hai bên tiếp tục cận chiến bằng huyết sắc cự côn và các loại kim binh, trong khi Tử văn Phệ Kim trùng cùng hôi sắc cự mãng cũng lao vào chiến đoàn. Vụ va chạm dữ dội làm không gian sụp đổ, khiến Hàn Lập bị cháy xém và mất ba kim nhận, còn Cự Ma bị đánh nát hai bên vai rồi chịu thêm phản phệ khi cự mãng bị hủy. Ở một chiến tuyến khác, hóa thân Huyết Quang dùng Thải Quang tháp phá Cửu cung thiên kiền phù và thoát khỏi Vạn Kiếm đồ, nhưng cả bản thân lẫn bảo tháp đều suy yếu rõ rệt. Cự Ma nhận thấy kế hoạch đoạt Trấn Ma Tỏa đã thất bại và hai kiện Huyền Thiên tàn bảo của phe mình đều bị mất hoặc tổn hại. Khi Hàn Lập khôi phục thân thể, tái hiện sáu kim binh và dùng đoạn Huyền Thiên tàn bảo dẫn động thiên địa nguyên khí, Cự Ma lập tức ra lệnh rút lui; hắn cùng hóa thân cầm Thải Quang tháp nhanh chóng rời khỏi chiến trường."},{"chuong":1935,"tieuDe":"Phế Thành","tomTat":"Ba hóa thân Huyết Quang Thánh Tổ chấm dứt giao chiến, hợp lực rút lui và đe dọa sẽ chuẩn bị đầy đủ bảo vật để báo thù Hàn Lập. Hàn Lập không truy kích mà giải trừ biến thân, thu hồi linh khu cùng Phệ Kim Trùng rồi dùng bí thuật của Xa Kỵ Cung gọi Tử Ngôn đỉnh trở về. Vì chiếc đỉnh vẫn còn lưu thần niệm của Huyết Quang, hắn dùng lưới điện, hộp bạch ngọc và pháp trận để tạm phong ấn nó. Sau khi nhận rõ sự đáng sợ của tu sĩ Đại Thừa và tiếc nuối vì Vạn Kiếm Đồ đã bị hủy, Hàn Lập quyết định tìm Hoàng Tuyền địa hỏa trước khi bí mật trở về Thiên Uyên Thành. Ba hóa thân Huyết Quang dùng huyết sắc tiểu thuyền trở lại Ỷ Thiên Thành đang nằm dưới sự kiểm soát của Ma tộc, rồi ra lệnh mở truyền tống trận tới đại quân Thánh tộc gần nhất. Nửa tháng sau, Hàn Lập bay qua một phế thành Nhân tộc và bất ngờ phát hiện dị trạng bằng thần niệm."},{"chuong":1936,"tieuDe":"Gặp Cũ","tomTat":"Hàn Lập phát hiện năm tu sĩ Hóa Thần đang bao vây một căn nhà được cấm chế bảo vệ, liền phóng khí tức Hợp Thể khiến chúng kinh hãi tháo chạy. Người được giải vây là Hứa Thiên Vũ cùng hai cháu gái, trong đó Tiểu Thanh vì bất bình chuyện hắn tha cho tà tu mà lỡ lời rồi phải xin lỗi. Hứa Thiên Vũ mời Hàn Lập vào căn nhà cũ của Hứa gia và kể rằng gia tộc đã chuyển đến Trấn Hoàng Thành trước ma kiếp. Nàng cùng một số tộc nhân từng theo Huyết Linh rời thành, nhưng đoàn người bị đại quân Ma tộc đánh tan trên đường trở về; Huyết Linh phá được vòng vây song vẫn bị vài Ma tộc cao cấp truy đuổi. Qua lời kể về các thành trì thất thủ, việc Ma tộc trú quân và nô dịch phàm nhân, Hàn Lập nhận định cuộc ma kiếp lần này mang ý đồ chiếm đóng Linh Giới lâu dài, với mục tiêu có thể bao gồm nhiều chủng tộc. Sau gần nửa canh giờ dò hỏi tình hình quanh Trấn Hoàng Thành, hắn khuyên ba nữ tu sớm trở về thành rồi tiếp tục lên đường. Khi hắn đã đi xa, Tiểu Thanh hỏi Hứa Thiên Vũ về cảnh giới cùng mối giao tình cũ giữa hai người tại Thiên Uyên Thành."},{"chuong":1937,"tieuDe":"Hư Hoàng Đỉnh","tomTat":"Hứa Thiên Vũ từ chối kéo Hàn Lập vào nhiệm vụ bí mật vì việc này liên quan trực tiếp đến khả năng Băng Phách tiên tử trở về, rồi dẫn hai nữ tử Hứa gia tiếp tục tìm vật cần thiết. Trong một động quật xa xôi, Huyết Linh giết ba Ma tộc cao giai và dùng Hư Thiên Đỉnh mở mật thất do bản thể Băng Phách để lại. Nàng thu được Hư Hoàng Đỉnh, một bảo đỉnh có công hiệu vượt Hư Thiên Đỉnh và Hư Linh Đỉnh, sau đó dùng huyết sắc lôi hỏa phá hủy đại sảnh để xóa dấu vết. Huyết Linh rời động quật và bay về thành nhỏ nơi ba nữ tử Hứa gia đang chờ. Một tháng sau, Hàn Lập bắt gặp hơn một trăm Ma tộc tinh nhuệ đang vây công hơn mười tu sĩ Nhân tộc. Khi pháp trận sắp tan vỡ và lão giả râu bạc chuẩn bị thả Nguyên Anh liều mạng, Hàn Lập chấn nhiếp chiến trường rồi phóng hàng trăm kiếm quang tiêu diệt toàn bộ Ma tộc cùng Nguyên Anh của chúng."},{"chuong":1938,"tieuDe":"Hắc Vũ Thượng Nhân","tomTat":"Sau khi tiêu diệt sạch nhóm ma tộc vây đánh Thiên Mã Môn, Hàn Lập từ chối nhận đại lễ và chỉ cho những người sống sót đi về phía tây. Giản Phi Thiên suy đoán ân nhân có thể là Hàn Thỉnh hoặc Hàn Lập, sau đó từ bỏ kế hoạch đến Hắc Thủy sơn mạch, cho môn nhân thu chiến lợi phẩm rồi rút lui. Trên hành trình tiếp theo, Hàn Lập nhiều lần gặp ma tộc vây tu sĩ nhân tộc và đều quét sạch chúng khi không có Ma Tôn hiện diện. Nửa tháng sau, hắn đến Hoàng Tuyền địa hỏa và gặp Thiên Thiền đại sư cùng lão giả Hợp Thể trung kỳ Vũ Khiếu Thiên, biệt hiệu Hắc Vũ Thượng Nhân. Vũ Khiếu Thiên kinh ngạc trước tốc độ tiến giai của Hàn Lập và tiết lộ Thánh đảo định kỳ mời các tu sĩ mới đạt Hợp Thể lên đảo. Hàn Lập xác nhận mình là khách khanh Thiên Uyên thành, đồng thời cho biết các đại hình cứ điểm bên ngoài thành gần như đều đã bị vây hãm. Cuối cùng, hắn hỏi nguyên nhân Thiên Thiền và Vũ Khiếu Thiên cùng che giấu khí tức và xuất hiện tại vùng địa hỏa này."},{"chuong":1939,"tieuDe":"Hoàng Tuyền Địa Hoả","tomTat":"Thiên Thiền đại sư và Vũ Khiếu Thiên tiết lộ họ phụng mệnh Thánh đảo tới Hoàng Tuyền địa hỏa để bắt sống Hoàng Lương thạch linh, một linh vật được thai nghén từ Hoàng Lương mộng thạch và sở hữu ảo thuật cực mạnh. Một đại năng của Thánh đảo đã bói được kỳ độ kiếp buộc linh vật phải rời nơi ẩn náu, tạo ra cơ hội hiếm có để vây bắt. Khi biết tinh thạch trong cơ thể nó là vật trọng yếu đối với kế hoạch chống ma kiếp của Nhân tộc, Hàn Lập nhận lời hỗ trợ và tạm hoãn việc dùng địa hỏa luyện chế pháp khí. Hắn ném một pháp bàn màu trắng xuống cự hố để thăm dò, nhưng pháp khí nhanh chóng bị kỳ hàn đóng băng rồi vỡ tan. Thiên Thiền giải thích Hoàng Tuyền địa hỏa là loại âm hỏa đặc thù, không thể tùy tiện hấp thu luyện hóa và chỉ phù hợp với một số pháp quyết riêng. Ba người sau đó bàn về lời đồn địa hỏa thông tới Minh giới, giới hạn thâm nhập của tu sĩ và con đường phi thăng Chân Tiên giới. Cuộc trò chuyện chuyển thành màn tranh biện giữa Thiên Thiền và Vũ Khiếu Thiên về trường sinh, thiện ác, nhân quả và mục tiêu tu hành."},{"chuong":1940,"tieuDe":"Bẫy Rập","tomTat":"Hàn Lập, Vũ Khiếu Thiên và Thiên Thiền đại sư nhập định suốt ba ngày bên cự hố để chờ Hoàng Lương Thạch Linh độ kiếp. Khi sương vàng, hàn khí, mây đen và lôi điện đồng loạt xuất hiện, họ xác nhận thiên kiếp của linh vật đã tới. Hai người Thánh Đảo lập tức dựng đại trận, bố trí ba Bạo Viêm Điểu cùng một bọ cạp xanh lam có cánh để kiềm chế mục tiêu. Họ còn dùng kỳ hàn và cuồng phong tạo bão tuyết phủ kín đỉnh núi, xóa sạch khí tức còn sót lại. Vũ Khiếu Thiên triển khai Ngân Tiêu Lôi Võng để khóa đường trốn trên không rồi giao Hàn Lập nhiệm vụ ngăn Thạch Linh phá cấm chế chạy xuống lòng đất. Dù tự tin vào thần niệm không dưới cấp Đại Thừa, Hàn Lập vẫn được cảnh báo phải đề phòng ảo thuật của linh vật. Sau khi hoàn tất bố trí, cả ba ẩn thân trong lúc vòng xoáy lôi điện trên trời và vòng xoáy sương vàng dưới hố đồng thời ngưng tụ, báo hiệu Hoàng Lương Thạch Linh sắp xuất hiện."},{"chuong":1941,"tieuDe":"Hoàng Lương Thạch Linh","tomTat":"Trên đỉnh núi, Hoàng Lương Thạch Linh dùng kim sắc yêu hỏa mang kỳ hàn chống lại thiên lôi và hiện nguyên hình giống thiềm thừ ba mắt. Thiên Thiền đại sư cho Hàn Lập biết yêu hỏa này được hình thành từ Hoàng Tuyền địa hỏa kết hợp với yêu khí sau mấy vạn năm tu luyện. Thạch linh tiếp tục phun kim sắc cự hoa nuốt lôi cầu, chuyển hóa lực lượng thiên lôi để tăng hình thể, khí tức và tu vi. Nhận thấy đối phương sẽ càng mạnh nếu tiếp tục vượt kiếp, Vũ Khiếu Thiên yêu cầu Hàn Lập và Thiên Thiền lập tức phối hợp ra tay. Vũ Khiếu Thiên dùng hắc ti, ngân chung và Ngân Tiêu Lôi Võng, còn Thiên Thiền dùng chuỗi phật châu hóa thành ngũ sắc quang cầu để vây công thạch linh. Ngân chung phá hủy kim sắc cự hoa rồi chụp kín mục tiêu, trong khi Ngân Tiêu Lôi Võng đánh tan và hấp thu hơn mười lôi giao từ trên trời. Hoàng Lương Thạch Linh cuối cùng bùng phát kỳ hàn cùng kim sắc yêu hỏa, phá nát ngân chung và lao trở lại cự hố để chạy trốn."},{"chuong":1942,"tieuDe":"Vây Công Thạch Linh","tomTat":"Vũ Khiếu Thiên, Thiên Thiền đại sư cùng các linh thú đồng loạt dùng âm ba, cấm chế, hỏa vân và độc mang vây công Hoàng Lương thạch linh, ngăn nó trở về địa hỏa. Thạch linh mở con mắt thứ ba thi triển thiên phú ảo thuật, khiến phần lớn đối thủ rơi vào những ảo cảnh riêng, nhưng phi hạt xanh lam không chịu ảnh hưởng. Nó nhân cơ hội tập trung đánh phá một điểm của cấm chế, song Hàn Lập dựa vào thần niệm cường đại thoát khỏi ảo thuật và dùng ngân xích phá tan toàn bộ quang cầu. Thạch linh tiếp tục tung Âm Hàn yêu hỏa nhưng bị Ngũ sắc hàn diễm của Hàn Lập kiềm chế. Trước sức ép từ hắc sắc tiểu sơn, nó buộc phải xuất bản mệnh yêu đan, tạo lực bài xích và vô số hỏa xà để giữ ngọn núi trên cao. Hàn Lập sau đó dùng đôi cánh trong suốt áp sát, mở Phá Diệt Pháp Mục đánh trúng con mắt thứ ba và dùng tiếng hừ công kích thần hồn, khiến thạch linh đau đớn, thân hình lung lay như sắp ngã."},{"chuong":1943,"tieuDe":"Chia Tay","tomTat":"Hàn Lập dùng Ích Tà Thần Lôi vây Hoàng Lương Thạch Linh, còn Vũ Khiếu Thiên điều khiển phi hạt màu xanh lam khắc chế yêu hỏa của linh vật. Khi thạch linh định tự bạo, Vũ Khiếu Thiên dùng Ngân Tiêu Lôi Võng ép nó thu nhỏ, phong bế pháp lực rồi bắt sống để mang về Thánh đảo. Qua cuộc trò chuyện sau đó, Hàn Lập biết Tế lôi thuật hoàn chỉnh gồm hai nửa và bản thân chỉ được Địa Uyên tứ đại yêu vương truyền nửa đầu, trong khi nửa sau đang được giữ tại Thánh đảo. Thiên Thiền cáo từ để trở về trợ giúp phòng thủ Thánh Hoàng thành, còn Vũ Khiếu Thiên mang thạch linh trở lại Thánh đảo. Hàn Lập quyết định sau này sẽ tới Thánh đảo tìm phần pháp quyết còn thiếu, nhưng trước mắt phải thương lượng với ma đầu trong hố lớn để lấy hỗn độn nhị khí. Hắn bố trí trận kỳ tạo sương mù che kín đỉnh núi, thả các thủ đoạn chuẩn bị xuống khu vực quanh hố rồi xuất Nguyên Anh khỏi cơ thể."},{"chuong":1944,"tieuDe":"Phong Tà Và Khiên Cơ Đại Pháp","tomTat":"Hàn Lập dùng nguyên anh phá lớp tơ vàng quanh hộp gỗ trắng sữa, kích hoạt nhóm ngọc năm màu rồi đưa một hóa thân thần niệm vào không gian trong Trấn Ma Tỏa. Tại đây, hắn gặp Phong Tà, kẻ đã ngầm giữ chân Xa Kỵ Cung và muốn thay lão giao phương pháp lấy, luyện hóa Hỗn Độn Nhị khí để đổi lấy một phần ba số khí. Xa Kỵ Cung thoát khỏi sự cản trở, xuất hiện giữa không gian đã biến thành sa mạc và lập tức giao chiến với Phong Tà. Phong Tà vận dụng Khiên Cơ Đại Pháp đã luyện đến mức đại thành, phân tách cự lực và làm đòn công kích của Xa Kỵ Cung mất một nửa uy năng. Khi Xa Kỵ Cung chuẩn bị tiếp tục ra tay, Phong Tà tiết lộ phương pháp cũ dùng để lấy Hỗn Độn Nhị khí có thiếu sót trí mạng và đề nghị truyền phương pháp thay thế. Lo ngại cuộc chiến sẽ khiến cả hai lưỡng bại câu thương và để Huyết Quang hưởng lợi, Xa Kỵ Cung tạm ngừng công kích để nghe truyền âm. Một ngày sau, Vũ Khiếu Thiên vội vã trở về Thánh đảo nhưng bị hai ngọn núi cao bất ngờ nổ tung và đổ xuống mai phục, còn kết quả chưa rõ."},{"chuong":1945,"tieuDe":"Ma Nữ Hiện Pháp","tomTat":"Vũ Khiếu Thiên dùng chuông bạc và Ngân Tiêu lôi võng chống lại hai thạch cự thủ, nhưng chuông bị đánh hỏng còn lôi võng bị một ngọc thủ bí ẩn đoạt mất. Hai cự thủ hợp kích phá tan phòng ngự, chiến giáp và pháp thể của lão, buộc Nguyên Anh phải thoát vào hư không. Vũ Khiếu Thiên dùng Thanh Minh lệnh chống hấp lực của cổ kính để tiếp tục chạy trốn, song lam sắc cung trang nữ tử Nguyên Sát hiện thân và triệu hồi ma ảnh ba đầu sáu tay bắt lão trở lại. Sau khi trói và thu Nguyên Anh vào cổ kính, Nguyên Sát kiểm tra trữ vật thủ trạc rồi phát hiện Hoàng Lương thạch linh, qua đó suy đoán mục đích Vũ Khiếu Thiên tới đây. Nàng quyết định tìm nơi yên tĩnh để phân thân tiến hành sưu hồn tù binh, dù bí thuật tự khóa thần niệm của tu sĩ Nhân tộc có thể hạn chế kết quả. Cuối chương, hai ngọn núi lộ ra hai thạch cự nhân bốn tay cao ngàn trượng, chính là hai trưởng lão đã trợ giúp Nguyên Sát hủy pháp thể đối phương."},{"chuong":1946,"tieuDe":"Tân Đại Địch","tomTat":"Một nữ tử Ma tộc bí ẩn thu hai cự nhân đá thành thạch cầu rồi rời đi, trong khi Hàn Lập thu hồi Nguyên Anh và thần niệm hóa thân khỏi Trấn Ma Tỏa. Vì nghi ngờ hai nguyên thần ma đầu còn che giấu mục đích, hắn dự định sau khi xử lý Hỗn độn nhị khí sẽ mang Trấn Ma Tỏa trở lại Ma giới. Hàn Lập vận dụng pháp tướng, âm hỏa và bí thuật suốt bảy ngày, cuối cùng rút được đoàn thanh khí chứa hai điểm sáng đen trắng có khả năng hỗ trợ hắn tiến lên Hợp Thể hậu kỳ. Đúng lúc ấy, nữ tử phá tan cấm chế, tiết lộ đã sưu hồn một tu sĩ Nhân tộc và nhận ra cả Trấn Ma Tỏa lẫn Hỗn độn nhị khí. Nàng dùng khăn lụa bạch sắc tranh đoạt bảo vật, đồng thời hai thạch chưởng khổng lồ từ lòng đất đánh úp Hàn Lập. Hàn Lập cho kim quang của pháp tướng bạo liệt để trì hoãn khăn lụa, điều Linh khu đoạt bảo vật rồi biến thành kim mao cự viên phá một phần thạch chưởng. Linh khu sau đó mang hộp gỗ cùng Hỗn độn nhị khí nhập trở lại thân thể cự viên, nhưng cuộc đối đầu với cường địch vẫn chưa kết thúc."},{"chuong":1947,"tieuDe":"Thạch Điện","tomTat":"Hàn Lập chuyển từ kim mao cự viên thành ngân sắc cự bằng bốn cánh, dùng tốc độ xuyên không để đào thoát khỏi nữ tử áo lam. Nữ tử hợp hai thạch thủ thành một tòa thạch điện xám trắng rồi điều khiển nó truy kích, đồng thời nhận ra Hàn Lập là tu sĩ Nhân tộc từng gặp hơn nghìn năm trước và được thuộc hạ gọi là Nguyên Sát. Theo lệnh nàng, Thạch Cảm cùng một đồng bạn dựng đại hình ngũ sắc truyền tống phù trận, đưa cả thạch điện đến gần Hàn Lập để chặn đường. Hàn Lập nhận ra trận pháp và cưỡng ép thi triển Phá Diệt pháp mục trong hình thái cự bằng, gây hỗn loạn không gian khiến thạch điện tạm thời không thể tiếp tục truy kích. Nguyên Sát truyền ma khí giúp hai thuộc hạ hồi phục, sau đó liên tục dùng truyền tống để kéo gần khoảng cách và tránh xuất hiện quá sát Hàn Lập. Cuộc truy đuổi kéo dài hơn nửa ngày khiến Hàn Lập phải nghĩ đến một phương án thoát thân khác, trong khi Nguyên Sát bí mật tế cổ kính màu đen để liên lạc với một Ma tộc chưa rõ danh tính."},{"chuong":1948,"tieuDe":"Đại Địch Liên Thủ","tomTat":"Nguyên Sát tiến vào khu vực do Huyết Quang phụ trách để truy sát Hàn Lập theo lệnh Lục Cực, đồng thời muốn báo thù cho tia phân hồn từng bị hắn tiêu diệt tại Nhân giới. Huyết Quang đề nghị cho ba hóa thân mang Càn Khôn Bàn tới mai phục phía trước, đổi lại Nguyên Sát phải giúp hắn đối phó một tu sĩ Hợp Thể kỳ khác và rời khỏi địa bàn sau khi hoàn tất giao dịch. Trong lúc chạy trốn bằng hình thái Tứ sí Côn Bằng, Hàn Lập bố trí hơn mười pháp trận cạm bẫy nhưng chúng nhanh chóng bị người phía sau phá bỏ. Từ khí tức quen thuộc, hắn đoán kẻ truy sát có liên hệ với Nguyên Sát và quyết định dùng đan dược cùng cực phẩm linh thạch để kéo đối phương vào cuộc đua tiêu hao pháp lực. Sau nửa ngày, tần suất thuấn di của thạch điện bắt đầu giảm đúng như dự đoán của hắn. Khi tới một vùng đầm lầy, Báo Lân Thú bất ngờ tỉnh lại, nói được tiếng người và cảnh báo rằng phía trước có những khí tức mang ác ý. Cùng lúc đó, ba hóa thân Huyết Quang theo dõi Tứ sí Côn Bằng qua tấm đá quan sát, nhận ra Hàn Lập và chờ sẵn trong ổ phục kích."},{"chuong":1949,"tieuDe":"Chặn Lại","tomTat":"Ba hóa thân của Huyết Quang Thánh Tổ ẩn trong Càn Khôn Bàn, bàn cách giao Hàn Lập cho Nguyên Sát nhưng giữ lại những bảo vật quan trọng. Hàn Lập phát hiện mai phục, phá lớp che giấu và buộc đối phương dựng quang mạc cấm không để trực tiếp chặn đường. Hắn dùng Kinh Chập Quyết hóa thành Thiên Phượng, mở khe không gian xuyên qua cấm chế rồi trở lại hình thái Côn Bằng tiếp tục đào thoát. Ba hóa thân Huyết Quang điều khiển Càn Khôn Bàn truy kích, còn Nguyên Sát thúc thạch điện bám sát phía sau. Trong nhiều tuần tiếp theo, Hàn Lập dùng điện hồ, kiếm khí và các hình thái chân linh để phá tan nhiều đội quân Ma tộc cùng đàn ma thú chặn đường. Sau khi đối đầu hai Ma tộc tôn giả trên một hồ nước, hắn tiếp tục chạy trốn thêm nhiều tuần. Cuối cùng, hơn mười huyết sắc Ma tộc có khả năng phục hồi giữ chân hắn tại một vùng ao đầm, trong khi Càn Khôn Bàn và thạch điện đã tiến đến cách hơn nghìn dặm."},{"chuong":1950,"tieuDe":"Chật Vật","tomTat":"Hàn Lập thả mấy ngàn Phệ Kim trùng thành thục, nhanh chóng cắn nuốt sạch kim sắc huyết ảnh rồi tiếp tục chạy trốn bằng cự bằng chi thân và lôi độn. Nguyên Sát cùng Huyết Quang đuổi tới, đánh giá giới hạn điều khiển linh trùng của hắn và bàn cách dùng bảo vật thuộc tính mộc để khắc chế. Hai hóa thân Thánh tổ thống nhất gọi thêm tinh nhuệ bên Lục Cực, đồng thời dùng quân của Huyết Quang phong tỏa đường tới Thiên Uyên Thành và các cứ điểm lớn của Nhân tộc. Sau hai tháng vượt qua ba bốn chục đợt chặn đánh, Hàn Lập chỉ còn chưa đầy năm thành pháp lực và hơn một nửa thần niệm, phải liên tục dùng đan dược để duy trì. Nhận thấy tuyến đường về Thiên Uyên Thành đã bị bố trí quá nhiều quân mai phục, hắn quyết định đổi hướng để tránh bị bào mòn đến kiệt sức. Trước sự giám sát của ba hóa thân Huyết Quang qua Càn Khôn Bàn, Hàn Lập bất ngờ dừng lại, khôi phục hình người và huyễn hóa thành tám thân ảnh giống nhau để bắt đầu kế nghi binh."},{"chuong":1951,"tieuDe":"Thoát Xác","tomTat":"Nhiều thân ảnh Hàn Lập tản ra các hướng, khiến hóa thân Huyết Quang dùng ma ảnh cự nhãn dò xét và nhận định có hai mục tiêu mang thực thể. Nguyên Sát cùng ba hóa thân Huyết Quang chia nhau truy bắt, nhưng một thân ảnh không có khí tức vẫn ẩn tại nơi xuất phát, chờ đối phương đi xa rồi dùng tấm da biến thành cự lang màu xám để tiếp tục chạy về Thiên Uyên thành. Ở một hướng khác, Nguyên Sát dùng thạch điện và ngũ sắc quang trận đánh sập cả ngọn núi nơi một thân ảnh Hàn Lập biến mất, sau đó kiểm tra phế tích nhưng không tìm thấy dấu vết. Hóa thân Huyết Quang báo rằng mục tiêu phía mình đã giết hơn nửa quân ngăn chặn và vượt qua ba vòng phong tỏa, khiến Nguyên Sát rời đi hỗ trợ. Hai canh giờ sau, một khúc gỗ trong phế tích hóa lại thành linh khu của Hàn Lập, cho thấy nó đã dùng nguyên hình Chi tiên chi thể qua mặt cả đợt oanh kích lẫn thần niệm dò xét. Nữ đồng xác nhận nhiệm vụ đã hoàn thành, nhập trở lại linh khu rồi cùng nó rời đi tìm nơi ẩn náu. Trong khi đó, hơn trăm Ma tộc tinh nhuệ vẫn vây quanh Càn Khôn Bàn trên một ngọn núi khác, tiếp tục tìm kiếm mục tiêu đang bị phong tỏa."},{"chuong":1952,"tieuDe":"Giương Đông Kích Tây","tomTat":"Ba hóa thân Huyết Quang dùng Càn Khôn Bàn phong tỏa và rà soát sơn cốc nhưng không thể phát hiện hóa thân Hàn Lập đang ẩn dưới lòng đất. Nguyên Sát đưa Hai Thạch trưởng lão tới hỗ trợ, trong khi Huyết Quang cử một hóa thân đi theo để bí mật giám sát nàng. Hai trưởng lão dựng Thạch Lôn đồ đằng, giúp Nguyên Sát ngưng tụ ma nguyên thành hơn vạn quạ đen có thể xuyên qua nhiều loại vật chất để dò tìm mục tiêu. Cuộc tìm kiếm vẫn chưa có kết quả thì hai hóa thân Huyết Quang ở nơi khác truyền tin rằng một Hàn Lập khác đã phá nhiều phòng tuyến, giết hai trợ thủ cấp Ma tôn rồi chạy về phía Thiên Uyên Thành. Việc người đào tẩu sử dụng Huyền Thiên tàn bảo và Phệ Kim trùng khiến Huyết Quang xác định đó mới là bản thể. Nhận ra mình đã trúng kế giương đông kích tây, huyết bào thiếu niên yêu cầu Nguyên Sát lập tức thu pháp để chuyển sang truy đuổi."},{"chuong":1953,"tieuDe":"Truy Anh","tomTat":"Nguyên Sát xác nhận mục tiêu trước mắt chỉ là một hóa thân của Hàn Lập nhưng vẫn quyết bắt sống, còn Huyết Quang dẫn một nửa quân Ma tộc tiếp tục truy tìm bản thể. Đàn quạ của Nguyên Sát phát hiện đệ nhị Nguyên Anh đang ẩn trong sơn cốc, buộc nó dùng ma khí hóa quái mãng và phân hóa nhiều tiểu nhân để phá vòng vây. Khi phần lớn hư ảnh bị đánh tan, đệ nhị Nguyên Anh hao tổn tinh huyết thi triển Huyết Ảnh độn, khiến Nguyên Sát phải thu hồi thạch điện và dẫn hơn trăm Ma tộc truy đuổi. Ở một hồ nước xa xôi, bản thể Hàn Lập dùng kiếm quang hóa thanh long tiêu diệt một Ma tộc cao giai cùng Nguyên Anh của đối phương, sau đó quyết định đổi hướng vì tuyến đường hiện tại đã bị phát hiện. Chương đồng thời hé lộ kế hoạch thoát vây trước đó: Hàn Lập tạo nhiều hư ảnh, để Khúc Nhi điều khiển linh khu và đệ nhị Nguyên Anh điều khiển kim thân làm mồi nhử, còn bản thể dùng Thái Nhất Hóa Thanh phù hư hóa rồi ẩn lại tại chỗ. Tuy nhiên, hiệu lực của tiên phù không còn duy trì được lâu do tu vi Hàn Lập đã tăng cao."},{"chuong":1954,"tieuDe":"Độn Xa","tomTat":"Hàn Lập dùng linh khu, kim thân và đệ nhị Nguyên Anh làm kế kim thiền thoát xác, đồng thời chuẩn bị các thủ đoạn ẩn nấp và độn thoát cho từng bên để đánh lừa hóa thân Huyết Quang. Sau khi chủ động hiện thân thu hút sự chú ý về bản thể, hắn chính thức từ bỏ Thiên Uyên thành và liên tục đổi hướng chạy trốn. Ba hóa thân Huyết Quang huy động đông đảo Ma tộc, tận dụng các điểm truyền tống đã chiếm giữ và nhiều lần suýt chặn được hắn, buộc hắn bỏ cả lộ tuyến tới Trấn Hoàng Thành cùng các cứ điểm lớn. Nguyên Sát sau đó tham gia truy đuổi, dùng một phương pháp chưa rõ để liên tục xác định vị trí đại khái của Hàn Lập và dồn hắn tới vùng biên hoang vu gần Man Hoang thế giới. Sau hơn nửa năm, Hàn Lập đã hao tổn đáng kể pháp lực và tinh thần nhưng vẫn quyết định tiếp tục giằng co thay vì quay lại tử chiến. Trong lúc truy đuổi, Nguyên Sát từ chối tiến vào Càn Khôn Bàn vì đề phòng công pháp thôn phệ của Huyết Quang, rồi dùng bí mật về Trấn Ma Tỏa và Hỗn độn nhị khí để thương lượng. Hai bên cuối cùng thỏa thuận chia Trấn Ma Tỏa, Tử Ngôn đỉnh, Hỗn độn nhị khí cùng các trọng bảo khác và chính thức kết minh truy bắt Hàn Lập."},{"chuong":1955,"tieuDe":"Hắc Quan","tomTat":"Nguyên Sát tiết lộ rằng Đệ nhị Nguyên Anh của Hàn Lập từng tự bạo anh thể để phân hồn chạy thoát, còn nàng chỉ bắt và luyện hóa được một phần tàn hồn nhằm cảm ứng phương vị bản thể. Huyết Quang đề nghị hai bên cùng thúc giục Càn Khôn Bàn để giảm hao tổn pháp lực nhưng Nguyên Sát từ chối, cho biết Thạch Ma điện do hai vị đại Thạch Ma trưởng lão hóa thành vốn đã giúp nàng tiết kiệm sức lực. Sau khi liên lạc chấm dứt, ba hóa thân Huyết Quang nghi ngờ Nguyên Sát nói dối và âm thầm định dùng Chân Ma tinh duy trì cuộc truy đuổi cho đến khi nàng suy yếu, qua đó độc chiếm quyền xử lý bảo vật của Hàn Lập. Trong Thạch Ma điện, phân thân nguyên thần Lục Cực tỉnh lại sau nhiều năm bị phong bế bên trong thân thể hóa thân của Nguyên Sát. Nguyên Sát lấy ra Hắc Quan chứa thân xác hóa thân gốc của Lục Cực, tháo bỏ các đạo cấm chế và mở nắp khiến ma khí tràn ngập đại điện. Nguyên thần Lục Cực hóa thành lục sắc tiểu nhân rồi bay vào quan tài, chính thức trở về thân xác của mình."},{"chuong":1956,"tieuDe":"Ngẫu Ngộ Man Hoang","tomTat":"Nguyên Sát đánh thức hóa thân Lục Cực trong ngọc quan và cầu viện nàng tham gia truy sát Hàn Lập. Biết Hàn Lập đang giữ Trấn Ma Tỏa, Tử Ngôn đỉnh và Hỗn độn nhị khí, Lục Cực đồng ý tương trợ, cung cấp Ma tinh cho Nguyên Sát phục hồi pháp lực và đồng thời đề phòng Huyết Quang. Một tháng sau, Hàn Lập vượt màn sương cấm chế tại tận cùng Nam Thiên để tiến vào Man Hoang, còn Nguyên Sát cùng các hóa thân Huyết Quang tiếp tục bám theo bằng Thạch điện và Càn Khôn Bàn. Trong nhiều tháng chạy trốn, Hàn Lập vừa săn cổ thú vừa luyện Nhiếp Linh Đan nhằm bù lại lượng pháp lực tiêu hao. Khi không thu được yêu đan, hắn phải trực tiếp nuốt linh thảo và linh quả Tiên giới từ Nghiễm Hàn Giới, khiến nhiều loại dược tính hỗn tạp tích tụ trong cơ thể. Sau hơn nửa năm, tình trạng của Hàn Lập suy yếu rõ rệt nên Bạch y nữ tử thay hắn điều khiển phi xa để hắn tranh thủ điều tức. Đúng lúc ấy, một lôi trận cực lớn đột ngột hình thành gần phi xa và đưa một thân ảnh khôi ngô đang loạng choạng xuất hiện tại trung tâm."},{"chuong":1957,"tieuDe":"Hoa Thụ Tái Hiện","tomTat":"Hàn Lập đang di chuyển giữa man hoang thì bất ngờ gặp lại Lôi Vân Tử, người cũng đang trong tình trạng bị cường địch truy sát. Sau khi trao đổi, Hàn Lập cho biết mình bị nhiều hóa thân Thánh tổ Ma tộc đuổi giết, còn Lôi Vân Tử tiết lộ hai truy binh của hắn có thể sử dụng ma khí tinh thuần và một người sở hữu công pháp khắc chế ngũ lôi chi thể. Hai người quyết định phối hợp bố trí Song trọng Lôi Quang trận để thoát thân. Tuy nhiên, một hư ảnh hoa thụ màu hồng xuất hiện và trút xuống phấn hồng quang hà, buộc họ rời khỏi trận trước khi toàn bộ lôi điện bị triệt tiêu. Một nam tử xấu xí mặc trường bào sau đó hiện thân, yêu cầu Lôi Vân Tử giao ra một vật chưa rõ. Cuối cùng, nữ tử váy trắng đứng trên cự hoa hồng nhạt xuất hiện với khí thế khiến Hàn Lập nhận định nàng ít nhất cũng là hóa thân của một tồn tại Đại Thừa kỳ."},{"chuong":1958,"tieuDe":"Bại Lộ","tomTat":"Bảo Hoa yêu cầu Lôi Vân Tử giao Thiên Đàm hoa để đổi lấy mạng sống, nhưng hắn từ chối và vẫn tin vào khả năng đào thoát bằng lôi độn cùng Lôi Quang trận. Khi Hắc Ngạc tức giận định ra tay, Bảo Hoa ngăn lại vì thuộc hạ mới hóa hình chưa phải đối thủ của Lôi Vân Tử. Nàng phân tích nguyên lý kết hợp lôi điện và không gian của trận truyền tống, đồng thời tiết lộ đã để lại ấn ký trên người Lôi Vân Tử và đang dần tìm ra cách khắc chế trận. Chuyển sang dò xét Hàn Lập, Bảo Hoa buộc hắn phải đồng thời vận chuyển Đại Diễn Quyết và Luyện Thần Thuật nhưng vẫn nhận ra chuyện hắn từng giết thuộc hạ của nàng tại Ma Kim sơn mạch. Nàng cắt đứt liên hệ thần niệm giữa Hàn Lập với Huyền Thiên Như Ý Nhận tàn phiến, thu hồi bảo vật rồi ban cho Hắc Ngạc. Từ những manh mối này, Hàn Lập suy đoán Bảo Hoa là một Thánh tổ Ma tộc từng ẩn tại Ma Kim sơn mạch. Lôi Vân Tử sau đó giả vờ cân nhắc rồi bất ngờ mở Lôi Quang trận cạnh Hàn Lập để cùng chạy trốn. Ngay khi Hàn Lập tiến vào trận, Hắc Ngạc dùng búa lớn màu đen chém phủ mang vào trung tâm trận, khiến kết quả truyền tống vẫn chưa rõ."},{"chuong":1959,"tieuDe":"Huyễn Nhật Thần Thông","tomTat":"Lôi Vân Tử kịp kích hoạt lôi trận, đưa Hàn Lập rời đi trước khi phủ mang của Hắc Ngạc phá hủy trận pháp. Bảo Hoa tiếp tục cảm ứng các điểm truyền tống, đồng thời tiết lộ Huyền Thiên Như Ý Nhận tàn phiến vốn thuộc về nàng nhưng đã bị ma viên đánh cắp rồi rơi vào tay Hàn Lập. Nàng cho biết Thiên Đàm Hoa có thể ức chế thương thế và sai Hắc Ngạc tìm thêm linh dược giúp khôi phục pháp lực, sau đó nhắc lại hai thuộc hạ Vân và Long đã chết trận. Trên đường truy đuổi, Bảo Hoa và Hắc Ngạc chạm mặt Nguyên Sát cùng ba đại hóa thân Huyết Quang tại Linh giới, qua đó xác nhận Thánh tế đã bắt đầu. Khi Bảo Hoa định giữ các hóa thân Huyết Quang lại làm sai vặt, chúng nhập vào Càn Khôn Bàn và dùng hắc bạch nhị khí tạo đồ án Thái Cực để ẩn độn bỏ chạy. Bảo Hoa thi triển Huyễn Nhật đại pháp, phóng vô số quang ti phủ kín hư không và ép Càn Khôn Bàn hiện hình, khiến Nguyên Sát cùng Huyết Quang phải vận dụng pháp bảo chống đỡ."},{"chuong":1960,"tieuDe":"Cung Thần Đả Thương Địch Thủ","tomTat":"Bảo Hoa dùng Huyễn Nhật và bạch diễm phá tan phòng ngự, hủy ngọc bàn rồi thiêu diệt hoàn toàn ba đại hóa thân Huyết Quang. Tại cự tháp gần Thiên Uyên Thành, Huyết Quang cảm ứng tổn thất nên kinh sợ và nổi giận, nhưng nhanh chóng che giấu sự việc trước các Ma tôn đang bàn kế hoạch bao vây thành. Khi Nguyên Sát lâm nguy, Lục Cực xuất hiện, dùng kim sắc viên châu phá Huyễn Nhật rồi đưa nàng rút lui. Bảo Hoa hóa hai cánh hoa thành cung tên, bắn xuyên tám tiểu thuẫn và gây một lỗ máu trên ngực Lục Cực. Lục Cực phun tinh huyết dập tắt bạch diễm, sau đó vẫn mang Nguyên Sát độn thoát khỏi chiến trường. Bảo Hoa tiếp tục phong tỏa bầu trời, còn kiếm khí từ cự hoa phá một góc pháp trận truyền tống của thạch điện. Truyền tống thất bại khiến thạch điện tách thành hai thạch nhân khổng lồ, chúng gầm thét uy hiếp Bảo Hoa và đại hán nhưng chưa dám xông lên."},{"chuong":1961,"tieuDe":"Thoát Thân","tomTat":"Bảo Hoa dùng lực lượng từ hồng sắc cự hoa kết tinh, thu nhỏ và thu giữ hai hóa thân dạng thạch cự nhân của Huyết Quang, đồng thời tiết lộ sáu đại hóa thân của Lục Cực đã bị trọng thương đến mức cần hơn trăm năm để hồi phục. Nàng không chấp nhận đề nghị truy sát Lục Cực của Hắc Ngạc mà tiếp tục ưu tiên Thiên Đàm Hoa. Trong hạp cốc, Lôi Vân Tử dùng Ngân sắc pháp bàn cùng Hàn Lập kích hoạt Song trọng Lôi Quang trận, truyền tống thành công ra ngoài ngàn vạn dặm trước khi hai kẻ truy đuổi tới nơi. Không thể xác định điểm đến và cũng mất liên hệ với ấn ký truy tung, Bảo Hoa từ bỏ bói toán từ xa rồi dẫn Hắc Ngạc tới lãnh địa Nhân tộc tìm linh dược chữa thương. Hàn Lập và Lôi Vân Tử xuất hiện trên một hồ rộng, xác nhận đã thoát khỏi sự giám sát rồi chia tay, để Lôi Vân Tử mang Thiên Đàm Hoa rời đi theo hướng riêng. Hàn Lập tiếp tục bay ba ngày ba đêm tới một dãy núi đá hoang vu, ẩn vào động quật, bố trí trận kỳ và uống đan dược để bắt đầu giai đoạn hồi phục dự kiến kéo dài ít nhất hai ba tháng."},{"chuong":1962,"tieuDe":"Uyện Hóa Thuật","tomTat":"Sau hai tháng nhập định, Hàn Lập hoàn toàn giải trừ hậu hoạn, khôi phục pháp lực và thần khí tới trạng thái đỉnh phong. Hắn lấy Hỗn độn nhị khí ra kiểm tra bằng Minh Thanh linh mục nhưng bị bổn nguyên chi lực kéo vào vô số luân hồi huyễn cảnh, chỉ kịp thoát nhờ đạo chân lực đã bố trí từ trước. Trải nghiệm nguy hiểm này giúp hắn xác nhận linh vật là thật và càng tin rằng việc luyện hóa nó có thể hỗ trợ mình tiến giai Hợp Thể hậu kỳ. Hàn Lập lưu lại một tia khí tức của linh vật trong kim sắc điện hồ rồi dùng thần niệm hóa thân tiến vào không gian bên trong Trấn Ma Tỏa. Tại đây, Phong Tà và Xa Kỵ Cung lần lượt kiểm tra vật chứng và xác nhận khí tức Hỗn độn nhị khí. Ba bên thống nhất chia pháp quyết luyện hóa thành nhiều phân đoạn để trao đổi lần lượt với từng phần linh vật. Phong Tà bắt đầu bằng phần pháp quyết thứ nhất và yêu cầu Hàn Lập mang phần Hỗn độn nhị khí tương ứng tới trong vòng ba ngày."},{"chuong":1963,"tieuDe":"Công Thành","tomTat":"Xa Kỵ Cung giao cho Hàn Lập một ngọc giản chứa phần pháp quyết luyện hóa Hỗn độn nhị khí chưa hoàn chỉnh, nhưng sau khi hắn rời đi lại cùng Phong Tà bàn kế thoát khỏi Trấn Ma Tỏa rồi bắt hắn để đoạt phần linh vật còn lại. Hàn Lập dành hai ngày hai đêm lĩnh hội pháp quyết, xác định nội dung có vẻ chân thật và quyết định không chờ lão quái vật Lũng gia mà sẽ tìm tiết điểm hai giới để ném Trấn Ma Tỏa về Ma giới. Cùng lúc đó, mấy nghìn quân Ma tộc cùng ma thú, ma tháp, phi xa và chiến thuyền bao vây Thiên Uyên thành. Theo lệnh của huyết bào thiếu niên, hồng giáp thị vệ phát tín hiệu khiến quân Ma tộc chính thức tổng công kích, trong khi phía Nhân tộc vận dụng cấm chế và quang trận đánh chặn. Ở một khu rừng tối, Lục Cực cho biết thương thế do Lạc Nhật chân diễm của Bảo Hoa chỉ có thể tạm áp chế và cần bế quan trăm năm mới mong khỏi hẳn. Nguyên Sát suy đoán Bảo Hoa mạo hiểm xuất hiện để tìm cơ hội khôi phục pháp lực, rồi đề nghị đưa Lục Cực trở về lãnh địa Nhân tộc hội hợp với một hóa thân khác."},{"chuong":1964,"tieuDe":"Lại Xâm Nhập Mộc Tộc","tomTat":"Hắc giáp nữ tử tiết lộ ý định tranh quyền cai quản một nửa lãnh địa Nhân tộc và quyết định dùng Tỏa Long Đan kích phát tiềm lực hóa thân để tiếp tục can thiệp chiến cuộc, còn Nguyên Sát nhận lời bảo vệ nàng. Hai nữ Thánh tổ bàn về ảnh hưởng còn sót lại của Bảo Hoa, dự tính lập lực lượng chuyên kiềm chế vị cựu Thủy tổ rồi lên hồng sắc phi xa trở về chiến trường. Năm tháng sau, Thiên Linh thành thất thủ; toàn bộ lực lượng phòng thủ tử trận, nhiều cường giả Nhân tộc tự bạo kéo theo ma tôn và hàng nghìn cao giai Ma tộc, còn Linh Hoàng trọng thương phá vây rồi mất tin tức. Ma tộc phá hủy phần lớn thành trì, chặt đổ cự thụ biểu tượng và bắt đầu xây pháp đài, trồng ma thụ để biến nơi đây thành chỗ đóng quân lâu dài. Gần lãnh địa Mộc tộc, các thế lực địa phương tập hợp mấy nghìn người, dùng Mộc độn thuật áp sát một cứ điểm bảo vệ tiết điểm nhỏ nối hai giới. Trúc lão nhận nhiệm vụ cầm chân bốn cao giai Ma tộc trong khi lực lượng còn lại phá hủy tiết điểm. Hàn Lập ẩn trong mây quan sát toàn bộ kế hoạch, sau đó che giấu thân hình và âm thầm bám theo liên quân Mộc tộc tiến về cứ điểm."},{"chuong":1965,"tieuDe":"Lẻn Vào","tomTat":"Hơn trăm mộc nhân khổng lồ cùng mấy nghìn Mộc tộc nhân bất ngờ tập kích cứ điểm Ma tộc, phá vỡ quang mạc phòng hộ và tràn vào trận địa. Quân trú phòng phản kích bằng hắc mang và ma thú hình tê ngưu, khiến chiến trường quanh cứ điểm nhanh chóng rơi vào hỗn loạn. Khi tuần sử Ma tộc hai sừng có tu vi Luyện Hư hậu kỳ xuất hiện, Trúc lão quyết định ở lại đoạn hậu, dùng thanh sắc mộc cầu tạo cường quang để đôi nam nữ Mộc tộc dẫn quân rút lui. Bốn Ma tộc Hóa Thần truy đuổi hai người bỏ chạy, còn tuần sử ngưng tụ ma tướng hai đầu để áp chế kiếm mạc của Trúc lão. Lợi dụng lúc đại quân hai bên giao chiến và truy đuổi, Hàn Lập bí mật tiếp cận tiết điểm, dùng kiếm ti giết sạch quân canh giữ và phá hủy các chiến thuyền. Hắn tiếp tục dùng ngân diễm xóa sạch dấu vết, lấy ngũ sắc quang hà xuyên qua ma khí cấm chế rồi mặc ma giáp cổ xưa. Cuối cùng, Hàn Lập hóa thành ngũ sắc Thiên phượng, xua tan hắc phong và bay thẳng vào hắc động."},{"chuong":1966,"tieuDe":"Băng Hà Dưới Đất","tomTat":"Hàn Lập hóa thành Thiên phượng, phá liên tiếp hơn mười vách ngăn không gian và lẻn qua tiết điểm vào Ma giới mà không bị các trạm gác phát hiện. Sau khi quan sát sa mạc xám dưới ba mặt trời đỏ, hắn dùng ma giáp và thu liễm khí tức để ngụy trang thành cao giai Ma tộc. Hắn phi hành nhiều ngày, bắt một ma vật đầu ngựa để sưu hồn tìm đường rồi dùng điện hồ tiêu diệt toàn bộ dấu vết tại hiện trường. Theo ký ức thu được, hắn đi xuống một hạp cốc đầy cuồng phong và phát hiện con sông băng ngầm có dòng chảy cực mạnh. Hàn Lập dùng thi thể hai lam sắc phi xà thử nước, xác nhận vật rơi xuống sẽ đóng băng rồi bị cuốn đi không rõ tung tích. Hắn quyết định ném hộp gỗ trắng liên quan đến Trấn Ma Tỏa xuống sông, cắt đứt dính dáng với Xa Kỵ Cung và Phong Tà trước khi chuẩn bị trở về Linh giới. Hai lão ma vẫn vận công trong các không gian bên trong và không biết biến cố bên ngoài, khiến mưu đồ chiếm đoạt một nửa Hỗn độn nhị khí còn lại của họ bị đảo lộn."},{"chuong":1967,"tieuDe":"Hành Trình Trở Về Và Ma Tộc Chi Mê","tomTat":"Hàn Lập trở lại sa mạc màu vàng, ngụy trang bằng ma khí rồi hóa thành Thiên phượng để vượt tiết điểm từ Ma giới về Linh giới. Vừa xuất hiện, hắn bị mấy trăm vệ sĩ Ma tộc, ma cầm hai đầu và hai chiến thuyền phục kích, nhưng đã nhận biết trước nên nhanh chóng hóa giải đợt công kích. Hắn dùng kiếm quang tiêu diệt ma cầm, lấy ngũ sắc hàn diễm đóng băng năm cao giai Ma tộc đang bỏ chạy rồi quét sạch toàn bộ cứ điểm. Vài ngày sau, Mộc tộc phát hiện nơi này không còn cạm bẫy, lập tức tiếp quản và bắt đầu bố trí đại trận phong ấn tiết điểm. Trên đường về lãnh địa Nhân tộc, Hàn Lập tiếp tục luyện hóa Hỗn độn nhị khí, dự tính đạt Hợp Thể trung kỳ đại viên mãn và chuẩn bị đột phá hậu kỳ với sự trợ giúp của Băng Phượng. Trong khi đó, Thiên Uyên thành và một thành trì trọng yếu của Yêu tộc đều đang chịu những đợt tấn công dữ dội từ đại quân Ma tộc. Tại một hòn đảo bí mật giữa hai tộc, hơn mười tồn tại Hợp Thể nhận được tin Ma tộc muốn chiếm đất, đóng quân lâu dài và đưa ít nhất hơn mười ức cổ ma đê giai sang Linh giới. Nhiều thành trấn Ma giới đã bị bỏ hoang, nhưng nguyên nhân thực sự của cuộc dị biến và di dân quy mô lớn này vẫn chưa được làm rõ."},{"chuong":1968,"tieuDe":"Ngao Khiếu Hiện Thân","tomTat":"Các tu sĩ Hợp Thể tại Thánh đảo tiếp tục bàn cách chống ma kiếp và nhận được tin ba đại Thủy tổ Ma tộc có thể cùng phủ xuống Linh giới. Tuần đạo hữu cùng Lạc huynh tiết lộ rằng Mạc Giản Ly đã đi tìm các Đại Thừa kỳ thuộc những tộc khác để cùng nghĩ đối sách, đem lại chút hy vọng cho hội nghị. Linh vũ nam tử sau đó công bố Hắc Vũ thượng nhân đã vẫn lạc, còn Hàn Lập mất tích và chưa thể xác định sống chết vì không để lại bổn mạng chi vật. Hoàng Lương thạch linh cũng biến mất theo biến cố ấy, khiến một bước quan trọng trong kế hoạch bảo vệ Nhân tộc và Yêu tộc không thể hoàn thành, trong khi các vật thay thế sẽ làm thủ đoạn suy yếu ba phần. Giữa lúc hội nghị bế tắc, Ngao Khiếu lão tổ truyền âm nhận giải quyết chuyện linh vật và tuyên bố còn một nhiệm vụ quan trọng cần mọi người thực hiện. Vị Đại Thừa duy nhất của Yêu tộc dẫn theo một nữ tử tóc bạc bước vào đại điện, được toàn thể tu sĩ đứng dậy bái kiến, rồi thể hiện thân pháp nhanh đến mức mọi người chỉ kịp thấy hoa mắt."},{"chuong":1969,"tieuDe":"Điện Nghị","tomTat":"Ngao Khiếu lão tổ đưa Ngân Nguyệt vào điện nghị sự của Thánh đảo, qua đó xác nhận nàng chính là Linh Lung tiên tử và đã dung hợp phần hồn phân liệt để khôi phục nguyên thần hoàn chỉnh. Ông cho biết thương thế sau lần độ kiếp trước đã bình phục, đồng thời nhận lời Mạc Giản Ly tới truyền đạt mệnh lệnh và lưu lại tọa trấn Thánh đảo. Tin tức từ Mạc Giản Ly cho thấy vị trí mới của đảo có thể đã bị lộ, khiến Ngao Khiếu nghi ngờ gian tế Ma tộc đã trà trộn và ra lệnh điều tra các sứ giả từng ra vào gần đây. Phương án chống Ma tộc được điều chỉnh, trong đó Hoàng Lương thạch linh đã mất sẽ được thay bằng một thiên địa linh vật bí mật do Ngao Khiếu mang tới. Trước nguy cơ ba đại Thủy tổ Ma tộc giáng lâm, Ngao Khiếu không tiết lộ đối sách mà yêu cầu mọi người trước mắt tập trung đối phó đại quân Ma tộc. Các trưởng lão báo cáo lực lượng linh thú đã gần hoàn tất, hung trùng đang được thúc dục và kế hoạch luyện chế Huyền Thiên thánh khí vẫn thiếu nguyên liệu vì tuyến vận chuyển bị Ma tộc khống chế. Sau nhiều canh giờ nghe báo cáo, Ngao Khiếu rời điện cùng Ngân Nguyệt nhưng bí mật gọi bạch phát lão giả và Tư đạo hữu tới gặp riêng."},{"chuong":1970,"tieuDe":"Ngân Nguyệt Và Thất Tinh Nguyệt Thể","tomTat":"Cuộc nghị sự trên đảo kết thúc sau khi Tư đạo hữu không thể giải thích mục đích Ngao Khiếu lão tổ triệu kiến mình và Lạc huynh. Tại một lầu các biệt lập, Ngao Khiếu nói rõ Ngân Nguyệt đã ba lần tiến giai Hợp Thể thất bại vì không vượt qua được tâm ma. Ông vạch lại việc Thiên Khuê từng mưu lấy nguyên âm của nàng, khiến nguyên thần nàng phân đôi và can thiệp vào Nghịch Tinh Bàn làm nàng chậm trở về Linh giới. Ngao Khiếu tiết lộ Ngân Nguyệt đã thức tỉnh Thất Tinh Nguyệt Thể, nhờ đó có hy vọng tiến giai Đại Thừa, đồng thời dự định phế Thiên Khuê và lấy lại ngôi Lang vương cho nàng sau ma kiếp. Trước áp lực đại chiến với Ma tộc, ông trao ngọc giản Vong Tình Quyết, một bí thuật có thể tu bổ tâm cảnh và tăng mạnh cơ hội vượt qua bình cảnh Hợp Thể. Đổi lại, người tu luyện sẽ dần mất đi thất tình lục dục và có thể bị ảnh hưởng trên con đường Đại Thừa. Ngân Nguyệt hỏi liệu mình có thể kịp tiến giai trước trận quyết chiến, nhưng vẫn được yêu cầu cân nhắc thêm trước khi đưa ra lựa chọn cuối cùng."},{"chuong":1971,"tieuDe":"Lão Ảnh","tomTat":"Ngao Khiếu lão tổ bí mật triệu kiến Tư đạo hữu và bạch phát lão giả, lần lượt giao nhiệm vụ vào Man Hoang thế giới gặp các đại năng dị tộc và tìm kiếm những tài liệu, pháp khí ghi trong ngọc giản. Ông yêu cầu cả hai tuyệt đối giữ kín kế hoạch, hoàn thành trong vòng năm năm vì những việc này liên quan đến việc đối phó ba đại Thủy tổ Ma tộc. Trước sự lo ngại của Ngân Nguyệt về gian tế, Ngao Khiếu khẳng định hai trưởng lão do Mạc Giản Ly tiến cử và nhóm trưởng lão vừa dự đại điện không có kẻ phản bội. Sau khi Ngân Nguyệt lên lầu nghỉ ngơi, Ngao Khiếu gọi Lão Ảnh, tai mắt đã được ông bố trí ẩn náu trên Thánh đảo nhiều năm, ra báo cáo tình hình bất lợi do Ma tộc gây nên. Lão Ảnh còn giao hồ sơ chưa hoàn chỉnh về Hàn Lập, trong đó có lời đồn về tốc độ tiến cảnh, chiến lực vượt trội và việc hắn bị Ma tộc truy sát rồi mất tung tích. Ngao Khiếu xác định Hàn Lập là vướng mắc chủ yếu trong tâm cảnh của Ngân Nguyệt, sau đó bộc lộ sát ý và cho rằng cái chết của hắn sẽ có lợi cho nàng."},{"chuong":1972,"tieuDe":"Hỏa Ly Tông","tomTat":"Lão Ảnh đề nghị sát hại Hàn Lập nếu hắn sống sót trở về, nhưng Ngao Khiếu nghiêm cấm vì Ngân Nguyệt sẽ nghi ngờ và mỗi tu sĩ Hợp Thể đều là chiến lực quý giá trước đại chiến Ma tộc. Ngao Khiếu nhắc lại hồn khế mười vạn năm với Lão Ảnh rồi dự định chuyển phần thời hạn còn lại sang Ngân Nguyệt để nàng có người bảo vệ. Khi Lão Ảnh cho rằng tu vi Ngân Nguyệt chưa đủ, ông tiết lộ nàng đã thức tỉnh Thất Tinh Nguyệt Thể, có thể tiến vào Hợp Thể trong chưa đầy trăm năm và còn có cơ hội đạt Đại Thừa. Ngao Khiếu cũng thừa nhận mình khó vượt qua lần lôi kiếp kế tiếp, vì vậy phải sớm chuẩn bị hậu sự cho chất nữ. Ở gần Thiên Uyên thành, Hỏa Ly Tông đứng trước nguy cơ bị Ma tộc tiêu diệt nên quyết định tìm truyền tống pháp trận bí mật để đưa môn nhân vào thành bảo toàn truyền thừa. Chưởng môn đích thân dẫn Lý sư đệ và Dương sư đệ tới hạp cốc dò xét, giao những người còn lại bảo vệ đệ tử và chuẩn bị rút lui. Cùng lúc, một thanh niên cầm ngọn núi nhỏ màu đen và một nữ đồng đang ăn linh quả cũng bay về chính hạp cốc ấy."},{"chuong":1973,"tieuDe":"Xuất Thủ","tomTat":"Báo Lân thú tỉnh khỏi giấc ngủ sâu, vượt thiên kiếp Hợp Thể kỳ nhờ huyết mạch Chân linh Kỳ lân cùng những thần thông mới có được sau khi nuốt yêu đan Ám Thú vương, rồi hóa thành một nữ đồng. Hàn Lập dùng nhiều linh dược chữa thương cho nó trong mấy tháng trước khi dẫn nó tới một điểm truyền tống bí mật để trở về Thiên Uyên thành. Trên đường, hắn dùng đồng thuật phát hiện hơn mười tu sĩ Nhân tộc đang bị ma thú và giáp sĩ Ma tộc truy sát. Bạch phát lão giả cầm Thiên Can song kiếm đã mất hai sư đệ trong trận mai phục tại sơn cốc, nhưng vẫn tiêu hao gần hết pháp lực để đoạn hậu và quay lại cứu những môn nhân bị tụt phía sau. Bốn cao giai Ma tộc Luyện Hư kỳ dùng năm kiện ma bảo hợp kích, phá nát kiếm mạc và đẩy lão giả tới sát bờ tử vong. Hàn Lập bất ngờ xuất hiện, phất tay đánh bật toàn bộ năm kiện ma bảo và khiến bốn Ma tộc đồng thời mất quyền khống chế chúng."},{"chuong":1974,"tieuDe":"Vào Thành","tomTat":"Hàn Lập xuất hiện cứu đoàn Hỏa Ly tông, trong khi Báo Lân thú cắt nát bốn cao giai Ma tộc và quét sạch đàn ma thú truy sát họ. Hàn Lập dùng Ích Tà thần lôi thiêu rụi hơn trăm giáp sĩ Ma tộc đang tháo chạy, khiến toàn bộ truy binh bị tiêu diệt chỉ trong thời gian ngắn. Chưởng môn Hỏa Ly tông cho biết nơi ẩn thân của tông môn đã bị phát hiện và truyền tống trận dẫn về Thiên Uyên thành cũng rơi vào tay Ma tộc. Hàn Lập lập tức cùng Báo Lân thú tới hạp cốc, tiêu diệt lực lượng trấn giữ và dùng phi kiếm xóa sổ Ma anh hai sừng đang bỏ chạy. Đoàn Hỏa Ly tông quyết định bám theo hắn, coi đây là cơ hội vào thành an toàn. Khi Hàn Lập kích hoạt pháp trận và truyền tống vào Thiên Uyên thành, lực lượng phòng thủ lập tức mở cấm chế ứng chiến nhưng nhanh chóng nhận ra hắn. Kim vệ cầm đầu vui mừng tiếp đón, cho biết các trưởng lão vẫn chờ tin tức của Hàn Lập và nhận lệnh chuẩn bị tiếp nhận đoàn Hỏa Ly tông sắp tới."},{"chuong":1975,"tieuDe":"Phiền Toái Ngoài Ý Muốn","tomTat":"Hàn Lập trở lại Thiên Uyên thành qua truyền tống trận và nhận thấy lực lượng tuần tra trong thành đã được tăng cường đáng kể giữa thời kỳ ma kiếp. Sau khi về thạch tháp, hắn triệu kiến Hải Đại Thiếu và Khí Linh Tử, bác bỏ lời đồn mình đã chết dưới tay hóa thân Thánh tổ Ma tộc và cho biết sắp đánh sâu vào bình cảnh Hợp Thể hậu kỳ. Hai đệ tử báo rằng chân thân Băng Phượng đã bị lộ và Thanh Long thượng nhân của Cửu Tinh tông đang gây sức ép buộc nàng song tu. Băng Phượng không đồng ý, từng lẩn tránh trong tháp nhưng vẫn bị uy hiếp và hiện phải tham dự một giao dịch hội tại Đâu Nguyên các. Hàn Lập suy đoán đối phương nhắm tới nguyên âm chi khí của nàng, lập tức nổi sát khí và quyết định tự mình đưa nàng trở về. Sau khi hắn rời đi, hai đệ tử bàn luận về khả năng Băng Phượng trở thành sư nương của họ. Hàn Lập hóa thành thanh hồng bay về Đâu Nguyên các, vừa hạn chế tốc độ trong nội thành vừa cân nhắc cách xử lý cuộc đối đầu sắp tới."},{"chuong":1976,"tieuDe":"Uy Bức","tomTat":"Hàn Lập xông thẳng vào Đâu Nguyên các, dùng linh áp khống chế các thủ vệ Nguyên Anh kỳ rồi xuyên qua cấm chế để tìm người. Một thủ vệ lâu năm nhận ra hắn là tu sĩ Hợp Thể trung kỳ từng bị đồn đã chết hai năm trước, khiến mọi người không dám tiếp tục ngăn cản. Trong một tầng lầu đã bị phong tỏa, Băng Phượng đang bị Tiểu Hồng cùng nhiều tu sĩ Nhân Yêu hai tộc ép chấp nhận song tu với Thanh Long thượng nhân. Băng Phượng kiên quyết khước từ và dùng quy tắc Nhân Yêu khác đường để chất vấn đối phương. Tiểu Hồng tiết lộ Thanh Long có xuất thân nửa người nửa yêu, mang linh huyết Yêu tộc nhưng lựa chọn ở lại Nhân tộc và trở thành đại trưởng lão Cửu Tinh tông. Khi việc thuyết phục thất bại, Thanh Long tuyên bố sẽ tự dùng thủ đoạn rồi bước ra đối mặt với Băng Phượng."},{"chuong":1977,"tieuDe":"Tức Giận","tomTat":"Thanh Long thượng nhân công khai việc đã trở thành trưởng lão Thiên Uyên thành và dùng địa vị mới cùng một thần thông chưa rõ để ép Băng Phượng phối hợp. Băng Phượng xé mở không gian chạy trốn nhưng bị cổ văn bạc từ ngọc thư của hắn đánh bật trở lại, rồi bị đám người Tiểu Hồng bao vây. Hàn Lập bất ngờ trở về, phá tung cửa lớn khiến hai tu sĩ Luyện Hư chặn cửa chết tại trận và làm Băng Phượng vô cùng vui mừng. Hắn tiếp tục đánh trọng thương ái đồ của Cố trưởng lão, phá nát chiến giáp của người này và buộc Thanh Long phải giải thích hành vi ức hiếp Băng Phượng. Thanh Long tìm cách thoái thác rồi thẹn quá hóa giận, chủ động đề nghị giao đấu; Hàn Lập lập tức triệu vô số tiểu kiếm xanh và phóng linh áp đáp lại. Ngay trước khi cuộc chiến bùng nổ, Kim Việt thiền sư bay vào đứng giữa hai người và đề nghị tạm dừng để ông hòa giải."},{"chuong":1978,"tieuDe":"Ma Giới Chi Chiến","tomTat":"Kim Việt thiền sư kịp thời tới Đâu Nguyên các, khiến Hàn Lập tạm nén ý định giao chiến với Thanh Long thượng nhân. Ông mời Cố lão giả và Ngân Quang tiên tử cùng hòa giải vì Thiên Uyên thành đang thiếu chiến lực Hợp Thể trong lúc Ma tộc gia tăng thế công. Cố lão giả chúc mừng Hàn Lập thoát khỏi hóa thân Thánh tổ, còn Ngân Quang kể lại việc nàng vừa trở về sau khi bị tôn giả Ma tộc truy sát. Kim Việt và Ngân Quang lần lượt đề nghị Thanh Long dùng linh thạch, tài liệu hoặc bảo vật bồi thường cho Băng Phượng, nhưng Hàn Lập không chấp nhận cách giải quyết này. Sau khi Băng Phượng giao quyền quyết định cho hắn, Hàn Lập yêu cầu Thanh Long đứng yên đỡ ba chiêu và cho phép đối phương sử dụng bảo vật. Thanh Long vì thể diện của tu sĩ cùng giai đã chấp thuận, đồng thời để Hàn Lập lựa chọn địa điểm tỷ thí."},{"chuong":1979,"tieuDe":"Hỗn Thiên Lưỡng Nghi Trận","tomTat":"Hàn Lập quyết định giải quyết ân oán với Thanh Long thượng nhân bằng ba lần công kích và mượn không gian tỷ thí riêng của Đâu Nguyên các. Trước khi rời đại sảnh, hắn buộc Tiểu Hồng cùng những người liên quan phải đến gặp vào ngày hôm sau, còn Thanh Long không lên tiếng che chở họ. Nhóm Tiểu Hồng hoảng sợ, nhưng sau khi cân nhắc nguy cơ bị lưu thần niệm ấn ký và việc Thiên Uyên thành đang bị Ma tộc bao vây, họ quyết định chuẩn bị lễ vật hoặc tìm trưởng bối trợ giúp rồi đến thỉnh tội. Cố lão giả kích hoạt truyền tống trận tại tầng cao nhất Đâu Nguyên các, đưa Hàn Lập, Thanh Long cùng những người quan chiến vào không gian riêng. Tại đài cao, ông dùng ngân sắc ngọc bàn triển khai Hỗn Thiên Lưỡng Nghi trận để ngăn cuộc giao đấu ảnh hưởng tới bên ngoài. Kim Việt thiền sư tiếp tục mong hai bên chỉ luận bàn đến điểm thì dừng, trong khi Băng Phượng âm thầm lo lắng. Cuộc tỷ thí chính thức bắt đầu khi Hàn Lập phóng điện quang từ hai tay, ngưng tụ thành hai kim sắc điện mãng tấn công Thanh Long thượng nhân."},{"chuong":1980,"tieuDe":"Lực Áp Thanh Long","tomTat":"Thanh Long thượng nhân dùng ngọc thư cùng đôi bút vàng bạc là bổn mạng pháp bảo để chống đỡ cự kiếm của Hàn Lập. Hàn Lập hợp nhất bảy mươi hai thanh kiếm nhỏ, dung nhập Ích Tà Thần Lôi và ngân diễm rồi chém xuống, khiến thạch thai cùng cấm chế chấn động dữ dội. Sau đòn giao phong, Hàn Lập vẫn đứng nguyên vị trí, còn Thanh Long thượng nhân rơi xuống thạch thai, ngọc thư rạn nứt và đôi bút suy giảm linh tính. Cố lão giả phải gia cố cấm chế, trong khi những người quan chiến tranh luận về nguồn gốc Chân linh huyết mạch của Hàn Lập. Hàn Lập tiếp tục thi triển Kinh Chập quyết hóa thành kim mao cự viên, còn Thanh Long thượng nhân dùng tinh huyết và bảy thanh kiếm nhỏ để thi triển Thanh Long chân thân. Cự viên ném hai tòa cực sơn xuống, khóa chặt đối thủ và chấn gãy song trảo của thân thể bán yêu. Thanh Long thượng nhân bị đánh bật lùi hàng chục bước, lộ vẻ sợ hãi rồi phun ra một ngụm máu đen."},{"chuong":1981,"tieuDe":"Bức Ly","tomTat":"Hàn Lập dùng biến thân Sơn Nhạc cự viên phối hợp với hai tòa cực sơn, đánh Thanh Long thượng nhân bay đi và khiến đối phương tạm thời không thể điều động phần lớn pháp lực. Hắn tiếp tục dùng thần niệm cắt đứt khả năng phản kháng, phá vỡ tấm khiên cùng chiến giáp lân phiến của Thanh Long nhưng chủ động đánh lệch đòn trí mạng, đồng thời bí mật đưa một vật vào tai đối phương. Sau khi giải trừ biến thân, Hàn Lập buộc Thanh Long phải rời Thiên Uyên thành trong vòng ba ngày rồi đưa Băng Phượng rời khỏi nơi giao đấu. Thanh Long thừa nhận mình không bằng Hàn Lập, quyết định rời thành ngay ngày hôm sau và từ bỏ chức trưởng lão. Kim Việt thiền sư cùng Cố lão giả lo ngại tổn thất nhân lực giữa lúc đại quân Ma tộc áp sát nên chuẩn bị triệu tập các đạo hữu khác để tìm cách cứu vãn. Trở về chỗ ở, Hàn Lập cho Hải Đại Thiếu và Khí Linh Tử lui xuống, nghe Băng Phượng kể việc suýt bị ám toán rồi giải thích rằng chiến sự cùng ý định tăng tu vi đã khiến Thanh Long bất chấp thể diện."},{"chuong":1982,"tieuDe":"Trảm Thảo Trừ Căn","tomTat":"Băng Phượng lo Trưởng lão hội sẽ ngăn Thanh Long rời Thiên Uyên thành và cảnh báo rằng hắn có thể trả thù, nhưng Hàn Lập quyết định không để đối phương sống sót thành hậu họa. Hàn Lập triệu Báo Lân thú đã hóa thành nữ đồng, lệnh cho nó ẩn thân bám theo rồi giết Thanh Long ngoài thành, đồng thời tiết lộ mình đã bí mật khiến mục tiêu chỉ còn phát huy được hai ba thành pháp lực. Qua cuộc trò chuyện, Băng Phượng biết Báo Lân thú đã đạt Hợp Thể sơ kỳ, mang một phần huyết mạch Kỳ lân Chân linh và đủ sức đối đầu tu sĩ Hợp Thể trung kỳ thông thường. Hàn Lập cũng cho biết mình đã có cơ duyên trùng kích Hợp Thể hậu kỳ và được Băng Phượng đồng ý dùng nguyên âm Thiên phượng trợ giúp sau khi Báo Lân thú trở về. Trong một điện phủ thuộc thạch tháp, Thanh Long thượng nhân từ chối giải thích nguyên nhân thật sự khiến hắn nhắm vào Băng Phượng và quyết định rời Thiên Uyên thành ngay trong đêm để tránh Hàn Lập truy sát. Hắn giao phần lớn đệ tử Cửu Tinh tông cho Lâm Loan tiên tử quản lĩnh, chỉ mang theo hai môn hạ đến Thánh Hoàng thành. Lâm Loan chấp thuận cách phân tán lực lượng này nhằm bảo toàn truyền thừa của tứ đại tông môn rồi nhìn Thanh Long cùng hai đệ tử rời đi."},{"chuong":1983,"tieuDe":"Thanh Long Vẫn Lạc","tomTat":"Thanh Long thượng nhân đưa hai đệ tử tới đại điện truyền tống của Thiên Uyên thành nhưng bị từ chối vì không có sự chấp thuận của Trưởng lão hội. Hắn bất ngờ giam cầm các tu sĩ thủ vệ, dùng ngọc bài phá cấm chế rồi cưỡng ép kích hoạt pháp trận để rời thành; ngay sau đó, một thân hình cực nhỏ cũng bí mật truyền tống theo. Ngoài thành, Báo Lân thú phục kích đoàn người, giết cả hai đệ tử của Thanh Long rồi hiện thân với tu vi Hợp Thể sơ kỳ để tiếp tục giao chiến. Khi Thanh Long huy động nhiều pháp bảo chống lại hơn trăm thú ảnh kim sắc, Linh Tuyền tà quang trong cơ thể hắn đột ngột phát tác và phủ hắc khí lên mặt. Năm ngày sau, Báo Lân thú trở về mật thất của Hàn Lập, còn Hàn Lập tiết lộ đã trộn tà quang vào Phệ Linh chân hỏa để âm thầm cài sát chiêu trong người Thanh Long. Hàn Lập cho rằng Thanh Long khó tránh khỏi cái chết khi phải vận dụng nhiều pháp lực, nhưng chương kết thúc trước khi Báo Lân thú xác nhận kết quả truy sát."},{"chuong":1984,"tieuDe":"Dư Âm","tomTat":"Báo Lân thú trở về Thiên Uyên thành và báo với Hàn Lập rằng nó đã nuốt Nguyên Anh của Thanh Long thượng nhân, dù đòn liều mạng của đối phương khiến nó phải dưỡng thương hai ngày. Không còn hậu họa, Hàn Lập bố trí mật thất cho linh thú, giao nó nhiệm vụ hộ pháp rồi gọi Băng Phượng tới để xác nhận kế hoạch trùng kích bình cảnh hậu kỳ. Trong cuộc họp của Trưởng lão hội, các trưởng lão xác nhận Thanh Long đã chết vì bản mạng hồn bài của ông tự vỡ, nhưng quyết định gác việc điều tra nguyên nhân tới sau ma kiếp. Kim Việt thiền sư thuật lại việc Hàn Lập chỉ dùng ba kích đánh Thanh Long trọng thương và thừa nhận bản thân gần như chỉ có thể chạy trốn nếu đối đầu hắn. Ngân Quang tiên tử cũng làm chứng rằng nhiều Ma tộc tôn giả từng chết trong tay Hàn Lập. Trưởng lão hội vì thế quyết định tiếp tục mời Hàn Lập gia nhập với các điều kiện có thể thương lượng. Cuối cùng, người chủ trì công bố tình báo đại quân Ma tộc có thể tiến công Thiên Uyên thành trong vài tháng đến khoảng nửa năm, khiến toàn bộ hội nghị chuyển sang bàn phương án ứng phó."},{"chuong":1985,"tieuDe":"Hợp Thể Hậu Kỳ (1)","tomTat":"Trưởng lão hội Thiên Uyên thành xử lý và giữ kín cái chết của Thanh Long thượng nhân, còn Lâm Loan tiên tử sau phút thất thố cũng không nhắc lại chuyện này. Việc mời Hàn Lập gia nhập Trưởng lão hội bị đình lại vì hắn bế quan suốt nửa năm, trong khi sức ép từ các đợt quấy nhiễu của Ma tộc ngày càng tăng. Thiên Uyên thành huy động nhân lực luyện khí, chế phù và quân dự bị, đồng thời kiểm tra toàn bộ pháp trận cùng cấm chế để chuẩn bị cho đại chiến. Sau nửa năm, một thiên tượng khổng lồ gồm xích vân, hỏa cầu, cầu vồng bảy màu và linh áp kinh người xuất hiện, che phủ gần nửa thành. Ngân phát lão giả, Kim Việt thiền sư, Ngân Quang tiên tử và nhiều tu sĩ khác tập trung quanh trung tâm thiên tượng để hộ pháp và quan sát. Căn cứ vào vị trí nơi ở, các trưởng lão nhận định Hàn Lập đang trùng kích Hợp Thể hậu kỳ, nhưng thanh thế vượt xa thông thường khiến khả năng hắn vượt kiếp thành công vẫn chưa thể xác định."},{"chuong":1986,"tieuDe":"Hợp Thể Hậu Kỳ (2)","tomTat":"Kim Việt thiền sư và ngân phát lão giả họ Cốc quan sát Hàn Lập trùng kích Hợp Thể hậu kỳ, vừa kinh ngạc trước tốc độ tiến giai của hắn vừa lo căn cơ tích lũy chưa đủ sâu. Họ nhận định nếu Hàn Lập thành công, Thiên Uyên Thành sẽ có thêm một chiến lực đủ khả năng cầm chân hóa thân Thánh tổ Ma tộc. Trên bầu trời, một hư ảnh màu xanh khổng lồ giúp phù văn xuyên qua hỏa vân, nhưng hình người ngũ sắc vừa ngưng tụ đã bị tám mươi mốt hắc giao xé nát. Kim sắc điện quang, ngân sắc hỏa điểu và ngũ sắc hàn diễm lần lượt chống lại quần giao, biển thiên hỏa và đợt băng trùy. Sau khi hai lớp công kích bị hóa giải, tám mươi mốt hắc giao tự nổ thành vô số cự thạch rồi đồng loạt giáng xuống thạch tháp. Trong mật thất sâu dưới lòng đất, Hàn Lập vẫn vận công giữa nhiều lớp phòng hộ, nhưng khắp người hắn đã xuất hiện dày đặc những điểm sáng màu xám tỏa âm hàn khí cực thịnh."},{"chuong":1987,"tieuDe":"Hợp Thể Hậu Kỳ 3","tomTat":"Trong lúc thân thể Hàn Lập ngồi bất động giữa những quang điểm tà dị và được Cực sơn, Thanh liên cùng các bảo vật bảo vệ, nguyên thần của hắn phải giao chiến với một tâm ma áo đen trong thần thức hải. Thiên ngoại ma đầu từng thất bại tại Vân Thành đã lợi dụng lúc hắn độ thiên kiếp để xâm nhập, thúc hóa tâm ma và dụ hắn giao ma giáp. Hàn Lập nhận ra lời dụ hàng có thể dẫn động tâm ma nên dứt khoát cự tuyệt, nhưng cuộc chiến đã kiềm chế gần một nửa nguyên thần, pháp lực và thần niệm của hắn đúng lúc thiên kiếp tiến tới giai đoạn then chốt. Hắn hóa thành Sơn Nhạc Cự Viên, song tâm ma cũng biến thành ma vật đầu trâu thân người có sức mạnh thân thể gần tương đương. Không còn thời gian kéo dài, Hàn Lập chấp nhận hao tổn lượng lớn linh lực, kết hợp Kinh Trập Quyết với Phạm Thánh Chân Ma Công để hóa thành cự viên ba đầu sáu tay. Sáu cánh tay tạo nên vòng xoáy kim sắc có hấp lực mạnh, cuốn mất các bảo vật sao chép và nhấn chìm tâm ma. Tuy nhiên, chương chưa xác nhận tâm ma đã bị tiêu diệt hoàn toàn, còn thiên kiếp Hợp Thể hậu kỳ bên ngoài vẫn tiếp diễn."},{"chuong":1988,"tieuDe":"Hợp Thể Hậu Kỳ (4)","tomTat":"Hàn Lập dùng Hắc U Băng Hương buộc ma niệm của thiên ngoại Ma đầu hiện hình rồi khu trừ nó khỏi thần thức hải. Trước khi tan biến, ma niệm tuyên bố bản thể sẽ tự mình phủ xuống khi hắn tiến giai Đại Thừa Kỳ. Trở về bản thể, Hàn Lập dùng kim sắc điện hồ tiêu diệt năm Mị Ảnh đang công kích quang mạc hộ thể. Khi thiên kiếp phá vỡ cấm chế của thạch tháp, hắn triển khai Thanh Bàn Kiếm Trận, hai tòa cực sơn và Nguyên Từ Thần Quang để chống ngũ sắc điện hồ cùng hỏa cầu. Sau một ngày một đêm, tám mươi mốt hắc long tự nổ và thiên kiếp chấm dứt. Hàn Lập thành công tiến vào Hợp Thể hậu kỳ, sau đó bắt đầu thôn phệ thiên địa nguyên khí để đúc lại nguyên thần, khiến lão giả tóc bạc phải yêu cầu các tu sĩ xung quanh rút lui."},{"chuong":1989,"tieuDe":"Đệ Nhất Ma Tôn","tomTat":"Sau khi thiên kiếp kết thúc, Hàn Lập chính thức tiến vào Hợp Thể hậu kỳ và tiếp tục hấp thu thiên địa nguyên khí để đúc lại nguyên thần. Lão giả tóc bạc cùng những người đồng hành ép các tồn tại cao giai khác rời đi, còn Kim Việt Thiền Sư xác nhận lần tiến giai này đem lại thêm một cường giả quan trọng cho Thiên Uyên Thành. Nguyên thần Hàn Lập hóa thành hư ảnh cao hơn năm ngàn trượng, thu nạp hơn phân nửa nguyên khí trong thành và tạo ra dị tượng bị các cứ điểm Ma tộc gần đó phát hiện. Tại một cự tháp Ma tộc, hóa thân Huyết Quang Thánh tổ nhận định người vừa tiến giai mạnh hơn Hợp Thể hậu kỳ thông thường và dự định phái người chuyên trách đối phó. Huyết Quang đồng thời tiết lộ ba đại hóa thân của mình đã chết sau lần thứ hai truy sát một tu sĩ Nhân tộc Hợp Thể trung kỳ. Hung, Ma Tôn được xưng là đệ nhất dưới Thánh tổ, chấp nhận săn mục tiêu sau khi buộc Huyết Quang tăng gấp đôi thù lao và cho mình quyền xem trọng bảo của đối phương. Không chịu nghỉ dưỡng hao tổn do phá giới, Hung rời cự tháp để tìm đối tượng giết chóc, trong khi Huyết Quang xác nhận ngày đại quân Ma tộc tấn công Thiên Uyên Thành đã gần."},{"chuong":1990,"tieuDe":"Lời Mời","tomTat":"Huyết Quang nhận thấy Hung không thực sự cung kính hóa thân của mình, nên ra lệnh triệu tập mười đại thống lĩnh để bàn định tình thế. Tại Thiên Uyên Thành, Hàn Lập hoàn tất tiến giai Hợp Thể hậu kỳ, khiến pháp lực và thần niệm tăng hơn gấp đôi. Nhìn lại thiên kiếp vừa qua, hắn nhận ra mình đã tổn thất nhiều bảo vật, trong đó một phần Thanh Trúc Phong Vân Kiếm bị hư hại, nhưng hai tòa cực sơn đã giúp chặn những đợt thiên lôi cuối. Vì những thiên kiếp tương lai sẽ còn nguy hiểm hơn, Hàn Lập quyết định luyện chế ba tòa cực sơn còn thiếu để hoàn chỉnh bộ năm ngọn. Sau hơn mười ngày củng cố cảnh giới, hắn xuất quan, nhận lời chúc mừng từ Băng Phượng và hai đệ tử, đồng thời biết Băng Phượng cũng đã tiến gần lần đột phá tiếp theo. Khí Linh Tử báo tin thành đang điều động tu sĩ trước nguy cơ đại quân Ma tộc công thành và chuyển lời mời của trưởng lão hội. Tại đại điện, Kim Việt Thiền Sư cùng Cốc huynh kinh ngạc vì không thể nhìn thấu tu vi Hàn Lập, xem hắn là tu sĩ đứng đầu trong thành và hỏi về khả năng đối phó hóa thân Thánh tổ. Hàn Lập không khẳng định có thể thắng mọi hóa thân, nhưng cho rằng mình đủ sức ứng phó loại đối thủ từng gặp."},{"chuong":1991,"tieuDe":"Thiên Qua Phù","tomTat":"Ngân phát lão giả phân tích mối đe dọa từ hóa thân Huyết Quang Thánh Tổ đang ẩn trong đại quân Ma tộc và đề nghị Hàn Lập trực tiếp đối phó với nó. Kim Việt thiền sư trình bày phương án cũ là dụ hóa thân vào đại trận rồi dùng cấm chế cùng nhân thủ đặc biệt vây giữ, nhưng kế hoạch khó chuẩn bị và tỷ lệ thành công thấp. Hai vị trưởng lão sau đó tranh luận về việc nên sớm sử dụng các trọng bảo đại sát khí hay giữ kín chúng cho giai đoạn sau của đại chiến. Rời đại điện, Hàn Lập trở về nơi ở, dặn dò Khí Linh Tử và Băng Phượng rồi tiến vào mật thất bế quan. Hắn dự định củng cố pháp lực Hợp Thể hậu kỳ, làm quen với những đại thần thông mới của Phạm Thánh Chân Ma công và luyện chế Thiên Qua phù bằng số vật liệu đã thu thập. Nhận thấy nhục thân hiện tại đã đủ mạnh, Hàn Lập cũng quyết định chân chính tu luyện lại Bách Mạch Luyện Bảo quyết thay vì tiếp tục dùng phương pháp dung hợp bảo vật mang tính mưu lợi."},{"chuong":1992,"tieuDe":"Thiên Uyên Thành Đại Chiến (1)","tomTat":"Hàn Lập ghi nhớ nội dung hai khối ngọc thư nhưng tạm hoãn tu luyện Tiên gia bí thuật để tập trung luyện chế Thiên Qua phù, một thủ đoạn bảo mệnh cho đại chiến sắp tới. Hắn cũng chuẩn bị hàng nghìn Phệ Kim trùng, các bí pháp còn lại của Phạm Thánh Chân Ma công, Báo Lân thú và nhóm hậu tuyển Phệ Kim trùng vương để đối phó cường địch. Quá trình luyện phù gây ra thiên tượng lớn trên thạch tháp, hút kim linh khí trong phạm vi hàng vạn dặm và ảnh hưởng tới nhiều bảo vật kim chúc ở vùng lân cận. Sau hai tháng, kim sắc phù lục thành hình giữa hai tay Hàn Lập, phía trên là pháp tướng ba đầu sáu tay mang ba biểu cảm hỉ, nộ, ai và nâng sáu hư ảnh pháp khí. Ngân Quang tiên tử đích thân tới báo rằng toàn bộ cao giai Ma tộc cùng đại quân ma thú đã xuất động, hóa thân Huyết Quang Thánh tổ cũng có thể đang hiện diện. Hàn Lập lập tức kết thúc bế quan, đưa Khí Linh Tử, Hải Đại Thiếu và Băng Phượng tới nơi tập kết rồi cùng Ngân Quang lên thạch tháp chỉ huy. Tại đây, ngân phát lão giả chỉ về phía quân địch và nhận định một kẻ trong đó chính là hóa thân Huyết Quang Thánh tổ, thống soái của đợt tiến công lần này."},{"chuong":1993,"tieuDe":"Thiên Uyên Thành Đại Chiến 2","tomTat":"Theo chỉ dẫn của Cốc huynh, Hàn Lập quan sát trung tâm đại quân Ma tộc và nhận ra thiếu niên huyết bào có dung mạo giống các hóa thân Huyết Quang từng truy sát mình. Huyết Quang dùng Hắc Quang ma nhãn ghim giữ ánh mắt hắn, nhưng Hàn Lập dựa vào thần niệm cường đại để thoát khỏi đồng thuật. Sau khi xác nhận đối phương nhiều khả năng là hóa thân của Huyết Quang Thánh tổ, Hàn Lập nhận nhiệm vụ kiềm chế hắn, còn các trưởng lão phụ trách ngăn những Ma tộc tôn giả khác can thiệp. Đại quân Ma tộc sau đó thả ra số lượng ma thú vượt xa tình báo, gồm hơn trăm ma thú hóa hình và trên một nghìn siêu cấp ma thú, khiến nhiều trưởng lão thủ thành kinh hãi. Cốc huynh kích hoạt các pháp trận và đưa Thiên hà tứ bảo lên bốn tế đàn để sát thương đê giai ma thú trên diện rộng, giảm thương vong và củng cố sĩ khí. Hàn Lập tiếp tục phát hiện các đội Ma tộc tinh nhuệ theo sau đàn thú, rồi chiến thuyền, phi tháp và vô số chiến xa đồng loạt rời ma hải. Việc đối phương tung toàn bộ lực lượng ngay từ đầu khiến Kim Việt thiền sư xác định trận chiến đã trở thành thời khắc quyết định sinh tử tồn vong của Thiên Uyên thành."},{"chuong":1994,"tieuDe":"Thiên Uyên Thành Đại Chiến 3","tomTat":"Sau khi các trưởng lão thống nhất dốc sức phòng thủ, Ngân phát lão giả bí mật giao nhiệm vụ cho Hàn Lập và đưa hắn tới tiếp quản Thanh Vân tam thập lục sĩ. Ba mươi sáu trận tu Hóa Thần kỳ cho biết đại trận thượng cổ mà họ khổ luyện tuy không mạnh về sát thương nhưng đủ khả năng tạm thời vây khốn Ma tộc tôn giả thông thường. Trong lúc Hàn Lập ngồi giữa trận chờ thời, biển ma thú cấp thấp dưới sự điều động của nhiều tồn tại cao cấp bắt đầu tổng công kích, khiến một số đoạn phòng hộ của Thiên Uyên thành rạn nứt. Ngân phát lão giả lập tức ra lệnh không tiếc linh thạch khởi động Thiên hà tứ bảo. Tinh sa, hắc thủy, kiếm ảnh và bạch quang đồng loạt quét qua chiến trường, nhanh chóng tiêu diệt hơn mười vạn ma thú cấp thấp. Phía Ma tộc liền xuất động hắc vân, hoàng sắc quái phong và hai đạo huyết hồng nhằm đối phó bốn bảo vật. Nhận ra cuộc chiến hiện tại mới chỉ là giai đoạn tiêu hao, Hàn Lập thu hồi thần niệm, tiếp tục dưỡng sức và quyết tâm giết hóa thân Huyết Quang Thánh tổ khi hai bên trực tiếp giao chiến."},{"chuong":1995,"tieuDe":"Thiên Uyên Thành Đại Chiến (4)","tomTat":"Sau ba canh giờ chờ đợi, Hàn Lập nhận ra Ma tộc đã tung toàn bộ lực lượng tinh nhuệ vào trận, khiến cuộc chiến quanh Thiên Uyên Thành bước sang giai đoạn quyết liệt. Khi ma âm từ một chiến đoàn cao giai xuyên qua cấm chế làm ba mươi sáu tu sĩ trong đại sảnh bị thương, hắn lập tức dựng linh quang bảo vệ và giúp họ ổn định thương thế. Dùng thần niệm quan sát, Hàn Lập thấy quầng sáng phòng hộ của thành đã tan vỡ, quân Ma tộc đông đảo áp sát, nhưng cấm không đại trận cùng các cao thủ Nhân Yêu lưỡng tộc vẫn duy trì được cục diện giằng co. Trên không trung, nhiều chiến đoàn từ Hóa Thần trở lên giao phong dữ dội bằng thủy hỏa, phong nhận và âm ba, song hóa thân Huyết Quang Thánh Tổ vẫn chưa lộ diện nên Hàn Lập tiếp tục án binh bất động. Khi nhiều Ma tôn từ ma hải tiến ra mà phía thủ thành thiếu tu sĩ Hợp Thể nghênh chiến, các tu sĩ Luyện Hư mặc ngũ sắc phục được điều động, một nhóm uống đan dược để bán yêu hóa, nhóm còn lại thả hàng trăm thi khôi lỗi có khả năng tự phục hồi. Nhờ thi khôi lỗi cầm chân đối phương, các tu sĩ thủ thành dùng trận bàn thuấn di và phiên kỳ dựng ngũ sắc vân vụ đại trận, nhốt toàn bộ Ma tôn bên trong. Cuối cùng, những tu sĩ đã yêu hóa dán kim ngân phù triện, hóa thành yêu phong xông vào trận, hợp lực giao chiến với các Ma tôn mà tạm thời không rơi xuống hạ phong."},{"chuong":1996,"tieuDe":"Thiên Uyên Thành Đại Chiến 5","tomTat":"Cuộc đại chiến ngoài Thiên Uyên Thành leo thang khi hơn trăm phi tháp đối đầu chiến thuyền và tam giác ma tháp của Ma tộc, còn khôi lỗi, linh thú, giáp sĩ cùng ma cầm lao vào hỗn chiến. Hàn Lập được truyền tống cùng ba mươi sáu tu sĩ tới một không gian pháp trận và lập tức dùng chiến giáp cùng bảy mươi hai tiểu kiếm hộ thân. Tại đây, hắn gặp ngân phát lão giả đã mất một cánh tay, Kim Việt đang trọng thương, Huyết Quang hóa thân và Ma Tôn hậu kỳ tên Hung. Đối phương nhận ra Hàn Lập đã tiến lên Hợp Thể hậu kỳ với pháp lực vượt tu sĩ cùng cấp thông thường. Ngân phát lão giả và Kim Việt tiết lộ Hung có chiến lực gần nửa bước Đại Thừa, đồng thời cảnh báo kết quả cuộc đối đầu này có thể quyết định toàn bộ chiến cuộc. Hai người nhận trách nhiệm dựa vào pháp trận để cầm chân Huyết Quang hóa thân, còn Hàn Lập một mình đối phó Hung. Trước khi giao chiến, Hung ném cánh tay cụt của ngân phát lão giả lên không rồi dùng lang nha bổng đánh nát thành huyết vũ để thị uy."},{"chuong":1997,"tieuDe":"Thất Diễm Phiến Cùng Đồng Tâm Hoàn","tomTat":"Hàn Lập chấp nhận một mình đối đầu Hung, đồng thời yêu cầu Ngân phát lão giả và Kim Việt thiền sư đưa Huyết Quang hóa thân ra xa để hắn không thể can thiệp. Hung vận dụng huyết văn, lang nha bổng và ma hỏa, còn Hàn Lập dùng kiếm quang, quyền lực cùng Kim thân pháp tướng ba đầu sáu tay để lần lượt hóa giải các đợt tấn công. Sau nhiều lần đối kích khiến cả hai cùng bị chấn lui, Hung khoác huyết sắc giáp y và gọi ma tướng, trong khi Hàn Lập triển khai đôi cánh phong lôi để bước vào cuộc chiến pháp thể song tu chưa phân thắng bại. Huyết Quang hóa thân vừa định tung bảo vật trợ chiến thì bị quang trận chuyển vào một không gian đầy sương trắng. Tại đó, Ngân phát lão giả và Kim Việt thiền sư tuy biết đối thủ mạnh hơn vẫn quyết định liều mạng giữ hắn lại. Ngân phát lão giả lấy Thất Diễm phiến cùng Đồng Tâm hoàn làm át chủ bài, còn Kim Việt thiền sư phát động áo cà sa, gọi ra vô số phạm văn và mười tám hư ảnh Phật tượng để chuẩn bị quyết chiến."},{"chuong":1998,"tieuDe":"Kinh Thiên Nhất Kích","tomTat":"Kim Việt thiền sư kích hoạt mười tám pho tượng mô phỏng Kim thân pháp tướng, phối hợp với lão giả tóc bạc dùng Thất Diễm phiến và năm ngân hoàn vây công Huyết Quang hóa thân. Huyết Quang hóa thân triệu ra huyết sắc khô lâu, ma vân và nhiều huyết sắc quang đoàn để chống lại thế hợp công. Ở một chiến tuyến khác, Hàn Lập cùng Hung đấu sức bằng hai ngọn núi và đôi cự giản, trong khi pháp tướng của đôi bên cận chiến mà chưa thể gây thương tổn đáng kể. Hung sau đó ngưng tụ ma sư ba đầu, hợp năm luồng sáng thành quang trụ bốn màu có uy năng gần ngang một kích tùy ý của tu sĩ Đại Thừa kỳ. Hàn Lập hóa thành kim mao cự viên, dung hợp Phạm Thánh kim thân và liên tiếp dùng hai ngọn núi cùng chiến giáp đen phòng ngự nhưng vẫn bị đẩy đến sát giới hạn. Hắn tiếp tục biến thành cự viên ba đầu sáu tay, dùng kim sắc toàn phong hóa giải quang trụ khiến Hung hao tổn nhiều chân nguyên mà không đạt kết quả. Cuối chương, Hàn Lập áp súc vòng xoáy thành quang cầu vàng rồi biến mất cùng nó, bắt đầu đòn phản kích chưa rõ kết quả."},{"chuong":1999,"tieuDe":"Hắc Nhật","tomTat":"Nam tử Ma tộc dùng huyết diễm từ chiến giáp và ma thương ba mũi phá tan vòng xoáy kim sắc của Hàn Lập, nhưng không thể áp đảo sáu kiện binh khí liên tục tái hiện trong tay cự viên ba đầu sáu tay. Hàn Lập huyễn hóa hàng nghìn binh ảnh tấn công, song đối phương dùng tử sắc cự võng mở rộng thành tử vân để thu sạch chúng. Báo Lân thú bất ngờ đánh lén từ phía sau, tạo cơ hội cho Hàn Lập phối hợp ngân quang trói buộc, binh khí kim sắc và hỏa điểu ngân diễm tiếp tục vây công. Nam tử Ma tộc phá thế trói rồi thi triển Cửu Ma Tử Mẫu thương, giấu đoản thương sau các trường thương khác và kích nổ thành hắc nhật ngàn trượng nuốt trọn hình thể cự viên. Khi hắc nhật tan đi, cự viên kim mao, ngũ sắc thải phượng và cự bằng trắng bạc vẫn tồn tại trong nhiều tầng quang tráo, nhưng cả ba đều vô thần và vị trí thật của Hàn Lập vẫn không lộ. Không tìm được đối thủ, nam tử Ma tộc gọi sinh vật từng giao chiến với Phạm Thánh kim thân trở lại, để rồi hắc khí tan ra và lộ nguyên hình một khôi lỗi đen khắc đầy kim ngân phù trận."},{"chuong":2000,"tieuDe":"Niết Bàn Thánh Thể","tomTat":"Hàn Lập khiến bản mạng Nguyên anh dung hợp với các hư ảnh cự viên, thải phượng và ngân bằng, ngưng tụ thành Niết Bàn Thánh Thể ba đầu sáu tay. Hắn vận dụng vạn nguyên chi lực phá liên tiếp huyết sắc quang diễm, lệnh bài hóa thuẫn và quyền ảnh, đánh trọng thương nam tử được xưng là đệ nhất tôn giả Ma tộc, nhưng bản thân cũng phun máu vì phản phệ. Không dừng lại, Hàn Lập dung hợp thêm năm chân linh hư ảnh và cưỡng ép tiến vào nhị niết biến thân với hình thái hai đầu bốn tay mặc chiến giáp vàng. Bốn kim thủ của hắn hợp thành cự chưởng trăm trượng, khóa chặt linh hồn đối thủ và buộc người này phải trực diện chống đỡ. Nam tử Ma tộc dùng quái nhận kim ngân cùng hơn mười kiện đỉnh giai bảo vật tự bạo nhưng chỉ khiến kim chưởng dao động nhẹ. Trước khi đòn đánh rơi xuống, hắn cho hư ảnh ma sư ba đầu nhập vào khôi lỗi nhiều mặt, khiến khôi lỗi hóa thành ma sư rồi bỏ chạy. Kim sắc cự chưởng cuối cùng nghiền nát mọi nhận mang và quang trụ, khiến thân thể nam tử Ma tộc phi hôi yên diệt."},{"chuong":2001,"tieuDe":"Thiên Qua Diệt Địch","tomTat":"Sau khi phá hủy pháp thể của nam tử Ma tộc, Hàn Lập giải trừ trạng thái ma hóa nhưng tinh khí suy giảm nghiêm trọng, buộc hắn phải lập tức dùng nhiều bình đan dược để ổn định thân thể. Chủ nguyên thần của đối phương bỏ nhục thân, phụ lên khôi lỗi ma sư ba đầu rồi quay lại truy sát hắn. Hàn Lập kích hoạt Không gian pháp trận và bí mật tráo vị trí với Báo Lân thú, để linh thú mang huyết mạch Kỳ lân cản các đòn công kích và hắc sắc lôi trảo. Khi đối phương tìm ra vị trí thật, hắn tế Thiên Qua phù, khiến kim qua khổng lồ áp chế pháp lực rồi chém nát cả khôi lỗi lẫn nguyên thần, làm nam tử Ma tộc hoàn toàn ngã xuống. Sau chiến thắng, Hàn Lập nhìn lại hai sát thủ giản đã sử dụng và xác nhận đòn phá hủy pháp thể vốn là thần thông của Phạm Thánh Chân Ma công dành cho cảnh giới Đại Thừa. Để cưỡng ép thi triển, hắn phải kết hợp Niết Bàn Thánh thể, Kinh Trập thập nhị quyết và Chân linh chi huyết, đổi lấy tổn thất nghiêm trọng về nguyên khí và Chân huyết."},{"chuong":2002,"tieuDe":"Thái Cực Đồ Truyện","tomTat":"Sau trận chiến với đại hán Ma tộc, Hàn Lập chỉ còn chưa tới nửa pháp lực nên phải lập tức điều tức giữa chiến trường, dùng ngân châm, phù lục và bí thuật tạm áp chế lượng dược lực tích tụ trong cơ thể. Không gian pháp trận bất ngờ bị huyết sắc khô lâu ba đầu sáu tay cưỡng ép đánh nát, khiến ba mươi sáu tu sĩ chủ trì đồng loạt chịu phản phệ và toàn bộ khí cụ bày trận bị hủy. Hàn Lập nhận ra Huyết Quang hóa thân đang chiếm ưu thế trước Kim Việt thiền sư và Ngân phát lão giả, nhưng đối phương cũng nhanh chóng chuyển ma phong sang tập kích hắn. Hắn thả hơn vạn Phệ Kim trùng thành thục thể, điều khiển chúng kết thành kim sắc thuẫn bài chặn công kích, phá sáu ma binh biến hóa rồi hóa thành cự ưng truy sát đối phương. Bị đàn trùng khắc chế, Huyết Quang hóa thân mang theo huyết sắc khô lâu bỏ chạy. Kim Việt thiền sư và Ngân phát lão giả lập tức hợp nhất hai nửa khăn gấm, tạo hư ảnh Thái Cực Đồ bao phủ chiến trường rồi co lại quanh Huyết Quang hóa thân. Chương khép lại khi đồ án phóng ra vô số ngũ sắc phù văn và dần ngưng thành thực chất, trong khi kết quả trấn áp vẫn chưa được xác định."},{"chuong":2003,"tieuDe":"Trùng Uy","tomTat":"Thái Cực Đồ phát ra cự lực xoay chuyển, khóa chặt hóa thân Huyết Quang cùng huyết sắc khô lâu và đẩy lui đại ấn màu đen. Huyết Quang nhập vào khô lâu, kích nổ ba vật để gia cường chiến thể rồi hợp sáu ma binh thành nguyệt đao, nhiều lần chém bảo vật thành hai mảnh. Lão giả tóc bạc và Kim Việt thiền sư liên tục tiêu hao tinh huyết để tái hợp Thái Cực Đồ, bất chấp thân thể nhanh chóng khô kiệt. Hàn Lập điều khiển hơn vạn Phệ Kim Trùng trưởng thành cắn phá huyết sắc khô lâu, buộc Huyết Quang phải cho chiến thể tự nổ để tìm đường thoát. Hơn mười Phệ Kim Trùng Vương bí mật lẫn trong đàn vẫn vượt qua khí lãng và bám lên lưng hắn, còn dị thú màu vàng kịp thời trì hoãn đường chạy. Đàn trùng sau đó đuổi kịp, cắn nuốt hoàn toàn cả thân thể lẫn Nguyên Anh của hóa thân Huyết Quang. Hàn Lập thu hồi linh trùng, trong khi hai người điều khiển Thái Cực Đồ vui mừng vì ma đầu đã chết nhưng phải chịu phản phệ nặng nề. Chương kết thúc khi lão giả tóc bạc hỏi Hàn Lập về số phận của Ma Tộc tôn giả còn lại."},{"chuong":2004,"tieuDe":"Đại Thắng","tomTat":"Hàn Lập xác nhận đã giết Ma Tôn hậu kỳ, khiến lão giả tóc bạc lập tức công bố thắng lợi và làm sĩ khí liên quân Nhân Yêu tăng mạnh. Nhiều Ma Tôn bỏ chạy, quân Ma tộc cấp thấp mất chỉ huy rồi hoàn toàn tan rã trước cuộc truy kích kéo dài ba ngày ba đêm của Thiên Uyên Thành. Hàn Lập không tham gia truy sát mà đưa Báo Lân Thú trở về thạch tháp, sau đó bế quan vì nguyên khí hao tổn và nhiều loại dược lực trong cơ thể đang xung đột. Trong hội nghị bí mật sau chiến thắng, các tu sĩ Hợp Thể biết hắn đã dùng hơn vạn Phệ Kim Trùng trưởng thành cắn nuốt hóa thân Huyết Quang và còn tự tay giết một Ma Tôn hậu kỳ. Thủy phu nhân đánh giá thần thông của Hàn Lập đủ đứng trong năm người hàng đầu Nhân Yêu hai tộc, nhưng mọi người chưa thể gặp hắn vì hắn đang bế quan. Giới lãnh đạo Thiên Uyên Thành cam kết báo đáp lực lượng viện trợ và quyết định chủ động truy quét tàn quân, đồng thời đề phòng Huyết Quang Thánh Tổ phái một hóa thân khác xuống Linh Giới."},{"chuong":2005,"tieuDe":"Khách Đến Ngoài Ý Muốn","tomTat":"Sau khi đẩy lui đại quân Ma Tộc, Thiên Uyên Thành tổ chức truy quét tàn quân, sửa chữa hệ thống phòng ngự và phá hủy các tiết điểm thông tới Ma Giới. Trận chiến chính thức kết thúc với thắng lợi đầu tiên của Nhân Yêu hai tộc kể từ khi Ma Kiếp bùng nổ, nhưng hơn một phần ba phòng tuyến bị phá hủy và lực lượng thủ thành chịu thương vong nghiêm trọng. Trong năm tiếp theo, đông đảo tán tu, tông môn và thế gia kéo tới gia nhập, giúp Thiên Uyên Thành nhanh chóng phục hồi. Tại thạch tháp, Hàn Lập kết thúc bế quan sau khi đã khôi phục hơn phân nửa nguyên khí để tiếp Lũng gia lão tổ. Vị lão tổ thừa nhận thực lực Hàn Lập hiện đã vượt mình rồi tiết lộ kế hoạch bí mật tiến vào Ma Giới phải được thực hiện sớm hơn dự định. Nguyên nhân là Nhân Yêu hai tộc sắp phát động phản công, trong khi ba đại thủy tổ Ma Giới có thể cùng phủ xuống Linh Giới và làm mất cơ hội tìm kiếm hai linh vật. Khi biết nguồn tin đến từ Thánh Đảo và do chính Ngao Khiếu nói ra, Hàn Lập kinh ngạc trước việc vị Đại Thừa Yêu Tộc này đang có mặt tại đó."},{"chuong":2006,"tieuDe":"Ước Định Sớm","tomTat":"Lũng gia lão tổ đề nghị Hàn Lập đẩy sớm kế hoạch tiến vào Ma Giới, tranh thủ lúc lực lượng Ma Tộc bị điều động cho đại chiến và trước khi các thủy tổ hàng lâm. Ông cho biết chủ lực Ma Tộc đang tập trung đánh Thánh Hoàng Thành, còn Ngao Khiếu dự kiến lưu lại Thánh Đảo và có thể dẫn theo một hậu nhân. Hàn Lập xin hai ngày suy xét rồi yêu cầu Khí Linh Tử và Hải Đại Thiếu giữ kín cuộc gặp. Biết Băng Phượng đã lĩnh ngộ và bắt đầu bế quan vì xuất hiện linh cơ đột phá, hắn ra lệnh cho hai đệ tử bảo vệ nàng khỏi bị quấy rầy. Hơn nửa năm sau, một nữ tử điều khiển hào quang năm màu đi ngang chiến trường và tiện tay dùng quang ti ngũ sắc tiêu diệt nhóm Ma Tộc. Sau khi nàng rời đi, Cung trang nữ tử cùng đại hán mặc chiến giáp đen hiện thân, để lộ rằng họ đã theo dõi nàng nhiều năm theo chỉ dẫn bói toán nhằm tìm linh dược trị thương."},{"chuong":2007,"tieuDe":"Nhiếp Linh Thiên Võng","tomTat":"Cung trang nữ tử phóng hà quang màu hồng, đưa mình và Đại hán mặc chiến giáp đen rời khỏi nơi đang đứng. Tại Tổ Vân Sơn gần khu vực Nhân Tộc, ba thái thượng trưởng lão Linh Tộc đối mặt Thanh niên áo bào vàng sau khi toàn bộ thành viên của cứ điểm bị hắn giết và hấp thu tinh nguyên bản thể. Người này gọi Linh Tộc là Linh nô, tự xưng đến từ Tiên Giới và muốn hạ huyết khế lên ba đối thủ. Cho rằng hắn có thể đang gặp vấn đề, ba Thánh Linh liên thủ dùng bạch diễm, cự mộc và phong nhận tấn công, nhưng tất cả đều bị kim ngân phù tráo đẩy lui. Thanh niên áo bào vàng sau đó ngưng tụ Nhiếp Linh thiên võng rộng nhiều dặm, khiến ba người mềm nhũn và không thể điều động hơn phân nửa pháp lực. Nhận ra lai lịch Tiên Giới của đối phương, ba thái thượng trưởng lão lập tức hóa hình chia hướng tháo chạy. Ngân võng tiếp tục mở rộng và phủ xuống cả vùng trời đất, còn kết cục của ba người chưa được xác nhận."},{"chuong":2008,"tieuDe":"Hoàng Cân Khôi Lỗi","tomTat":"Thanh niên áo bào vàng vận dụng tấm lưới bạc dẫn động thiên địa nguyên khí, phá hủy thân thể biến hóa và xóa linh trí của ba đại Thánh Linh. Hắn thu lại cổ kích bạc, nửa đoạn trúc xanh cùng quang cầu xanh nhạt để tế luyện, rồi tiếp tục tính chuyện tìm thêm bảo vật dù Linh Tộc có cường giả Đại Thừa tọa trấn. Một pháp khí hình con mắt màu tím bí mật ghi nhận trận chiến và truyền hình ảnh về cung điện vàng, khiến lão giả tóc bạc nhận ra đối phương đang sử dụng phỏng chế phẩm Nhiếp Linh thiên võng có khả năng khắc chế Linh Tộc. Lão giả vì thế quyết định vận dụng một thủ đoạn chưa được tiết lộ để trấn áp thanh niên áo bào vàng. Ở khu rừng núi giữa Thánh Thành và Thiên Uyên Thành, Hàn Lập gặp Diệp tiên tử và lập tức nhìn thấu Hoàng Cân khôi lỗi đang ngụy trang thành cây đại thụ. Hàn Lập xác nhận đã tiến giai Hợp Thể hậu kỳ nhưng nói giảm chiến tích trước các cường giả Ma Tộc. Cuối cùng, Diệp tiên tử tiết lộ Thánh Đảo là một nửa Huyền Thiên Linh Bảo và là nơi duy trì truyền thừa của Nhân Yêu hai tộc."},{"chuong":2009,"tieuDe":"Thỉnh Cầu","tomTat":"Diệp tiên tử tiết lộ rằng mật điển của một vị tổ tiên Đại Thừa thuộc Diệp gia từng ghi lại cảnh một Đại thủy tổ Ma Tộc giao chiến với Chân Linh, qua đó cho thấy thực lực của đối phương vượt xa Đại Thừa thông thường. Vị tổ tiên ấy nhiều lần lẻn vào Ma Giới tìm linh dược nhưng mất tích trong chuyến đi cuối cùng. Nàng nhận định Mạc Giản Ly khó vượt qua đại thiên kiếp kế tiếp, Ngao Khiếu không còn nhiều thọ nguyên, còn tư chất của Thánh Hoàng và Phách Hoàng đều không thể so với Hàn Lập, nên Thánh Đảo có thể xem hắn là hy vọng phục hưng Nhân Yêu hai tộc. Vì lo Diệp gia bị diệt trong đại chiến, nàng xin Hàn Lập thu nhận những hậu bối có huyết mạch Thiên Phượng tinh thuần và đưa họ tới Thánh Đảo. Hàn Lập từ chối thu đồ nhưng đồng ý viết thư cho trưởng lão Thánh Đảo, cho những hậu bối ấy đến Thiên Uyên Thành tìm môn hạ của mình. Diệp tiên tử cũng quyết định sát cánh cùng hắn trong Ma Giới vì không tin Lũng gia lão tổ và đề phòng Linh Tộc có mục đích riêng. Cuối chương, Hàn Lập bắt đầu tạo ngọc giản truyền tin để nàng chuyển về cho tộc nhân."},{"chuong":2010,"tieuDe":"Hai Tộc Gặp Nhau","tomTat":"Hàn Lập trả ngọc giản và ngọc bội cho Diệp tiên tử, xác nhận mình đã tiến lên Hợp Thể hậu kỳ rồi cùng nàng tới thạch động trao đổi tâm đắc tu luyện và bàn kế hoạch vào Ma Giới. Gần sơn cốc, Cung trang nữ tử bí mật bói toán Hàn Lập nhưng hoàn toàn thất bại, còn pháp khí hỗ trợ cũng vỡ vụn vì Huyền Thiên Linh Bảo hoàn chỉnh đang phong ấn trong cơ thể hắn. Nàng ngăn thuộc hạ ra tay và quyết định tiếp tục theo dõi Diệp tiên tử, người mang huyết mạch Thiên Phượng và được xem là đầu mối dẫn tới linh dược nghịch thiên. Năm ngày sau, bốn người Linh Tộc tới nơi bằng một chiến thuyền xanh khổng lồ và thống nhất tạm thời toàn lực hợp tác với Nhân Tộc để tìm linh vật trong Ma Giới. Họ hy vọng chuyến đi sẽ giúp Linh Tộc xuất hiện thêm một tồn tại Đại Thừa Kỳ, đồng thời bí mật chuẩn bị một chiến lực có linh trí không đầy đủ do Thiên Thu thánh nữ dùng bí bảo khống chế. Ở một hướng khác, Lũng gia lão tổ dẫn hắc bào nhân mặt sẹo và một nam tử tóc xõa bay về phía sơn cốc, báo hiệu các chiến lực hai tộc sắp chính thức hội tụ."},{"chuong":2011,"tieuDe":"Thiên Mệnh Đồng Tiễn","tomTat":"Cự thuyền của Linh Tộc và nhóm Lũng gia lão tổ gần như đồng thời tới tiểu cốc, nơi Hàn Lập cùng Diệp tiên tử đang chờ sẵn. Thiên Thu thánh nữ kinh ngạc phát hiện Hàn Lập đã đạt Hợp Thể hậu kỳ, khiến thực lực biểu hiện giữa hai đội trở nên cân bằng hơn. Nàng lần lượt giới thiệu Kim Cổ trưởng lão, Tàng Hình, Bạch Thích và Chỉ Thủy cùng những sở trường cần thiết cho hành trình Ma Giới. Hai bên nhanh chóng điều chỉnh các chi tiết cuối cùng của kế hoạch rồi cùng lên cự thuyền rời đi. Phía sau, cung trang nữ tử và đại hán mặc chiến giáp đen bí mật bám theo; Thiên Mệnh Đồng Tiễn của nàng tự phản ứng trước một dị bảo có thể tạo thành uy hiếp, đồng thời nàng còn mơ hồ cảm ứng được linh dược trên một người trong đoàn. Cự thuyền tàng hình suốt ba tháng, cẩn thận vòng tránh các cứ điểm Ma Tộc và cuối cùng tới một bờ biển mênh mông."},{"chuong":2012,"tieuDe":"Luyện Đỉnh","tomTat":"Cự thuyền màu xanh đưa đoàn tu sĩ tiếp tục vượt biển tới gần tiết điểm thông đạo vào Ma giới, trong khi mọi người âm thầm điều tức để chuẩn bị cho hành trình nguy hiểm. Trong mật thất, Hàn Lập hội hợp với linh khu, Khúc Nhi và Đệ nhị Nguyên Anh; Đệ nhị Nguyên Anh đã tái ngưng tụ thân thể và hồi phục khoảng bảy tám phần sau lần tự bạo thoát thân. Hàn Lập dùng chân diễm ép phân niệm Huyết Quang khỏi Tử Ngôn Đỉnh, tiêu diệt nó bằng kim sắc điện hồ rồi tế luyện bảo vật bằng tinh huyết. Sau mười ngày tiếp tục tế luyện và lĩnh hội, hắn nắm giữ hơn phân nửa công năng của Tử Ngôn Đỉnh. Hàn Lập thử thúc giục Huyền Thiên chi kiếm nhưng cánh tay và kinh mạch đau đớn, khiến hắn nhận ra pháp lực Hợp Thể hậu kỳ vẫn chưa đủ và có lẽ phải đạt Đại Thừa kỳ. Hai tháng sau, đoàn tới gần tiết điểm đã định, rời cự thuyền để chuyển sang tự bay. Tàng Hình thi pháp thu nhỏ cự thuyền thành một cây gỗ xanh rồi cất vào người."},{"chuong":2013,"tieuDe":"Thiên Bặc","tomTat":"Lũng gia lão tổ cho biết đoàn người chỉ còn cách tiết điểm Ma tộc khoảng bốn, năm ngày và giải thích rằng lối đi này có thể đưa họ nhanh chóng tới Huyết Thạch Sơn Mạch trong Ma giới. Đoàn chia nhóm lên đường, nhiều lần âm thầm vượt qua các đội tuần tra của Bạo Ma tộc mà không giao chiến. Khi tới quần đảo san hô có cao cấp Ma tộc trú đóng, Thiên Thu thánh nữ dùng phiên kỳ tạo cấm chế sương trắng, còn mọi người nuốt Ngụy Ma Châu để che giấu thân phận trước khi tiến vào trung tâm quần đảo. Cách đó hơn trăm dặm, cô gái cung trang áo trắng quyết định chịu thêm phản phệ để mở đàn Thiên Bặc truy tìm đoàn Hàn Lập và cơ hội khôi phục pháp lực. Nàng bác đề nghị để Hắc Ngạc dùng Chấn Nguyên Giản vì hắn không thể phát huy đầy đủ uy năng, đồng thời Thiên Mệnh Đồng Tiền cho biết phía đối phương có vật đủ sức đối kháng. Hắc Ngạc hiện pháp tướng khổng lồ, dựng thạch đài xanh, bố trí tám tượng mộc nhân và tạo thủy mạc bao quanh. Sau khi cô gái cung trang bắt đầu làm phép, toàn bộ tế đàn dần biến mất khỏi hư không, còn các mộc nhân tự chia thành từng cặp đứng tại bốn góc thạch đài."},{"chuong":2014,"tieuDe":"Diệt Khẩu","tomTat":"Cung trang nữ tử biến đồng tiền thành chậu đồng phù văn, kích hoạt tám người gỗ rồi sai Đại hán mặc chiến giáp đen rót tinh huyết cổ thú Hợp Thể kỳ vào làm tế phẩm. Nàng tiếp tục lấy chất lỏng màu bạc từ cơ thể, khiến cây hoa màu hồng chuyển thành màu bạc, sau đó dùng khăn đen dựng một không gian tối chứa vô số điểm sáng vận chuyển như tinh tú. Trong lúc tám mặt quỷ tạo cột sáng chống đỡ không gian, nàng liên tục vận dụng la bàn vàng để suy diễn và hao tổn đến mức sắc mặt tái nhợt. Sau nửa canh giờ, màn nước che giấu nơi làm phép bất ngờ hiện hình rồi nổ tung đúng lúc đội vệ sĩ Bạo Ma tộc do Thạch Thước dẫn đầu bay ngang qua. Kết quả suy diễn khiến nữ tử vừa khó tin, vui mừng, sợ hãi vừa do dự, nhưng nàng vẫn lập tức ra lệnh diệt khẩu những người đã phát hiện hai người. Đại hán phóng hắc khí chứa yêu trùng sát hại đội vệ sĩ, đuổi theo chém đầu Thạch Thước rồi mang thủ cấp trở về. Sau cuộc truy sát, cung trang nữ tử không chú ý đến những việc xung quanh mà tiếp tục vuốt ve la bàn với vẻ âm tình bất định."},{"chuong":2015,"tieuDe":"Xông Vào","tomTat":"Cung trang nữ tử cho biết lần bói toán đã gây phản phệ ngoài dự liệu, phá hủy tế đàn cùng tám khôi lỗi thế thân và khiến nàng tạm thời khó sử dụng lại thuật này. Dù quẻ tượng còn mơ hồ, nàng xác định đoàn người phía trước có liên quan tới việc khôi phục tu vi nên cùng hắc giáp đại hán bí mật truy tung họ. Khi đoàn Hàn Lập tới đảo san hô, họ phát hiện cứ điểm Ma tộc bảo vệ thông đạo đã được mở rộng thành một thành lũy kiên cố với quân tuần tra, ma cầm và nhiều tầng cấm chế. Lũng gia lão tổ phản đối việc đổi thông đạo, đề nghị cả đoàn ẩn nấp tiếp cận tiết điểm rồi dùng thực lực cưỡng ép vượt qua nếu bị phát hiện, và Thiên Thu thánh nữ cùng đồng bạn chấp thuận. Yêu vân do Thiên Thu thánh nữ điều khiển giúp mọi người vượt qua nhiều đội tuần tra, nhưng một pháp trận bí mật cuối cùng vẫn phát hiện họ và phóng vô số hắc mang tập kích. Cả đoàn hợp lực phá tan cấm chế rồi lao thẳng về phía tiết điểm, khiến hệ thống phòng thủ của cứ điểm đồng loạt khởi động và đại quân Ma tộc bay lên nghênh chiến."},{"chuong":2016,"tieuDe":"Bảo Hoàng Thánh Hoa","tomTat":"Đội Hàn Lập bị quang mạc đen chặn đường, nhưng Tàng Hình dùng phù lục phá cấm mở ra một lỗ hổng cho cả đoàn vượt qua. Mười cường giả Hợp Thể sau đó liên kết độn quang thành trường hồng bảy màu, quét sạch quân tuần tra và xuyên thủng nhiều tầng cấm chế của Ma tộc. Khi lôi võng xuất hiện trong mây đen, Lũng gia lão tổ dùng Tinh Lôi bình hút sạch điện hồ, đồng thời để lộ xuất thân Lũng gia. Ma Tôn Khách huynh nhận thấy lực lượng hai bên chênh lệch nên dẫn thuộc hạ tránh đường, để đoàn Hàn Lập tiến vào thông đạo dẫn tới Ma giới. Phong huynh tới muộn, biết chuyện đoàn dị tộc xâm nhập và định báo cáo lên Thánh Tổ, nhưng một nữ tử bí ẩn yêu cầu hai Ma Tôn giữ kín tin tức. Bảo Hoàng thánh hoa hiện hình khiến Phong huynh nhận ra Bảo Hoa và hoảng sợ bỏ chạy. Các cánh hoa lập tức bốc cháy, hóa thành vô số ngọn lửa hồng từ trên không rơi xuống."},{"chuong":2017,"tieuDe":"Thiên Khấp Và Hạc Nhan","tomTat":"Bảo Hoa dùng phấn diễm tiêu diệt gần như toàn bộ Ma tộc quanh thông đạo, chỉ để lại Ma Tôn Khách Vân, một thành viên ám bộ cũ lập tức quỳ xuống nhận chủ. Sau khi biết Khách Vân bị khống chế, nàng dò xét thần thức, hóa giải cấm chế âm độc trong người hắn rồi đặt một cấm chế khác để che mắt những kẻ đứng sau. Khách Vân báo rằng một đoàn gồm Nhân tộc và Linh tộc với tu vi ngoài Hợp Thể kỳ đã vượt thông đạo, vì vậy Bảo Hoa ra lệnh giữ kín tin tức càng lâu càng tốt. Nàng cùng Hắc Ngạc trở lại Ma giới, cho thuộc hạ xử lý lực lượng canh giữ và hội hợp tại một ngọn núi vô danh. Bảo Hoa thừa nhận chuyến trở về có thể khiến mình mất mạng vì Thiên Khấp và Hạc Nhan vẫn có thể truy sát, trong khi nàng hiện không đủ sức chống lại cả hai cùng lúc. Do quẻ bói trước đó chỉ được giải một nửa, nàng yêu cầu Hắc Ngạc không được động đến đoàn dị tộc, phải che giấu sự tồn tại của hai chủ tớ và có thể còn phải âm thầm giúp họ hoàn thành mục đích. Để khích lệ sự tận tâm của Hắc Ngạc, Bảo Hoa hứa sau khi khôi phục pháp lực sẽ trợ giúp hắn vượt bình cảnh tiến giai Đại Thừa kỳ."},{"chuong":2018,"tieuDe":"Ma Nguyên Hải","tomTat":"Hắc Ngạc cảm tạ ân huệ của Bảo Hoa và thề tận lực giúp nàng hoàn thành tâm nguyện, sau đó cùng nàng truy đuổi nhóm tu sĩ Nhân tộc. Trong khi ấy, đoàn Hàn Lập tránh giao chiến lớn với quân Ma tộc gần cửa thông đạo rồi mất hơn nửa tháng vượt khỏi Huyết Thạch sơn mạch. Tại thảo nguyên bên ngoài sơn mạch, Thiên Thu thánh nữ cho biết Tẩy Linh Trì và Tịnh Linh Liên nằm trên một đảo nhỏ thần bí ở cực đông Ma Nguyên Hải. Lũng gia lão tổ trình bày ba lộ tuyến gồm dùng truyền tống trận trong cự thành Ma tộc, theo Đệ Ngũ Ma Hà ra biển hoặc băng qua vùng hoang dã và Huyễn Khiếu sa mạc. Tuyến cự thành có nguy cơ bại lộ thân phận, đường biển đầy ma thú cấp cao, còn Huyễn Khiếu sa mạc áp chế chín thành tu vi và buộc mọi người phải đi bộ. Khi cả đoàn lo ngại hành trình qua sa mạc sẽ kéo dài năm sáu chục năm, Thiên Thu thánh nữ hé lộ rằng nàng có cách rút thời gian xuống khoảng ba mươi năm, khiến Hàn Lập muốn nghe chi tiết."},{"chuong":2019,"tieuDe":"Bát Túc Ma Tích Và Tiên Hồn Đan","tomTat":"Thiên Thu thánh nữ giới thiệu Bát Túc Ma Tích, loài ma thú bản địa có thể giúp đoàn thám hiểm rút ngắn gần một nửa hành trình qua Huyễn Khiếu sa mạc nhưng đã trở nên cực hiếm vì bị săn lấy ma hạch, xương và da. Huy trưởng lão muốn cưỡng đoạt ma tích từ các thế lực Ma tộc, Lũng gia lão tổ lo việc này sẽ kinh động cường giả, còn Tàng Hình đề nghị trộm hoặc trao đổi để tránh xung đột lớn. Hàn Lập đưa ra phương án tới gần sa mạc trước để tìm đủ thú cưỡi, nếu thất bại mới quay lại đi hải vực, và được cả Linh tộc lẫn Lũng gia lão tổ chấp thuận. Đoàn người đổi hướng bay về phía tây thảo nguyên mà không phát hiện một kẻ đang ẩn trong phấn hồng quang hà bám theo từ xa. Tại một cấm địa bí mật của Linh tộc ở Linh giới, tám Thánh Linh Hợp Thể kỳ vận hành đại trận phù văn, phối hợp ti võng và viên châu bạc để vây khốn một sứ giả mặc kim sắc chiến giáp. Sứ giả tự nhận đã tu thành Kim Tiên chân hồn và đe dọa tiêu diệt Linh tộc sau khi thoát vây. Nam tử bí ẩn trong kim điện thừa nhận trận pháp cùng pháp bảo chưa đủ trực tiếp giết linh hồn Chân Tiên, nhưng tuyên bố sẽ phong ấn sứ giả rồi dùng chân hỏa phối hợp với cửu u Địa Hỏa luyện hóa người này thành Tiên Hồn Đan trong mười vạn năm."},{"chuong":2020,"tieuDe":"Tích Huyết Phục Linh Hoa Và Huyễn Quang","tomTat":"Cự đại nhân ảnh phản đối âm mưu luyện chân hồn mình thành Tiên Hồn Đan, cảnh báo hành vi này vi phạm thiết luật Tiên giới, nhưng thanh âm già nua vẫn quyết thực hiện để tăng tu vi và củng cố Linh tộc. Tiên sứ đánh pháp quyết vào Nhiếp Linh Thiên võng, đẩy Phong Tiên Châu lên cao và tạm khôi phục pháp lực, buộc tám Thánh Linh thúc giục pháp trận ngưng tụ phù liên để trói hắn. Hắn hấp thu huyết vụ từ các ma ảnh, niệm thượng cổ chú ngữ và để lộ thân thể được ngưng tụ từ Tích Huyết Hoạch Linh Hoa. Khi yêu cầu được thả không thành, hắn quyết định tự bạo thân thể yêu hoa dù đã tiêu tốn hơn mười vạn năm để tạo dựng nó. Tám Thánh Linh bỏ chạy và tung linh bảo hộ thân nhưng không thể thoát khỏi phạm vi vụ nổ. Bạch bào lão giả chấp nhận nguy cơ bản thể tổn thương vạn năm, triệu xuất Huyễn Quang Thiên Tinh Tháp và dùng hàn quang khiến huyết hoa cùng hỏa diễm ngưng kết trì trệ. Cự đại nhân ảnh nhận ra bảo tháp, kinh hãi suy đoán bạch bào lão giả là linh nô do bảo vật biến thành và liên hệ tòa tháp với trận đại loạn tại Bắc Minh tiên cung từ trăm vạn năm trước."},{"chuong":2021,"tieuDe":"Huyền Hóa Phong Linh Phù","tomTat":"Sứ giả đến từ Tiên giới thiêu đốt tinh huyết hóa thành nhiều hỏa mãng để trì hoãn Huyễn Quang Thiên Tinh Tháp, nhưng toàn bộ hỏa mãng nhanh chóng bị quang tuyến xanh tiêu diệt. Theo lệnh Linh Vương, tám Thánh Linh tái khởi động Khốn Ma đại trận, phối hợp với băng tháp đóng băng sứ giả và Tích Huyết Phục Linh Hoa trong một băng phong khổng lồ. Linh Vương tiết lộ Huyễn Quang Thiên Tinh Tháp chính là bản thể đã bị tàn phá của mình, đồng thời giao tộc vụ cho trưởng lão hội cùng cộng đồng vì ông cần hơn vạn năm duy trì và hóa giải phong ấn. Ông tiếp tục dùng phù lục Tiên giới khắc Kim Triện Văn để phong bế thần trí đối phương, khiến một thanh niên mặc kim bào dưới đáy băng phong rơi vào hôn mê. Ở một giới diện xa lạ, đạo sĩ mặt đen phát hiện chân hồn chi bài phản ứng mạnh và quyết định đi tìm người có chân hồn gặp chuyện. Trong khi đó, Hàn Lập điều khiển bảy mươi hai đạo kiếm quang cùng kiếm liên liên tục chém giết ma thú thấp giai, nhưng đàn ma thú vẫn không sợ chết và tiếp tục vây công."},{"chuong":2022,"tieuDe":"Thảo Nguyên Thú Triều","tomTat":"Hàn Lập cùng đội ngũ của Lũng gia và Linh tộc bị thú triều vô tận vây công suốt hai ngày hai đêm, dù đã tiêu diệt hơn trăm vạn ma thú vẫn không thể phá vây. Nhận thấy đàn thú hung hãn không sợ chết có thể đang chịu sự điều khiển của Thú Vương, Hàn Lập đề xuất tìm và giết kẻ cầm đầu trước khi cuộc chiến thu hút Ma tộc cao giai. Lũng gia lão tổ cùng Thiên Thu thánh nữ thông qua kế hoạch để bốn tu sĩ Hậu kỳ chia nhau tìm kiếm trong ba canh giờ, còn những người khác ở lại duy trì phòng tuyến. Hàn Lập nhận hướng Đông, dùng bảy mươi hai thanh Thanh Trúc Phong Vân Kiếm mở đường và nhận ra uy lực phi kiếm đã tăng mạnh theo tu vi của mình. Khi thời hạn sắp hết, những tiếng nổ phía trước khiến đàn ma thú đột ngột quay đầu tháo chạy, nên Hàn Lập lập tức đuổi theo. Hắn phát hiện một khu vực có bầy ma thú xanh kịch độc và hơn mười ma thú màu bạc đang vây công hai nhân ảnh, bên cạnh là một ma thú đen mọc hai sừng năm màu nằm bất động. Một đoạn chỉ bạc xuyên qua nửa cây nhang xám tạo thành vòng khói xanh khiến toàn bộ ma thú xung quanh kiêng kỵ và không dám xông vào."},{"chuong":2023,"tieuDe":"Cứu Nạn","tomTat":"Hàn Lập phát hiện hai hộ pháp Ma tộc đang bị thú triều vây khốn bên cạnh thi thể Thú Vương mọc quái sừng năm màu. Thiết đạo hữu cầm chân đàn thú để Ô lão dựng pháp trận truyền tống, nhưng một Ngân Cảnh Thú bất ngờ phá hủy trận pháp và chặn đường thoát của họ. Hàn Lập kích thích Thương Ma Châu để giả lập khí tức Ma tộc, vượt qua đám lục thú rồi yêu cầu hai hộ pháp phải giúp mình một việc để đổi lấy sự cứu viện. Sau khi hai người chấp thuận, hắn triển khai điện võng lôi đình, bảo vệ họ và thiêu thành tro hơn phân nửa đàn ma thú. Thiết đạo hữu tiết lộ rằng tiêu diệt toàn bộ Ngân Cảnh Thú sẽ khiến thú triều lập tức tan rã và ngăn Thú Vương mới xuất hiện trong vòng trăm năm. Hàn Lập khóa thần niệm vào hơn mười Ngân Cảnh Thú đang bỏ chạy và gọi pháp tướng ba đầu sáu tay để chuẩn bị truy sát."},{"chuong":2024,"tieuDe":"Điệp Vĩ Thú","tomTat":"Hàn Lập dùng kim quang từ sáu mắt của pháp tướng tiêu diệt các ngân thú đang tháo chạy, khiến Hạo Lang thú triều mất lực lượng chỉ huy và nhanh chóng tan rã. Hai hộ pháp Huyết Nha Thành được cứu bèn khai rõ nhiệm vụ giết Hạo Lang Thú Vương, đồng thời cho biết họ phải dựa vào bảo vật đặc chế và linh dược mới có thể trà trộn vào đàn thú. Lão giả giới thiệu Huyết Nha Thành là thành trì xây trên quặng Huyết Quang Tinh, có một Ma tôn tu luyện công pháp Huyết Hà tọa trấn và sắp tổ chức hội đấu giá, nhưng Hàn Lập từ chối ghé lại. Khi biết hắn muốn tới hoang địa, hai người cảnh báo thú triều Điệp Vĩ Thú đã chiếm giữ khu vực phía đông suốt nửa tháng, với độc vụ có thể ăn mòn nhiều lớp phòng ngự. Hàn Lập dùng phù lục truyền tin triệu tập Lũng gia lão tổ, Thiên Thu thánh nữ cùng những đồng bạn đã kích phát Ngụy Ma Châu tới hội quân. Thiên Thu thánh nữ nhận định cả nhóm có thể tiêu diệt số lượng lớn Điệp Vĩ Thú riêng lẻ, nhưng nếu cưỡng ép đánh tan toàn bộ thú triều thì có thể tổn hao hơn nửa nguyên khí."},{"chuong":2025,"tieuDe":"Phong Hồn","tomTat":"Lũng gia lão tổ phái Huy trưởng lão dò xét thú triều, đồng thời tra hỏi hai Ma tộc về các thành trì lân cận, đường vòng và tình hình Huyết Nha Thành. Đại hán Ma tộc giao ra tinh thạch đen chứa bản đồ vùng phụ cận, để Lũng gia lão tổ sao chép cho cả đoàn cùng nghiên cứu. Hàn Lập đề nghị tiến vào Huyết Nha Thành nhằm quan sát cách hành xử của Ma tộc, tránh lộ thân phận trong thời gian lưu lại Ma giới và tìm kiếm tài nguyên quý hiếm; Lũng gia lão tổ cùng Thiên Thu thánh nữ đều tán thành. Huy trưởng lão trở về xác nhận vô số Điệp Vĩ thú đã phong tỏa mọi con đường phía đông, khiến phương án vào thành càng được củng cố. Lũng gia lão tổ sau đó bất ngờ đánh ngất hai Ma tộc vì không muốn giết họ và làm thành chủ chú ý. Lão quyết định dùng Phong Hồn đại pháp tạm thời phong ấn ký ức của họ, rồi bắt đầu thi pháp lên lão giả Ma tộc."},{"chuong":2026,"tieuDe":"Huyết Nha Thành","tomTat":"Đoàn Hàn Lập tới Huyết Nha thành, thu liễm tu vi và dùng Ngụy Ma châu che giấu thân phận Ma tộc để thuận lợi vượt qua cổng thành đang được canh phòng nghiêm ngặt. Hàn Lập dùng linh mục kiểm tra các pháp trận tại cổng, đồng thời biết rằng tường thành xây bằng đá Huyết Quang tinh có khả năng làm suy yếu pháp thuật và trong thành đang kích hoạt cấm chế cấm không. Sau khi vào thành, Lũng gia lão tổ đề nghị mọi người tạm thời phân tán cho đến khi Điệp Vĩ thú rời đi. Ông tiếp tục bí mật lôi kéo thái thượng trưởng lão Lâm gia tham gia một kế hoạch quan trọng, nhưng đối phương vẫn trì hoãn câu trả lời. Thiên Thu thánh nữ phát hiện phong ấn Chỉ Thủy bị ma khí Ma giới kích thích nên lỏng ra, khiến nhóm Linh tộc phải tìm khách điếm để lập tức củng cố phong ấn. Trong lúc vũ y thiếu nữ tìm thấy một khối khoáng thạch xanh biếc khiến nàng hứng thú, Hàn Lập đi tới khu quầy hàng đông đúc của Ma tộc và vui vẻ quan sát cảnh giao dịch quen thuộc."},{"chuong":2027,"tieuDe":"Dị Ma Kim","tomTat":"Hàn Lập dạo qua khu hàng rong tại Huyết Nha thành, dùng thần niệm kiểm tra hàng trăm quầy nhưng phần lớn vật phẩm không còn hữu dụng với cấp bậc của hắn. Một cuộc tranh chấp nổ ra khi Hải Phi đột ngột tăng giá khối Dị Ma Kim dù Ngưu Lực đã đặt cọc và mang đủ số ma thạch theo thỏa thuận cũ. Sau khi kiểm tra khối khoáng thạch hai màu đen trắng, Hàn Lập nhận ra nó có giá trị đặc biệt và âm thầm chú ý. Hải Phi nổi giận vì Lam Đồn tộc bị xúc phạm, phóng hàn mang tấn công Ngưu Lực nhưng đòn đánh bị Hàn Lập bắt gọn. Hàn Lập tiếp tục dùng linh áp Luyện Hư ép Ngưu Lực rút lui, qua đó chấm dứt cuộc xung đột. Hải Phi sợ hãi nên định bán Dị Ma Kim với giá thấp, song Hàn Lập không muốn ỷ mạnh ép người và lấy một thanh phi kiếm cấp ma khí cao cấp ra trao đổi. Đổi lại, hắn yêu cầu Hải Phi phải tiết lộ nơi tìm được khối Dị Ma Kim."},{"chuong":2028,"tieuDe":"Quang Cầu Và Lục Khí","tomTat":"Hàn Lập dùng một thanh phi kiếm ma khí thu được từ Ma tôn tại Linh giới để đổi lấy Dị Ma Kim của một người bán hàng Ma tộc. Sau đó, hắn tìm được hai loại linh dược còn thiếu cho phương thuốc luyện đan giúp tu sĩ Hợp Thể kỳ ngưng tâm định thần và nâng cao hiệu quả lĩnh ngộ thần thông. Trong căn phòng kín tại nhà trọ, Hàn Lập bổ đôi Dị Ma Kim, lấy ra một tinh châu xám nhưng lập tức phải đối phó với cột sáng cuồng bạo do nó phóng ra. Hắn vận dụng Phạm Thánh Chân Ma Công trấn áp cột sáng thành quang cầu, dùng phù văn vàng phong cấm rồi phối hợp Đại Diễn Quyết và Luyện Thần Thuật để dò xét. Kết quả cho thấy năng lượng trong quang cầu là trạng thái dung hợp hoàn toàn giữa linh khí và ma khí, đặc biệt phù hợp với Phạm Thánh Chân Ma Công. Hàn Lập thử hấp thu một phần nhỏ và nhận thấy chân nguyên tăng lên, nhưng quá trình chuyển hóa lại sinh ra một đám lục khí cực mỏng chưa rõ bản chất."},{"chuong":2029,"tieuDe":"Hội Đấu Giá Của Ma Tộc","tomTat":"Hàn Lập thử dùng ngân sắc hỏa diễm, chân nguyên, cấm chế, nhiều loại thần thông và Tử Ngôn Đỉnh để xử lý lục khí quỷ dị, nhưng dị vật vẫn xuyên qua phòng hộ và tự quay về đan điền của hắn. Nhận thấy lục khí có thể đã khóa vào thần hồn ấn ký, hắn đưa đệ nhị ma anh vào kim thân, chuyển dị vật sang đan điền ma anh rồi dùng ma khí tạo tinh cầu màu đen để tạm phong ấn. Hàn Lập cũng xác định phần quang đoàn màu xám trắng đã hấp thu mang lại lượng chân nguyên tương đương bảy, tám năm khổ tu, còn toàn bộ có thể giúp tiết kiệm hơn trăm năm tu luyện. Hắn thu phần năng lượng còn lại vào bình, giữ tinh châu rỗng và hai nửa Dị Ma Kim để tiếp tục điều tra, đồng thời dự định tìm thêm tinh châu nhằm tiến gần Hợp Thể hậu kỳ đại viên mãn. Sau gần hai ngày tìm kiếm trong các cửa hàng của Huyết Nha Thành, hắn mua thêm được Dị Ma Kim nhưng không phát hiện viên tinh châu thứ hai. Biết hội đấu giá lần này có quy mô đặc biệt lớn do thú triều và có thể xuất hiện nhiều trọng bảo, Hàn Lập cải trang rồi tiến vào cung điện đấu giá. Khi khoảng ba, bốn nghìn Ma tộc cao giai đã tụ tập đầy phòng, một bóng người bước ra từ cửa nhỏ và tiến về thạch đài trung tâm, khiến toàn trường lập tức im lặng."},{"chuong":2030,"tieuDe":"Ám Huyết Ngũ Sắc Linh","tomTat":"Trưởng lão Việt Liên Thiên xuất hiện chủ trì hội đấu giá tại Huyết Nha Thành, dùng khí tức Luyện Hư hậu kỳ đại thành ổn định hội trường và bố trí tám vệ sĩ Luyện Hư làm nhiệm vụ chấp pháp. Hàn Lập âm thầm vận dụng Linh mục dò tìm Lũng gia lão tổ cùng những người đồng hành đã tách khỏi mình nhưng không phát hiện được ai. Vật mở màn là Ám Huyết Ngũ Sắc linh, bộ năm chuông có các hiệu quả mê hồn, kịch độc, làm chậm, sôi máu và ảo ảnh, cuối cùng được một Ma tộc đeo mặt nạ quỷ bạc mua với giá một ngàn năm trăm vạn ma thạch. Hàn Lập nhận thấy bộ chuông tương tự Lưu Li Ngũ Diệu linh ghi trong Kim Khuyết ngọc thư và nghi nó có thể là phỏng chế phẩm, song không tranh mua vì thiếu ma thạch và không thật sự cần đến. Phiên đấu giá tiếp tục với tinh hạch Băng Bào thú, nhiều khoáng thạch, linh thảo, đan dược và ma khí, trong đó những vật Hàn Lập gửi bán đều đạt giá khá cao. Sau cùng, Việt Liên Thiên đưa ra một vật phẩm áp trục là Thánh Chuyên chứa nhiều công pháp của Khấp Linh thánh tổ, đồng thời bảo đảm hội đấu giá sẽ bồi thường gấp mười lần nếu di sản này là giả."},{"chuong":2031,"tieuDe":"Thánh Chuyên Và Huyết Nha Thành Chủ","tomTat":"Việt Liên Thiên xác nhận Thánh chuyên lưu hai bộ công pháp không hoàn chỉnh của Khấp Linh thánh tổ, nhưng từ chối tiết lộ danh xưng theo điều kiện của người gửi bán. Nhiều Ma tộc cao giai liên tục nâng giá, trong khi Hàn Lập chỉ quan sát vì các công pháp vừa thuộc Ma tộc vừa thiếu khẩu quyết mấu chốt. Bỉnh Thiên Nhận bất ngờ tiến vào phòng đấu giá, dùng uy thế Ma tôn trung giai áp chế mọi người và đẩy giá lên chín mươi lăm vạn ma thạch. Một người không rõ danh tính trả chín mươi chín vạn, khiến vị thành chủ đột ngột bỏ cuộc rồi rời hội trường. Người mua được xác định là Dương lão Nhị, một luyện khí sư Luyện Hư sơ kỳ vốn nổi tiếng nhún nhường tại Huyết Nha Thành; hắn thanh toán, thu Thánh chuyên nhưng vẫn bình thản trở lại chỗ ngồi với sắc mặt đờ đẫn. Hàn Lập dò hỏi lai lịch người này và nhận thấy sự việc có điểm khác thường. Sau đó, một nữ Ma tộc dùng vật hình tròn màu xanh phóng bạch quang, đưa kiện đồ vật áp trục dài rộng tới chục trượng lên bãi đá."},{"chuong":2032,"tieuDe":"Chân Linh Di Cốt","tomTat":"Việt Liên Thiên đưa ra một đoạn cự cốt xanh biếc và xác nhận đó là di cốt của thượng cổ chân linh trôi vào Ma giới từ khe nứt không gian. Chân nguyên cùng linh tủy trong xương đã tiêu tán, nhưng độ cứng còn lại vẫn đủ để luyện thành bảo vật có uy lực không dưới linh bảo bình thường. Hàn Lập nhận ra dược hương cực nhạt trong linh cốt, còn Khúc Nhi khẩn cầu hắn mua bằng được vì vật này có tác dụng lớn với nàng. Sau khi trực tiếp kiểm tra, Hàn Lập tạm dừng đấu giá để tới hậu điện đổi tài sản lấy ma thạch. Trở lại phòng đấu giá, hắn liên tục nâng giá và phớt lờ lời gây sức ép của mỹ phụ thuộc Hải gia ở Khô Tịch thành. Hàn Lập cuối cùng trả một trăm triệu ma thạch, khiến đối phương bỏ cuộc, rồi thanh toán và thu linh cốt vào vòng tay trữ vật. Sau khi rời đấu giá hội, Khúc Nhi tiết lộ linh cốt có thể đem lại hy vọng rất lớn để tiên linh khu của nàng đạt thần thông Đại Thừa trong tương lai."},{"chuong":2033,"tieuDe":"Thông Huyền Dược Linh","tomTat":"Hàn Lập xác định linh cốt vừa mua là Dược Linh Chi Cốt do một Thông Huyền Dược Linh để lại, có thể thay thế hơn mười loại tiên dược khi luyện đan. Khúc Nhi cho biết chi tiên linh khu sau khi dung hợp vật này có thể dịch kinh tẩy tủy, tăng mạnh pháp lực, kế thừa một phần thần thông và bổn nguyên của chủ nhân cũ, thậm chí có hy vọng tiến lên Đại Thừa kỳ. Dù quá trình luyện hóa kéo dài hơn trăm năm và khiến Khúc Nhi tạm thời không thể trợ chiến, Hàn Lập vẫn giao linh cốt cho nàng vì coi đây là cơ hội tạo ra một trợ thủ Đại Thừa. Sau đó, hắn tới cửa hàng tài liệu tìm thêm Dị Ma Kim với hy vọng thu được những tinh châu thần bí có thể rút ngắn thời gian khổ tu. Trên đường đi, Hàn Lập bị một Ma tộc mỹ phụ cùng hai thuộc hạ Luyện Hư trung kỳ chặn lại để đòi đổi lấy linh cốt. Hắn dứt khoát từ chối rồi dùng hộ thể linh quang và khí tức phản chấn hai người trọng thương mà không cần dừng bước. Nhóm Ma tộc nghi hắn là Ma tôn cải trang và liên hệ sự xuất hiện của hắn với Nam gia tam huynh đệ cùng nhiều cao thủ bí ẩn khác, qua đó nhận ra Huyết Nha Thành có thể sắp xảy ra đại sự."},{"chuong":2034,"tieuDe":"Bán Dạ Ma Ảnh","tomTat":"Ma tộc phụ nhân của Hải gia xác định linh chi cốt trong tay Hàn Lập là tài liệu cần thiết để luyện chế chí bảo, vì vậy sai người tìm Nam gia Tam huynh đệ và chuẩn bị cầu viện Huyết Nha Thành chủ. Trong lúc đó, Hàn Lập kiểm tra nhiều khối Dị Ma Kim tại các cửa hàng nhưng vẫn không tìm được Tinh Châu. Đêm xuống, hắn phát hiện một người trong lục quang bí mật rời thành và một người trong hôi quang bám sát phía sau nên quyết định âm thầm theo dõi. Ma khí cảm ứng của đội tuần tra phá được trạng thái ẩn hình của người trong lục quang, dẫn đến một cuộc vây công ngắn gần tường thành. Người trong hôi quang sau đó dùng thần thông huyết sắc đánh bật ngân ti cảm ứng, khiến thống lĩnh ma vệ kiêng kỵ và từ bỏ truy bắt. Cả hai người vượt qua cấm chế rời thành, còn Hàn Lập cũng ẩn thân xuyên qua tường thành mà không bị phát hiện để tiếp tục bám theo."},{"chuong":2035,"tieuDe":"Khấp Linh Bí Tàng","tomTat":"Hàn Lập ẩn mình bám theo Huyết Nha Thành chủ và Dương lão nhị rời khỏi Huyết Nha Thành, vượt hơn vạn dặm tới một vùng loạn thạch đen tuyền. Thành chủ dùng dù đen ép Dương lão nhị hiện hình rồi ra tay tập sát, nhưng đối phương bộc lộ tu vi Hợp Thể trung kỳ và đỡ được đòn công kích. Dương lão nhị vạch trần chuyện thành chủ từng lấy trộm ba trong bốn khối Thánh Chuyên tại nơi Khấp Linh thánh tổ tọa hóa, khiến Lôi Hải Thất Sát và Thiên Phòng Sơn giao chiến với nhau. Hắn tiết lộ bốn khối Thánh Chuyên hợp nhất có liên quan tới toàn bộ thần thông của Khấp Linh thánh tổ và bí đồ dẫn tới bảo tàng của vị này. Dương lão nhị đề nghị hai bên hợp tác chia đều Khấp Linh bí tàng, đồng thời nhắc tới Mặc linh thánh thuyền như một phi hành chí bảo đặc biệt quý giá. Khi Huyết Nha Thành chủ dùng thần niệm kiểm tra khối Thánh Chuyên thứ tư, vật này bất ngờ vỡ thành bạch quang và tạo vòng sáng bạc hút thần niệm. Ngay sau đó, kim quang quấn về cổ thành chủ còn một quỷ thủ tái nhợt chộp xuống Dương lão nhị, khiến cả hai đồng thời rơi vào đòn đánh lén trí mạng chưa rõ nguồn gốc."},{"chuong":2036,"tieuDe":"Thất Sát Huyết Sát Cùng Hắc Cốt Ma Trùng","tomTat":"Kim quang chém vào cổ Huyết Nha Thành chủ nhưng bị ngọc bài đỏ tự động hộ chủ cản lại, giúp ông tránh một đòn chí mạng. Thân ngoại hóa thân có dung mạo giống hệt ông sau đó hiện ra tập kích Dương lão nhị, còn người điều khiển kim quang cũng lộ diện là Kim Hồ Ma Tôn. Huyết Nha Thành chủ tung Thất Sát huyết sát và Hắc Cốt ma trùng đã tế luyện nhiều năm, buộc Dương lão nhị cùng Kim Hồ Ma Tôn bỏ chạy nhưng vẫn bị huyết sát và trùng vân chặn kín. Dương lão nhị đề nghị giao khối Thánh Chuyên cuối cùng để đổi lấy đường sống, đồng thời yêu cầu đối phương phát tâm ma chi thệ và ký huyết khế. Khi ông lấy khối Thánh Chuyên thứ tư khỏi hộp gỗ để kiểm chứng, hư không bất ngờ nứt ra và một bàn tay màu vàng chụp lấy bảo vật. Dương lão nhị lập tức thúc quỷ đầu tấn công, còn Kim Hồ Ma Tôn dùng kiếm quang chém vào nơi kẻ đoạt bảo đang ẩn thân."},{"chuong":2037,"tieuDe":"Đoạt Vật","tomTat":"Bàn tay vàng khổng lồ áp chế bảo vật của Dương Lão Nhị và Kim Hồ Ma Tôn, giúp Hàn Lập đoạt lấy một khối Thánh Chuyên rồi hiện thân yêu cầu Huyết Nha Thành chủ giao nốt ba khối còn lại. Huyết Nha Thành chủ từ chối và phát động Thất Sát Huyết Sát, nhưng toàn bộ huyết quang bị lốc xoáy vàng từ Pháp Tướng ba đầu sáu tay hấp thu sạch. Hóa thân áo đen của lão đánh lén từ trên cao cũng bị Hàn Lập phát hiện và dùng lôi trận Ích Tà Thần Lôi đánh thành tro bụi. Sau đó, đàn Hắc Cốt Ma Trùng được tung ra nhưng nhanh chóng bị hơn một nghìn Phệ Kim Trùng thành thục cắn nuốt đến mức chỉ còn vài trăm con. Huyết Nha Thành chủ chịu tổn thương thần niệm vì hóa thân bị diệt và vội bỏ chạy. Một tiếng hừ của Hàn Lập đánh sâu vào linh hồn khiến lão rơi khỏi không trung, rồi trùng vân vàng lập tức kéo đến bao vây."},{"chuong":2038,"tieuDe":"Tây Môn Phong","tomTat":"Hàn Lập dùng Phệ Kim trùng thôn phệ thân thể và Nguyên Anh của Huyết Nha Thành chủ, qua đó lấy được ba khối thánh chuyên giấu bên trong và nâng tổng số mình nắm giữ lên bốn. Trong lúc ấy, Tử Ngôn đỉnh vây chặt Dương lão nhị cùng Kim Hồ Ma Tôn, buộc một người tự bạo hơn mười kiện ma khí để phá cấm còn người kia gọi hư ảnh Hỏa Kỳ Lân mở đường. Hàn Lập phái trùng vân truy đuổi Dương lão nhị và giao Báo Lân thú đuổi theo Kim Hồ Ma Tôn vì kim sắc hồ lô của đối phương có trộn linh cốt Hỏa Kỳ Lân. Báo Lân thú sau đó trở về, xác nhận đã tiêu diệt Kim Hồ Ma Tôn nhưng tỏ ra kinh hoàng trước một trùng triều đang tiến đến. Hàn Lập nhìn thấy vô số Điệp Vĩ thú mang kịch độc tràn tới trong sương xanh, song Vạn Độc Hỗn Nguyên thân khiến hắn không quá e ngại độc tính của chúng. Phía sau đàn Điệp Vĩ thú là mây tím vô biên gồm vô số trường trùng, khiến hàng vạn Điệp Vĩ thú rơi xuống như mưa và báo hiệu một mối đe dọa còn lớn hơn."},{"chuong":2039,"tieuDe":"Hấp Ma Nghĩ","tomTat":"Hàn Lập nhận ra đàn ma trùng màu tím là Hấp Ma Nghĩ hải, một trong những đại thiên tai của Ma giới, nên lập tức đưa nữ đồng rút về Huyết Nha Thành. Trùng triều không đuổi theo mà cắn nuốt sạch lục vụ rồi rút đi, trong khi Hàn Lập nhớ lại Nghĩ hải có thể hút linh lực, ma khí và từng vây chết cả tồn tại cấp Thánh Tổ. Khi trở lại thành, hắn phát hiện hàng triệu ma thú đang tụ tập bên ngoài, còn cả ma thú lẫn Ma tộc đều bất an trước tai họa đang đến gần. Lũng gia lão tổ triệu tập Hàn Lập cùng Vũ y thiếu nữ, Phi phát nam tử Lâm gia và Huy trưởng lão, thông báo Hấp Ma Nghĩ đã xuất hiện ở cả bốn phía trong phạm vi mấy vạn dặm. Nhóm quyết định phân tán phá vây, tự vượt vùng man hoang rồi gặp lại tại khách sạn lớn nhất ở Huyễn Dạ Thành vào cùng ngày hai năm sau. Hàn Lập đồng thời biết Thiên Thu thánh nữ và các đồng đạo Linh tộc đã rời thành từ hai ngày trước vì một việc quan trọng, nhưng vẫn để lại lời hẹn tại Huyễn Dạ Thành. Khi cuộc thương nghị còn diễn ra, các đội Ma tộc trung và cao giai bắt đầu rời thành, kéo theo vô số Ma tộc cấp thấp hoảng loạn tháo chạy về mọi hướng."},{"chuong":2040,"tieuDe":"Thôn Phệ Chi Uy","tomTat":"Nhóm Hàn Lập trà trộn vào đoàn trung giai Ma tộc rời Huyết Nha Thành, định mượn đại quân đông đảo làm bình phong phá vây. Một cụm Hấp Ma Nghĩ nhỏ nhanh chóng bị tiêu diệt, nhưng đó chỉ là mồi nhử để đại quân Ma Nghĩ ẩn trên cao bất ngờ phủ xuống, khiến đội ngũ Ma tộc tan rã. Lũng gia lão tổ yêu cầu mọi người ngừng che giấu tu vi và chia nhau thoát đi bằng pháp bảo hoặc độn thuật riêng. Sau khi phá khỏi vòng vây đầu tiên, Hàn Lập lại gặp một Nghĩ Hải khác cách thành ba bốn vạn dặm và dùng lôi trận dịch chuyển vào bên trong. Kiếm khí hoa sen, Phệ Linh Thiên Hỏa, hào quang tối mờ và ngũ sắc hàn diễm đều có thể tiêu diệt nhiều Hấp Ma Nghĩ, nhưng linh lực của các công kích vẫn bị chúng thôn phệ. Nhận ra việc tiếp tục thử nghiệm chỉ gây hao tổn, Hàn Lập toàn lực thúc giục bảy mươi hai Thanh Trúc Phong Vân Kiếm, hóa thành kiếm quang xuyên qua Nghĩ Hải mà tốc độ không suy giảm."},{"chuong":2041,"tieuDe":"Ma Giới Hoang Địa","tomTat":"Nhận thấy pháp lực tiêu hao quá nhanh trong Nghĩ Hải, Hàn Lập thu nhỏ kiếm quang hộ thân rồi tiếp tục mở đường giữa đàn Hấp Ma Nghĩ. Các Ma tộc cấp thấp lần lượt cạn pháp lực và bị nuốt chửng, trong khi ba người Hải gia cùng ba anh em nhà Nam Cung hợp lực tiến gần rìa biển kiến. Hàng trăm Cự Nghĩ biến dị dùng dịch tím phá hắc khí Giao Long và màn sáng từ cốt thuẫn, khiến nữ phụ nhân Hải gia cùng hai thuộc hạ bỏ chạy, để ba anh em Nam Cung mắc kẹt. Cao giai Ma Nghĩ khiến phần lớn những kẻ còn chống cự thiệt mạng, nhưng Hàn Lập, một số Ma Tôn và ma thú mạnh vẫn phá được vòng vây. Trùng triều kéo dài nửa năm, hủy diệt bảy tám thành trì và cắn nuốt hàng triệu Ma tộc. Một năm sau, Hàn Lập đã cắt đuôi đàn kiến trong man hoang chi địa, chém giết đàn quái điểu truy đuổi và thu được một khối Phong Viêm Tinh lớn. Hắn không tìm nhóm Lũng gia lão tổ mà tiếp tục tiến về Huyễn Khiếu sa mạc, đồng thời thu hoạch hơn mười loại tài liệu và linh dược hiếm trên đường."},{"chuong":2042,"tieuDe":"Trùng Tu Linh Quyết","tomTat":"Sau khi lấy được một khối Phong Viêm tinh lớn và thoát khỏi đàn ma cầm trong hạp cốc, Hàn Lập tiến vào nội hải. Hắn dùng tơ xám tiêu diệt hàng vạn quái ngư màu lam tập kích, rồi tìm một tiểu đảo để nghỉ khi những hải thú mạnh bắt đầu hoạt động lúc trời tối. Trong thạch động, Hàn Lập kích phát bốn khối thánh chuyên và nghiên cứu ma công, bí thuật do Khấp Linh thánh tổ để lại, nhưng quyết định không từ bỏ Phạn Thánh Chân Ma công. Bốn khối thánh chuyên còn ghép thành bản đồ Khấp Linh bí tàng có ký hiệu hắc long một sừng, song hắn chưa thể xác định vị trí vì thiếu bản đồ đối chiếu chi tiết. Sau đó, Hàn Lập dựng Chân Ma pháp tướng và một pháp trận ngũ sắc để bài xích ma khí, tạo môi trường linh khí tinh thuần. Hắn bắt đầu trùng tu linh quyết, khiến phù văn bạc và lớp vảy ngọc trên thân biến đổi rồi ngưng tụ thành những sợi tơ bạc bắn ngược về phía mình."},{"chuong":2043,"tieuDe":"Huyễn Dạ Bạch Gia","tomTat":"Hàn Lập vận chuyển Bách Mạch Luyện Bảo Quyết, chịu đau đớn dữ dội để rèn thân thể và khiến Kim Triện Văn hình thành trên xương cốt, nhưng hắn chỉ có thể tu luyện trong thời gian ngắn để tránh kinh mạch vỡ vụn. Sau đó, hắn tiếp tục tìm hiểu tầng thứ hai Luyện Thần Thuật, một tầng có thể khiến thần niệm tăng lên nhiều lần và gia tăng hy vọng tiến giai Đại Thừa. Sáng hôm sau, Hàn Lập rời đảo, bay qua vùng biển rồi mất hơn mười ngày vượt một sơn mạc ẩm ướt phủ đầy sương mù, dùng Phệ Linh Thiên Hỏa thiêu rụi những ma thú tập kích. Gần rìa sơn mạc, hắn phát hiện đoàn người Bạch gia đang bị hơn ba mươi con dơi đỏ thẫm vây khốn trên một Tử Quang Thụ khổng lồ. Ba Ma tộc Luyện Hư cố duy trì trận pháp chống biển quái diễm xanh, trong khi hơn mười đồng bạn Hóa Thần đã gần cạn pháp lực. Hàn Lập cũng nhận ra Tử Linh quả quý hiếm trên ngọn cây nhưng không có ý tranh đoạt vì loại quả này không còn hữu dụng với hắn. Khi mỹ phụ váy xanh công khai thân phận Bạch gia, cầu cứu và hứa gia tộc sẽ hậu tạ, Hàn Lập đồng ý tương trợ. Hắn lập tức biến thân, mọc lân phiến đen và Hắc Ma trảo rồi lao thẳng vào đàn dơi đỏ thẫm."},{"chuong":2044,"tieuDe":"Bạch Vân Hinh","tomTat":"Hàn Lập xông vào đàn Huyết Tuyến dơi ma, dùng thân pháp quỷ dị, ma trảo và hắc sắc ma giáp để giết hàng loạt ma vật, giải nguy cho nhóm Ma tộc đang bị vây. Dơi đầu đàn có sừng tím dùng lục diễm và lôi điện chống trả nhưng bị hắn chém đứt một cánh, buộc phải thi triển Huyết Ảnh độn chạy trốn. Nhóm Ma tộc nhân cơ hội phá khỏi biển lửa, giết thêm nhiều dơi ma và khiến số còn lại tán loạn. Người dẫn đầu tự giới thiệu là Bạch Vân Hinh, đệ tử chân truyền Bạch gia, đồng thời giới thiệu hai tộc huynh Bạch Ẩn và Bạch Anh. Biết Bạch gia cần Tử Linh quả làm chủ dược luyện đan, Hàn Lập nhường phần linh quả của mình và nhận lại một vòng trữ vật chứa ma thạch. Nhận thấy thần thông của hắn, Bạch Vân Hinh mời hắn cùng trở về Huyễn Dạ thành để Bạch gia hậu tạ và kín đáo bày tỏ ý muốn mượn sức. Bạch Anh còn cho biết trong gia tộc có một vị lão tổ tu luyện Luyện thể thuật, có thể chỉ điểm cho Hàn Lập."},{"chuong":2045,"tieuDe":"Kim Hi Thử","tomTat":"Bạch Vân Hinh giới thiệu Phúc Thiên Cư Sĩ, một lão tổ Bạch gia đã luyện Thiên Ma công tới cực hạn, khiến Hàn Lập quyết định theo đoàn đến Huyễn Dạ Thành để bái kiến. Sau năm ngày nghỉ ngơi, đoàn dùng Bát Hoang Hoàng Mộc Chu rời hoang địa và vài tháng sau tới vùng cát vàng ở rìa ngoài. Tại đây, ba huynh đệ Bạch gia đang giao chiến với bốn đệ tử Trữ gia để tranh thi thể Kim Hi Thử, còn Dạ Yểm Sư của Trữ gia đã đẩy họ xuống thế yếu. Vì đại nạn sắp tới và nội đan con thú có thể giúp phá bình cảnh Nguyên Anh hậu kỳ, Bạch Binh chuẩn bị thi triển bí thuật gây tổn hại chân nguyên. Bát Hoang Hoàng Mộc Chu xuất hiện đúng lúc, Bạch Vân Hinh nhận ra hậu bối trong tộc và buộc bốn đệ tử Trữ gia rút lui. Đoàn tiếp tục tiến về Huyễn Dạ Thành, còn Hàn Lập theo Bạch Vân Hinh vào khoang thuyền để nghe giải thích về Huyễn Khiếu sa mạc. Sau khi họ rời đi, Bạch Binh cùng hai người em xuống mặt cát phân chia thi thể Kim Hi Thử."},{"chuong":2046,"tieuDe":"Huyễn Dạ Thành","tomTat":"Sau hơn một tháng di chuyển, cự thuyền của Bạch gia đưa Hàn Lập tới Huyễn Dạ thành, một cự thành lơ lửng trên đại cấm chế màu vàng và là địa bàn của tứ đại gia tộc. Bạch Vân Hinh tiếp tục mời hắn làm khách khanh, nhưng Hàn Lập giữ thân phận tán tu Luyện Hư hậu kỳ và lấy lý do tìm cơ hội tiến giai ma tôn để từ chối. Khi hắn hỏi mua Bát Túc ma tích nhằm vượt Huyễn Khiếu sa mạc, nàng tiết lộ loài ma thú này bị các đại gia tộc kiểm soát và chỉ lão tổ Bạch gia có thể quyết định việc giao cho người ngoài. Sau khi vào thành, Hàn Lập phát hiện nơi đây có cả cấm không lẫn cấm chế hạn chế thần niệm nên không cưỡng ép dò xét để tránh bại lộ tu vi thật. Bạch Vân Hinh trở về gia tộc nhưng trước đó trao ngọc bài tùy thân, giúp hắn có thể trực tiếp tới Bạch gia tìm nàng. Hàn Lập một mình tham quan thành, quan sát đông đảo ma tộc cao giai, nhiều loại cửa hàng và các ma quán truyền thụ ma công cơ bản. Cuối cùng, một bảng hiệu trên cự tháp khiến hắn lập tức lộ vẻ kinh ngạc."},{"chuong":2047,"tieuDe":"Vạn Nô Tháp","tomTat":"Tại Huyễn Dạ thành, Hàn Lập tò mò bước vào Vạn Nô Tháp và được chưởng quầy Ma tộc tu vi Hóa Thần đích thân tiếp đón. Hắn đi cùng ba khách nhân Nguyên Anh có dấu hiệu của Trữ gia qua Truyền Tống trận tới tầng giam giữ nô lệ. Trước cửa vàng, Hàn Lập phát hiện hai vệ sĩ thực chất là ma tinh khôi lỗi độc môn, vận hành bằng pháp khí và pháp quyết thay vì nguyên thần ký phụ. Bên trong khu giam giữ, chưởng quầy giới thiệu khoảng tám thiếu nam thiếu nữ Thổ Âm tộc đã đạt Trúc Cơ và có thiên phú với ma công thổ thuộc tính. Sau khi chất vấn tư chất và mặc cả, thiếu nữ Trữ gia giao ma thạch mua cả nhóm nô lệ. Hàn Lập từ chối mua nô lệ vì quen độc hành, nhưng yêu cầu chưởng quầy dẫn mình tới nơi bán ma tinh khôi lỗi."},{"chuong":2048,"tieuDe":"Nữ Nô","tomTat":"Phương chưởng quỹ dẫn Hàn Lập tới truyền tống pháp trận để sang tầng khác xem ma tinh khôi lỗi, nhưng họ gặp Hoàng chưởng quỹ cùng bốn vệ sĩ đang áp giải một thiếu nữ hoàng sam bị phong cấm tu vi. Nhận thấy nàng không có ma khí và mang điều khác thường, Hàn Lập kiên quyết đòi mua dù biết Triệu Văn Hảo, người đứng đầu thế hệ hiện tại của Triệu gia, đã nhìn trúng nàng. Hắn vượt qua nhóm vệ sĩ, đưa thiếu nữ về bên mình rồi truyền pháp lực kiểm tra và xác nhận phán đoán chưa được nói rõ. Khi Hoàng chưởng quỹ viện dẫn cường giả tọa trấn để ngăn cản, Hàn Lập phóng uy áp Hợp Thể, đánh văng hai chưởng quỹ, ép bốn vệ sĩ quỵ xuống và khiến cấm chế toàn tháp rung chuyển. Hai tu sĩ Luyện Hư từ mật thất tầng cao nhất chạy tới, nhận ra hắn có cấp bậc Ma tôn và đồng ý giao thiếu nữ miễn phí. Hàn Lập vẫn trả đủ ma thạch bằng một vòng trữ vật, hé lộ rằng còn việc muốn thương lượng nhưng tạm hoãn, sau đó dùng độn quang cuốn thiếu nữ xuyên thủng cấm chế rời Vạn Nô tháp."},{"chuong":2049,"tieuDe":"Tố Nữ Công","tomTat":"Hai hộ pháp Luyện Hư của Vạn Nô tháp quyết định không chọc giận Hàn Lập, đồng thời giao Hoàng chưởng quỹ nhiệm vụ giải thích với Triệu gia và tìm một nữ nô khác thay thế Chu Quả Tâm. Trên đường rời tháp, Hàn Lập nhớ tới một thiếu nữ áo trắng, khiến tâm cảnh đã được tôi luyện suốt ngàn năm của hắn nổi sóng và khơi dậy nỗi tương tư sâu nặng. Hắn đưa Chu Quả Tâm tới Thánh Linh viện, thuê một lầu các có cấm chế trong thời hạn một năm rồi bố trí thêm trận kỳ cách ly tầng cao nhất. Hàn Lập phá tan ma văn phong tỏa trên người Chu Quả Tâm, giúp linh lực của nàng khôi phục lưu chuyển. Chu Quả Tâm khai mình là nhân tộc thuần túy và đã một mình lưu lạc vào Ma giới. Hàn Lập nhận ra nàng tu luyện Tố Nữ Luân Hồi công do mẹ truyền lại, nhưng nàng biến sắc và do dự khi bị hỏi về danh tính mẹ cùng nguồn gốc công pháp."},{"chuong":2050,"tieuDe":"Tiểu Linh Thiên","tomTat":"Hàn Lập nhận ra Chu Quả Nhi từng đạt Nguyên Anh kỳ và hiện chỉ biểu hiện tu vi Kết Đan vì đang ở Luân Hồi kỳ của Tố Nữ Luân Hồi công. Khi nàng định tự bạo để bảo vệ bí mật của mẫu thân, hắn phong bế thân thể cùng pháp lực, khống chế thần trí rồi tìm hiểu nguồn gốc công pháp. Chu Quả Nhi tiết lộ Lăng Phi Tiên là người truyền dạy, nhưng những dấu hiệu bất thường cho thấy phía sau bà có thể còn một người thực sự tinh thông Tố Nữ Luân Hồi công. Hàn Lập tiếp tục điều tra nguyên thần và biết Chu Quả Nhi vốn bị truy sát tại Tiểu Linh Thiên, sau đó rơi qua vết nứt không gian tới Ma Giới. Ký ức của nàng cho thấy Tiểu Linh Thiên là một giới diện vỡ gần như độc lập, có quy mô xấp xỉ Quảng Hàn Giới và hơn một ức Nhân tộc sinh sống. Từ khả năng những người phi thăng thất bại có thể lưu lạc vào tiểu giới này, Hàn Lập nhận ra Nam Cung Uyển rất có thể đang mắc kẹt ở đó. Dù xúc động trước hy vọng đoàn tụ, hắn vẫn quyết định kiểm chứng thêm tin tức và tìm manh mối về cửa vào Tiểu Linh Thiên."},{"chuong":2051,"tieuDe":"Phúc Thiên Cư Sĩ","tomTat":"Sau khi Chu Quả Nhi tỉnh lại, Hàn Lập thừa nhận đã dò xét ký ức và phát hiện nàng đến từ Tiểu Linh Thiên chứ không phải Linh Giới. Hắn cho biết đã đặt cấm chế trong cơ thể nàng, buộc nàng tạm thời làm tỳ nữ trong thời gian lưu lại Huyễn Dạ thành và chỉ để ngỏ khả năng trả tự do về sau. Ba ngày sau, gia chủ Triệu gia gửi thiếp bạc bày tỏ mong muốn giao hảo và mời Hàn Lập dự lễ tế tổ; Hàn Lập nhận lời. Bạch Vân Hinh tiếp đó tới theo lệnh gia tổ, kinh hãi khi Hàn Lập bộc lộ tu vi Hợp Thể kỳ và xin thứ tội vì sự thất lễ trước đây. Hàn Lập nhận lời gặp Phúc Thiên cư sĩ rồi cùng nàng lên thú xa, được mười sáu Hổ Sát vệ hộ tống tới thành trì Bạch gia. Tại đây, hắn nhận thấy Bạch gia có cơ nghiệp kiên cố, vật liệu xây dựng kỳ lạ và nhiều tầng cấm chế phòng hộ. Khi Phúc Thiên cư sĩ đích thân xuất hiện và tự giới thiệu, diện mạo hoặc trạng thái của người này khiến Hàn Lập sửng sốt, phải hỏi lại thân phận của đối phương."},{"chuong":2052,"tieuDe":"Phiền Toái","tomTat":"Hàn Lập gặp Phúc Thiên Cư Sĩ và bất ngờ khi Bạch gia lão tổ mang danh xưng này lại là một nữ tử tóc tím có sừng trắng. Hai bên âm thầm dò xét nhưng đều không thể nhìn thấu tu vi của đối phương, còn Hàn Lập giả xưng mình tu luyện Sát Lục Chi Đạo và mới tiến giai Ma Tôn vài trăm năm. Khi hắn hỏi mua Bát Túc Ma Tích để tiến vào Huyễn Khiếu Sa Mạc, Phúc Thiên Cư Sĩ giải thích loài ma thú này là phương tiện thiết yếu giúp các gia tộc khai thác và vận chuyển tài nguyên từ sâu trong khu vực cấm độn thuật. Vì vậy Bạch gia không muốn bán trực tiếp, nhưng nàng đưa ra một điều kiện trao đổi. Một mạch khoáng trọng yếu của Bạch gia đã bị ma thú Ma Tôn cấp chiếm giữ, nên Hàn Lập được mời tham gia cuộc vây đánh và sẽ nhận một đầu Bát Túc Ma Tích nếu thành công. Phúc Thiên Cư Sĩ cho biết Bạch gia đã tập hợp nàng, một Thái Thượng trưởng lão cùng hai Ma Tôn bên ngoài, còn sự góp sức của Hàn Lập sẽ khiến kế hoạch chắc chắn hơn."},{"chuong":2053,"tieuDe":"Quảng Âm Bảo Kính","tomTat":"Phúc Thiên cư sĩ kể cho Hàn Lập về ma thú chiếm mạch khoáng Hỏa Vân thạch, có pháp lực tương đương Ma Tôn hậu kỳ đại thành và lục diễm đủ sức đốt tan hư không. Bạch gia chỉ định tập hợp bốn người đánh trọng thương rồi xua đuổi nó, trong đó những người được mời sở hữu băng hàn chi lực hoặc bảo vật chí âm chí hàn để khắc chế ma diễm. Sau khi cân nhắc thù lao gồm một con Bát Túc Ma Tích, ma thạch và thời gian hành trình, Hàn Lập đồng ý tham gia chuyến đi. Trong lúc chờ xuất phát, hắn trao đổi tâm đắc luyện thể với Phúc Thiên cư sĩ và hiểu thêm một số điểm khó trong Phạm Thánh chân ma công. Khi Hàn Lập rời đi, Bạch Giao bước ra khỏi chỗ ẩn và tiết lộ rằng Quảng Âm bảo kính không thể nhìn thấu cảnh giới của hắn. Bạch Giao còn cho rằng thần niệm của Hàn Lập đã phát hiện việc thăm dò nhưng đối phương cố ý không biểu lộ. Chương kết thúc khi Bạch Giao thi pháp khiến bảo kính phát ra hào quang ngũ sắc và dần hiển thị một hình ảnh chưa rõ nội dung."},{"chuong":2054,"tieuDe":"Nhất Tiến Huyễn Khiếu","tomTat":"Bạch Giao dùng Quảng Âm bảo kính và Quảng Âm cảnh bí thuật dò xét Hàn Lập, nhận ra chân ma chi khí cùng trình độ luyện thể gần Tử Tủy Kim Cốt nhưng không thể nhìn thấu lớp thần thông sâu hơn. Sau lần dò xét, ông quyết định Bạch gia không nên đắc tội cũng không cần cố lôi kéo một người có thực lực vượt quá khả năng dung nạp của gia tộc. Hàn Lập đã sớm phát hiện đối phương, dùng yêu mục cùng tinh cầu màu trắng dò xét ngược và xác định Bạch Giao chỉ có tu vi Ma Tôn trung kỳ. Trong thời gian chờ đồng đội, hắn thường tới Bạch gia trao đổi công pháp, từ chối lời mời của hai gia tộc khác nhưng tham dự lễ tế tổ của Triệu gia. Khi những người trợ chiến của Bạch gia hội đủ, Hàn Lập dặn dò Chu Quả Nhi rồi gặp Bạch Giao, Ngũ muội, Long Thiên quân, Hàn Kỳ, Bạch Vân Hinh cùng sáu tu sĩ Luyện Hư ngoài cửa thành. Cả đội sau đó thi triển độn quang, chính thức bay về phía Huyễn Khiếu sa mạc để khu trục ma thú cấp Ma Tôn."},{"chuong":2055,"tieuDe":"Chương 2055","tomTat":"Đoàn Bạch gia bay tới rìa Huyễn Khiếu sa mạc rồi phải hạ xuống vì độn quang sẽ mất hiệu lực khi tiến sâu vào cấm địa. Tóc tím nữ tử phân phối mười một Bát Túc Ma Tích và Khu thú bài cho mọi người, đồng thời giải thích sáu tu sĩ Luyện Hư đi cùng có thể dựa vào trận pháp liên thủ để miễn cưỡng chống lại một Ma Tôn sơ kỳ. Hàn Lập từng cân nhắc cướp số thú cưỡi nhưng từ bỏ sau khi đánh giá nguy cơ từ bốn Ma Tôn, các đại gia tộc và những tồn tại cấp Thánh Tổ. Khi tiến vào sa mạc, hắn nhận ra pháp lực của mình bị áp chế hơn chín thành, còn năng lượng hỗn tạp nơi đây bài xích cả linh khí lẫn ma khí. Sau hơn mười ngày, Bạch Vân Hinh cùng nhóm Luyện Hư tiêu diệt một đàn bò cạp xanh đang bao vây đoàn người. Nửa tháng sau, một con Sa Kim mãng phục kích nhưng bị Đại hán dùng viên hoàn đen siết đứt đầu rồi thiêu sạch thi thể và tàn hồn bằng ma diễm đỏ sẫm. Đại hán sau đó tiết lộ tam đại ma hại của Huyễn Khiếu sa mạc nguy hiểm đến mức ngay cả ông cũng chỉ có thể chạy trốn nếu chạm trán."},{"chuong":2056,"tieuDe":"Huyết Nha Mễ","tomTat":"Trên đường xuyên Huyễn Khiếu sa mạc, Bạch Giao giải thích cho Hàn Lập về Tam Thiên Ma Hại gồm Lạc Hồn Phong, Yên Sa và Huyễn Khiếu Ma Lang. Sau hơn nửa tháng, đoàn khu trục tới ốc đảo Ngân Xuyên, nơi Bạch gia đặt một cứ điểm gần mạch khoáng. Bạch Vân Hinh dẫn sáu đệ tử vào kiểm tra và phát hiện cấm chế cùng pháp trận vẫn nguyên vẹn, không có dấu vết giao chiến, nhưng toàn bộ người trấn giữ đã biến mất. Hàn Lập âm thầm dùng Minh Thanh Linh Mục nhìn xuyên màn hắc vụ để theo dõi tình hình bên trong. Sau đó, Bạch gia giao Huyết Nha Mễ ngàn năm cho Loan Long Thiên Quân để hỗ trợ ma công Huyết hệ và tạm thời gia tăng pháp lực trước cuộc khu trục. Hàn Lập nhận ra linh vật này có thể tăng tinh huyết, cải thiện thân thể và chính là một trong những kỳ vật hắn muốn tìm trong chuyến đi Ma giới."},{"chuong":2057,"tieuDe":"Ti Hồn Bội","tomTat":"Hàn Lập nhận ra Huyết Nha Mễ là linh vật cực hiếm sinh trưởng tại Lam Bộc Hồ, nhưng Bạch gia từ chối giúp hắn và Hàn Kỳ Tử thu mua thêm. Loan Long Thiên Quân ăn một viên thượng phẩm, khiến khí tức tăng vọt và thân thể xuất hiện phản ứng mạnh, làm Hàn Lập càng chú ý đến công hiệu của loại linh vật này. Trong khi đó, hai huynh muội Bạch gia bí mật bàn về những đệ tử trung giai mất tích tại cứ điểm nhưng chưa tìm được đầu mối. Sau một ngày một đêm nghỉ ngơi, đoàn người cưỡi Bát Túc Ma Tích tiến về phía tây, rồi thu tọa kỵ và liễm tức để tránh kinh động ma thú cấp Ma Tôn. Bạch huynh mở cửa dự bị bị chôn dưới một cồn cát khổng lồ và dẫn mọi người qua thông đạo bí mật chưa bố trí cấm chế. Hắn dùng Quảng Âm bảo kính thăm dò rồi mở vách núi đỏ thẫm, để lộ khu vực nham thạch nóng nằm sâu trong mạch khoáng. Cuối cùng, nữ tử tóc tím lấy Tư Hồn Bội chứa máu huyết của ma thú, chuẩn bị dùng nó xác định vị trí mục tiêu."},{"chuong":2058,"tieuDe":"Hài Cốt Cùng Hồ Dung Nham","tomTat":"Ngũ muội dùng Tư Hồn Bội cùng tơ máu dẫn đoàn người xuyên qua mạng lưới đường hầm của khoáng mạch Hỏa Vân Thạch, nơi họ phát hiện thi thể không đầu và khô kiệt của Bạch Nham. Đi sâu hơn, cả đoàn tiếp tục gặp năm sáu thi thể đệ tử Bạch gia lưu thủ, cho thấy cứ điểm đã gặp tai họa nghiêm trọng nhưng hung thủ vẫn chưa được xác định. Khi dấu vết ma thú chỉ còn cách vài dặm, đại hán tóc vàng yêu cầu mọi người thi triển thủ đoạn ẩn nấp rồi tiếp tục tiến sâu qua các khe nứt tự nhiên. Đoàn người cuối cùng tới một hồ dung nham rộng khoảng ngàn mẫu, quanh đó tập trung hàng vạn khối cực phẩm Hỏa Vân Thạch có giá trị khổng lồ. Ngũ muội xác nhận tinh huyết của mục tiêu chỉ đúng nơi này, còn đại hán tóc vàng suy đoán ma thú đang ẩn dưới dung nham. Bạch Vân Hinh cùng năm đệ tử lập tức bố trí đại trận phục kích quanh hồ. Loan Long Thiên Quân và Hàn Kỳ Tử dùng ma khí hàn thuộc tính hộ thân, trong khi Hàn Lập biến Ngũ Sắc Cực Diễm thành liên hoa rồi hạ xuống gần mặt hồ để chuẩn bị giao chiến."},{"chuong":2059,"tieuDe":"Ma Thú","tomTat":"Hàn Lập cùng các Ma tôn dò xét hồ dung nham và phát hiện một bóng đen khổng lồ ẩn sâu bên dưới, trong khi sáu đệ tử Bạch gia hoàn tất pháp trận phong tỏa xung quanh. Theo yêu cầu của lão tổ Bạch gia, Loan Long Thiên Quân dùng viên bát xanh lam khuấy động dung nham để ép ma thú xuất hiện. Ma thú Ma tôn hậu kỳ phản kích bằng hỏa lãng và thú trảo lục diễm, đánh Loan Long Thiên Quân văng vào thạch bích nhưng chiến giáp đen giúp ông chỉ bị thương nhẹ. Khi ma thú rời khỏi dung nham, Hàn Lập dùng Nguyên Từ Thần Quang tấn công nhưng thần thông vốn khắc chế ngũ hành lại bị ma diễm xanh lục hóa giải. Hàn Kỳ Tử cùng hai lão tổ Bạch gia lần lượt dùng hàn quang, lôi võng và hư ảnh hắc hổ, song ma thú vẫn một mình chống lại nhiều Ma tôn mà không rơi xuống hạ phong. Cuối chương, Loan Long Thiên Quân triệu Huyết Sắc Tiểu Cổ từ trong bụng, tạo ra hàn phong và vô số bông tuyết đỏ tươi phủ xuống chiến trường."},{"chuong":2060,"tieuDe":"Khoáng Mạch Kịch Chiến Thượng","tomTat":"Hàn Lập, Hàn Kỳ Tử và Bạch Vân Hinh toàn lực công kích ma thú hồ dung nham, trong khi sáu đệ tử Bạch gia vận hành trận pháp phong nhận để khóa đường trốn. Ma thú lộ bản thể đầu hươu mình trâu chân sư tử rồi dùng Thạch chuyên xanh lục dựng tường đá có khả năng tự phục hồi bằng lục diễm. Bạch Vân Hinh, đại hán tóc vàng, Hàn Kỳ Tử và Loan Long Thiên Quân liên tiếp thi triển thủ đoạn, khiến tường đá bị phá và buộc ma thú co nó thành thạch cầu bảo vệ thân thể. Khi thạch cầu sắp vỡ, ma thú hút dung nham tạo thành cự nhân khổng lồ, phát biển lửa xích diễm trói buộc các Ma Tôn và làm suy yếu công kích của họ. Hàn Lập cho kiếm quang tự bạo để mở khoảng trống, sau đó dùng Ngũ Sắc Cực Diễm bao phủ thân thể và thoát khỏi biển lửa. Đúng lúc ấy, một tiếng thét vô cùng thảm thiết vang lên từ trong hồ dung nham rồi đột ngột tắt ngấm."},{"chuong":2061,"tieuDe":"Khoáng Mạch Kịch Chiến Trung","tomTat":"Quái vật bạch quang liên tiếp sát hại các đệ tử Bạch gia trong hắc khí, sau đó chém đầu Bạch Vân Hinh cùng những người chạy thoát và hút sạch huyết nhục của họ. Dấu vết trên các thi thể giúp Hàn Lập xác định nó cũng là hung thủ gây ra vụ thảm sát những người trông coi cứ điểm trước đó. Đại hán tóc vàng chia lực lượng thành hai nhóm, giao Hàn Lập và nữ tử tóc tím đối phó quái vật, còn mình cùng Loan Long Thiên Quân và Hàn Kỳ Tử vây công ma thú đầu hươu. Nữ tử tóc tím phỏng đoán quái vật là ma linh do linh khí mạch khoáng hóa thành, có thân thể vô hình và rất khó bị đao kiếm làm tổn thương. Ba Ma Tôn áp đảo ma thú nhưng chưa thể kết liễu vì hồ dung nham liên tục chữa trị thân thể cho nó. Hàn Lập dùng hóa kiếm thành tơ và hàng chục phi kiếm phân cắt ma linh, song các mảnh quang ảnh lập tức tái hợp. Khi hắn chuyển sang ngân diễm, ma linh bị thiêu đến rú thảm và điên cuồng tìm cách dập lửa."},{"chuong":2062,"tieuDe":"Khoáng Mạch Kịch Chiến Hạ","tomTat":"Ngân diễm của Hàn Lập nhanh chóng thiêu ma linh đầu tiên thành khói xanh, trong khi hắc diễm của nữ tử tóc tím không thể gây tổn thương cho ma linh còn lại. Nữ tử dùng trường kích và không gian lực phá nát hình thể đối phương, nhưng ma linh phân hóa thành hàng trăm tia sáng, xuyên qua các lớp hộ thể rồi điều khiển hai quang thủ phản kích. Khi nàng sắp phải dùng chiến giáp đón đòn trực diện, Hàn Lập phóng ngân diễm phá hủy quang thủ và hợp hai luồng lửa thành hỏa điểu bạc truy đuổi. Ma linh dùng kiếm quang tím cản đường rồi nhập vào thạch bích của động quật và trốn thoát. Nữ tử tóc tím cảm tạ Hàn Lập, đồng thời khẳng định phải trừ bỏ ma linh thì khoáng mạch mới có thể tiếp tục khai thác. Ở chiến trường còn lại, đại hán tóc vàng và ba Ma tôn đã ép người khổng lồ dung nham vào thế bất lợi nhưng vẫn phải né tránh những hỏa đoàn xanh khổng lồ. Cuối chương, nữ tử tóc tím chuyển sang hỗ trợ họ, còn Hàn Lập triệu pháp tướng ba đầu sáu tay màu vàng lao vào trận."},{"chuong":2063,"tieuDe":"Giải Quyết","tomTat":"Ma thú đầu hươu phá cồn cát đào thoát sau khi bị đánh trọng thương, nhưng vẫn bị Hàn Lập chém rơi nửa đoạn sừng tím. Hàn Lập thu đoạn sừng, nhận định ma thú phải tĩnh dưỡng hàng trăm năm mới có thể hồi phục rồi cùng Phúc Thiên tiên tử trở lại hang động. Tại đây, Bạch gia đề nghị ba vị khách tiếp tục tiêu diệt ma linh đang cản trở việc khai thác mạch khoáng. Đại hán tóc vàng tăng gấp đôi thù lao, hứa riêng cho Hàn Lập một con Lục Túc Ma Tích và quyền chọn ba bảo vật, đồng thời dùng huyết luyện tinh kim thuyết phục Loan Long Thiên Quân. Sau khi Hàn Kì Tử cũng đồng ý, năm người điều tức rồi chia thành hai nhóm tìm kiếm. Hàn Lập đi cùng Phúc Thiên tiên tử dùng linh bàn dò xét hầm mỏ, còn nhóm đại hán tóc vàng đi theo hướng khác. Hai ngày sau, nhóm kia báo đã tìm thấy và đang liên thủ công kích ma linh đang suy yếu, khiến Hàn Lập cho rằng họ có thể sớm trở về Huyễn Dạ thành."},{"chuong":2064,"tieuDe":"Tái Kiến Dị Ma Kim","tomTat":"Một tháng sau, đoàn người của Hàn Lập cưỡi Bát Túc Ma Tích rời Huyễn Khiếu Sa Mạc, khiến lực lượng áp chế thần bí biến mất và pháp lực của hắn khôi phục hoàn toàn. Trở lại Huyễn Dạ Thành, đại hán tóc vàng giao thù lao cho Hàn Lập, Loan Long Thiên Quân và Hàn Kỳ Tử; hai người sau nhận thưởng rồi cáo từ. Hàn Lập ở lại để thực hiện quyền chọn ba món trong bảo khố Bạch gia, còn đại hán tóc vàng âm thầm tiếc khoản thù lao đã bỏ ra dù khoáng mạch đã được giải nguy. Phúc Thiên tiên tử dùng ngọc bội màu tím và pháp quyết mở cấm chế, dẫn Hàn Lập vào tàng bảo khố được canh giữ nghiêm ngặt. Sau khi xem xét nhiều ma khí và vật liệu, Hàn Lập chọn một hộp ngọc bị phong ấn kín làm món đầu tiên. Tại hai giá cuối, hắn nhận ra khối Dị Ma Kim trắng đen lớn bằng đầu người và lập tức thu lấy làm món thứ hai, khiến Phúc Thiên tiên tử kinh ngạc vì vật liệu này có giá trị tương đối thấp trong bảo khố."},{"chuong":2065,"tieuDe":"Kim Kình Châu","tomTat":"Hàn Lập chọn Âm La Bàn làm bảo vật cuối cùng từ bảo khố Bạch gia, hoàn tất việc lấy một hộp Kim Kình Châu, một khối Dị Ma Kim và kiện ma khí định hướng này. Trên đường rời bảo khố, hắn hỏi về nguồn gốc Dị Ma Kim và được Phúc Thiên tiên tử cho biết khối khoáng thạch từng đi kèm một giao dịch Huyết Nha Mễ, còn người giao dịch rất có thể đến từ Lam Bộc Hồ. Sau khi tiễn Hàn Lập, Phúc Thiên tiên tử và đại hán tóc vàng cùng nghi ngờ khối Dị Ma Kim có huyền cơ, rồi đại hán quyết định bế quan điều dưỡng và giao nàng tạm thời tọa trấn Bạch gia. Trở về chỗ ở, Hàn Lập kích hoạt toàn bộ cấm chế và thử một viên Kim Kình Châu, khiến nó hiện hóa thành hư ảnh cá voi vàng dài hơn mười trượng, có sừng và lân phiến. Tuy nhiên, thứ hắn coi trọng nhất lại là Dị Ma Kim; khi bổ đôi khối khoáng thạch, hắn lấy ra một viên cầu xám trắng cỡ trứng gà được giấu bên trong. Hàn Lập hưng phấn đưa tay chộp vật bí ẩn, đồng thời cánh tay biến đổi và được một lớp vảy vàng rực bao phủ kín."},{"chuong":2066,"tieuDe":"Ma Giới Chi Chiến","tomTat":"Hàn Lập phong tỏa khối tinh cầu, dẫn khí xám trắng vào cơ thể và xác nhận nguồn năng lượng này cùng loại với năng lượng từng lấy từ Dị Ma Kim. Sau hơn mười ngày, hắn luyện hóa sạch toàn bộ năng lượng thành pháp lực, nhưng lục khí cũng tái xuất khiến hắn phải tính chuyện phong ấn nó vào ma anh. Nhận thấy Dị Ma Kim có thể giúp pháp lực tiến tới Hợp Thể kỳ viên mãn và tiết kiệm hơn ngàn năm khổ tu, hắn quyết định phải tới Lam Bộc Hồ. Trong thời gian lưu lại Huyễn Dạ Thành, Hàn Lập mua bí thuật luyện chế Ma Tinh Khôi Lỗi bậc trung tại Vạn Nô Tháp, nghiên cứu ưu khuyết điểm và thử chế tạo một số khôi lỗi cấp thấp. Một tấm lụa truyền tin khiến hắn lập tức rời thành, còn Chu Quả Nhi được lệnh tiếp tục ở lại lầu các chờ đợi. Tại ngọn núi ngoài thành, Hàn Lập gặp Lũng gia lão tổ và trưởng lão họ Huy, người đã mất một cánh tay, mặt mang hắc khí và cực kỳ tiều tụy sau khi gặp cường địch. Vì những đồng hành khác vẫn chưa tới, cả nhóm tiếp tục chờ cho tới khi Diệp tiên tử xuất hiện và được Lũng gia lão tổ mở cấm chế đón vào."},{"chuong":2067,"tieuDe":"Tính Kế","tomTat":"Diệp tiên tử và Huy đạo hữu đến hội hợp với Lũng gia lão tổ sau những biến cố trong vùng man hoang, còn Hàn Lập đã ở Huyễn Dạ Thành từ vài tháng trước. Hàn Lập cho biết chỉ tứ đại gia tộc sở hữu Bát Túc Ma Tích và rất khó mua vì loài ma thú này giúp họ khai thác Huyễn Khiếu Sa Mạc. Lũng gia lão tổ quyết định cùng Hàn Lập vào thành thử giao dịch, trong khi Diệp tiên tử và Huy đạo hữu ở ngoài chờ; nếu không mua được, ông sẽ chuẩn bị phương án lẻn vào cưỡng đoạt. Sau khi áp chế tu vi và dùng thân phận giả tiếp xúc các thế gia, Lũng gia lão tổ thất bại trong những lần cầu mua ban đầu nhưng kết giao được với một đệ tử cao giai của Triệu gia. Nhóm Thiên Thu thánh nữ tới nơi nguyên vẹn, song Hàn Lập phát hiện khí tức âm hàn của Chi Thủy tăng mạnh và thần niệm của mình mất tác dụng khi dò xét người này. Thiên Thu thánh nữ cùng Tàng Hình sau đó vào thành trợ giúp, khiến nhóm chuyển trọng tâm sang Triệu gia và đồng thời dò xét nơi chăn nuôi ma tích cùng hệ thống cấm chế để chuẩn bị hậu thủ."},{"chuong":2068,"tieuDe":"Phản Toán","tomTat":"Hai tháng sau, Lâm gia lão tổ trở về động phủ tạm thời trong tình trạng mất một mắt, một cánh tay và phần lớn pháp lực vì bị Nhiếp Hồn thú biến dị cấp Hợp Thể đánh lén. Không còn khả năng tiến vào Huyễn Khiếu Sa Mạc, ông quyết định rút khỏi đoàn, trở về Linh Giới và bế quan vài trăm năm. Hàn Lập tặng ông một viên Tôi Tinh Đan để ổn định thương thế, đồng thời bí mật nhờ ông đưa một tiểu nha đầu Nhân tộc về Linh Giới chăm sóc. Sau khi biết Triệu gia đòi Vạn năm Huyết Tử Linh Chi và Băng Tinh Chi Tâm để đổi Bát Túc Ma Tích, Thiên Thu thánh nữ cùng những người khác nhận định đối phương thiếu thành ý. Lũng gia lão tổ quyết định tương kế tựu kế, tự mình nhử hai Ma Tôn Triệu gia rời đi để đồng đội tập kích nơi đàn Bát Túc Ma Tích định kỳ trở về nghỉ chân. Sau khi đoạt đủ ma tích, cả đoàn sẽ che giấu thân phận, hạn chế giết chóc và chạy thẳng vào Huyễn Khiếu Sa Mạc để tránh bị cường giả Ma tộc chặn đầu."},{"chuong":2069,"tieuDe":"Chương 2069","tomTat":"Thiên Thu thánh nữ, Hàn Lập, Lũng gia lão tổ và vũ y nữ tử thống nhất kế hoạch đoạt Bát Túc Ma Tích rồi rút lui, trong khi mưu kế của Lũng gia lão tổ đã khiến hai Ma Tôn Triệu gia quyết định tự mình nhập cuộc. Sau hai tháng chờ đợi tại Huyễn Dạ Thành, Hàn Lập đưa Chu Quả Nhi ra ngoài thành và giao nàng cho Lâm đạo hữu hộ tống về Linh Giới. Chu Quả Nhi kinh ngạc khi biết Hàn Lập và người hộ tống đều là Nhân tộc, đồng thời bắt đầu liên hệ mối uyên nguyên giữa mình với Hàn Lập cùng Tố Nữ Luân Hồi công. Trên đường tiến về man hoang, phi chu của hai người bị một nữ nhân bí ẩn chặn lại bằng cự trảo kết từ vô số cánh hoa màu phấn hồng. Lâm đạo hữu dùng khôi lỗi, màn hào quang và cốt nhận chống trả nhưng toàn bộ phòng ngự đều bị phá, pháp lực ngưng trệ và cả hai người bị bắt. Khi tỉnh lại trong một khu rừng âm u, ông phát hiện mình bị dây hoa trói chặt, đan điền trống rỗng và không thể khôi phục pháp lực. Một hắc giáp đại hán báo tình hình với Bảo Hoa đại nhân, sau đó bạch y nữ tử dưới tán cây chỉ dùng ánh mắt đã khiến Lâm đạo hữu rơi vào trạng thái si mê và muốn hy sinh vì nàng."},{"chuong":2070,"tieuDe":"Nhị Tiến Huyễn Khiếu","tomTat":"Tu sĩ họ Lâm phá được ảnh hưởng thần niệm của Bảo Hoa nhưng nhận ra không còn khả năng phản kháng, đành tự giao nguyên thần để nàng tra xét. Bảo Hoa thiêu thân xác hắn thành tro song vẫn để lại một ngọn lửa trắng làm cơ hội luân hồi, rồi biết được đoàn tu sĩ Linh Giới đang tìm Tẩy Linh Trì và Tịnh Tinh Liên. Nàng quyết định không tiến vào Huyễn Khiếu Sa Mạc mà đi thẳng tới địa điểm đoàn người phải đến, đồng thời ra lệnh giữ mạng và mang Chu Quả Nhi theo. Ở phía khác, nhóm vũ y nữ tử trở về điểm tiếp ứng sau khi lấy được tám con Bát Túc Ma Tích từ Triệu gia, còn Lũng gia lão tổ và Bạch Thích xác nhận đã dùng pháp trận cầm chân hai ma tôn truy đuổi. Hàn Lập nhận thấy âm hàn khí trên người Chi Thủy mạnh hơn trước nhưng chưa xác định được nguyên nhân. Sau khi hội đủ thành viên và tọa kỵ, cả đoàn cưỡi Bát Túc Ma Tích tiến vào Huyễn Khiếu Sa Mạc. Một ngày sau, hai ma tôn Triệu gia thoát khỏi pháp trận, lần theo khí tức còn lưu lại và xác định đoàn Hàn Lập đã đi vào sa mạc."},{"chuong":2071,"tieuDe":"Thú Tôn Điện","tomTat":"Hai Ma tôn Triệu gia lần theo dấu vết vụ mất Ma Tích đến gần Huyễn Khiếu sa mạc và nhận định đối phương có thể mạnh hơn Luyện Hư, khiến gia tộc không đủ sức trực tiếp truy cứu. Người huynh trưởng quyết định bảo toàn hai trụ cột của gia tộc, tìm người thế mạng để che giấu thất bại và dùng ma thạch dự trữ bí mật thuê Thú Tôn điện truy sát mục tiêu trong thời hạn một trăm năm. Sau khi họ trở về Huyễn Dạ thành, vụ cướp dần chìm xuống vì Triệu gia không có chứng cứ công khai, còn đệ tử Phương gia đưa Ma Tích vào sa mạc bốn tháng sau đó. Ở đầu bên kia sa mạc, Hàn Lập cùng tám người còn lại cuối cùng thoát ra sau hơn mười năm, nhưng đoàn chỉ còn năm trong số mười con Ma Tích ban đầu. Hành trình của họ nhiều lần gặp Tam đại Ma Hại, nguy hiểm nhất là Sa Ảnh thú Hợp Thể hậu kỳ bám theo đánh lén nhiều năm trước khi Chỉ Thủy cầm chân nó và Hàn Lập tung một kích tiêu diệt. Việc để lộ một phần thực lực thật khiến Lũng gia lão tổ, Thiên Thu thánh nữ và phía Linh tộc thêm khách khí nhưng cũng kiêng kị Hàn Lập. Theo kế hoạch đã thống nhất, đoàn người chia thành các nhóm đi theo những tuyến khác nhau tới Ma Nguyên Hải nhằm tránh bị truy dấu và giảm sự chú ý của Ma tộc."},{"chuong":2072,"tieuDe":"Thanh Loan Chân Huyết","tomTat":"Đội thâm nhập Ma Giới chia thành bốn nhóm, trong đó Hàn Lập đi cùng Diệp tiên tử, còn Lũng gia lão tổ, Thiên Thu thánh nữ và Bạch Thích lần lượt dẫn những đường khác. Diệp tiên tử lấy Hắc Ngọc chu làm phương tiện, giao cho khôi lỗi lực sĩ khăn vàng điều khiển rồi mời Hàn Lập vào khoang để bí mật bàn kế hoạch. Nàng dùng bí thuật truyền thừa của Diệp gia nhận ra Hàn Lập mang Thiên Phượng chi huyết cùng nhiều loại Chân linh chi huyết khác. Sau đó, nàng tiết lộ một số tộc nhân hạch tâm của Thanh Dực tộc tại Thiết Sa lĩnh kế thừa Thanh Loan chân huyết và muốn Hàn Lập giúp mình đoạt lấy. Hàn Lập nhận ra loại chân huyết này có thể giúp Kinh Chập quyết tiến thêm một tầng, nên chấp thuận hợp tác sau khi Diệp gia hứa trả lượng lớn linh thạch và toàn lực tương trợ hắn một lần trong tương lai. Hai người kích chưởng lập ước, nhưng Diệp tiên tử lập tức cảnh báo rằng muốn đoạt được Thanh Loan chân huyết, họ rất có thể phải trực tiếp đối mặt với một Thánh tổ Ma tộc."},{"chuong":2073,"tieuDe":"Đối Thủ Ngoài Ý Muốn","tomTat":"Hàn Lập tỏ ra dè chừng khi biết Thiết Sa Lĩnh có liên quan đến một Thánh tổ Ma tộc, nhưng Diệp tiên tử giải thích nơi đó chỉ do hóa thân của Lăng Nguyên Thánh tổ trấn giữ. Nàng cho biết bản thể Lăng Nguyên đã bế sinh tử quan hơn vạn năm và trình bày kế hoạch dùng Hồn Thiên Châu tạo một phương thiên địa, sau đó thi triển bí thuật Diệp gia để vây hóa thân ít nhất nửa ngày. Sau khi cân nhắc, Hàn Lập đồng ý đảm nhiệm việc cầm chân đối phương trong chốc lát để hỗ trợ lấy Thanh Loan chân huyết. Trên đường vượt qua vùng cao nguyên, hắn phát hiện một ma thú cấp thấp có khả năng hòa khí tức với hoàn cảnh đang ẩn dưới đất; sau khi phi chu rời đi, con thú vẫn nhìn theo và phát tiếng hống quỷ dị. Một tháng sau, Lạc huynh và Lãnh huynh chờ phục kích tại Thổ Long Trấn dựa trên tình báo của Nhãn Ma về những nhóm người vừa rời Huyễn Khiếu Sa Mạc. Khi phi chu đen phù hợp hoàn toàn với hình ảnh tình báo hạ xuống quảng trường, hai kẻ mai phục xác nhận mục tiêu đã xuất hiện và chuẩn bị ra tay."},{"chuong":2074,"tieuDe":"Chặn Lại","tomTat":"Đạo sĩ trung niên họ Lãnh và đại hán mày rậm họ Lạc, hai trưởng lão Thú Tôn Điện, bí mật theo dõi Hàn Lập cùng Diệp tiên tử vì một khoản thù lao cao. Sau khi nhận ra Diệp tiên tử đang che giấu cảnh giới Ma Tôn còn tu vi Hàn Lập sâu không lường được, họ quyết định đợi hai người rời trấn mới hành động. Hàn Lập cảm thấy có kẻ dò xét nhưng không thể xuyên qua cấm chế tửu lâu, vì vậy cùng Diệp tiên tử mua thêm Thanh Ma Tinh rồi nhanh chóng lên đường. Tại một ngọn núi cách trấn hàng trăm vạn dặm, hai trưởng lão chặn phi chu và lấy lý do tỷ thí công pháp để ép họ giao đấu. Hàn Lập bắt được Truy Ảnh Trùng bám theo mình, thiêu nó thành tro rồi buộc đối phương đồng ý tiết lộ nguyên nhân thật nếu thất bại. Để công pháp phi ma đạo của Diệp tiên tử không làm lộ lai lịch, hắn bảo nàng đứng ngoài canh chừng và tự mình đối phó cả hai. Hàn Lập vận chuyển Phạm Thánh Chân Ma Công, hiển hóa pháp tướng vàng ba đầu sáu tay với sáu bảo vật cùng ba con mắt đen, chuẩn bị nghênh chiến hai trưởng lão Thú Tôn Điện."},{"chuong":2075,"tieuDe":"Tranh Đấu","tomTat":"Hàn Lập không còn che giấu tu vi Hợp Thể hậu kỳ, dùng linh áp kết hợp Phạm Thánh Chân Ma Công buộc đại hán họ Lạc phải gọi Lãnh huynh cùng liên thủ. Hai Ma Tôn hiện ra bán thú chi thân, để lộ họ vốn là ma thú Hóa Hình, rồi hợp lực hóa giải đòn thăm dò từ Phạm Thánh Ma Tướng. Lạc huynh thi triển Vạn Hư Chi Kiếm kết thành kiếm sơn bạc, còn Lãnh huynh điều khiển hổ lửa lục diễm phối hợp tấn công. Hàn Lập dùng hắc ti triệt tiêu cột sáng và vận dụng Động Tuyền Kim Quang tạo xoáy nước đối đầu kiếm sơn, khiến cả hai thần thông cùng tan biến. Nhận thấy Hàn Lập vẫn chưa dùng toàn lực, hai Ma Tôn chủ động dừng tay và thừa nhận không bằng hắn. Lãnh huynh sau đó tiết lộ họ đến từ Thú Tôn Điện, nêu uy danh của Vạn Thú Thánh Tổ và mời Hàn Lập gia nhập với thân phận khách khanh trưởng lão."},{"chuong":2076,"tieuDe":"Thiết Sa Lĩnh","tomTat":"Hàn Lập từ chối lời mời gia nhập Thú Tôn Điện, còn trung niên đạo sĩ thừa nhận điện đã nhận thù lao lớn từ một người nặc danh để đối phó nhiều nhóm ngoại lai. Sau khi ngọc bội phát tín hiệu, hai Ma Tôn của Thú Tôn Điện rời đi; Diệp tiên tử đề nghị diệt khẩu nhưng Hàn Lập bác bỏ vì đối phương rất mạnh và các nhóm khác cũng đã bị theo dõi. Hai người nghi ngờ đại sự mà Thú Tôn Điện đang chuẩn bị có liên quan đến cuộc xâm nhập Linh giới, đồng thời quyết định hành động thận trọng hơn và tiếp tục tìm Thanh Loan chân huyết. Ở hướng khác, nhóm Lũng gia lão tổ quyết định toàn lực tới Ma Nguyên Hải vì lo ngại Vạn Thú Thánh Tổ có thể phái hóa thân truy đuổi, còn hai Ma tộc đối diện Thiên Thu Thánh nữ và Chi Thủy lại tỏ ra cực kỳ sợ hãi Chi Thủy. Hàn Lập và Diệp tiên tử sau đó tới một thành trì Ma tộc, thu thập được tin cuộc chiến tại Linh giới vẫn giằng co dù Thánh tổ Ma tộc và tu sĩ Đại Thừa đã tham chiến. Sau ba tháng tiếp tục phi hành, họ tới gần Thiết Sa Lĩnh và nhìn thấy một dãy núi đen nhánh phủ màu hắc lục đầy vẻ bất an."},{"chuong":2077,"tieuDe":"Thanh Vân Môn","tomTat":"Hàn Lập và Diệp tiên tử tới Thiết Sa lĩnh, địa bàn có ma khí nồng đậm và nhiều ma thú do Thanh Dực tộc kiểm soát bằng Khu thú thuật. Vì chỉ còn tối đa một tháng trước kỳ hẹn tụ họp, hai người thu phi chu rồi chia nhau ẩn nặc dò tìm tộc nhân hạch tâm, đồng thời đề phòng hóa thân của Lăng Nguyên thánh tổ. Trong quá trình tìm kiếm, Hàn Lập dùng năm đạo hắc ti tiêu diệt hơn mười ma cầm, còn Diệp tiên tử bắt hai ma nhân có cánh và sưu hồn một người để lấy tin. Nàng xác định trại ven rìa không có tộc nhân hạch tâm, dùng pháp bàn truyền tin cho Hàn Lập rồi dẫn hắn tới Huân Hương trại, một trong bốn nơi cư trú lớn nhất của Thanh Dực tộc. Hai người nhận thấy sơn trại được sương trắng có mùi thơm và cấm chế lợi hại bảo vệ nên chưa thể trực tiếp xông vào. Khi một đoàn ma nhân Thanh Dực tộc cưỡi phi xà trở về, Hàn Lập quyết định bám theo họ để trà trộn qua cấm chế. Hắn giao Thái Nhất Hóa Thanh phù cho Diệp tiên tử, cảnh báo nàng không được sử dụng thần thông đặc thù sau khi kích phát, rồi tự dán một tấm giống hệt lên người để bắt đầu kế hoạch xâm nhập."},{"chuong":2078,"tieuDe":"Đột Nhập","tomTat":"Hàn Lập và Diệp tiên tử kích phát Thái Nhất Hóa Thanh phù, ẩn thân bám theo đoàn Thanh Dực tộc vượt qua thông đạo cấm chế để tiến vào Huân Hương trại. Sau khi thâm nhập thành công, hai người chia nhau trinh sát trong hai ngày; Hàn Lập cải trang thành Thanh Dực nhân để quan sát hệ thống phòng hộ, còn Diệp tiên tử biến thành nữ Ma tộc và dùng thiết bài đỏ dò tìm mục tiêu. Diệp tiên tử xác định một tòa nhà tập trung nhiều hạch tâm đệ tử nhưng cảnh báo rằng nơi đó có thể được cấm chế mạnh và nhiều Ma tôn bảo vệ. Hàn Lập nhận nhiệm vụ phá điểm yếu của trấn trại cấm chế và cầm chân các Ma tôn, để nàng trực tiếp bắt sống một hạch tâm đệ tử. Hai người quyết định tập kích ngay trong đêm nhằm tránh kéo dài sinh biến, đồng thời chuẩn bị đối phó nếu hóa thân của Lăng Nguyên thánh tổ xuất hiện. Khi tế đàn trong đại điện phát cảnh báo, Ma tôn tóc đen mắt xanh rời chỗ tu luyện và phát hiện Hàn Lập đã xâm nhập. Đúng lúc chấn động vang lên ở nơi khác, Hàn Lập dùng lôi độn chặn đường đối phương rồi kết kiếm khí thành thanh sắc kiếm võng, chính thức mở màn cuộc giao chiến đánh lạc hướng."},{"chuong":2079,"tieuDe":"Triền Đấu","tomTat":"Hàn Lập cải trang lẻn vào đại sảnh, dùng kiếm ti phá cuồng phong, hư ảnh giao hổ và Ma Phong Độn của ma nhân Thanh Dực tộc. Hắn tiếp tục dùng ngân diễm ép Thanh trưởng lão cùng Tam Thủ Thanh Xà đang ẩn nấp phải hiện thân. Hai ma nhân quyết định chia người tới Tàng Linh Các cầu viện, đồng thời thúc Tam Thủ Thanh Xà hóa thành cự mãng ba đầu và triệu ma cầm trắng để phối hợp tác chiến. Hàn Lập gọi Báo Lân Thú đã tiến giai Hợp Thể kỳ, hiện ma giáp, triển khai hắc sắc tiểu sơn cùng Ngân Sắc Hỏa Điểu nghênh chiến. Trong khi Hàn Lập ung dung cầm chân Thanh trưởng lão và cự mãng, Báo Lân Thú liên tục chặn ma nhân cùng ma cầm khỏi rời đại sảnh. Hàn Lập có đủ sức tiêu diệt đối thủ nhưng cố ý chỉ phòng thủ để tránh gây thêm phiền toái. Cuối cùng, Diệp tiên tử truyền âm báo mình đã đắc thủ và hai người có thể rời đi, khiến Hàn Lập mừng rỡ."},{"chuong":2080,"tieuDe":"Đắc Thủ","tomTat":"Hàn Lập triệu ma tướng ba đầu sáu tay đánh lui những kẻ ngăn cản, cùng Báo Lân Thú thoát khỏi Huân Hương Trại rồi dùng một phù trận khổng lồ vây khốn nam tử Ma tộc đang truy đuổi. Hắn thi triển Lôi Dực và phá cấm chế bên ngoài, sau đó biến thành Lôi Bằng bạc để cùng Diệp tiên tử, người đã hóa thành Ngũ Sắc Thải Phượng, cắt đuôi các Ma Tôn Thanh Dực tộc. Trong một sơn động, Diệp tiên tử lấy Thanh Loan chân huyết từ đệ tử hạch tâm bị bắt và chia cho Hàn Lập một bình có độ tinh khiết vượt xa dự liệu. Hai người lập tức rời Thiết Sa Lĩnh, còn thanh niên Thanh Dực tộc được tìm thấy sau đó vẫn sống nhưng đã mất sạch chân huyết. Các Ma Tôn Thanh Dực tộc định cầu viện Lăng Nguyên Thánh Tổ, song hóa thân của vị Thánh Tổ này đã trọng thương sau một chuyến đi xa và phải bế quan. Trước tổn thất chân huyết cùng tình trạng của chỗ dựa trong tộc, các Tôn Giả Ma tộc đồng loạt cấm bàn tán và nhanh chóng đàn áp mọi tin tức."},{"chuong":2081,"tieuDe":"Ma Nguyên Hải","tomTat":"Một năm sau, đoàn Hàn Lập dùng cự thuyền do hải thú kéo để vượt Ma Nguyên Hải, nơi hắc vụ và lôi điện dày đặc khiến họ không thể phi hành. Lũng gia lão tổ cùng Diệp tiên tử bàn về tạp khí trong vùng biển, thông tin mơ hồ của Linh tộc và nguy cơ thân phận cả đoàn bị Ma tộc phát hiện. Trong khoang thuyền, Hàn Lập nghe được cuộc trò chuyện và nhớ lại việc mình cùng Diệp tiên tử từng đánh trọng thương hóa thân Lăng Nguyên thánh tổ sau khi đoạt Thanh Loan chân huyết. Khi hội họp trước đó, đoàn phát hiện Kim trưởng lão đã mất tích và được Linh tộc thông báo là hồn phi phách tán, trong khi khí tức âm hàn trên người Chỉ Thủy cũng biến mất một cách đáng ngờ. Hàn Lập xem xét Thanh Loan chân huyết, nhận ra nó có thể bổ sung biến hóa Thanh Loan cho Kinh Chập quyết nhưng quyết định chờ về Linh giới mới luyện hóa. Sau ba tháng tìm kiếm, hắn phát hiện Ma Viên San Hô cách cự thuyền hơn ba ngàn dặm và được Thiên Thu thánh nữ xác nhận. Cả đoàn đổi hướng rồi nhìn thấy một tòa núi giữa biển có hình dáng sống động như cự viên ngửa cổ giang hai tay lên trời."},{"chuong":2082,"tieuDe":"Lôi Hải","tomTat":"Thiên Thu thánh nữ xác nhận Ma Viên San Hô là mốc định hướng tới đảo nhỏ, đồng thời tiết lộ di huấn của một tiền bối Đại Thừa từng cảnh báo về nguy hiểm ở vùng phụ cận. Để chuẩn bị, đoàn thám hiểm gia cố cự thuyền bằng pháp trận, bộ ma phiên, hai khôi lỗi thượng cổ và tám đầu Hàn Thủy Tê. Sau một tháng, họ tiến vào vùng biển đầy bão tố và lôi điện, nơi thần niệm chỉ còn cảm ứng được khoảng mười dặm. Hàn Lập dùng Thanh Minh Linh Mục phát hiện một vùng dị thường cách năm ngàn dặm, còn Bạch Thích chỉ có thể xác nhận nơi đó có biến động. Khi cự thuyền tới gần, mọi người nhìn thấy một Lôi Hải rộng lớn với vô số lôi cầu bao kín đảo nhỏ mục tiêu. Lũng gia lão tổ định cưỡng hành xông qua, nhưng Hàn Lập cảnh báo rằng trong Lôi Hải còn có điều khác thường."},{"chuong":2083,"tieuDe":"Hoàng Kim Giải","tomTat":"Hàn Lập chém mở hắc vụ trên Lôi Hải, để lộ một cự giải vàng lớn như núi với điện hồ quấn quanh thân và khí tức khiến các tu sĩ Hợp Thể kinh sợ. Bạch Thích dùng linh mục kiểm tra, không phát hiện dấu hiệu sinh mệnh nên cả đoàn ban đầu cho rằng đó là Chân Linh di hài và động lòng trước giá trị của nó. Hàn Lập nhận thấy một vật quý như vậy không thể bị Ma tộc cao giai bỏ mặc vô cớ, từ đó xác định cự giải thực chất là ma tinh khôi lỗi. Hắn lấy cự lang khôi lỗi cấp thấp do mình phỏng chế tại Huyễn Dạ thành ra làm mẫu đối chiếu. Bạch Thích nhận thấy hoa văn trên hai cỗ khôi lỗi tương tự nhau rồi thi triển Linh Quang Hồi Tố Thuật cùng gương đồng để tái hiện rõ hình dáng Hoàng Kim Giải. Sau khi công nhận kết luận của Hàn Lập, đoàn người suy đoán cỗ khôi lỗi đã hư hại không thể sửa chữa và quyết định không mạo hiểm thu lấy. Họ quay lại mục tiêu chính là vượt qua giông tố để tiến vào đảo nhỏ trong Lôi Hải."},{"chuong":2084,"tieuDe":"Tam Đại Thủy Tổ","tomTat":"Trước lôi hải cuồng bạo, Hàn Lập và Lũng gia lão tổ xác định cả đoàn vẫn có thể xông qua nếu cùng nhau chống đỡ, dù khó tránh tổn thương nguyên khí. Mọi người kích phát các tầng phòng thủ trên cự thuyền; Lũng gia lão tổ triệu hai khôi lỗi thượng cổ, Hàn Lập vận dụng Bộ ma phiên, còn Thiên Thu thánh nữ trang bị Thú Giáp cho tám đầu Hàn Thủy Tê. Khi cự thuyền tiến vào vùng sấm chớp, Chỉ Thủy bí mật xuất hiện kim sắc phù văn trong tay áo, đồng thời Hoàng Kim Giải ẩn trong mây đen cũng phát sinh dị động tương ứng. Trên một đảo nhỏ giữa lôi hải, nữ tử Thủy Tổ biết đoàn người đã tới rồi biến mất, khiến hắc giáp đại hán lập tức rời đi. Ở một đảo hắc khí khác, hắc bào thanh niên thất bại trong thí nghiệm nuôi trồng linh dược, sau đó nhận tín hiệu Khổ Linh Đảo bị xâm nhập và cưỡi tam thủ hắc giao bay tới lôi hải. Vị Thủy Tổ thứ ba là trung niên kim bào vẫn nằm bất động trong quan tài dưới lòng đất dù ký hiệu vàng bên cạnh đã phát sáng. Ba người được hé lộ là Tam Đại Thủy Tổ Ma giới, những tồn tại cấp Thánh Tổ đã tiến tới bước cuối trước khi độ kiếp phi thăng Chân Ma giới."},{"chuong":2085,"tieuDe":"Linh Đảo","tomTat":"Cự thuyền màu xanh bị sấm chớp dày đặc cùng sức mạnh vô hình trong Lôi hải kìm hãm, khiến tám Hàn Thủy Tê kéo suốt nửa ngày mà chỉ tiến được vài dặm. Theo đề nghị của Lũng gia lão tổ, Thiên Thu Thánh nữ dùng huyết trận, đan dược và kim bài thi triển bí pháp kích phát tám linh thú, khiến chúng mọc cánh dơi đỏ và kéo thuyền tăng tốc. Khi tinh thuẫn do hai thạch khôi lỗi hợp lực tạo thành tan vỡ, mưa sét đánh thủng lớp phòng hộ ngoài cùng và hủy diệt một tòa pháp trận trên thuyền. Hàn Lập lập tức vận Phạm Thánh Chân Ma công, chuyển pháp lực thành ma khí để phục hồi và mở rộng mạng lưới ma phiên, một mình gánh gần nửa mưa sét. Trong lúc mọi người chống đỡ, phù văn vàng kim bí mật xuất hiện trên cánh tay Hắc bào thanh niên và đồng thời hiện lên trên vỏ Hoàng Kim Giải đang ẩn trong mây đen. Sau gần nửa ngày, đoàn người vượt khỏi Lôi hải dù cự thuyền đã rách nát và tám Hàn Thủy Tê đều cháy đen, gần như hấp hối. Tại vùng biển yên tĩnh tràn đầy linh khí tinh thuần, họ nhìn thấy một hòn đảo xanh biếc khổng lồ được Lũng gia lão tổ xác nhận là Linh Đảo, nơi có khả năng tồn tại Tẩy Linh Trì và Tinh Linh Liên."},{"chuong":2086,"tieuDe":"Linh Khí Tinh Hoá","tomTat":"Nhóm Thiên Thu thánh nữ và nhóm tu sĩ Nhân tộc cùng tiến vào cự đảo, nhưng bắt đầu chủ động giữ khoảng cách vì lo ngại đối phương độc chiếm Tẩy Linh Trì và Tịnh Linh Liên. Hàn Lập riêng xác nhận với Diệp tiên tử rằng hai người sẽ cùng tiến cùng lui nếu thỏa thuận phân chia linh vật xảy ra biến cố. Thiên Thu thánh nữ dùng một viên châu trắng phủ tơ máu xác định mục tiêu, sau đó Lũng gia lão tổ kích phát Bán Long Chi Khu và dùng cự phủ phá núi, làm lộ sơn cốc bí mật có Linh Tiêu Thiên Hủ. Khi mọi người chuẩn bị tiến vào, Thiên Thu thánh nữ âm thầm kết pháp ấn khiến Chỉ Thủy phát sinh dị trạng, nhưng lời truyền âm của Bạch Thích buộc nàng lập tức dừng tay trong lúc Hàn Lập dường như đã nhận ra. Bên trong sơn cốc, Hàn Lập gom ngũ sắc quang điểm thành tinh thạch và xác nhận linh khí nơi đây đã tinh hóa, tinh thuần hơn bên ngoài gấp mười lần. Đoàn người tiếp cận một hồ nước xanh biếc được nghi là Tẩy Linh Trì, song Bạch Thích cảnh báo rằng tìm thấy chưa có nghĩa là có thể dễ dàng đi vào. Cùng lúc đó, một bóng người áo trắng có đồng tử phát ngân quang và một hắc giáp đại hán đang âm thầm theo dõi sơn cốc từ ngọn núi cách đó vài trăm dặm."},{"chuong":2087,"tieuDe":"Nguyên Yểm Thủy Tổ","tomTat":"Bảo Hoa đứng ngoài sơn cốc quan sát nhóm Hàn Lập, đồng thời tiết lộ rằng nàng trở về Thánh giới vừa để khôi phục pháp lực, vừa vì Nguyên Yểm. Qua gương bạc, nàng nhìn thấy Nguyên Yểm cưỡi tam thủ hắc giao vượt lôi hải bằng một cây trường thương ma văn, nhưng đối phương nhanh chóng phát hiện sự dò xét và phá hủy chiếc gương. Bảo Hoa sau đó giao cho Hắc giáp đại hán một nhiệm vụ bí mật rồi tiếp tục theo dõi linh trì. Tại sơn cốc, Bạch Thích, Lũng gia lão tổ và Hàn Lập được phân công làm chủ lực phá cấm chế bằng Vạn Năm Hủ Châu, thần thông phá cấm và hai tòa núi dị bảo. Khi các đợt công kích đồng loạt phát động, Nguyên Yểm bất ngờ giáng lâm và triệu một bàn tay tối om lớn nghìn trượng, đánh tan toàn bộ thế công rồi ép phần lớn mọi người cắm sâu vào bùn đất. Hàn Lập nhờ thân thể chuyển thành màu vàng rực nên chỉ bị lún nửa thước, còn Chỉ Thủy gần như không hề hấn và bộc lộ linh văn bạc quỷ dị khi đối diện vị Ma tộc Thánh tổ."},{"chuong":2088,"tieuDe":"Ngụy Tiên Khôi Lỗi","tomTat":"Hắc bào thanh niên phóng hai viên đan hoàn đen tấn công Hàn Lập và Chỉ Thủy, khiến Hàn Lập bị giam trong một cột ma diễm không rõ sống chết. Chỉ Thủy phá được ma diễm và dựng ngân sắc thuẫn bài, nhưng vẫn bị ma châm xuyên thủng đầu, qua đó lộ ra bản chất ngụy tiên khôi lỗi thử nghiệm sử dụng Ma Hồn lực thay cho Tiên Nguyên tinh. Thiên Thu thánh nữ thúc giục Bán Túc Chi Thân để điều khiển Chỉ Thủy rồi bị tiên văn phản phệ. Hắc bào thanh niên dùng một thanh chủy thủ Huyền Thiên chi bảo chém chết nàng, làm lộ bản thể thông linh chi bảo dưới hình dạng cổ kính bóng loáng, sau đó thu cả cổ kính lẫn Chỉ Thủy làm trận nhãn. Hắn tiếp tục dùng chủy thủ giết lão nho và Huy trưởng lão, khiến Lũng gia lão tổ nhận ra uy lực của Huyền Thiên chi bảo. Trước tình thế nguy cấp, Lũng gia lão tổ phóng kim long ngũ trảo, còn Diệp tiên tử hóa vũ y thành chiến giáp ngũ sắc để liều mạng chống cự, trong khi Bạch Thích vẫn bất động trong màn bạch quang."},{"chuong":2089,"tieuDe":"Huyền Thiên Hắc Chủy","tomTat":"Kim long hộ thể và ngũ sắc chiến giáp tự động phát động, giúp Lũng gia lão tổ cùng Diệp tiên tử tạm thời làm suy yếu cự đại ma thủ và tìm đường thoát khỏi lực trói buộc. Lũng gia lão tổ hóa thành bán long chi khu, mượn phản chấn thoát vây rồi tung nhiều bảo vật phòng thân, còn Diệp tiên tử biến chiến giáp thành quang diễm chi sí để lẩn vào hư không. Hắc bào thanh niên dùng Huyền Thiên Hắc Chủy phá hủy phần lớn bảo vật của Lũng gia lão tổ và xuyên thủng không gian bí thuật, buộc Diệp tiên tử thi triển thế kiếp đại pháp, hy sinh một cánh tay để giữ mạng. Hắn tiếp tục dẫn ma khí từ hắc động trên trời nhập vào hắc chủy, khiến vũ khí hóa thành một thanh cự kiếm có uy thế vượt xa trước đó. Nhát chém sau đó bất ngờ đổi hướng sang đoàn ma diễm che giấu Hàn Lập vì hắc bào thanh niên đã nhìn thấu thuật thu liễm khí tức và đánh giá hắn là người mạnh nhất nhóm. Kiếm quang hóa thành vô số hắc ti, kết thành hắc võng co rút quanh Hàn Lập. Hàn Lập tạo chữ “phong” bằng tử quang để khiến ma diễm và hắc võng đình trệ trong khoảnh khắc, rồi vận dụng lôi độn thoát đến bên Lũng gia lão tổ và Diệp tiên tử."},{"chuong":2090,"tieuDe":"Trùng Trùng Nguy Cơ","tomTat":"Hàn Lập dùng Tử Ngôn Đỉnh chống lại những hắc ti do Hắc Ma Chủy phát ra, nhưng bảo vật bị phá hủy khi Nguyên Yểm gia tăng uy năng. Bị hắc sắc ti võng vây kín, hắn liên tiếp vận dụng Phạm Thánh Kim Thân, Tịch tà thần lôi, phi kiếm, ma giáp và nhiều thủ đoạn khác để chống đỡ. Trong lúc đối thủ phân tâm, Lũng gia lão tổ và Diệp tiên tử chia hướng đào tẩu, nhưng màn sáng của Khốn Linh Cốc lần lượt đánh bật độn quang và ngăn mọi bí thuật không gian, còn Bạch Thích vẫn đứng nguyên tại chỗ. Hàn Lập sau đó biến thành Kim Mao Cự Viên, nâng hai tòa cực sơn và phối hợp các thần thông để miễn cưỡng mở một khe nhỏ trong ti võng rồi thoát ra. Nguyên Yểm tỏ ra hứng thú với chân linh huyết mạch của Hàn Lập, đồng thời tuyên bố đòn kế tiếp sẽ vận dụng một nửa uy năng Hắc Ma Chủy. Khi biết nơi đây là Khổ Linh Đảo và mọi đường rời Khốn Linh Cốc đã bị khóa, Hàn Lập kêu gọi những người còn lại từ bỏ tâm tư riêng, hợp sức tử chiến để tìm đường sống."},{"chuong":2091,"tieuDe":"Linh Vương Cùng Vẫn Giới Thạch","tomTat":"Lũng gia lão tổ và Diệp tiên tử hội hợp với Hàn Lập, trong khi Bạch Thích vẫn đứng riêng trước Nguyên Yểm. Hàn Lập nhận ra linh khí tinh thuần tại Khốn Linh Cốc đang áp chế đối phương, còn Lũng gia lão tổ đề nghị ngăn Hắc Ma Chủy hấp thu chân ma khí bên ngoài để kéo dài khả năng chống đỡ. Nguyên Yểm thừa nhận mình bị hoàn cảnh Khổ Linh Đảo hạn chế, nhưng vẫn tin vào uy lực của Huyền Thiên chi bảo và truy hỏi bố trí của Linh Vương trong người Bạch Thích. Bạch Thích giải phóng Phân Linh phù, khiến một tia hồn niệm của Linh Vương hiện thân và nhận diện Nguyên Yểm là một trong Tam Đại Thủy Tổ. Linh Vương đề nghị đổi một vật lấy cơ hội cho hậu bối Linh tộc tiến vào Tẩy Linh Trì cùng một cây Tịnh Linh liên, đồng thời cho biết bản thể đang bận đối phó cuộc tiến công của Ma tộc. Khi Nguyên Yểm bác bỏ giao dịch, Linh Vương đưa Vẫn Giới Thạch ra và tiết lộ kỳ thạch có thể trì hoãn đại kiếp Ma tộc ít nhất trên vạn năm. Nguyên Yểm kinh động vì bí mật của Ma giới đã bị biết, nhưng sau khi suy tính lại bất ngờ vung hắc sắc cự kiếm chém Bạch Thích và dùng Ma thủ chộp phân hồn Linh Vương."},{"chuong":2092,"tieuDe":"Niết Bàn Châu","tomTat":"Nguyên Yểm bất ngờ trở mặt, dùng Hắc Ma Chủy cùng ma trảo phá tan mọi lớp phòng ngự, giết Bạch Thích và tiêu diệt tia phân hồn của lão giả áo trắng. Sau khi lục soát di vật mà không tìm thấy Vẫn Giới Thạch, hắn tra hỏi rồi quyết định giết cả ba người Hàn Lập. Nguyên Yểm phóng kiếm quang lên cấm chế nhằm dẫn ma khí vào Khốn Linh Cốc; ba kim xoa của Lũng gia lão tổ bị chém đứt, còn Niết Bàn Châu của Diệp tiên tử chỉ làm kiếm quang suy yếu. Hàn Lập biến thành Sơn nhạc cự viên, ném hai tòa Cực Sơn phá nát kiếm quang, nhưng Nguyên Yểm lập tức dùng hai quyền đánh bật chúng trở lại. Ba người Hàn Lập phải tụ lại để tránh bị tiêu diệt riêng lẻ. Đúng lúc ấy, một sợi tơ trắng từ những mảnh chuông bạc của Bạch Thích bất ngờ chui vào Ngụy Tiên Khôi Lỗi, khiến Nguyên Yểm kinh sợ và lập tức ra tay chộp lấy khôi lỗi."},{"chuong":2093,"tieuDe":"Tham Thiên Tạo Hóa Lộ","tomTat":"Khi Nguyên Yểm Thánh Tổ định bắt lấy Ngụy Tiên Khôi Lỗi, tia thần niệm do Linh Vương lưu trong khôi lỗi thức tỉnh, điều khiển nó tránh đòn và tuyên bố sẽ trực tiếp giao chiến. Linh Vương lấy Cố Linh Bình phỏng chế, rót ra một giọt Tham Thiên Tạo Hóa Lộ đã pha loãng mười lần, khiến Hàn Lập chấn động vì cảm nhận được khí tức quen thuộc. Nguyên Yểm dùng Hắc Ma Chủy và hắc sắc tiêm trùy ngăn cản, nhưng khôi lỗi vẫn hấp thu được tiên dịch rồi dùng hai bàn tay phủ lục quang xé tan kiếm quang và đánh bật tiêm trùy. Linh Vương giải thích tiên dịch pha loãng không thể luyện Tham Thiên Tạo Hóa Đan, song một tia tiên linh khí còn lại vẫn đủ kích phát một phần thần thông của khôi lỗi. Trước sức mạnh tăng vọt của đối thủ, Nguyên Yểm triệu Cửu Đầu Ma Thiềm pháp tướng, dùng chiếc lưỡi vàng hóa thành kim võng đánh bật bảo vật và quấn khôi lỗi tám vòng. Hắn siết thân khôi lỗi đến phát tiếng rạn vỡ và định nghiền nát nó, nhưng Linh Vương vẫn không hề sợ hãi, trái lại còn tỏ vẻ châm chọc như vẫn nắm giữ hậu thủ."},{"chuong":2094,"tieuDe":"May Mắn Thoát Thân","tomTat":"Ngụy Tiên Khôi Lỗi bị linh văn lục sắc trói chặt liền kích hoạt tự bạo, hóa thành một vầng mặt trời năm màu có uy lực hủy diệt và tàn phá toàn bộ sơn cốc. Nguyên Yểm dùng hư ảnh ma thiềm cùng Hắc Ma Chủy phòng ngự nhưng vẫn mất một bên bả vai, khí tức suy yếu hơn phân nửa và phải chém nát các khe không gian để xả giận. Lũng gia lão tổ hóa thành Ngũ Trảo Kim Long, còn Diệp tiên tử biến thân Thiên Phượng và vận dụng thần thông không gian đến cực độ, song cả hai đều bị hủy diệt hoàn toàn. Hàn Lập triển khai nhiều tầng phòng ngự gồm hai tòa Cực Sơn, ma giáp, kim thân pháp tướng và trùng thuẫn do Phệ Kim Trùng tạo thành. Sau vụ nổ, ma giáp cùng pháp tướng bị hủy và đàn Phệ Kim Trùng tổn thất hơn phân nửa, nhưng bản thân Hàn Lập vẫn hoàn toàn vô sự. Sự sống sót kỳ lạ của hắn khiến Nguyên Yểm kinh ngạc và chăm chú quan sát để tìm nguyên do. Nước hồ trong sơn cốc biến mất, để lộ một trận pháp mơ hồ trên phiến đá lớn dưới đáy, còn Hàn Lập âm trầm nhìn bàn tay mình rồi thở dài khi nhìn về nơi hai người đã chết."},{"chuong":2095,"tieuDe":"Bảo Hoa Hiện Thân","tomTat":"Sau vụ tự bạo, Nguyên Yểm vẫn dùng Hắc Ma Chủy tấn công Hàn Lập, buộc hắn triệu hồi Phạm Thánh Kim Thân chuẩn bị chống đỡ. Bảo Hoa cùng Hắc Ngạc bất ngờ hiện thân từ một đóa hoa phấn hồng và thu lấy kiếm quang của Nguyên Yểm. Trong cuộc đối chất, Bảo Hoa xác nhận từng bị Lục Cực hạ độc thủ và trúng Mộng Yểm Huyết Chú của Nguyên Yểm, còn Nguyên Yểm hé lộ Mộng Yểm Đại Pháp có bảy Tích Huyết Nguyên Thần giúp hắn tránh bị tiêu diệt hoàn toàn. Bảo Hoa tuyên bố Lục Cực mới là đại thù chính và sẵn sàng lập Thiên Ma Chi Thệ để tạm thời không giao chiến với Nguyên Yểm. Nàng sau đó xác định Hàn Lập mới là mục tiêu mình tìm đến Khổ Linh Đảo và bất ngờ dùng tám thành pháp lực tập kích hắn. Hàn Lập dùng bàn tay phát lục quang chặn được đòn có uy lực gần đạt một kích của Đại Thừa kỳ, trong khi Phạm Thánh Kim Thân bị xuyên thủng phần ngực. Khi Bảo Hoa chuẩn bị tung đòn tiếp theo, một bóng kiếm bí ẩn xuất hiện trong lòng bàn tay Hàn Lập khiến nàng biến sắc và dừng tay."},{"chuong":2096,"tieuDe":"Niết Bàn Thánh Thể Cùng Huyền Thiên Kiếm","tomTat":"Lục sắc tiêu ký trên tay Hàn Lập hút thiên địa nguyên khí và ngưng tụ thành kiếm ảnh, khiến Bảo Hoa cùng Nguyên Yểm nhận ra khí tức của Huyền Thiên Chi Bảo. Nguyên Yểm từ chối thay Bảo Hoa thăm dò Hàn Lập, còn Bảo Hoa trực tiếp dùng Liên Hoa Chỉ hóa vô số hoa hồng thành kiếm lốc để ép kiếm mạc xanh rung chuyển. Trước sức ép đó, Hàn Lập triệu ra năm hư ảnh chân linh, dung nhập chúng vào nguyên anh rồi biến thành Niết Bàn Thánh Thể ba đầu sáu tay. Hắn tiếp tục gọi ra tiểu kiếm xanh mang kim ngân ký hiệu, qua đó chứng minh mình có thể kích phát Huyền Thiên Trảm Linh Kiếm trong trạng thái biến thân. Hàn Lập cảnh báo rằng tiếp tục giao đấu trong hoàn cảnh hiện tại sẽ khiến đôi bên cùng tổn thương, và Bảo Hoa thừa nhận hắn đã có tư cách liều mạng với nàng. Nàng đồng ý ngừng tay với điều kiện Hàn Lập giao ra một loại linh dược bí ẩn mà nàng tin đang nằm trong tay hắn. Bảo Hoa giải thích rằng chỉ sau khi những người có khả năng nắm giữ khác đều ngã xuống, nàng mới có thể khóa mục tiêu vào Hàn Lập."},{"chuong":2097,"tieuDe":"Thiên Âm Lôi Hạch","tomTat":"Bảo Hoa cho biết linh dược nàng cần là vật Hàn Lập đã có trước khi tiến vào Thánh giới, thuộc loại thế gian khó tìm và Linh giới chưa chắc tồn tại. Nàng đưa Chu Quả Nhi đang hôn mê ra làm điều kiện bổ sung, rồi sai Hắc Ngạc giao thiếu nữ cho Hàn Lập trước; sau khi kiểm tra và xác nhận nàng chỉ bị một cấm chế đơn giản, Hàn Lập thu nàng vào bảo vật. Hàn Lập cũng hỏi về Lâm đạo hữu nhưng chỉ nhận được câu trả lời mập mờ rằng người này không hữu dụng nên không được lưu lại. Chấp nhận giao dịch, Hàn Lập lần lượt lấy ra nhiều linh dược từ Quảng Hàn giới nhưng đều bị Bảo Hoa từ chối. Thiên Âm lôi hạch khiến cả Bảo Hoa lẫn Nguyên Yểm biến sắc, song Bảo Hoa xác nhận đây vẫn không phải vật mình cần, còn Hàn Lập nhờ phản ứng của họ mà biết thêm lai lịch linh dược. Những vật tiếp theo, gồm một đóa bạch hoa bí ẩn, đều không được hai vị Thánh Tổ nhận ra. Cuối cùng, Hàn Lập đưa ra một gốc linh thảo màu bạc nhạt khiến Bảo Hoa và Nguyên Yểm đồng thời thất thanh, khép lại chương ở thời điểm lai lịch của nó vẫn chưa được tiết lộ."},{"chuong":2098,"tieuDe":"Ngân Bồng Tái Hiện","tomTat":"Nguyên Yểm nhận ra Luyện Ma Thảo trong tay Hàn Lập và lập tức ra tay cướp đoạt, nhưng bị Hàn Lập chặn lại trong một lần đối quyền chưa phân cao thấp. Hàn Lập tiếp đó vận dụng Nhị niết biến thân, hóa thành hình thái hai đầu bốn tay và khiến Nguyên Yểm sinh lòng kiêng kỵ. Bảo Hoa tiết lộ Luyện Ma Thảo là linh dược thượng giới, đặc biệt quan trọng đối với bước cuối cùng của Nguyên Yểm, khiến hắn sẵn sàng đe dọa liều cả chủ mạng nguyên thần trước khi chuyển sang thương lượng. Hàn Lập sau đó lấy ra một ngân sắc đài sen nằm trong linh tuyền trắng ngà, khiến Bảo Hoa vui mừng và mất vẻ bình thản. Bảo Hoa đề nghị dùng khẩu quyết công pháp, đan dược hoặc nhiều loại chân linh huyết để trao đổi, nhưng Hàn Lập từ chối những loại không phù hợp. Cuối cùng, Hàn Lập cho biết mình vào Ma giới để tìm hai loại linh vật và sẽ giao linh dược nếu Bảo Hoa giúp hắn đạt được mục đích."},{"chuong":2099,"tieuDe":"Thái Hư Diệu Linh Đan","tomTat":"Hàn Lập xác nhận vẫn muốn tiến vào Tẩy Linh Trì và dùng Tịnh Linh Liên để tìm cơ hội đột phá Đại Thừa. Bảo Hoa cảnh báo chưa đến một phần mười số người từng sử dụng hai linh vật này thành công, còn người thất bại tuy nhận được lợi ích nhất thời nhưng về sau sẽ mất hy vọng bước vào Đại Thừa. Sau khi kiểm tra nước suối và xác nhận linh dược mình tìm kiếm, nàng trao cho Hàn Lập một ngọc giản ghi những phương pháp hóa giải hậu hoạn. Các phương án trong đó đều đòi hỏi bảo vật Tiên giới hoặc nguyên liệu Chân Linh gần như không thể tìm được, nhưng Hàn Lập phát hiện Hư Linh Đan mình giữ từ Quảng Hàn giới chính là Thái Hư Diệu Linh Đan, có một nửa khả năng giúp tránh tai họa ngầm. Nhờ đó, hắn quyết định giữ nguyên kế hoạch tiến vào Tẩy Linh Trì. Hàn Lập hứa giao thứ Bảo Hoa cần và Luyện Ma Thảo cho Nguyên Yểm sau khi trở ra, đồng thời tuyên bố sẽ hủy cả hai loại linh dược và giao chiến nếu hai Thủy Tổ không chấp thuận."},{"chuong":2100,"tieuDe":"Thánh Giới Đại Kiếp Nạn","tomTat":"Nguyên Yểm uy hiếp sẽ đón lõng Hàn Lập ngoài Lôi Hải hoặc dùng siêu cấp pháp trận xóa sổ Khổ Linh đảo, nhưng Hàn Lập bình tĩnh đáp rằng hắn có thể ở lại vạn năm và sẽ hủy toàn bộ linh dược nếu bị ép. Bảo Hoa can thiệp, phân tích lợi hại và khiến Nguyên Yểm chấp nhận để Hàn Lập vào Tẩy Linh Trì trước rồi mới giao Luyện Ma Thảo cùng linh dược. Dù yêu cầu hai Thánh tổ phát tâm ma thệ không thành, Hàn Lập vẫn chấp nhận lời cam đoan không chủ động ra tay, giải trừ Niết Bàn nhị niết rồi bước vào pháp trận bên hồ. Pháp trận truyền tống hắn tới Tẩy Linh Trì, một không gian thần bí dưới đảo có linh khí tinh thuần nhưng bài xích sinh linh, khiến hắn chỉ có thể lưu lại tối đa ba ngày. Sau đó, Bảo Hoa tiết lộ mình từng là một trong ba Thủy tổ Ma tộc và đã bị Lục Cực thay thế khi bà dồn tâm sức ứng phó đại kiếp nạn Thánh Giới. Bà tuyên bố sẽ rời Thánh Giới sau khi lấy được linh dược, đồng thời nhận định Hàn Lập sở hữu Niết Bàn Thánh Thể cùng Huyền Thiên Chi Bảo nên rất khó bị giữ lại nếu quyết tâm đào thoát. Cuộc đối thoại cuối cùng hé lộ Ma tộc đang cưỡng chiếm và ma hóa một phần Linh giới để di chuyển toàn bộ tộc nhân khỏi đại kiếp nạn, nhưng chiến sự hiện vẫn giằng co trước liên minh các tộc Linh giới."},{"chuong":2101,"tieuDe":"Dò Xét Hồ","tomTat":"Bảo Hoa cảnh báo Nguyên Yểm không nên xem thường các tồn tại Đại Thừa tại Linh giới, đồng thời nêu nghi vấn về các đời Linh vương và quan hệ giữa Linh tộc với Chân Tiên Giới. Cuộc đối thoại chuyển sang Thủy Ấn chi địa, nơi phong ấn đã suy yếu và sinh vật bí ẩn từng thức tỉnh lần thứ hai, buộc Niết Bàn phải thi triển biến thân tam niết để đánh tới lưỡng bại câu thương rồi chìm vào ngủ say. Nguyên Yểm hé lộ sinh vật ấy có thể đạt sức mạnh sánh với Chân Tiên trong lần thức tỉnh kế tiếp, vì vậy Ma tộc xâm lấn Linh giới để chiếm một địa bàn làm đường lui. Nội bộ Ma giới cũng bị chia rẽ khi Thú Tôn điện được Thiên Khấp, Hạc Nhan cùng một số Thánh Tổ chống lưng. Ở không gian bí cảnh, Hàn Lập tìm thấy hồ nước bạc được tạo thành từ linh khí tinh thuần hóa lỏng và suy đoán đây là Tẩy Linh Trì, nhưng chưa phát hiện Tịnh Linh Liên. Thần niệm và Minh Thanh Linh Mục đều không thể xuyên sâu qua lớp bạch quang trong hồ, nên hắn đưa phân thần vào khôi lỗi Thanh Lang rồi điều khiển nó lặn xuống dò xét."},{"chuong":2102,"tieuDe":"Tịnh Linh Liên","tomTat":"Hàn Lập để phân niệm bám vào khôi lỗi cự lang và điều khiển nó thăm dò hồ nước bạc, nhưng áp lực cùng lực trói buộc tăng mạnh khiến khôi lỗi không thể xuống đáy. Hắn đổi sang thả hàng trăm Phệ Kim Trùng trưởng thành, nhờ đó tìm thấy bảy gốc Tịnh Linh Liên dưới lớp cát trắng, trong đó có một đóa đã nở hoàn toàn và mang dược hiệu thần kỳ. Sau một thời gian ngâm trong linh thủy, đàn trùng trở nên kích động và xuất hiện những sợi tơ trắng cực nhỏ trên giáp xác, cho thấy Tẩy Linh Trì đang kích phát một lần biến dị mới. Tuy nhiên, Hàn Lập thu chúng trở lại Linh Thú Hoàn vì muốn dành năng lượng trong hồ cho việc tẩy tủy và tiến giai Đại Thừa. Hắn gọi Báo Lân Thú ra canh phòng, để đệ nhị Ma Anh nhập vào Chi Tiên linh khu rồi tới khu rừng lân cận hỗ trợ cảnh giới. Sau khi dựng thêm ba tòa pháp trận bao phủ linh trì để đề phòng kẻ địch xâm nhập, Hàn Lập mới hạ xuống hồ."},{"chuong":2103,"tieuDe":"Thoát Thai Hoán Cốt","tomTat":"Hàn Lập chìm xuống đáy Tẩy Linh Trì, dùng tơ xanh cắt Tịnh Linh Liên rồi thu nguyên vẹn đóa hoa vào hộp ngọc. Hắn phá bỏ màn sáng hộ thể, để nước hồ rót linh lực vào kinh mạch và vận chuyển Phạm Thánh Chân Ma Công nhằm luyện hóa một phần linh lực thành pháp lực, trong khi năng lượng thần kỳ của hồ bắt đầu cải tạo toàn thân. Sau gần nửa ngày chịu đau đớn, hắn nuốt cánh sen đầu tiên nhưng dược lực quá mạnh khiến hắn hôn mê hơn hai canh giờ; lúc tỉnh lại, da thịt, huyết nhục và xương cốt đều đã biến đổi rõ rệt. Hàn Lập tiếp tục dùng cánh sen thứ hai, và sau hai ngày hai đêm, Tẩy Linh Trì xuất hiện vòng xoáy bạc, phù văn tím, mây ngũ sắc cùng cột sáng tím phá hủy điện hồ năm màu. Khi rời khỏi hồ, hắn đã hoàn tất dịch kinh tẩy tủy, thân hình cao và rắn chắc hơn, da thịt óng ánh như ngọc. Chỉ bằng lực lượng thân thể, hắn nghiền khối đá xanh thành bụi và tạo một hố lớn khoảng mười trượng, sau đó thử thêm pháp lực khiến sóng hồ dâng cao năm sáu trượng."},{"chuong":2104,"tieuDe":"Thôn Phệ","tomTat":"Hàn Lập hoàn tất quá trình tẩy kinh dịch tủy trong Tẩy Linh Trì, xác nhận pháp lực tăng đáng kể, còn thần niệm và Nguyên Anh đều lớn mạnh thêm ba phần. Hắn cho Báo Lân Thú, Chi Tiên Linh Khu, Khúc Nhi và hơn mười Tử Văn Phệ Kim Trùng xuống hồ để cùng hưởng cơ duyên, đồng thời thả hàng vạn Phệ Kim Trùng trưởng thành đi thôn phệ linh thảo, linh mộc và linh quáng trong toàn bộ không gian. Sau khi bầy trùng biến nơi đây thành hoang địa, Hàn Lập phục dụng Hư Linh Đan để giảm nguy cơ từ Tịnh Linh Liên và bước đầu xác nhận dược lực phù hợp với tình trạng của mình. Hắn tiếp tục cho đàn trùng xuống Tẩy Linh Trì, rồi dùng hồ lô vàng thử thu nước hồ nhưng phát hiện linh thủy lập tức biến thành nước thường khi rời khỏi vị trí này. Gần hết thời hạn ba ngày, Hàn Lập quan sát những hình vẽ giống thượng cổ văn tự trên vách đá nhưng quyết định không mạo hiểm lưu lại lâu hơn. Trước lúc rời đi, hắn thu Báo Lân Thú, Chi Tiên Linh Khu và Khúc Nhi, sau đó thúc toàn bộ trùng vân cùng hơn mười Tử Văn Phệ Kim Trùng lao xuống hồ. Chỉ một lát sau, một cảnh tượng kinh người bắt đầu xuất hiện trong Tẩy Linh Trì."},{"chuong":2105,"tieuDe":"Song Bình","tomTat":"Hàn Lập cho hơn vạn Phệ Kim Trùng vừa ngâm mình vừa nuốt nước Tẩy Linh Trì, khiến mực hồ giảm mạnh trước khi ổn định trở lại. Lặn xuống đáy hồ, hắn phát hiện một pháp trận đá không trọn vẹn đang bảo vệ lỗ thủng liên tục phun ra linh thủy. Kiếm quang, hỏa cầu bạc và Phệ Kim Trùng thông thường đều không phá được màn sáng năm màu, trong khi những vết cắn của hậu tuyển Trùng Vương nhanh chóng bị cấm chế tự tu bổ. Hàn Lập cân nhắc sử dụng Huyền Thiên chi kiếm nhưng quyết định bảo toàn nguyên khí để chuẩn bị đối phó hai đại Thủy Tổ Ma tộc, rồi kích hoạt truyền tống trận rời khỏi không gian. Sau khi hắn biến mất, một bình nhỏ vàng sẫm có hoa văn xanh lá trôi ra từ nguồn nước, hiện đôi mắt đen với vẻ thất vọng rồi quay lại lỗ thủng trước khi mọi dấu tích xung quanh tan biến. Trở về Khổ Linh Đảo, Hàn Lập phát hiện bình nhỏ thần bí màu xanh của mình đang phát ra một tầng thúy mang khác thường. Dị tượng nhanh chóng biến mất, khiến hắn chưa thể xác định nguyên nhân và lập tức cất bình khi nhận ra động tĩnh từ xa."},{"chuong":2106,"tieuDe":"Thoát Thân","tomTat":"Hàn Lập giữ lời giao linh dược thật cho Bảo Hoa và Nguyên Yểm, nhưng bí mật lưu hai tia phân niệm tạm thời trên thuốc. Hắn tuyên bố phân niệm chỉ tự tiêu tán khi mình bình an rời khỏi Lôi Hải, còn nếu bị ngăn cản thì chúng có thể tự bạo và làm tổn hại linh dược. Vì Luyện Ma Thảo quá quan trọng, Bảo Hoa và Nguyên Yểm không dám đánh cược dù đều có khả năng thử khu trừ thủ đoạn này, nên buộc phải để Hàn Lập rời đi. Hắc Ngạc xin bám theo nhưng bị Bảo Hoa ngăn lại vì thần thức của Hàn Lập đủ sức nhìn thấu Ẩn Nặc Thuật. Sau đó, Bảo Hoa và Nguyên Yểm thừa nhận Hàn Lập đã nắm đúng nhược điểm khiến họ bó tay. Đúng lúc hai người chờ phân niệm tiêu tán, Niết Bàn bất ngờ truyền âm, tuyên bố sẽ chặn Hàn Lập và thu lấy toàn bộ những linh dược khác trên người hắn."},{"chuong":2107,"tieuDe":"Lại Thấy Ngụy Tiên Lộ","tomTat":"Bảo Hoa và Nguyên Yểm nhận định người chặn đường Hàn Lập là một hóa thân của Niết Bàn, đồng thời lo hắn bị ép đến mức dẫn nổ phân niệm trên linh dược. Bảo Hoa tiết lộ nàng và Niết Bàn từng đoạt được hai giọt Tham Thiên Tạo Hóa Lộ pha loãng, trong đó phần của Niết Bàn có thể dùng để đánh thức Ngụy Tiên Bảo. Trong lúc đó, Hàn Lập vận dụng phi kiếm, kim hồ hộ thể, hai ngọn núi nhỏ và nhục thân đã được Tẩy Linh Trì cường hóa để nhanh chóng vượt lôi hải. Khi hắn sắp thoát khỏi khu vực, điện hồ đồng loạt bị thu lên trời, Hoàng Kim Bàng Giải xuất hiện cùng một hóa thân trung niên mặc kim bào của Niết Bàn. Niết Bàn rót Ngụy Tạo Hóa Lộ vào cự giải, khiến nó thức tỉnh và xác nhận sẽ toàn lực xuất thủ hai lần theo quy định cung phụng. Vì căm thù người Linh giới, Niết Bàn ra lệnh giết Hàn Lập. Hoàng Kim Bàng Giải lập tức biến càng thành kéo vàng khổng lồ, bất ngờ khóa Hàn Lập từ hai phía bằng đòn tấn công đầu tiên."},{"chuong":2108,"tieuDe":"Thánh Giải Chi Uy","tomTat":"Hoàng Kim Cự Giải phát ra hai luồng kim quang từ kéo vàng, buộc Hàn Lập dùng Huyền Thiên chi kiếm cùng nhiều lớp phòng ngự để chống đỡ. Khi phòng tuyến bị xuyên thủng, hắn tiêu hao phân nửa máu huyết kích phát hóa kiếp khôi lỗi luyện từ Khấp Linh Huyết Mộc, nhờ đó tránh được đòn chí mạng. Thánh Giải lập tức nâng công kích lên mười hai thành thần thông và ngưng tụ một khối cầu phù văn vàng khổng lồ. Hàn Lập dung hợp Phạm Thánh Pháp Tướng cùng các pháp tướng Chân Long, Thải Phượng và Lôi Bằng để thi triển Nhị niết biến thân, khiến hóa thân của Niết Bàn Thánh tổ kinh hãi. Kiếm ảnh do một phần uy năng Huyền Thiên chi kiếm tạo thành dẫn động thiên địa nguyên khí, nhưng cuối cùng vẫn bị những hư ảnh kim văn chứa lực lượng pháp tắc đánh tan. Trước khi kim quang phủ kín phạm vi trăm dặm, Hàn Lập hóa thành đại bàng bốn cánh kim ngân và độn khỏi vị trí, còn hóa thân Niết Bàn tiếp tục quan sát khắp nơi để tìm hắn."},{"chuong":2109,"tieuDe":"Quay Giáo","tomTat":"Hàn Lập sống sót sau đòn toàn lực thứ hai của Hoàng Kim Cự Giải nhưng bị thương nặng, nguyên khí hao tổn và phong ấn trên cánh tay mang Huyền Thiên kiếm xuất hiện biến đổi. Người trung niên mặc kim bào lập tức truy sát, buộc hắn biến thành Ngũ Sắc Thải Phượng phá vỡ hư không né tránh. Qua công pháp đối phương thi triển và cuộc đối thoại, Hàn Lập xác định đây là hóa thân của Niết Bàn Thánh tổ. Hắn dùng Kim Thân cùng Linh khu do Khúc nhi thao túng chống các đoạn móng tay đen nhưng dần rơi xuống hạ phong. Thay vì thả Phệ Kim Trùng, Hàn Lập lấy một giọt lục dịch thần bí làm tế phẩm và đổi được ba lần xuất thủ của Hoàng Kim Cự Giải. Theo lệnh hắn, cự giải quay sang công kích hóa thân Niết Bàn, cắt nát Bạch Cốt Cự Phiên rồi bắn cột sáng kim sắc xuyên thủng lớp hắc phong bao quanh kẻ đang tháo chạy. Kết cục của hóa thân Niết Bàn và lần xuất thủ thứ ba vẫn chưa được xác định."},{"chuong":2110,"tieuDe":"Giải Đạo Nhân","tomTat":"Kim quang trong vết thương của hóa thân Niết Bàn Thánh Tổ bộc phát thành vô số kim ti, phá hủy cả thân thể lẫn Nguyên Anh của hắn. Sau khi xác nhận không có tàn hồn trốn thoát, Hàn Lập hỏi Hoàng Kim Cự Giải về nguồn gốc và biết nó là Ngụy Tiên Khôi Lỗi do thượng giới luyện chế, đã tự hình thành linh trí nhưng phải dựa vào Tiên Linh lực để hoạt động. Hai bên thỏa thuận Hàn Lập sẽ cung cấp một giọt Tạo Hóa Lộ mỗi tháng, còn mỗi lần khôi lỗi xuất thủ đều cần thù lao riêng. Hàn Lập dùng tinh huyết hoàn tất khế ước trên phiến đá ghi ngân khoa văn, sau đó Hoàng Kim Cự Giải hóa thành thanh niên mặc lục bào và tự xưng Giải Đạo Nhân. Hai người cùng rời Khổ Linh Đảo. Ở nơi khác, Nguyên Yểm tuy không trực tiếp truy sát Hàn Lập nhưng quyết định ban Diệt Tiên Lệnh để phong tỏa hắn trong Thánh giới, còn Bảo Hoa bắt đầu nghi ngờ Hàn Lập vẫn cất giấu một thủ đoạn bảo mệnh ngoài dự liệu."},{"chuong":2111,"tieuDe":"Nán Lại","tomTat":"Bảo Hoa quyết định rời Ma Nguyên Hải để tìm nơi an ổn luyện hóa đan dược, sau khi Hắc Ngạc báo rằng đã lưu huyết mạch ấn ký lên Tam Thủ Ma Giao của Nguyên Yểm. Bảy ngày sau, Thiên Khấp và bà lão áo hồng đến Khốn Linh Cốc, phát hiện khí tức Bảo Hoa và chuẩn bị huy động phân đàn Thú Tôn Điện giám sát các truyền tống trận để truy bắt nàng. Thiên Khấp nhắm đến Ngự Lôi Ký nhằm chuẩn bị vượt thiên kiếp, còn bà lão muốn báo thù vì từng bị Bảo Hoa hủy thân thể. Hai người cũng nhận ra Hoàng Kim Cự Giải đã biến mất khỏi lôi hải và liên hệ chuyện này với tu sĩ Hợp Thể Nhân tộc bị nhắc trong Diệt Tiên Lệnh của Nguyên Yểm. Ở gần bờ Ma Nguyên Hải, Hàn Lập nhận thấy mình cần khoảng nửa năm tĩnh dưỡng mới có thể khôi phục trạng thái đỉnh phong. Nhờ Giải Đạo Nhân đi theo bảo vệ, hắn quyết định nán lại Ma giới và đến Lam Bộc Hồ thu thập Huyết Nha Mễ cùng Dị Ma Kim. Hàn Lập còn kiểm tra một con Phệ Kim Trùng trưởng thành bị thương nặng, trong khi Giải Đạo Nhân ngồi bất động trong khoang thuyền và được một nữ tử hoàng bào lén nhìn với vẻ e thẹn."},{"chuong":2112,"tieuDe":"Huyết Quang Vẫn Lạc","tomTat":"Một tháng sau khi Nguyên Yểm ban Diệt Tiên Lệnh, phần thưởng lớn khiến nhiều Thánh Tổ, hóa thân và Ma Tôn tham gia truy sát Hàn Lập, dù một số người biết nội tình vẫn án binh bất động. Giải Đạo Nhân lần lượt phá các vòng vây tại Phỉ Thúy Ma Thành và Thước Kim Hà Cốc, giết bốn Ma Tôn rồi tiêu diệt hóa thân Thiên Nha Thánh Tổ cùng hai kẻ truy bắt khác. Tại Trầm Thủy Trấn, Hàn Lập thi triển Nhị Niết biến thân, phối hợp với Giải Đạo Nhân đánh bản thể Huyết Quang trọng thương, đồng thời diệt hai hóa thân và toàn bộ thuộc hạ của hắn. Huyết Quang chạy thoát khỏi chiến trường nhưng bị Xa Kỵ Cung và Phong Tà bắt giữ, phá hủy thân thể rồi giam nguyên anh trong Luyện Hồn Đỉnh để tra khảo vị trí động phủ bí mật. Hắn kiên quyết không giao kho báu, buộc Xa Kỵ Cung tăng cường cực hình luyện phách. Tin Huyết Quang mất thân thể khiến các Thánh Tổ khác sợ bị cừu nhân thừa cơ tập kích, làm cuộc truy sát Hàn Lập trên thực tế tan rã. Ở một nơi khác trong Ma giới, Bảo Hoa và Hắc Ngạc bị hơn trăm Ma tộc song giác thân đỏ đồng loạt dùng lệnh bài đen phóng quang cầu vây công."},{"chuong":2113,"tieuDe":"Huyền Thiên Thánh Thụ","tomTat":"Hắc Ngạc một mình chống lại khoảng năm trăm ma tộc hai sừng, giết sạch chúng nhưng cũng bị quang cầu xuyên qua ma giáp, cạn pháp lực và ngất xỉu khi vẫn cố che chắn cho Bảo Hoa. Bảo Hoa biến hắn về hình dạng cá sấu nhỏ rồi thu vào tay áo, sau đó buộc Thiên Khấp và Hạc Nhan đang ẩn nấp phải hiện thân. Hạc Nhan muốn báo thù chuyện năm xưa, còn Thiên Khấp cầu mượn Ngự Lôi Thiêm để tăng cơ hội vượt qua thiên kiếp sắp tới. Bảo Hoa hứa cho hắn mượn bảo vật một vạn năm nếu có thể đỡ được một kích của nàng. Nàng triệu ra Huyền Thiên Thánh Thụ đã dung hợp với thân thể và triển khai Huyền Thiên Hoa Giới, khiến phạm vi ngàn trượng biến thành một thiên địa riêng biệt. Nhận ra Bảo Hoa đã luyện thành Huyền Thiên Lĩnh Vực, Thiên Khấp và Hạc Nhan lập tức tháo chạy bằng hai phương thức khác nhau. Bảo Hoa tuyên bố họ đã chạy quá muộn, ngắt một bông hoa từ thánh thụ rồi ném vào hư không để phát động đòn truy kích."},{"chuong":2114,"tieuDe":"Lam Bộc Hồ","tomTat":"Bảo Hoa vận dụng Huyền Thiên Linh Vực phá đường thoát của Hạc Nhan và đưa Thiên Khấp trở lại khu vực bị hoa ảnh vây kín, đồng thời cắt đứt khả năng vay mượn thiên địa nguyên khí của cả hai. Hạc Nhan dùng quải trượng hóa bạch hạc và gọi ra mặt quỷ phun ma phong, còn Thiên Khấp hóa thành ma sư huyết hồng rồi triển khai huyết sắc vụ hải để phản công. Bảo Hoa biến hơn trăm đóa hoa thành biển ma diễm, buộc hai Thánh tổ phải uống đan dược kích thích tiềm lực để chống đỡ suốt bảy ngày. Khi Hoa giới xuất hiện bất ổn, Thiên Khấp và Hạc Nhan bỏ lại thân thể đã bị luyện thành tro, lần lượt thoát đi dưới dạng huyết quang và nữ anh. Cuộc giao chiến khiến thương thế của Bảo Hoa chuyển biến nghiêm trọng, buộc nàng phải trở về Linh giới và dự tính mất hai ba trăm năm mới khôi phục thần thông. Trong khi đó, Hàn Lập cùng Huyền Thiên và Chu Quả Nhi tới Lam Bộc hồ; dù biết nơi này thuộc địa bàn của Lam Thác Thánh tổ, hắn vẫn quyết định tiến vào vì bắt buộc phải lấy Huyết Nha Mễ."},{"chuong":2115,"tieuDe":"Nhập Hồ","tomTat":"Lo ngại mình đã bị Ma tộc nhận diện sau những biến động trước đó, Hàn Lập quyết định cả nhóm cải trang và tạm thời chia nhau hành động. Hắn giao Chu Quả Nhi cho Giải Đạo Nhân, còn bản thân biến thành một trung niên nam tử nho nhã rồi tiến vào Lam Bộc hồ để dò xét Lam Bộc thành. Dù không bị đại hình cấm chế cấm không trong hồ hạn chế, Hàn Lập vẫn đáp xuống một tiểu đảo và thuê thuyền nhằm tránh gây chú ý. Người chèo thuyền Quan Ương dùng đôi mái chèo ma khí gia truyền đưa hắn đi nhanh qua hồ, đồng thời giải thích các quy định mua Huyết Nha mễ. Hàn Lập biết giao dịch công khai bị giới hạn nghiêm ngặt và loại thượng phẩm gần như không chảy ra ngoài, nhưng vẫn tin rằng có thể tìm được cách nếu trả đủ giá. Sau hai canh giờ, thuyền tới đảo lớn có Lam Bộc thành xây bằng đá lam, nơi nhiều Ma tộc vũ trang đang canh giữ đại môn."},{"chuong":2116,"tieuDe":"Hắc Sa Nữ Tử","tomTat":"Quan Ương dựa vào quan hệ với thủ vệ để đưa Hàn Lập vào Lam Bộc thành mà không bị kiểm tra, sau đó kín đáo chỉ điểm hắn đến Nghiễm Nguyên trai. Trên đường đi, Hàn Lập nhận thấy trong thành tập trung nhiều tu sĩ cao giai và thoáng thấy một nữ tử che hắc sa có bóng lưng giống người quen, nhưng hắn tự phủ nhận vì khí tức khác biệt rồi niệm Luyện Thần quyết để ổn định tâm cảnh. Ở một cửa hàng khác, hắc sa nữ tử được gọi là Thất tiểu thư dẫn thuộc hạ đến nhận hàng và bất ngờ kiểm tra sổ sách. Mộ Tịch, người giả làm tiểu nhị, đưa ra cuốn sổ giao dịch thật chứng minh Liêu chưởng quầy đã tham ô trong nhiều thập niên. Liêu chưởng quầy dùng phù lục độn thổ bỏ trốn nhưng bị Thạch Hoả khống chế, sau đó bị hắc sa nữ tử bắn hắc mang xuyên qua mi tâm giết chết. Mộ Tịch được bổ nhiệm làm chưởng quản mới, còn Thạch Hoả thiêu thi thể Liêu chưởng quầy thành tro. Hàn Lập cuối cùng đến Thiên Hải các và phát hiện bên trong lầu các là một tiểu Tu Di không gian rộng vài mẫu, qua đó xác nhận quy mô lớn của cửa hàng."},{"chuong":2117,"tieuDe":"Thu Mua","tomTat":"Hàn Lập tới Thải Hiên Các, để lộ linh áp tương đương Luyện Hư hậu kỳ và được đại trưởng quầy Hiếu Nhan đích thân tiếp đãi. Hắn hỏi mua lượng lớn Dị Ma Kim cùng Huyết Nha Mễ, nhưng được biết Huyết Nha Mễ bị thành chủ kiểm soát chặt chẽ về sản lượng và danh sách người mua. Hàn Lập mua sạch hơn trăm khối Dị Ma Kim của cửa hàng rồi dành bảy ngày ghé gần hết các cửa hàng lớn nhỏ trong Lam Bộc thành để tiếp tục thu gom. Dù bỏ ra lượng Ma Thạch rất lớn, hắn vẫn không tìm thấy khối Dị Ma Kim nào chứa năng lượng thần bí cần thiết. Hoạt động thu mua bất thường nhanh chóng lọt vào tai một số người có mạng lưới tin tức trong thành. Sang ngày thứ tám, một nam tử Ma tộc râu cá trê tìm gặp Hàn Lập, khẳng định đồng bạn đang có rất nhiều Dị Ma Kim và mời hắn tới Tiên Cư Lâu. Hàn Lập nhận lời, được đưa vào một gian phòng kín và gặp vài nam nữ Ma tộc xa lạ."},{"chuong":2118,"tieuDe":"Vô Ưu","tomTat":"Tại Lam Bộc thành, một thanh niên Ma tộc tự xưng Vô Ưu tiếp xúc Hàn Lập để thương lượng việc bán Dị Ma kim. Hàn Lập nhìn thấu tu vi Luyện Hư hậu kỳ đại thành của đối phương và nhận ra nguồn hàng có ẩn tình. Vô Ưu yêu cầu hắn phát tâm ma huyết thệ để giữ bí mật, đồng thời dọa dùng bí thuật xóa ký ức nếu giao dịch không thành, nhưng Hàn Lập kiên quyết không cho người khác can thiệp thần niệm. Sau một hồi trả giá, Hàn Lập nhận mua toàn bộ hơn hai nghìn miếng Dị Ma kim cực phẩm với giá bằng một nửa thị trường và hẹn giao hàng vào ngày hôm sau. Khi Hàn Lập rời đi, Vô Ưu cho thuộc hạ biết giao dịch đã thành, còn Thiết Hổ báo cáo rằng những người biết nội tình đã bị giết và mỏ quặng đã bị phong kín. Vô Ưu giải thích việc khai thác trái phép đã xâm phạm lợi ích của nhiều thế lực, buộc cả nhóm phải bán tháo khoáng thạch rồi lập tức bỏ trốn. Cuối cùng, y hé lộ rằng quá trình điều tra nguyên nhân mỏ xuất hiện nhiều khoáng thạch quý hiếm còn dẫn đến một tin tức bất lợi chưa được công bố."},{"chuong":2119,"tieuDe":"Quảng Nguyên Trai","tomTat":"Vô Ưu giải thích rằng nhóm của y đã đào lệch khỏi mỏ trung phẩm và vô tình xâm nhập cực phẩm khoáng mạch thuộc thành chủ Lam Bộc hồ. Trước sức mạnh của thế lực thành chủ và chỗ dựa Lam Bộc Thánh tổ, y quyết định bán rẻ khoáng thạch cho người ngoài để đổi lấy Ma Thạch rồi đưa cả nhóm đào thoát. Trong khi đó, Hàn Lập rời cửa đông Lam Bộc thành, đi vào khu rừng và tìm thấy lối dẫn đến Quảng Nguyên Trai. Linh áp hắn cố ý để lộ khiến người sàng lọc bí mật lập tức thông báo cho các chốt phía sau nhường đường. Tại tầng một của lầu các, Hàn Lập nhìn thấu Tứ Tượng Trận và phát hiện thêm sát trận bí mật, nhờ đó được Hi Nhi miễn thử thách tầng hai. Khi gặp Chu Di, hắn nhận ra nàng là Ma Tôn hậu kỳ đại thành, còn nàng cũng phát hiện hắn đang che giấu một phần tu vi. Chu Di cho Hi Nhi lui xuống và tự mình dẫn Hàn Lập lên gặp tiểu thư Quảng Nguyên Trai."},{"chuong":2120,"tieuDe":"Thiếu Nữ Áo Gai","tomTat":"Sau khi biết Hàn Lập che giấu tu vi, thiếu nữ áo lục rời tầng hai, còn Chu Di giải trừ cấm chế cầu thang và dẫn hắn lên trên. Tại tầng ba, Hàn Lập gặp một thiếu nữ áo vàng cùng tám Ma tộc trẻ tuổi, nhưng nhanh chóng nhận ra nàng chỉ là người thế thân dùng để tiếp khách thông thường. Chu Di tiếp tục đưa hắn lên tầng bốn, nơi một thiếu nữ áo gai đang dệt vải trong không gian mô phỏng nhà nông. Khi Hàn Lập dùng thần niệm dò xét, một lực vô hình từ bảo vật hộ thân của nàng lập tức đẩy thần niệm ra ngoài. Thiếu nữ áo gai tự xưng Lam Dĩnh, xác nhận mình là người chủ trì Quảng Nguyên Trai và giới thiệu các quy củ giao dịch tình báo của tổ chức. Nàng cho biết Quảng Nguyên Trai không trực tiếp can dự sự việc, có thể dùng bói toán để suy tính thông tin nhưng người thi triển sẽ hao tổn thọ nguyên. Hàn Lập hỏi cách thu được số lượng lớn thượng phẩm Huyết Nha Mễ tại Lam Bộc thành, và Lam Dĩnh xác nhận tổ chức có tin tức này nhưng giá bán không thấp."},{"chuong":2121,"tieuDe":"Gặp Lại Hồng Nhan","tomTat":"Hàn Lập kiểm tra phần tình báo do Lam Dĩnh cung cấp và quyết định mua phương thức liên lạc với người trong phủ thành chủ đang bí mật bán lượng lớn Huyết Nha Mễ. Sau khi ghi nhớ tin tức rồi phá hủy thạch giản, hắn đưa đoàn lục khí trong cơ thể ra nhờ nàng giám định. Dị lực lập tức khiến guồng quay tơ luyện từ Tiêu Ma Mộc hóa thành tro, còn Lam Dĩnh chỉ có thể xác nhận nó tương đồng với một thứ trong ký ức. Hàn Lập cho biết đoàn lục khí xuất hiện sau khi hắn hấp thu tinh cầu năng lượng trong Dị Ma Kim và hiện chỉ có thể bị tạm phong ấn trong Ma Anh. Cuộc giám định bị gián đoạn khi Tử Linh tới Quảng Nguyên Trai hỏi Lam Dĩnh về quẻ bói liên quan đến người nàng muốn gặp. Hàn Lập và Tử Linh nhận ra nhau, hắn khôi phục chân diện rồi trực tiếp chào hỏi cố nhân sau nhiều năm xa cách."},{"chuong":2122,"tieuDe":"Môn Hạ Của Lục Cực","tomTat":"Sương đen quanh thiếu nữ áo tím tan đi, giúp Hàn Lập nhận ra nàng chính là Tử Linh, hồng nhan cũ đã mất liên lạc từ thời Nhân giới. Trong lúc vui mừng đoàn tụ, hắn cũng cảnh giác với Lam Dĩnh và Chu Di vì hai người đã biết thân phận Nhân tộc của mình. Tử Linh bảo đảm Lam Dĩnh là tri kỷ đáng tin, đồng thời tiết lộ Quảng Nguyên Trai chỉ là một chi nhánh trong hệ thống thế lực hoạt động tại nhiều giới diện. Sau khi lui xuống tầng năm, Lam Dĩnh và Chu Di nhận định Hàn Lập cực kỳ nguy hiểm nhưng vẫn đáng để Quảng Nguyên Trai bỏ ra lợi ích lớn nhằm lôi kéo. Hàn Lập xác nhận phần lớn những biến động gần đây tại Ma giới có liên quan tới mình, song nói rõ hắn không thể trực tiếp khống chế Cự Giải khôi lỗi. Tử Linh cho biết nàng đã cải tu ma công, đạt Luyện Hư hậu kỳ và được chuẩn bị đầy đủ tài nguyên để tiến vào Hợp Thể kỳ. Cuối cùng, nàng tiết lộ mình chỉ là đệ tử thứ bảy trên danh nghĩa của Lục Cực Thánh Tổ và thực chất đang bị đối phương chuẩn bị làm hóa thân, khiến Hàn Lập kinh hãi hỏi về cấm chế khống chế."},{"chuong":2123,"tieuDe":"Kiếp Nạn Của Tử Linh","tomTat":"Tử Linh giải thích với Hàn Lập rằng nàng tu luyện công pháp Ma đạo do Lục Cực sáng tạo nên pháp lực có thể bị vị Thủy Tổ này khống chế chỉ bằng một ý niệm. Nàng kể lại quãng thời gian mắc kẹt ở Nguyên Anh Kỳ tại Nhân giới, vô tình khởi động tế đàn Cổ Ma rồi nhờ thần niệm Lục Cực chỉ dẫn dùng Chân Ma Khí quán thể, cải tu ma công và tiến vào Hóa Thần Kỳ. Sau khi phi thăng Ma giới, Tử Linh mới biết Xá Nữ Tố Âm Chi Thể của mình được Lục Cực nhắm tới để chuẩn bị một hóa thân, buộc nàng phải chọn giữa mất tu vi và trở thành đệ tử thứ bảy kiêm hóa thân dự bị. Hàn Lập thông cảm cho tình cảnh ấy và hứa sau khi tiến vào Đại Thừa Kỳ sẽ đến Ma giới mặc cả với Lục Cực để giải phóng nàng. Hai người tiếp tục trao đổi hành trình đã qua, trong đó Tử Linh tiết lộ mình từng cứu Lam Dĩnh nên được đối phương xem như tỷ muội. Tử Linh cũng cho biết Quảng Nguyên Trai đã suy yếu nghiêm trọng sau cái chết của cựu trai chủ và nhiều cao giai hộ pháp, hiện chỉ còn Lam Dĩnh cùng Chu Di miễn cưỡng duy trì. Sau gần nửa ngày trò chuyện và ân ái, Lam Dĩnh lên tiếng báo giờ đóng cửa, tiễn khách và hỏi Hàn Lập còn điều gì cần giải đáp hay không."},{"chuong":2124,"tieuDe":"Đại Âm Dương Ngũ Hành Chân Quang","tomTat":"Sau khi Tử Linh thu hồi cấm chế, Lam Dĩnh cùng Chu Di xuống gặp Hàn Lập và bắt đầu giám định lục khí thần bí trong cơ thể hắn. Lam Dĩnh xác định đây là Địa Sát Âm Khí biến dị từ Đại Âm Dương Ngũ Hành Chân Quang, đồng thời cảnh báo nó sẽ khiến kinh mạch và cơ bắp của tu sĩ Nhân tộc dần khô cứng. Qua lời Lam Dĩnh và Tử Linh, Hàn Lập biết Đại Âm Dương Ngũ Hành Chân Quang còn được gọi là Vạn Pháp Chi Mẫu, từng kết hợp với Thông Thiên Ma Công để tạo nên uy lực kinh người cho một Thủy Tổ thời thượng cổ. Hắn nhận ra Chân Quang này tương ứng với Chân Quang Sơn trong Nguyên Hợp Ngũ Cực Sơn, từ đó quyết định lưu lại Ma giới để tìm kiếm. Lam Dĩnh cho biết khẩu quyết luyện hóa sát khí đang nằm trong tay một lão quái vật Hợp Thể Hậu kỳ và nhận lời liên hệ giúp hắn. Đổi lại, Hàn Lập đồng ý trợ giúp cá nhân Lam Dĩnh trong phạm vi khả năng. Cuối cùng, Lam Dĩnh tiết lộ Quảng Nguyên Trai là thế lực hoạt động tại nhiều giới diện và có phương pháp xuyên giới, khiến Hàn Lập vô cùng kinh ngạc."},{"chuong":2125,"tieuDe":"Minh Trùng Mẫu","tomTat":"Hàn Lập hỏi Lam Dĩnh về phương tiện phá giới và được nàng hứa liên hệ người trong Quảng Nguyên Trai để chuẩn bị một bảo vật đặc biệt, dù vật này chỉ có thể sử dụng vài lần. Khi hắn dò hỏi nguyên nhân cuộc xâm nhập Linh giới, Lam Dĩnh viện quy định trung lập của Quảng Nguyên Trai và từ chối tiết lộ. Tử Linh chủ động kể rằng Minh Trùng Mẫu là trùng chúa có thực lực ngang Chân Tiên, từng hủy diệt nhiều giới diện trước khi bị hai Chân Tiên dẫn tới Ma giới, đánh trọng thương và phong ấn. Nàng còn cho biết Phệ Kim Trùng cùng một số hung trùng hiện tại có thể mang huyết mạch của Minh Trùng Mẫu. Hơn vạn năm trước, trùng chúa đã tỉnh lại, sinh thêm con cháu và bắt đầu phá phong ấn, khiến Tam đại Thủy Tổ phải dồn phần lớn sức lực đối phó. Việc Ma giới xâm chiếm Linh giới là một biện pháp cuối cùng trước đại kiếp, trong khi Linh giới cũng có thể trở thành mục tiêu kế tiếp nếu Ma giới bị hủy. Hàn Lập quyết định sau khi trở về Nhân tộc sẽ báo tin cho các tu sĩ Đại Thừa, rồi cùng Tử Linh lên xe về thành để tiếp tục thương lượng."},{"chuong":2126,"tieuDe":"Trộm Mỏ","tomTat":"Trên đường trở về Lam Bộc Thành, Hàn Lập nhờ Tử Linh dựa vào đầu mối của Lam Dĩnh để khẩn cấp điều tra Vô Ưu. Sáng hôm sau, hắn gặp nhóm Vô Ưu, kiểm tra lượng lớn Dị Ma Kim thượng phẩm rồi thanh toán đủ Ma Thạch theo thỏa thuận. Hàn Lập đề nghị trả thêm một phần ba để mua vị trí nguồn quặng nhưng Vô Ưu từ chối vì sợ bí mật khai thác bị bại lộ. Sau khi hắn rời đi, Vô Ưu bác bỏ đề nghị bán thông tin về mỏ trộm và ra lệnh đồng bọn chia nhóm rời thành, sau đó hội họp tại Sư Nhai Thành. Kiểm tra kỹ lô hàng, Hàn Lập phát hiện hơn hai chục khối Dị Ma Kim biến dị hai màu đen trắng và tiết lộ mình đã bí mật lưu dấu thần niệm trên Vô Ưu. Hắn quyết định chờ cả nhóm ra khỏi thành rồi truy bắt và sưu hồn để lấy thông tin. Cuối cùng, thạch giản do một hắc giáp Ma tộc chuyển đến xác nhận nhóm Vô Ưu đang khai thác trộm mỏ, khiến Hàn Lập tin rằng đầu mối mình cần đã cơ bản nằm trong tay."},{"chuong":2127,"tieuDe":"Tin Tức","tomTat":"Tử Linh vận dụng thế lực tại Lam Bộc hồ để điều tra Vô Ưu và vụ khai thác trộm, sau đó nhanh chóng gửi kết quả cho Hàn Lập. Khi kiểm tra những dấu thần niệm đã bí mật lưu lại, Hàn Lập phát hiện phần lớn nhóm Vô Ưu đã rời Lam Bộc thành nhưng đôi vợ chồng phụ trách khai thác lại đang tìm đến khách sạn của hắn. Hai người tiết lộ rằng chính họ đã phát hiện Dị Ma Kim tại nơi sâu nhất của khoáng mạch sau hơn trăm năm khai thác trộm, đồng thời tố cáo Vô Ưu định dùng họ làm kẻ gánh tội. Hàn Lập hỏi kỹ vị trí, bí mật dùng bí thuật phân tích thật giả để xác nhận lời khai rồi giao vòng trữ vật chứa đủ số ma thạch đã hứa. Hắn không dùng Sưu Hồn Thuật vì lo hành động bắt người trong khách sạn sẽ kinh động tu sĩ Ma tộc cao giai hoặc cấm chế tại đây. Sau khi nhận tiền, đôi vợ chồng quyết định tách khỏi nhóm Vô Ưu, đổi đường rời Lam Bộc hồ, còn Hàn Lập lập tức chuẩn bị tới khu mỏ để trực tiếp kiểm chứng tin tức."},{"chuong":2128,"tieuDe":"Người Đào Quặng Thuê (1)","tomTat":"Hàn Lập rời khách sạn, đi xe kéo về phía cửa thành rồi bay suốt ba ngày qua một dãy núi xanh sẫm để tìm đến ngọn núi cao vạn trượng có hình dáng như một thanh cự kiếm. Sau khi dùng thần niệm dò xét bề mặt ngọn núi, hắn thi triển pháp quyết khiến vô số ký hiệu vàng hiện trên thân và trực tiếp tiến vào một đường hầm nằm sâu trong lòng núi. Trong bóng tối, Hàn Lập dùng quang cầu chiếu sáng và phát hiện những lá phù màu đen được ngụy trang trong khoáng thạch hoặc giấu sau lớp đá. Nhận ra các lá phù có liên hệ với nhau, hắn thu lấy chúng và dựa theo sự chỉ dẫn để đi xuyên qua mạng lưới đường hầm phức tạp. Sau ba bốn canh giờ tiến xuống, các nhánh rẽ cùng dấu vết khai thác dần thưa đi. Những mẩu khoáng thạch còn sót lại cho thấy khu vực sâu trong mỏ có chủng loại và phẩm chất vượt xa phần bên ngoài."},{"chuong":2129,"tieuDe":"Người Đào Quặng Thuê (2)","tomTat":"Hàn Lập dùng độn thuật xuyên qua đoạn đường hầm bị cố ý phá sập và phát hiện cặn Dị Ma Kim trong một lối đào mới. Khi dùng thần niệm dò xét vỉa quặng, hắn nhận ra phía trước có cấm chế ngăn cách và phát hiện ba quặng nô Ma tộc còn sống. Hàn Lập hứa cứu họ khỏi khu mỏ nếu họ thành thật cung cấp tin tức. Người quặng nô trung niên cho biết hơn một trăm người đã mất hai tháng khai thác nơi này, nhưng gần lúc hoàn tất thì vài người đột nhiên ngã xuống và hóa thành tro bụi. Hàn Lập dùng một sợi lục ti nghiền tảng đá thành bột để kiểm chứng và được xác nhận hiện tượng ấy rất giống cái chết của các nạn nhân. Sau đó, hắn yêu cầu ba người dẫn tới từng hiện trường tử vong và nghiêm giọng truy hỏi liệu Dị Ma Kim trong mỏ đã thực sự bị khai thác sạch hay chưa."},{"chuong":2130,"tieuDe":"Đấu Thú","tomTat":"Báo Lân Thú hóa ra hơn mười hư ảnh vây công Từ Quang Thú nhưng không thể gây thương tổn, trái lại còn bị các cột sáng năm màu phá hủy và khóa chặt chân thân. Hàn Lập dùng kiếm quang giải cứu tiểu thú, sau đó phóng lớn Nguyên Từ Cực Sơn để chặn cột sáng cùng mưa đá của đối phương. Hắn toàn lực thúc giục Nguyên Từ Thần Quang, tạo thành đám mây màu tro mang áp lực khủng bố hạ xuống cự thú. Từ Quang Thú làm thân thể trở nên trong suốt, kích hoạt khối đá xanh trong cơ thể và thi triển Đại Âm Dương Ngũ Hành Chân Quang, khiến hai loại thần quang đồng thời tiêu tán. Qua lần đối đầu, Hàn Lập nhận ra chân quang năm màu có đặc tính dung nhập vạn pháp và uy lực vượt Nguyên Từ Thần Quang một bậc. Vì càng ham muốn loại thần thông này, hắn hóa thành cự viên lông vàng, hiện pháp tướng ba đầu sáu tay rồi đồng thời phóng cột sáng đen và ném Nguyên Từ Cực Sơn tấn công. Từ Quang Thú lập tức thu nhỏ thân hình, thúc khối đá xanh sáng rực và ngưng tụ một vòng sáng như mặt trời năm màu để chuẩn bị chống trả."},{"chuong":2131,"tieuDe":"Thu Lấy Tinh Thể","tomTat":"Hàn Lập dùng ngọn núi nhỏ màu đen và các cột sáng đen xuyên thủng vầng sáng năm màu hộ thể của Từ Quang Thú, sau đó biến thành cự viên áp sát đối thủ. Từ Quang Thú ngưng tụ cây thương mang kỳ hàn để phản kích, nhưng bị ngân diễm hòa tan, còn khối đá trong cơ thể nó cũng bị Hàn Lập luyện hóa. Khi sức mạnh của con thú suy yếu, Hàn Lập trấn áp thân thể, đánh nát đầu và dùng kiếm khí tiêu diệt tinh hồn đang bỏ chạy. Khối đá xanh được nung thành một tinh thể xanh nhạt chứa lượng lớn tài liệu, khiến Hàn Lập dự định dùng nó luyện chế Đại Âm Dương Ngũ Hành Cực Sơn. Hắn thu Báo Lân Thú, thiêu hủy thi thể Từ Quang Thú rồi nhanh chóng rời xa chiến trường để tránh cao giai Ma tộc. Không lâu sau, Lam Bộc thánh tổ tới xem xét hiện trường, tiếp đó hóa thân Lục Cực đi kim thuyền xuất hiện và tuyên bố mang lợi ích tới cảm tạ sự giúp đỡ trước đây. Lời đề nghị ấy không khiến Lam Bộc vui mừng mà làm sắc mặt ả lập tức trở nên vô cùng khó coi."},{"chuong":2132,"tieuDe":"Âm Mưu Bí Mật","tomTat":"Phân thân Lục Cực báo cho Lam Bộc Thánh Tổ biết Bảo Hoa đã trở lại Thánh giới, từng dùng Huyền Thiên Linh Vực đánh hủy thân thể Thiên Khấp và Hạc Nhan. Nàng đề nghị Lam Bộc huy động hóa thân cùng môn hạ quanh Lam Bộc hồ truy tìm và vây giết Bảo Hoa, đổi lại Lam Bộc được giữ phần lớn chiến lợi phẩm cùng các bảo vật hỗ trợ độ kiếp. Lam Bộc chấp thuận sau khi yêu cầu được sao chép bí quyết Huyền Thiên Linh Vực, đồng thời thừa nhận đã bí mật bán Huyết Nha Mễ cho các thế lực khác để đổi tài nguyên và duy trì ổn định địa bàn. Lục Cực giải thích rằng bản thể đang bị đại kiếp nạn kiềm chế, còn phần lớn sáu đại hóa thân đều đã chết, bế quan hoặc đang đảm nhiệm nhiệm vụ khác. Sau khi Lam Bộc rời đi, Lục Cực kiểm tra mảnh thân thể Từ Quang Thú và nhận ra bản thể Đại Âm Dương Ngũ Hành Chân Quang đã hiện thế, nhưng tạm thời từ bỏ việc truy đoạt. Trên đường vòng trở về Lam Bộc Thành, Hàn Lập kiểm tra lượng Dị Ma Kim biến dị do khôi lỗi khai thác và xác định Địa Âm Sát Khí trong đó đủ giúp mình tiến tới Hợp Thể Hậu Kỳ đỉnh phong, tiết kiệm hơn ngàn năm khổ tu."},{"chuong":2133,"tieuDe":"Nước Chảy Ngầm","tomTat":"Hàn Lập trở lại Lam Bộc thành, dự định liên hệ Quảng Nguyên Trai để lấy phương pháp luyện hóa Địa Âm Sát Khí và nhanh chóng mua đủ Huyết Nha Mễ. Tử Linh bất ngờ tới báo rằng một hóa thân Hợp Thể hậu kỳ của Lục Cực đã đến Lam Bộc Hồ, triệu tập nàng cùng thuộc hạ và tìm kiếm một người chưa rõ danh tính. Để tránh khiến nàng bị phát hiện, Hàn Lập đề nghị hai người tạm ngừng liên hệ, đồng thời hứa sau khi tiến giai Đại Thừa sẽ trở lại Ma giới đưa nàng rời đi hoặc phá giới cứu nàng nếu nàng gặp nguy hiểm. Hai ngày sau, Hàn Lập gặp người mặc áo bào màu tro và chấp nhận mua lượng lớn Huyết Nha Mễ thượng phẩm với giá tăng hai thành. Sau khi hắn rời đi, người áo bào tro cùng Phương huynh tiết lộ họ từng cân nhắc tập kích khách mua nhưng từ bỏ vì e ngại thần thông, lai lịch và thế lực đứng sau Hàn Lập. Phương huynh sau đó cho biết mình vừa nhận lệnh triệu hồi của một lão thánh tổ và phải lập tức rời Lam Bộc thành."},{"chuong":2134,"tieuDe":"Lục Tuyệt Thanh Lôi Trận","tomTat":"Sau cuộc gặp kín kéo dài với Lam Dĩnh tại Quảng Nguyên Trai, Hàn Lập dùng căn phòng khách sạn làm bình phong rồi âm thầm rời Lam Bộc thành. Hắn hội hợp với Giải Đạo Nhân và Chu Quả Nhi, dùng phi xa rời Lam Bộc Hồ để tìm thông đạo bí mật trở về Linh giới. Trên đường đi, Hàn Lập nhớ tới Tử Linh và chấp nhận để nàng tạm ở lại Ma giới vì trở ngại từ Ma công do Lục Cực ép tu luyện. Phi xa sau đó lọt vào Lục Tuyệt Thanh Lôi Trận, một đại trận được che giấu tinh vi nhưng có phần khiếm khuyết. Theo chỉ dẫn của Giải Đạo Nhân, cả nhóm tiến thẳng tới trung tâm trận, trong khi Hàn Lập phá ảo thuật, bố trí trận kỳ và dùng Ích Tà Thần Lôi chống lại sương mù cùng thanh lôi. Khi họ đến gần trung tâm, thanh lôi và lôi cầu xanh xuất hiện ngày càng dày đặc. Từ vùng sương mù phía trước, một thiếu nữ chưa rõ danh tính lên tiếng ép Bảo Hoa chịu trói và đe dọa chỉ lưu lại cho nàng một đạo tàn hồn."},{"chuong":2135,"tieuDe":"Đại Chiến Trong Tuyệt Trận Thượng","tomTat":"Hàn Lập và Giải Đạo Nhân tiến vào trung tâm Lục Tuyệt Thanh Lôi trận, nơi Bảo Hoa cùng Hắc Ngạc đang chống đỡ vô số thanh lôi. Hàn Lập nhận ra thiếu nữ trẻ tuổi là hóa thân Lục Cực và xác định thiếu phụ áo lam chính là bản thể Lam Bộc Thánh Tổ. Hai nữ ma đầu đã bố trí đại trận chưa hoàn chỉnh để dụ Bảo Hoa vào bẫy, lợi dụng lúc nàng trọng thương và không thể tiếp tục vận dụng Huyền Thiên Hoa Thụ. Không muốn can dự vào cuộc giao tranh, Hàn Lập đề nghị được rời đi; Lam Bộc tuy muốn giết hắn nhưng kiêng dè Giải Đạo Nhân nên dùng trận kỳ mở một thông đạo an toàn. Khi Hàn Lập sắp ra khỏi trận, Bảo Hoa tiết lộ rằng nàng biết cách tìm Tiểu Linh Thiên và là người duy nhất có thể xác định vị trí nơi ấy. Vì mục tiêu tại Tiểu Linh Thiên có ý nghĩa cực kỳ quan trọng, Hàn Lập lập tức dừng lại và chất vấn nàng."},{"chuong":2136,"tieuDe":"Đại Chiến Trong Tuyệt Trận Trung","tomTat":"Hàn Lập không chấp nhận mạo hiểm chỉ dựa vào lời Bảo Hoa, buộc nàng phải đưa ra chứng cứ về khả năng tìm đường tới Tiểu Linh Thiên. Bảo Hoa giao cho hắn một khúc Thái Huyền Cương Mộc, còn Chu Quả Nhi xác nhận đây là thần mộc đặc hữu được hình thành trong hoàn cảnh đặc biệt tại quê hương mình. Hàn Lập sau đó bay khỏi thông đạo, còn Lam Bộc Thánh Tổ lập tức dùng trận kỳ đóng lối ra và cùng thiếu nữ đồng minh tổng công kích Bảo Hoa. Hắc Ngạc hóa thành cự ngạc, tạo ma xà chống sáu lôi giao nhưng nhanh chóng bị đánh tan và chịu thương tổn. Bảo Hoa dùng Chấn Nguyên Giản kiềm chế lôi giao rồi bất ngờ tự bạo chí bảo, phá hủy bàn tay bạc của ma tượng cùng đám lôi giao và buộc hai đối thủ phải tránh lui. Đúng lúc Lam Bộc và đồng minh chờ uy lực vụ nổ tiêu tán, một cột sáng vàng từ bên ngoài xuyên thủng cục bộ thế giới lôi điện. Bảo Hoa nhân cơ hội thu Hắc Ngạc vào quang hà, gọi ra hư ảnh hoa thụ màu hồng và rời khỏi tuyệt trận. Bên ngoài, Hàn Lập đứng cạnh Giải Đạo Nhân đã hiện nguyên hình cua vàng, xác nhận chính hắn đã yêu cầu khôi lỗi tung đòn toàn lực để cứu viện."},{"chuong":2137,"tieuDe":"Linh Vực Lại Xuất Hiện","tomTat":"Sau khi thoát khỏi pháp trận, Hàn Lập cảm tạ Giải Đạo Nhân, nhưng đối phương khẳng định chỉ trợ chiến đến khi lượng lục dịch đã nhận bị tiêu hao hết. Bảo Hoa trở lại trong trạng thái suy yếu và uống đan dược để khôi phục một phần pháp lực, trong khi thiếu nữ trẻ trung cùng Lam Bộc Thánh Tổ thoát khỏi biển sương rồi triển khai ma tượng, ma thú, băng sơn và cự quy. Hàn Lập biến thành cự viên lông vàng, gọi ra hai tòa núi, Phạm Thánh Kim Thân và Chi Tiên Linh Khu để bảo vệ Bảo Hoa. Hắn cự tuyệt đề nghị rút lui dù bị đe dọa sẽ phải nhận thêm lệnh truy sát của một Thủy Tổ. Lam Bộc Thánh Tổ dùng băng sơn cùng khí trắng của cự quy tạm thời vây khốn Giải Đạo Nhân, còn đồng bọn mở đợt công kích vào Hàn Lập và Bảo Hoa. Đúng lúc giao chiến bùng nổ, Bảo Hoa mở Huyền Thiên Linh Vực, biến phạm vi ngàn trượng thành biển hoa và làm toàn bộ băng sơn, tay bạc cùng tường lửa tan biến. Thiếu nữ trẻ trung kinh hoàng nhận ra linh vực của Bảo Hoa, khiến tương quan cuộc đối đầu lập tức thay đổi."},{"chuong":2138,"tieuDe":"Kinh Sợ Thối Lui","tomTat":"Bảo Hoa thừa nhận Thiên Hồn Đan đã kích phát tiềm lực, giúp nàng tái triển khai Huyền Thiên Linh Vực và dùng khả năng tung kích cuối cùng để uy hiếp Lam Bộc. Sau khi cân nhắc nguy cơ trọng thương, sự can thiệp của Hàn Lập và Giải Đạo Nhân cùng thiên kiếp sắp tới, Lam Bộc quyết định chấm dứt cuộc vây giết rồi rút khỏi chiến trường. Hóa thân thiếu nữ của Lục Cực bị bỏ lại nhưng được Bảo Hoa phóng thích theo đề nghị của Hàn Lập, vì hắn lo Tử Linh có thể bị bắt luyện thành hóa thân thay thế. Hàn Lập sau đó chỉ ra rằng Bảo Hoa có thể đã không còn sức tung thêm một kích, song nàng không xác nhận suy đoán ấy. Đoàn người lên phi xa rời đi, còn Bảo Hoa giao lại tư liệu về lối vào Tiểu Linh Thiên trước khi tách khỏi họ. Hàn Lập xác nhận tư liệu là thật, khiến Chu Quả Nhi có thêm hy vọng trở về quê hương, đồng thời giải thích rằng hắn không cưỡng ép giữ Bảo Hoa vì chưa chắc đối phó được những thủ đoạn bảo mệnh của một cựu Thủy Tổ Ma giới."},{"chuong":2139,"tieuDe":"Dị Biến Trong Thông Đạo","tomTat":"Hàn Lập giải thích với Chu Quả Nhi rằng việc thả Bảo Hoa là một mưu kế nhằm khiến Lam Bộc và Lục Cực ưu tiên truy sát nàng, qua đó giảm nguy cơ cho nhóm mình. Hắn lập tức thúc phi xa đưa Chu Quả Nhi và Giải Đạo Nhân rời khu rừng, tiếp tục tìm đường trở về Linh giới. Trong khi đó, Bảo Hoa cùng Hắc Ngạc hội hợp với một thuộc hạ cũ bí mật, rồi lên ma thuyền tới động phủ của người này để ẩn náu và điều dưỡng. Nửa ngày sau, Lam Bộc, hóa thân Lục Cực và những người đi cùng lần tới đỉnh núi; nhờ Nhiếp Linh Điêu, họ phát hiện ngoài Bảo Hoa và Hắc Ngạc còn có người thứ ba hỗ trợ. Phe truy sát quyết định điều tra những Ma tộc từng có quan hệ sâu với Bảo Hoa, đóng các truyền tống trận lân cận và trước tiên kiểm tra động phủ khả nghi tại Đồng La Sơn. Nửa năm sau, nhóm Hàn Lập tới một vùng đồi núi vàng và phát hiện tòa thành nhỏ tại mục tiêu đã được quân lính, ma vân cùng nhiều pháp trận bảo vệ nghiêm ngặt, trái hẳn thông tin trước đó."},{"chuong":2140,"tieuDe":"Xâm Nhập","tomTat":"Hàn Lập quan sát cứ điểm bảo vệ thông đạo và nhận ra hệ thống phòng thủ chỉ mới được tăng cường trong vài chục năm gần đây, vì vậy loại trừ khả năng Lũng Gia Lão Tổ cùng Linh Tộc đã chuẩn bị bẫy từ trước. Bất chấp đề nghị tìm đường khác của Chu Quả Nhi, hắn quyết định tiếp tục xâm nhập vì không muốn kéo dài thời gian. Giải Đạo Nhân nhận phá các pháp trận bằng một bí thuật phải tiêu hao gần nửa số cống phẩm và khiến tu vi của mình tạm giảm một cảnh giới. Khi kế hoạch bắt đầu, hắn dùng hai lệnh bài vàng bạc tạo thành trận mưa ký hiệu, tiêu diệt toán vệ sĩ cản đường và xuyên thủng phần lớn cấm chế quanh cứ điểm. Giải Đạo Nhân suy yếu nghiêm trọng sau khi ra tay, còn Hàn Lập lập tức điều khiển phi xa đưa cả nhóm lao qua lỗ hổng phòng tuyến. Các Ma tôn trấn giữ cứ điểm đồng loạt truy cản bằng nhiều loại công kích nhưng không thể buộc phi xa dừng lại. Tới trước lớp ma vân che phủ lối vào, Hàn Lập phóng lôi điện màu vàng đánh tan mây đen và mở ra một vùng trống trong hư không."},{"chuong":2141,"tieuDe":"Thuyền Lớn Trong Thông Đạo","tomTat":"Nhóm Hàn Lập điều khiển phi xa tiến vào trung tâm ma vân nhưng bị hai Ma tôn trấn giữ cửa thông đạo dùng hắc sắc lôi điện và kiếm quang màu xanh chặn lại. Sau khi hóa giải đợt công kích đầu tiên, Hàn Lập biến thành Sơn Nhạc Cự Viên, tung quyền toàn lực phá nát vòng phong tỏa rồi đưa phi xa xông vào thông đạo. Hai Ma tôn không nhận ra kẻ xâm nhập nên triệu tập các Ma tộc cao giai tại cứ điểm để tra hỏi, qua đó biết nhóm ba người là tu sĩ Nhân tộc đến từ Linh giới và từng có tin đồn đánh bại Thánh Tổ. Trong thông đạo, Hàn Lập phấn chấn vì chỉ còn vài canh giờ nữa sẽ trở về Linh giới, dù cửa ra nằm trong địa vực Mộc tộc. Hành trình bất ngờ bị gián đoạn khi một cự thuyền màu đen dài hơn trăm trượng, chở đông đảo vệ sĩ Ma tộc, xuất hiện từ hướng đối diện. Nhận thấy chủ nhân cự thuyền có thể không phải Ma tôn bình thường, Hàn Lập lập tức vận chuyển pháp lực và chuẩn bị ứng phó giữa khu vực đầy lốc xoáy không gian."},{"chuong":2142,"tieuDe":"Về Đến Mộc Tộc","tomTat":"Trên đường vượt thông đạo trở về Linh giới, phi xa của Hàn Lập chạm trán một cự thuyền chở đông đảo vệ sĩ và cao thủ Ma tộc. Thôn Thiên mở khe không gian, dùng bàn tay xương trắng phá phòng hộ, buộc Hàn Lập biến thành cự viên lông vàng và hợp lực với Giải Đạo Nhân chống đỡ. Hàn Lập dốc pháp lực thúc phi xa dịch chuyển khỏi chiến trường, còn Thôn Thiên quyết định không truy bắt vì phải ưu tiên công việc chính. Sau vài canh giờ, phi xa xông khỏi đầu thông đạo phía Mộc tộc và bỏ xa các đội tuần tra cùng những Ma tôn xuất động từ tháp canh. Hàn Lập xác nhận mình đã trở lại lãnh thổ Mộc tộc, đồng thời nhận lời cho Chu Quả Nhi đi cùng khi tìm đường tới Tiểu Linh Thiên. Đi sâu vào rừng, họ phát hiện cây cối mang đặc điểm Ma giới, tử khí chứa ma khí và sự vắng bóng hoàn toàn của người Mộc tộc, cho thấy nơi đây đã xảy ra biến cố liên quan đến Ma tộc."},{"chuong":2143,"tieuDe":"Kinh Biến Ở Mộc Tộc","tomTat":"Hàn Lập bác bỏ suy đoán rằng Mộc tộc đã bị tiêu diệt hoàn toàn và cho rằng cư dân quanh thông đạo chỉ rút đi trước sức ép của Ma tộc. Trên đường tiến sâu vào lãnh địa Mộc tộc, hắn dùng bảy mươi hai tiểu kiếm phân hóa thành hơn một nghìn kiếm quang, tiêu diệt toán truy cản thứ bảy cùng hàng trăm ma cầm. Một tháng sau, Hàn Lập cứu một bộ lạc hơn vạn người và được trưởng lão của họ kể rằng Ma tộc đã bí mật chuyển một nửa lực lượng từ chiến trường Nhân–Yêu sang mở cuộc tổng công kích. Đại trưởng lão Mộc tộc bị ba Thánh tổ mai phục, phải cầu viện linh mộc thông linh mới thoát chết nhưng mất gần hết pháp lực và rơi khỏi cảnh giới Đại Thừa. Vì thế, Mộc tộc tổn thất bảy tám phần mười lực lượng, mất phần lớn lãnh thổ, còn viện quân các tộc chỉ đủ giữ vùng đất còn lại. Hàn Lập từ chối hộ tống cả bộ lạc vì đã bị cao giai Ma tộc chú ý, nhưng nhận lời chuyển tin và mang theo tư liệu cùng bản đồ phân bố quân Ma. Hơn mười ngày sau, một bàn tay khổng lồ màu xanh bất ngờ vươn lên từ hồ nước, chụp lấy và bóp nát phi xa chở Hàn Lập cùng Chu Quả Nhi."},{"chuong":2145,"tieuDe":"Khách Đến Bất Ngờ","tomTat":"Hàn Lập dùng Phá Diệt Pháp Mục tìm ra bản thể Tinh Tượng Thú giữa hơn trăm hóa thân, xuyên thủng thân thể rồi thiêu hủy nó bằng lửa bạc. Tuy nhiên, ma thạch bản mạng của ma thú đã được Nguyên Sát luyện hóa nên nó vẫn có khả năng được tế luyện hồi sinh. Nguyên Sát thôi khinh thường đối thủ, triệu hồi bản mạng ma tướng hình sói và dùng uy áp Đại Thừa ép Hàn Lập lùi lại, trong khi Giải Đạo Nhân bảo vệ Chu Quả Nhi. Hàn Lập dung hợp Phạm Thánh Kim Thân để biến thành cự viên ba đầu sáu tay, còn Giải Đạo Nhân trở về bản thể Hoàng Kim Cự Giải, chuẩn bị phối hợp chống Nguyên Sát. Nguyên Sát bất ngờ dùng cây chùy trăm mắt công kích một ngọn núi gần đó, buộc Ngao Khiếu cùng Ngân Nguyệt đang ẩn thân phải xuất hiện. Ngao Khiếu chặn đòn rồi cảnh cáo Nguyên Sát rằng tương quan lực lượng hiện tại đã khiến chính ả rơi vào thế bất lợi. Hàn Lập nhận ra Ngân Nguyệt và vui mừng tột độ khi được tái ngộ nàng sau thời gian dài xa cách kể từ Côn Ngô Sơn."},{"chuong":2146,"tieuDe":"Ngao Khiếu Và Ngân Nguyệt","tomTat":"Sự xuất hiện của Ngao Khiếu khiến Nguyên Sát từ bỏ việc vây giết Hàn Lập, thu hồi pháp bảo rồi dẫn tòa điện và sói khổng lồ rút khỏi hiện trường. Hàn Lập cùng Giải Đạo Nhân khôi phục hình người, thu lại hai tòa cực sơn và lên chiếc thuyền bạc năm tầng do Ngao Khiếu triệu ra. Trong phòng, Ngao Khiếu nhận ra Hàn Lập đã đạt Hợp Thể hậu kỳ, đồng thời gọi Ngân Nguyệt ra chào người từng cứu giúp nàng tại Nhân Giới. Ông cũng nhận diện Giải Đạo Nhân là Hoàng Kim Thánh Giải đến từ Ma Nguyên Hải. Sau đó, Ngao Khiếu cho biết mình tới xác minh việc ba Thánh Tổ Ma tộc phụ trách khu vực bị thay đổi và điều tra sự khuếch trương của Ma Hóa Mẫu Trận trên lãnh địa Mộc tộc. Từ sự mất tích trước đây của Hàn Lập và những người đồng hành, ông suy ra hắn từng bí mật vào Ma giới rồi tiến sâu tới Tẩy Linh Trì. Chương kết thúc khi Ngao Khiếu hỏi thẳng Hàn Lập có từng ăn Tịnh Linh Liên hay không."},{"chuong":2147,"tieuDe":"Vong Tình Quyết","tomTat":"Ngao Khiếu dò hỏi và khiến Hàn Lập dè dặt thừa nhận mình đã tiến vào Tẩy Linh Trì, qua đó đánh giá cơ hội tiến lên Đại Thừa của hắn đã tăng đáng kể. Biết được điều này, lão hối hận vì từng ngăn Ngân Nguyệt sớm gặp Hàn Lập và để nàng lựa chọn Vong Tình Quyết, trong khi nàng lạnh nhạt khẳng định yêu hận không còn đáng lưu tâm. Đoàn người rời khu vực Ma tộc chiếm đóng để trở về Thành Mộc Miên và đại doanh liên quân; trên đường, Giải Đạo Nhân phát hiện Bích Long trà có linh lực hữu ích với mình. Sau khi bảo Ngân Nguyệt lui về an dưỡng, Ngao Khiếu kể rằng nàng từng quỳ bảy ngày đêm ngoài nơi lão bế quan khi mới từ Nhân giới trở về. Lão tiết lộ thể chất của nàng không phù hợp với Vong Tình Quyết, khiến việc luyện tiếp hay dừng lại đều có thể gây tổn hại nghiêm trọng đến tu vi và pháp lực. Ngân Nguyệt hiện chỉ duy trì được bản tính thật trong một phần ba thời gian mỗi ngày, buộc Ngao Khiếu thường xuyên dùng Trấn Thần Thuật để giảm tổn thương thần thức. Cuối cùng, lão cho biết Thất Tinh Nguyệt Thể đã trỗi dậy và tương khắc với Vong Tình Quyết, khiến hai sức mạnh quấn chặt vào nhau đến mức lão cũng chưa thể hóa giải."},{"chuong":2148,"tieuDe":"Chuyện Trò","tomTat":"Giải Đạo Nhân nhận ra Thất Tinh Nguyệt Thể của Linh Lung và xác nhận thể chất này cực kỳ hiếm gặp ngay cả tại Chân Tiên Giới, còn Ngao Khiếu cho biết nó giúp nàng có thêm hy vọng tiến vào Đại Thừa. Khi biết Ngao Khiếu đã chuẩn bị một phương pháp nhằm giảm thiểu hoặc loại bỏ ảnh hưởng của Vong Tình quyết, Hàn Lập nhận lời góp sức vì tình nghĩa năm xưa với Ngân Nguyệt. Ngao Khiếu yêu cầu Giải Đạo Nhân lánh mặt rồi bí mật bàn bạc với Hàn Lập trong vài canh giờ, nhưng nội dung phương pháp chưa được tiết lộ. Sau đó, Ngân Nguyệt tìm đến gặp Hàn Lập trong khoảng thời gian Vong Tình quyết tạm ngừng phát tác và mong hắn vẫn coi nàng là người đồng hành giàu tình cảm năm xưa. Hai người ôn lại những lần giúp đỡ lẫn nhau tại Nhân giới, trong đó Ngân Nguyệt từng báo vị trí tiết điểm giúp Hàn Lập tìm đường phi thăng. Hàn Lập kể lại hành trình từ biến cố Côn Ngô sơn, quãng thời gian lưu lạc tới Bắc Minh Đảo, quá trình tiến giai Hóa Thần và phi thăng Linh giới. Ngân Nguyệt cũng kể về những trải nghiệm của mình, đồng thời trách Ngao Khiếu từng định gả nàng cho Thiên Khuê Lang Vương và bắt nàng tu luyện Vong Tình quyết để hóa giải ma tâm, khiến Hàn Lập ngoài mặt vẫn mỉm cười nhưng trong lòng hoảng hốt."},{"chuong":2149,"tieuDe":"Thành Mộc Miên","tomTat":"Ngân Nguyệt hỏi Hàn Lập về phương pháp áp chế Vong Tình Quyết và được biết nàng có thể phải ở bên hắn cho tới khi tiến vào Đại Thừa kỳ hoặc tìm được cách hóa giải khác. Sau đó, nàng triệu Lão Ảnh và biết Ngao Khiếu từng đề nghị gả nàng cho Hàn Lập, kèm theo kinh nghiệm tiến giai Đại Thừa cùng hơn nửa số bảo vật tích cóp cả đời, nhưng Hàn Lập đã từ chối hôn sự và chỉ nhận lời giúp nàng. Lão Ảnh cũng tiết lộ Thiên Khuê Lang Vương, chồng trên danh nghĩa của Ngân Nguyệt, đã bị nhiều Ma tôn đánh lén rồi ngã xuống hơn chục năm trước. Hàn Lập quyết định sẽ tìm biện pháp khác nếu bí thuật của Ngao Khiếu không thể chữa trị hoàn toàn cho Ngân Nguyệt. Nhờ nền tảng Luyện Thần Thuật, hắn chỉ mất hai tháng để luyện thành mấy tầng đầu của bí thuật thần niệm. Phi thuyền của Ngao Khiếu sau đó tiến vào khu vực do liên quân kiểm soát trên lãnh thổ Mộc tộc và bay thẳng tới tổng bộ. Đoàn người cuối cùng nhìn thấy Thành Mộc Miên, một thành trì mười tầng dựng trên hơn mười cây khổng lồ, hiện là đại doanh liên quân và từng là trọng điểm thứ hai của Mộc tộc."},{"chuong":2150,"tieuDe":"Mạc Giản Ly","tomTat":"Thuyền bạc chở Ngao Khiếu, Hàn Lập, Giải Đạo Nhân, Ngân Nguyệt và Chu Quả Nhi vượt qua cấm chế, hạ xuống quảng trường thành Mộc Miên. Mạc Giản Ly dùng pháp trận truyền tống ra nghênh đón, nhận ra Hàn Lập là tu sĩ Nhân tộc từng tiến vào Ma giới và dùng linh mục xác định Giải Đạo Nhân chính là Thánh Giải ở Ma Nguyên Hải. Giải Đạo Nhân nhắc lại việc Mạc Giản Ly từng cùng vài người Linh giới tìm cách vượt Lôi Hải vào Khổ Linh Đảo nhưng phải trọng thương rút lui. Khi Ngao Khiếu tiết lộ Giải Đạo Nhân đã ký khế ước đi theo Hàn Lập, Mạc Giản Ly đổi cách nhìn và coi Hàn Lập là hy vọng kế nghiệp của hai tộc Nhân–Yêu. Tại động phủ, mọi người thưởng thức Tiên Diệp Tửu và bàn về tình trạng suy yếu của Mộc tộc sau cuộc xâm lấn của Ma tộc. Thánh thụ Mộc tộc đã bị dời đến thành Mộc Miên và tổn thương nguyên khí, còn đại trưởng lão khó khôi phục tu vi kịp thời để tham gia chiến cuộc. Cuối cùng, Ngao Khiếu công bố Hàn Lập đã tiến vào Tẩy Linh Trì và ăn Tịnh Linh Liên, khiến Mạc Giản Ly kinh hãi bật dậy."},{"chuong":2151,"tieuDe":"Ma Ảnh Lại Xuất Hiện","tomTat":"Mạc Giản Ly đánh giá Hàn Lập có ba đến bốn phần cơ hội tiến vào Đại Thừa nhờ tư chất, Tẩy Linh Trì, Tịnh Linh Liên và sự trợ giúp của hai tu sĩ Đại Thừa. Ngao Khiếu tiết lộ Ngân Nguyệt mang Thất Tinh Nguyệt Thể, nhưng quá trình tu luyện của nàng đang gặp phiền phức, khiến lão phải thỏa thuận với Mạc Giản Ly về việc tương trợ hai hậu bối. Hai lão tổ giải thích sứ mệnh bồi dưỡng người kế tục của Thánh Đảo, song Hàn Lập vẫn chọn tiếp tục con đường độc hành và chỉ để ngỏ khả năng tới tham quan. Hàn Lập sau đó xác nhận Lũng gia lão tổ và Diệp tiên tử đã chết tại Ma giới, gây tổn thất đáng kể cho Chân Linh thế gia và Nhân tộc. Mạc Giản Ly cho biết Mộc tộc đang chuẩn bị phản công với sự đồng ý của Tang Hải thuộc Dạ Xoa tộc, nhưng Ngao Khiếu phản đối kế hoạch này. Tình hình chiến tranh trở nên nguy cấp khi Ma tộc đồng loạt đưa lực lượng lớn vào lãnh địa nhiều tộc tại Linh giới và phát động tấn công dữ dội. Đáng lo hơn, Thánh Đảo đã xác nhận trong đại quân mới có hóa thân của một trong ba Ma giới Thủy Tổ, dù Ngao Khiếu cho rằng bản thể các Thủy Tổ khó có thể dễ dàng tiến vào Linh giới."},{"chuong":2152,"tieuDe":"Mộc Giới Ba Mươi Sáu Thiên Tuyệt Trận","tomTat":"Mạc Giản Ly và Ngao Khiếu lo ngại Nhân tộc cùng Yêu tộc sẽ lâm vào nguy hiểm nếu bản thể các Thủy Tổ Ma tộc tiến vào Linh giới trong lúc họ còn ở Mộc tộc. Hàn Lập tiết lộ Minh Trùng Mẫu bị tiên nhân phong ấn tại Ma giới nay đã tỉnh lại và đang công kích phong ấn, buộc Ma tộc phải dùng hơn nửa lực lượng để trấn áp. Tin tức này khiến hai vị Đại Thừa suy đoán cuộc xâm lược Linh giới còn nhằm chuẩn bị đường lui cho Ma tộc nếu đại kiếp vượt khỏi tầm kiểm soát. Mạc Giản Ly đề nghị phái người vào Ma giới xác minh rồi phát tán tin tức để các Đại Thừa khắp Linh giới không thể tiếp tục đứng ngoài. Ngao Khiếu và Mạc Giản Ly thống nhất trước hết sẽ phối hợp Mộc tộc đánh quân Ma tộc tổn thất nặng, sau đó trở về tập trung lực lượng bảo vệ hai tộc. Hàn Lập nhận lời tham chiến và dự định sau trận sẽ trở về bế quan, cố gắng sớm đạt Hợp Thể hậu kỳ đại thành. Cuối cùng, Mạc Giản Ly tiết lộ Mộc tộc sẽ dùng toàn bộ ba mươi sáu thánh thụ dự phòng bố trí Mộc Giới Ba Mươi Sáu Thiên Tuyệt Trận, một tuyệt trận mô phỏng Huyền Thiên Linh Vực và được đồn có thể giết tu sĩ Đại Thừa."},{"chuong":2153,"tieuDe":"Nhiệm Vụ","tomTat":"Ngao Khiếu và Mạc Giản Ly hoàn tất việc bàn bạc sách lược đối phó Ma tộc, thỉnh thoảng hỏi ý Hàn Lập, trong khi những người còn lại không tham gia nghị sự. Sau khi Ngao Khiếu đưa Ngân Nguyệt rời đi, Hàn Lập được bố trí ở một lầu các trên nhánh đại thụ và bế quan nửa tháng tu luyện thần niệm bí thuật nhằm sớm trợ giúp nàng. Qua những điều Chu Quả Nhi quan sát được khi đi thăm Mộc Miên thành cùng Giải Đạo Nhân, Hàn Lập nhận ra đại quân các tộc đã bắt đầu chuẩn bị xuất chiến. Mạc Giản Ly sau đó giao cho Hàn Lập bảo vệ một trong ba trận nhãn của Mộc Giới Ba Mươi Sáu Thiên Tuyệt Trận, đồng thời cho biết ba Đại Thừa sẽ phụ trách đối phó các Thánh Tổ Ma tộc. Do Giải Đạo Nhân chưa thể khôi phục chiến lực đỉnh phong, Hàn Lập phải phối hợp với cao giai Mộc tộc và Dạ Xoa tộc giữ vị trí này, nhưng được yêu cầu ưu tiên bảo toàn tính mạng. Nửa tháng sau, Mộc Miên thành rung chuyển khi vô số chiến xa, cự thuyền, phi hành pháp khí và hơn trăm lực lượng khổng lồ đồng loạt xuất động, báo hiệu đại chiến sắp mở màn."},{"chuong":2154,"tieuDe":"Trận Nhãn","tomTat":"Hơn nửa lực lượng tinh nhuệ tại Mộc Miên thành cùng ba vị Đại Thừa kỳ lên đường, dự kiến hội quân với các đơn vị biên giới và quân đoàn từ những thành lân cận để đối đầu đại quân Ma tộc. Hàn Lập ở lại tu luyện thêm năm ngày rồi nhận lời triệu tập của Mộc tộc, đồng thời yêu cầu Chu Quả Nhi ở lại thành vì tu vi còn thấp. Một thanh niên Mộc tộc dẫn Hàn Lập và Giải Đạo Nhân tới cung điện, trên đường cho biết Tử Hàn đang tạm quyền đại trưởng lão. Trước khi vào điện, Hàn Lập bí mật truyền âm khiến Giải Đạo Nhân tách khỏi đoàn và đi sang mé cung điện. Tử Hàn phân Hàn Lập, Thảo Tật và Phỉ Tiểu Tịch thành một tổ bảo vệ trận nhãn của đại trận Mộc Giới, trong đó Thảo Tật phụ trách vận dụng pháp quyết phối hợp với người điều khiển đại trận. Sau khi bàn bạc, cả ba nhận thẻ ngọc ghi cách vận dụng cấm chế để đối phó tập kích. Nửa ngày sau, hàng ngàn phi xa và chiến thuyền rời Mộc Miên thành, tiến thẳng về phía đại quân Ma tộc đang chiếm đóng."},{"chuong":2155,"tieuDe":"Tuyệt Trận Hoàn Thành","tomTat":"Hơn nửa tháng sau, Hàn Lập, Phỉ Tiểu Tịch và Thảo Tật quan sát quá trình xây dựng ba mươi sáu cụm pháp trận trong khu vực rộng hàng trăm vạn dặm. Thảo Tật cho biết việc bổ sung ba mươi sáu thánh thụ dự phòng khiến Mộc Giới Ba Mươi Sáu Thiên Tuyệt Trận đủ sức vây khốn cả tu sĩ Đại Thừa. Trước nguy cơ các Thánh Tổ Ma tộc phái hóa thân tới phá mắt trận, Hàn Lập đưa ra phương án để hai người đồng hành vây một đối thủ bằng đại trận, còn những kẻ khác do hắn ứng phó. Phỉ Tiểu Tịch và Thảo Tật chấp nhận nghe theo sự điều động của Hàn Lập, xác lập hắn là người chỉ huy nhóm trấn thủ. Sau năm ngày, Hàn Lập hạ đám mây xanh xuống cạnh thánh thụ và kích hoạt thành công mắt trận thứ hai. Nửa tháng sau, toàn bộ tuyệt trận được kích hoạt trọn vẹn, biến khu vực hàng trăm vạn dặm thành bẫy giết người chờ đại quân Ma tộc bị dẫn vào."},{"chuong":2156,"tieuDe":"Mộc Linh Bát Tử","tomTat":"Hàn Lập cùng hai người khác tiếp tục canh giữ trận nhãn dưới đại thụ, còn Giải Đạo Nhân được giấu trong kiến trúc giữa đám mây và ngụy trang thành trung giai Nhân tộc. Chiến báo cho thấy liên quân đã trải qua nhiều trận ác chiến với Ma tộc, sau đó vừa đánh vừa rút để dẫn đối phương tiến sát Mộc giới đại trận. Tại khu vực trận địa của Mộc tộc, Đại trưởng lão tạm thời tiếp nhận kết quả bói toán thuận lợi từ Mộc Linh Bát Tử và yêu cầu họ tiếp tục suy đoán chiến cục mỗi ngày. Ở các chiến trường bên ngoài, Mạc Giản Ly, Ngao Khiếu lão tổ và Nguyên Sát lần lượt duy trì thế đối kháng, khiến hóa thân của ba Thủy Tổ Ma tộc không thể rời đi cứu viện. Do thiếu các lực lượng cấp Thủy Tổ tọa trấn, đại quân Ma tộc bị dẫn vào phạm vi tuyệt trận và đứng trước nguy cơ chịu tổn thất nặng. Tuy nhiên, một đội hơn ngàn phi xa Ma tộc bất ngờ bí mật áp sát từ biên giới, trên xe là những Ma tộc bịt mặt đứng im lặng như một đoàn quân xác chết."},{"chuong":2157,"tieuDe":"Đại Chiến Ở Mộc Tộc","tomTat":"Thôn Thiên bí mật dẫn một đạo Ma quân quay lại Linh Giới và ra lệnh tăng tốc tới thành Mộc Miên trong mười ngày, nhằm phá hủy gốc thánh thụ giữ vai trò quan trọng đối với phòng tuyến Mộc tộc. Bảy ngày sau, Hàn Lập nhận được quân lệnh báo rằng đại quân Ma tộc sắp hoàn toàn lọt vào bẫy, liền phân công Thảo Tật điều động lực lượng và Phỉ Tiểu Tịch kiểm tra cấm chế, còn mình trấn thủ trung tâm. Mộc Giới Ba Mươi Sáu Tuyệt Trận sau đó biến khu vực hàng trăm vạn dặm thành biển cây, áp chế khả năng phi hành và che giấu toàn bộ liên quân. Người gỗ, cự mộc, cuồng phong, rồng gió và mưa lá đao liên tiếp phát động mười ba đợt công kích, tiêu diệt hơn nửa mấy trăm vạn Ma quân. Do tiêu hao quá lớn, tuyệt trận tạm thời chỉ duy trì vây khốn và cần ít nhất nửa ngày để phục hồi trước đợt tấn công tiếp theo. Bên ngoài màng cấm chế, lực lượng Ma tộc chưa lọt vào trận đang tìm cách phá vây thì hàng loạt truyền tống trận xuất hiện, đưa liên quân tới mở cuộc chém giết trực diện."},{"chuong":2158,"tieuDe":"Đại Chiến Ở Mộc Tộc (2)","tomTat":"Hơn nửa đại quân Ma tộc bị vây trong đại trận, còn lực lượng bên ngoài bị liên quân đánh tan ma trận phòng thủ và buộc phải rút lui trong cảnh truy sát. Nguyên Sát nhận tin chiến trường bất lợi rồi vội quay về phía Mộc tộc, nhưng bị Ngao Khiếu chặn đường, phong tỏa các hư ảnh đào thoát và kéo vào một cuộc đại chiến mới. Hai Thánh Tổ Ma tộc khác cũng bị Mạc Giản Ly cùng tu sĩ Đại Thừa của tộc Dạ Xoa cầm chân, khiến không cường giả nào có thể cứu viện. Bên trong Mộc Giới, các toán Ma tộc tranh thủ lúc đại trận tạm ngừng công kích để tìm đường tiến vào trung tâm và phá trận. Đội Luyện Hư do Ma Tôn đầu trâu dẫn đầu bị hơn trăm mộc kiếm tiêu diệt gần hết; người dẫn đầu sống sót nhờ chiếc ô phòng hộ nhưng bị thương và vẫn tiếp tục tiến sâu. Ở một dải núi khác, pháp trận ánh sáng vàng phá tan thái cực đồ của ba Ma Tôn và khiến cả ba mất tung tích. Tại trung tâm dãy núi, tín hiệu từ gốc cây chọc trời báo cho Hàn Lập biết một nhóm Ma tộc có tu vi không thấp đã đến gần vị trí hắn trấn giữ."},{"chuong":2159,"tieuDe":"Đại Chiến Ở Mộc Tộc 3","tomTat":"Thảo Tật và Phỉ Tiểu Tịch trở lại mắt trận sau khi linh thụ báo nguy, còn Hàn Lập kích hoạt pháp trận giám sát để phát hiện ba Ma Tôn cùng bốn Ma tộc Luyện Hư đang tiến về trung tâm dãy núi. Nhận ra bốn tên Luyện Hư có hình dáng, ma công và cách phối hợp tương tự, Hàn Lập nghi ngờ chúng vốn là một thể bị ma thuật phân hóa nên không giao chúng cho các thuộc hạ bình thường. Hắn để Thảo Tật ở lại bảo vệ mắt trận, giao Phỉ Tiểu Tịch đối phó bốn tên Luyện Hư và tự nhận chặn ba Ma Tôn. Giải Đạo Nhân được gọi ra với khí tức Hợp Thể Hậu Kỳ mạnh không thua Hàn Lập, khiến hai đồng đội chấp thuận kế hoạch. Thảo Tật cùng hơn trăm người Mộc tộc vận hành Điên Đảo Hoán Hình Ngũ Nhạc, trong khi Hàn Lập, Giải Đạo Nhân, Phỉ Tiểu Tịch và hơn mười vệ sĩ Luyện Hư xuất kích. Cấm chế dùng mây năm màu cùng ký hiệu xanh bao phủ bảy Ma tộc và thay đổi vị trí của chúng. Ma Tôn mặt mũi dữ tợn dùng gương đồng phá khỏi vòng vây nhưng phát hiện sáu đồng bọn đã bị chuyển đi nơi khác, còn Hàn Lập đang từ chân trời lao tới đối đầu."},{"chuong":2160,"tieuDe":"Đại Chiến Ở Mộc Tộc (4)","tomTat":"Ma Tôn mặt xanh dùng gương đồng hóa thành đầu quỷ, phóng Diêm Đô Ma Viêm bao vây Hàn Lập, nhưng chim lửa bạc của hắn nhanh chóng nuốt gần hết ma diễm. Nhận ra đối thủ có thực lực đáng sợ, Ma Tôn kích nổ bảo vật, hy sinh hai cánh tay và thi triển Huyết Ảnh Độn để chạy trốn. Hàn Lập phá lưới tơ đen, dùng Ích Tà Thần Lôi đánh tan huyết vụ rồi vận dụng pháp trận sấm sét màu bạc vượt lên chặn đường. Pháp tướng ba đầu sáu tay của hắn chém đôi thân thể và nghiền nát nguyên anh, khiến Ma Tôn Hợp Thể Trung Kỳ hoàn toàn diệt vong. Ở một khu rừng khác trên chiến trường, Phỉ Tiểu Tịch cùng hơn mười tu sĩ Mộc tộc bao vây bốn Ma tu Luyện Hư đang vận hành Huyết Kha Vô Lượng Ma Công. Nhận ra loại ma công từng được cho là đã thất truyền, nàng ra lệnh cho lực lượng Mộc tộc đồng loạt tấn công để ép đối phương lộ sơ hở. Chương khép lại khi các tu sĩ Mộc tộc phóng dải sáng xanh và linh khí hóa dây thừng về phía bốn Ma tu."},{"chuong":2161,"tieuDe":"Đại Chiến Ở Mộc Tộc (5)","tomTat":"Bốn Ma tộc Luyện Hư đứng dựa lưng vào nhau, phối hợp tung sóng khí màu máu để phá vòng vây của quân Mộc tộc, khiến hai người rút lui chậm bị xé nát và hút hết máu. Phỉ Tiểu Tịch kịp dùng đao khí phá vỡ mặt trước của luồng sóng, cứu những người còn lại. Bốn Ma tộc sau đó thi triển Tứ Tượng Hợp Nhất, hóa thành người khổng lồ lông đỏ có khí tức không thua tu sĩ Hợp Thể hậu kỳ và nhanh chóng áp đảo đợt công kích đầu tiên. Phỉ Tiểu Tịch dùng trận kỳ tạo mây mù năm màu, đồng thời huy động lưỡi đao, kiếm vàng bạc, tháp bạc và quái vật phối hợp với quân Mộc tộc mở cuộc vây công mới. Ở một bãi chiến khác, Hàn Lập tìm thấy Giải Đạo Nhân bên cạnh thi thể hai Ma tộc cao cấp vừa bị tiêu diệt. Sau khi xác nhận ba Ma Tôn đã được giải quyết, Hàn Lập đề nghị Giải Đạo Nhân cùng quay lại trợ giúp Phỉ Tiểu Tịch đối phó hợp thể của bốn Ma tộc còn lại."},{"chuong":2162,"tieuDe":"Đại Chiến Ở Mộc Tộc (6)","tomTat":"Hàn Lập và Giải Đạo Nhân dùng quang trận dịch chuyển thoát khỏi không gian cấm chế ngay trước khi nơi đó sụp đổ hoàn toàn. Vừa hiện thân, Hàn Lập nhận tin từ Thảo Tật rằng mắt trận số ba đã bị sáu hóa thân Thánh tổ Ma tộc công phá, khiến Mộc Giới đại trận suy yếu. Lo mắt trận số một sẽ trở thành mục tiêu tiếp theo, hắn ra lệnh mở rộng gấp đôi phạm vi dò xét rồi lập tức tới cứu viện Phỉ Tiểu Tịch. Tại một vòng sáng năm màu, Phỉ Tiểu Tịch và lực lượng Mộc tộc đang bị hơn mười huyết giao của huyết mao cự nhân áp chế, trong khi Huyết Kha Vô Lượng Ma Công giúp những huyết giao bị diệt có thể tái ngưng tụ. Hàn Lập hóa thành Sơn Nhạc Cự Viên, dùng thần lực ném hai tòa cực sơn liên tiếp phá vỡ huyết sắc quang thuẫn của đối phương. Bị dồn vào tình thế sinh tử, huyết mao cự nhân ngưng tụ quyền giáp đen và thi triển cấm thuật kích phát tiềm lực, chuẩn bị tung đòn liều mạng."},{"chuong":2163,"tieuDe":"Đại Chiến Ở Mộc Tộc (7)","tomTat":"Hàn Lập điều khiển hai ngọn núi nghiền nát thân thể hợp thành của bốn Ma tộc Luyện Hư, rồi dùng một cú chụp cách không tiêu diệt cả bốn Nguyên Anh đang phân hướng đào tẩu. Thảo Tật truyền tin rằng các hóa thân Thánh Tổ đã chia thành ba mũi tiến công ba mắt trận, trong đó mắt trận thứ ba đã bị phá và năm kẻ Hợp Thể Hậu Kỳ đang áp sát nơi hắn trấn giữ. Thảo Tật cần thêm nửa canh giờ để đảo ngược đại trận, truyền năng lượng vào gốc thánh thụ dự phòng và kích hoạt cấm chế giam địch. Hàn Lập nhận lời cầm chân nhóm địch, điều Phỉ Tiểu Tịch cùng những người Mộc tộc trở về hỗ trợ phòng thủ rồi cùng Giải Đạo Nhân truyền tống đi chặn đường. Trước nhóm năm Ma tộc cao cấp, Ngưu mỗ chủ động ở lại giao chiến để bốn đồng bọn tiếp tục tiến về mắt trận. Hàn Lập hiện Phạm Thánh Pháp Tướng, chém sáu luồng kiếm khí vào không gian nhằm giữ toàn bộ đối phương lại. Ngưu mỗ ngưng tụ ma khí thành cây búa đen và bổ ra đao mang khổng lồ, còn Giải Đạo Nhân bước lên trước Hàn Lập, búng một ngón tay nghênh đón công kích."},{"chuong":2164,"tieuDe":"Đại Chiến Ở Mộc Tộc 8","tomTat":"Giải Đạo Nhân dùng quang cầu vàng chặn lưỡi dao đen của Ngưu mỗ, trong khi kiếm quang của Hàn Lập ép hai hóa thân Thánh Tổ đang ẩn mình phải hiện thân. Lão già áo bào thuyết phục Ngưu mỗ từ bỏ ý định đơn độc giao chiến, khiến cả năm hóa thân thống nhất hợp lực vì nhiệm vụ có quan hệ đến thắng bại của trận chiến. Giải Đạo Nhân nhận đối phó ba kẻ, còn Hàn Lập tự mình giải quyết hai đối thủ còn lại. Năm hóa thân đồng loạt phát động thế công bằng búa ảnh, đàn ong đỏ, ba cột thần quang, võng tơ hồng và vô số mũi băng đen. Hàn Lập dùng Lôi độn rời khỏi vòng vây, để Giải Đạo Nhân một mình dùng quầng sáng vàng chống đỡ nguyên vẹn toàn bộ đợt công kích. Sau đó, Hàn Lập xuất hiện trên cao, triệu Phạm Thánh Pháp Tướng ba đầu sáu tay và ném một quang cầu chứa vô số ký hiệu vàng xuống chiến trường bất chấp sự ngăn cản của đối phương."},{"chuong":2165,"tieuDe":"Đại Chiến Ở Mộc Tộc (9)","tomTat":"Hàn Lập hợp nhất sáu khối hào quang thành cơn lốc ký hiệu vàng bạc, phá các đòn công kích và tạm thời áp chế năm Ma tộc. Hắn dùng lôi điện từ đôi cánh dựng pháp trận dưới chân lão già mặc áo bào cùng Linh tiên tử, rồi lấy tiếng hừ lạnh công kích thần hồn để ngăn lão già thoát thân và cưỡng chế truyền tống cả hai đi hơn vạn dặm. Sau khi Hàn Lập tự truyền tống truy kích, ba Ma tộc còn lại xác định đồng bọn vẫn sống nhưng lập tức phải đối diện với Giải Đạo Nhân vừa hiện chân thân Hoàng Kim Cự Giải. Ma tộc ba mắt dùng Bảo Luân Pháp Mục nhận định pháp lực của Thánh Giải chưa đạt Đại Thừa, vì vậy kêu gọi hai đồng bọn hợp lực kéo chân đối thủ. Ba Ma tộc lần lượt dùng cự phủ trong mây đen, ba bộ xương ngọc và hồ lô hóa đàn quạ hồng, còn Giải Đạo Nhân đáp lại bằng lưới điện bạc cùng hai quả cầu điện. Ở nơi cách chiến trường hơn vạn dặm, Hàn Lập triển khai pháp tướng ba đầu sáu tay và bảy mươi hai thanh kiếm xanh, khiến hai Ma tộc bị truyền tống kinh sợ trước cuộc đối đầu sắp tới."},{"chuong":2166,"tieuDe":"Đại Chiến Ở Mộc Tộc 10","tomTat":"Biết lão già Ma tộc và Linh tiên tử đều chỉ là hóa thân, Hàn Lập chủ động đưa họ tới chiến trường riêng và một mình đối phó cả hai. Lão già triệu ra ảo ảnh côn trùng đỏ, điều khiển vô số tơ máu xuyên qua không gian, nhưng Hàn Lập dùng Phạm Thánh Pháp Tướng và kiếm quang màu xanh ngăn chặn. Linh tiên tử nhân lúc đó âm thầm áp sát bằng thân hình trong suốt, song linh mục và thần niệm mạnh mẽ giúp Hàn Lập nhìn thấu đòn đánh lén. Nàng tiếp tục vận dụng ảo thuật nửa thật nửa giả, để lại nhiều hư ảnh và liên tiếp tấn công từ các hướng khác nhau, khiến thế công giống như do tám người đồng thời phát động. Hàn Lập nhận ra nguyên lý của ảo thuật, điều khiển sáu thanh kiếm của pháp tướng chém khắp xung quanh và bình tĩnh chờ đối phương giảm tốc. Đúng lúc hắn gọi ra một tòa núi nhỏ màu đen, tơ máu ẩn trong sương bất ngờ tái ngưng tụ tập kích, buộc hắn dùng áo điện màu vàng bảo vệ thân thể. Sương máu sau đó khép kín quanh Hàn Lập, còn bảy hình thể của Linh tiên tử đồng thời ném bảy lá cờ để dựng bảy pháp trận ánh sáng màu máu có ngọn lửa đỏ chớp động ở giữa."},{"chuong":2167,"tieuDe":"Đại Chiến Ở Mộc Tộc (11)","tomTat":"Bảy thiếu nữ Ma tộc có cánh hợp nhất bảy pháp trận dung nham, tạo biển lửa và màn sáng hai màu nhằm phong tỏa, luyện hóa Hàn Lập. Lão già Ma tộc thả ba hỏa giao trắng từ bình ngọc và dùng vòng bạc hỗ trợ kết giới, trong khi chim lửa bạc, sáu cột sáng cùng kiếm quang xanh của Hàn Lập liên tục phản công. Hàn Lập hóa thành cự viên vàng, hợp vô số quyền ảnh thành một đòn lớn và đánh vỡ màn sáng, sau đó cản vòng sáng trấn áp rồi dịch chuyển ra sau lão già. Trong cuộc giao thủ trực diện, hắn phá trùng ảnh huyết sắc và đầu hỏa giao nhưng không thể chém hỏng bình ngọc, đồng thời bị lửa trắng quấn giữ một cánh tay. Đúng lúc lão già phải tập trung phần lớn pháp lực đối phó Hàn Lập, bóng người màu xanh và Linh Khu xuất hiện từ hai bên, lần lượt tung lưới xanh cùng sáu quang cầu vàng giáp công. Lão già phóng hai bạch cốt phi xoa chống trả, nhưng một chiếc bị chặn còn chiếc kia bị thân thể cứng rắn của Linh Khu hất bật."},{"chuong":2168,"tieuDe":"Đại Chiến Ở Mộc Tộc 12","tomTat":"Sáu quang cầu vàng của Linh Khu phá vỡ phòng ngự của lão già Ma tộc, tạo cơ hội để Hàn Lập xuyên ngực, móc tim và dùng lửa bạc thiêu diệt cả thân thể lẫn nguyên anh của đối phương. Ma nữ có cánh dùng Phân Thân Thuật chia thành bảy bóng bỏ chạy, nhưng Hàn Lập vận dụng linh mục màu lam tìm ra chân thân rồi dùng đôi cánh trong suốt truy đuổi. Sau khi phá tan nhiều tầng phòng ngự, hắn thi triển Niết Bàn Biến Thân và dùng một chưởng ép chết Ma nữ cùng nguyên anh. Khúc Nhi điều khiển Linh Khu mang chiến lợi phẩm của lão già Ma tộc về giao cho Hàn Lập, còn hắn thu dọn vật phẩm rồi vượt hơn vạn dặm trở lại chiến trường của Giải Đạo Nhân. Tại đây, ba Ma tộc phát hiện đồng bọn gặp nạn nên đồng loạt rút lui, nhưng Giải Đạo Nhân dựng pháp trận sấm chớp buộc chúng phải dừng lại chống đỡ. Trận pháp chỉ kéo dài vài nhịp thở, song ngay khi nó tan vỡ, Hàn Lập kịp xuất hiện và chặn đứng đường lui của cả ba."},{"chuong":2169,"tieuDe":"Đại Chiến Ở Mộc Tộc 13","tomTat":"Thảo Tật báo cấm chế tại mắt trận số hai đã sẵn sàng, nhưng Hàn Lập cho biết mình và Giải Đạo Nhân đã tiêu diệt cả ba hóa thân Thánh Tổ đến trước, đồng thời thu được cây búa đen của tên Ma tộc mặc giáp vàng. Dị tượng từ phương xa sau đó xác nhận gốc thánh thụ dự bị tại mắt trận số một đã bị phá hủy, buộc phe Mộc tộc phải chuẩn bị đối phó các đợt công kích tiếp theo. Sau khi hai người trở về nghỉ ngơi, cây cối quanh chiến trường nhanh chóng tái sinh và che kín mọi dấu vết giao tranh. Không lâu sau, một cung điện ẩn trong ma khí đưa bảy Ma tộc mạnh tới mắt trận số hai, nơi lưới sáng xanh bất ngờ phát động, bắt bốn kẻ vào quang cầu và để ba kẻ còn lại thoát ra. Lão Quý cùng hai đồng bọn đuổi theo các quang cầu nhưng bị Hàn Lập và Giải Đạo Nhân chặn đường. Hàn Lập thi triển biến thứ nhất của Niết Bàn Thánh Thể, còn Giải Đạo Nhân hiện lại bản thể cua khổng lồ để chuẩn bị giao chiến. Vài canh giờ sau, đại quân Ma tộc đã chiếm mắt trận số một nhưng vẫn không thể liên lạc với nhóm lão Quý, khiến tầng chỉ huy nhận định mắt trận số hai thực sự có vấn đề."},{"chuong":2170,"tieuDe":"Kinh Biến","tomTat":"Sau hai lần thất bại tại mắt trận thứ hai, các thủ lĩnh Ma tộc từ bỏ tiến công và dựng Huyễn Quang Ma Diễm trận quanh mắt trận thứ nhất để bảo toàn quân tinh nhuệ, đồng thời kéo dài thời gian cho hành động bí mật của Thôn Thiên. Hơn trăm vạn quân Ma tập trung về đây vẫn liên tục bị Mộc Giới Đại Trận công kích, sau nửa tháng chỉ còn khoảng tám đến chín vạn người. Trên đài cao của Mộc tộc, tám Mộc Linh chết vì Thiên Diễm phản phệ khi thôi toán, buộc tám hậu bối lập tức tiếp quản pháp trận. Tin khẩn từ thành Mộc Miên sau đó xác nhận thánh địa đã thất thủ, Thánh thụ bị hủy và đại trưởng lão đang dưỡng thương cũng tử trận. Đại trưởng lão lâm thời trấn định hội đồng trưởng lão, phong tỏa tin tức và chuyển mục tiêu sang rút lui, bảo toàn hàng trăm triệu tộc nhân bằng hy vọng đặt vào những cây Thánh thụ dự phòng. Hội đồng trưởng lão quyết định rút phần lớn quân, báo cho các tộc đồng minh và kích phát mắt trận thứ hai để tự bạo toàn bộ Mộc Giới Tuyệt Trận. Được Thảo Tật báo tin trước, Hàn Lập cùng nữ tử Dạ Xoa tộc và các tu sĩ Nhân tộc rời mắt trận thứ hai, nhanh chóng trở về thành Mộc Miên trong lúc chiến tuyến liên quân đứng trước nguy cơ tan rã."}];
